(function () {
  const D = window.CHINESE_DATA;
  const extra = [{"id":31,"hsk":3,"zh_title":"我比你更喜欢音乐","pinyin_title":"Wǒ bǐ nǐ gèng xǐhuan yīnyuè","title":"Tôi thích âm nhạc hơn bạn","words":[{"id":"w_31_1","hsk":3,"lesson":31,"hanzi":"变","pinyin":"biàn","pos":"Động từ","hanviet":"biến","meaning":"biến, thay đổi"},{"id":"w_31_2","hsk":3,"lesson":31,"hanzi":"变化","pinyin":"biànhuà","pos":"Động từ, Danh từ","hanviet":"biến hóa","meaning":"biến hóa, thay đổi","example":"这里的生活近几年变化得很大（有很大的变化）。— Cuộc sống ở đây những năm gần đây thay đổi rất lớn (có sự thay đổi rất lớn)."},{"id":"w_31_3","hsk":3,"lesson":31,"hanzi":"暑假","pinyin":"shǔjià","pos":"Danh từ","hanviet":"thử giả","meaning":"kỳ nghỉ hè","example":"你什么时候放暑假？— Bạn lúc nào nghỉ hè?"},{"id":"w_31_4","hsk":3,"lesson":31,"hanzi":"比","pinyin":"bǐ","pos":"Giới từ","hanviet":"tỉ","meaning":"so sánh, so với"},{"id":"w_31_5","hsk":3,"lesson":31,"hanzi":"人口","pinyin":"rénkǒu","pos":"Danh từ","hanviet":"nhân khẩu","meaning":"nhân khẩu, dân số","example":"你知道越南的人口多少吗？— Bạn biết dân số Việt Nam bao nhiêu không?"},{"id":"w_31_6","hsk":3,"lesson":31,"hanzi":"最","pinyin":"zuì","pos":"Phó từ","hanviet":"tối","meaning":"nhất"},{"id":"w_31_7","hsk":3,"lesson":31,"hanzi":"城市","pinyin":"chéngshì","pos":"Danh từ","hanviet":"thành thị","meaning":"thành phố","example":"胡志明市是越南最大城市。— TP. HCM là thành phố lớn nhất Việt Nam."},{"id":"w_31_8","hsk":3,"lesson":31,"hanzi":"增加","pinyin":"zēngjiā","pos":"Động từ","hanviet":"tăng gia","meaning":"tăng thêm, tăng lên","example":"最近，城市的人口增加得很快。— Gần đây, dân số của thành phố tăng rất nhanh."},{"id":"w_31_9","hsk":3,"lesson":31,"hanzi":"建筑","pinyin":"jiànzhù","pos":"Động từ, Danh từ","hanviet":"kiến trúc","meaning":"kiến trúc, xây dựng","example":"我们城市近几年增加了很多新的建筑。— Thành phố của chúng tôi những năm gần đây đã tăng thêm rất nhiều kiến trúc mới."},{"id":"w_31_10","hsk":3,"lesson":31,"hanzi":"过去","pinyin":"guòqù","pos":"Danh từ","hanviet":"quá khứ","meaning":"quá khứ","example":"都是过去的事了，不用说了。— Đều là chuyện quá khứ rồi, không cần nói nữa."},{"id":"w_31_11","hsk":3,"lesson":31,"hanzi":"更","pinyin":"gèng","pos":"Phó từ","hanviet":"cánh","meaning":"hơn, càng","example":"你觉得哪件更好看？— Bạn thấy bộ nào đẹp hơn?"},{"id":"w_31_12","hsk":3,"lesson":31,"hanzi":"漂亮","pinyin":"piàoliang","pos":"Tính từ","hanviet":"phiêu lượng","meaning":"đẹp, xinh đẹp","example":"你今天怎么这么漂亮！— Bạn hôm nay sao mà xinh đẹp như thế này!"},{"id":"w_31_13","hsk":3,"lesson":31,"hanzi":"冬天","pinyin":"dōngtiān","pos":"Danh từ","hanviet":"đông thiên","meaning":"mùa đông","example":"我更喜欢冬天。— Tôi thích mùa đông hơn."},{"id":"w_31_14","hsk":3,"lesson":31,"hanzi":"暖和","pinyin":"nuǎnhuo","pos":"Tính từ","hanviet":"noãn hòa","meaning":"ấm áp","example":"今年冬天不太冷，我觉得今年比较暖和。— Mùa đông năm nay không lạnh lắm, tôi cảm thấy năm nay khá là ấm áp."},{"id":"w_31_15","hsk":3,"lesson":31,"hanzi":"可是","pinyin":"kěshì","pos":"Liên từ","hanviet":"khả thị","meaning":"nhưng","example":"我想去旅行，但是（可是）没钱。— Tôi muốn đi du lịch, nhưng mà không có tiền."},{"id":"w_31_16","hsk":3,"lesson":31,"hanzi":"暖气","pinyin":"nuǎnqì","pos":"Danh từ","hanviet":"noãn khí","meaning":"hệ thống sưởi","example":"天冷了！房间里有暖气吗，开吧！— Trời lạnh rồi! Trong phòng có lò sưởi không, bật lò sưởi đi!"},{"id":"w_31_17","hsk":3,"lesson":31,"hanzi":"天气","pinyin":"tiānqì","pos":"Danh từ","hanviet":"thiên khí","meaning":"thời tiết","example":"今天的天气不太好，一直下雨。— Hôm nay thời tiết không tốt lắm, cứ mưa mãi."},{"id":"w_31_18","hsk":3,"lesson":31,"hanzi":"预报","pinyin":"yùbào","pos":"Động từ, Danh từ","hanviet":"dự báo","meaning":"dự báo, báo trước","example":"听天气预报说，明天会下雨。— Nghe dự báo thời tiết nói ngày mai sẽ mưa."},{"id":"w_31_19","hsk":3,"lesson":31,"hanzi":"气温","pinyin":"qìwēn","pos":"Danh từ","hanviet":"khí ôn","meaning":"nhiệt độ không khí","example":"今天的气温很低，所以觉得很冷。— Hôm nay nhiệt độ không khí rất thấp, nên cảm thấy rất lạnh."},{"id":"w_31_20","hsk":3,"lesson":31,"hanzi":"高","pinyin":"gāo","pos":"Tính từ","hanviet":"cao","meaning":"cao"},{"id":"w_31_21","hsk":3,"lesson":31,"hanzi":"度","pinyin":"dù","pos":"Lượng từ","hanviet":"độ","meaning":"độ","example":"今天最高的气温是25度，最低是22度。— Nhiệt độ cao nhất ngày hôm nay là 25 độ, thấp nhất là 22 độ."},{"id":"w_31_22","hsk":3,"lesson":31,"hanzi":"屋子","pinyin":"wūzi","pos":"Danh từ","hanviet":"ốc tử","meaning":"phòng","example":"因为屋子里没有暖气，所以也很冷。— Vì trong phòng không có máy sưởi, nên cũng rất lạnh."},{"id":"w_31_23","hsk":3,"lesson":31,"hanzi":"感觉","pinyin":"gǎnjué","pos":"Động từ, Danh từ","hanviet":"cảm giác","meaning":"cảm giác","example":"我感觉今天比较温暖。— Tôi cảm thấy hôm nay khá là ấm áp."},{"id":"w_31_24","hsk":3,"lesson":31,"hanzi":"家庭","pinyin":"jiātíng","pos":"Danh từ","hanviet":"gia đình","meaning":"gia đình"},{"id":"w_31_25","hsk":3,"lesson":31,"hanzi":"旅馆","pinyin":"lǚguǎn","pos":"Danh từ","hanviet":"lữ quán","meaning":"nhà nghỉ, khách sạn","example":"这家旅馆有点小，我们找别的地方吧。— Nhà nghỉ này hơi bé, chúng ta tìm chỗ khác đi."},{"id":"w_31_26","hsk":3,"lesson":31,"hanzi":"饭店","pinyin":"fàndiàn","pos":"Danh từ","hanviet":"phạn điếm","meaning":"tiệm ăn"},{"id":"w_31_27","hsk":3,"lesson":31,"hanzi":"迷","pinyin":"mí","pos":"Động từ, Danh từ","hanviet":"mê","meaning":"mê, lạc (đường)","example":"他是一个足球迷。— Anh ấy là 1 người hâm mộ/đam mê bóng đá."},{"id":"w_31_28","hsk":3,"lesson":31,"hanzi":"光","pinyin":"guāng","pos":"Phó từ","hanviet":"quang","meaning":"chỉ","example":"他有很多书，光中文书就有几十本了。— Anh ấy có rất nhiều sách, chỉ riêng sách tiếng Trung đã có mấy chục quyển rồi."},{"id":"w_31_29","hsk":3,"lesson":31,"hanzi":"也许","pinyin":"yěxǔ","pos":"Phó từ","hanviet":"dã hứa","meaning":"có thể, có lẽ","example":"也许明天天气会变温暖一点。— Có lẽ ngày mai thời tiết sẽ thay đổi ấm áp hơn 1 chút."},{"id":"w_31_30","hsk":3,"lesson":31,"hanzi":"古典","pinyin":"gǔdiǎn","pos":"Tính từ","hanviet":"cổ điển","meaning":"cổ điển","example":"我觉得古典和现代音乐都好听，但是我个人更喜欢听现代音乐。— Tôi cảm thấy âm nhạc cổ điển và hiện đại đều hay, nhưng cá nhân tôi thích nghe nhạc hiện đại hơn."},{"id":"w_31_31","hsk":3,"lesson":31,"hanzi":"现代","pinyin":"xiàndài","pos":"Danh từ, Tính từ","hanviet":"hiện đại","meaning":"hiện đại","example":"我觉得古典和现代音乐都好听，但是我个人更喜欢听现代音乐。— Tôi cảm thấy âm nhạc cổ điển và hiện đại đều hay, nhưng cá nhân tôi thích nghe nhạc hiện đại hơn."},{"id":"w_31_32","hsk":3,"lesson":31,"hanzi":"世界","pinyin":"shìjiè","pos":"Danh từ","hanviet":"thế giới","meaning":"thế giới"},{"id":"w_31_33","hsk":3,"lesson":31,"hanzi":"名曲","pinyin":"míngqǔ","pos":"Danh từ","hanviet":"danh khúc","meaning":"bài ca nổi tiếng","example":"这是世界名曲，大家都听过了吧！— Đây là bài hát nổi tiếng thế giới, mọi người đều nghe qua rồi nhỉ!"},{"id":"w_31_34","hsk":3,"lesson":31,"hanzi":"民歌","pinyin":"míngē","pos":"Danh từ","hanviet":"dân ca","meaning":"dân ca","example":"她很喜欢唱民歌。— Cô ấy rất thích hát dân ca."},{"id":"w_31_35","hsk":3,"lesson":31,"hanzi":"歌曲","pinyin":"gēqǔ","pos":"Danh từ","hanviet":"ca khúc","meaning":"bài hát","example":"你唱给我听一首越南歌曲（歌）可以吗？— Bạn hát cho tôi nghe 1 bài hát Việt Nam được không?"},{"id":"w_31_36","hsk":3,"lesson":31,"hanzi":"歌词","pinyin":"gēcí","pos":"Danh từ","hanviet":"ca từ","meaning":"lời bài hát","example":"这首歌曲的歌词很有意思。— Lời bài hát của bài này rất thú vị/có ý nghĩa."},{"id":"w_31_37","hsk":3,"lesson":31,"hanzi":"流行","pinyin":"liúxíng","pos":"Tính từ","hanviet":"lưu hành","meaning":"lưu hành, thịnh hành","example":"这首歌曲最近很流行。— Bài hát này gần đây rất thịnh hành."},{"id":"w_31_38","hsk":3,"lesson":31,"hanzi":"年轻","pinyin":"niánqīng","pos":"Tính từ","hanviet":"niên khinh","meaning":"trẻ trung, trẻ tuổi","example":"很多年轻人都喜欢听流行音乐。— Rất nhiều người trẻ đều thích nghe nhạc pop."},{"id":"w_31_39","hsk":3,"lesson":31,"hanzi":"有些","pinyin":"yǒuxiē","pos":"Đại từ","hanviet":"hữu ta","meaning":"một vài","example":"有些人喜欢古典音乐，可是也有些人喜欢民歌。— Có vài người thích nhạc cổ điển, nhưng cũng có vài người thích dân ca."},{"id":"w_31_40","hsk":3,"lesson":31,"hanzi":"遥远","pinyin":"yáoyuǎn","pos":"Tính từ","hanviet":"dao viễn","meaning":"xa xôi, xa thẳm"}],"dialogue":[{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"田芳，上海怎么样？我想坐火车去上海旅行。","py":"Tián Fāng, Shànghǎi zěnmeyàng? Wǒ xiǎng zuò huǒchē qù Shànghǎi lǚxíng.","vi":"Điền Phương, Thượng Hải thế nào? Tôi muốn đi tàu hỏa đến Thượng Hải du lịch."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"上海很好，这几年变化很大。今年暑假我还在那儿玩了一个多月呢。我的一个同学家就在上海。","py":"Shànghǎi hěn hǎo, zhè jǐ nián biànhuà hěn dà. Jīnnián shǔjià wǒ hái zài nàr wánle yí ge duō yuè ne. Wǒ de yí ge tóngxué jiā jiù zài Shànghǎi.","vi":"Thượng Hải rất tốt, mấy năm nay thay đổi rất nhiều. Kỳ nghỉ hè năm nay tôi còn ở đó chơi hơn một tháng đấy. Nhà một người bạn học của tôi ở ngay Thượng Hải."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"上海比北京大吧？","py":"Shànghǎi bǐ Běijīng dà ba?","vi":"Thượng Hải lớn hơn Bắc Kinh nhỉ?"},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"不，上海没有北京大，不过人口比北京多。上海是中国人口最多的城市。这几年，增加了不少新建筑，上海比过去变得更漂亮了。","py":"Bù, Shànghǎi méiyǒu Běijīng dà, búguò rénkǒu bǐ Běijīng duō. Shànghǎi shì Zhōngguó rénkǒu zuì duō de chéngshì. Zhè jǐ nián, zēngjiāle bù shǎo xīn jiànzhù, Shànghǎi bǐ guòqù biàn de gèng piàoliang le.","vi":"Không, Thượng Hải không lớn bằng Bắc Kinh, nhưng dân số đông hơn Bắc Kinh. Thượng Hải là thành phố đông dân nhất Trung Quốc. Mấy năm nay có thêm không ít công trình kiến trúc mới, Thượng Hải trở nên đẹp hơn trước kia."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"上海的公园有北京的多吗？","py":"Shànghǎi de gōngyuán yǒu Běijīng de duō ma?","vi":"Công viên ở Thượng Hải có nhiều bằng Bắc Kinh không?"},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"上海的公园没有北京的多，也没有北京的公园这么大。","py":"Shànghǎi de gōngyuán méiyǒu Běijīng de duō, yě méiyǒu Běijīng de gōngyuán zhème dà.","vi":"Công viên ở Thượng Hải không nhiều bằng Bắc Kinh, cũng không rộng như công viên ở Bắc Kinh."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"上海的冬天是不是比北京暖和一点儿？","py":"Shànghǎi de dōngtiān shì bu shì bǐ Běijīng nuǎnhuo yìdiǎnr?","vi":"Mùa đông ở Thượng Hải có phải ấm hơn Bắc Kinh một chút không?"},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"上海不一定比北京暖和。","py":"Shànghǎi bù yídìng bǐ Běijīng nuǎnhuo.","vi":"Thượng Hải chưa chắc đã ấm hơn Bắc Kinh."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"可是，我看天气预报，上海的气温比北京高得多。","py":"Kěshì, wǒ kàn tiānqì yùbào, Shànghǎi de qìwēn bǐ Běijīng gāo de duō.","vi":"Nhưng tôi xem dự báo thời tiết, nhiệt độ ở Thượng Hải cao hơn Bắc Kinh nhiều."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"是，上海的气温比北京高好几度，不过因为屋子里没有暖气，所以感觉还没有北京暖和。","py":"Shì, Shànghǎi de qìwēn bǐ Běijīng gāo hǎo jǐ dù, búguò yīnwèi wūzi li méiyǒu nuǎnqì, suǒyǐ gǎnjué hái méiyǒu Běijīng nuǎnhuo.","vi":"Đúng vậy, nhiệt độ ở Thượng Hải cao hơn Bắc Kinh mấy độ liền, nhưng vì trong nhà không có hệ thống sưởi nên cảm giác vẫn không ấm bằng Bắc Kinh."},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"山本","zh":"上海人家里没有暖气？","py":"Shànghǎirén jiā li méiyǒu nuǎnqì?","vi":"Trong nhà người Thượng Hải không có hệ thống sưởi à?"},{"section":"Bài khóa 1: 北京比上海大吧","speaker":"田芳","zh":"一般的家庭没有，不过旅馆和饭店里有。","py":"Yìbān de jiātíng méiyǒu, búguò lǚguǎn hé fàndiàn li yǒu.","vi":"Các gia đình bình thường thì không có, nhưng trong nhà nghỉ và khách sạn thì có."},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"Kể","zh":"林老师和王老师在谈音乐……","py":"Lín lǎoshī hé Wáng lǎoshī zài tán yīnyuè……","vi":"Cô Lâm và thầy Vương đang nói chuyện về âm nhạc…"},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"林老师","zh":"王老师，你喜欢音乐吗？","py":"Wáng lǎoshī, nǐ xǐhuan yīnyuè ma?","vi":"Thầy Vương, thầy có thích âm nhạc không?"},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"王老师","zh":"喜欢啊！我是个音乐迷，光CD就有好几百张呢。","py":"Xǐhuan a! Wǒ shì ge yīnyuèmí, guāng CD jiù yǒu hǎo jǐ bǎi zhāng ne.","vi":"Thích chứ! Tôi là một người mê âm nhạc, chỉ riêng đĩa CD đã có tới mấy trăm đĩa rồi."},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"林老师","zh":"我也很喜欢音乐，也许比你更喜欢。你喜欢古典音乐还是喜欢现代音乐？","py":"Wǒ yě hěn xǐhuan yīnyuè, yěxǔ bǐ nǐ gèng xǐhuan. Nǐ xǐhuan gǔdiǎn yīnyuè háishi xǐhuan xiàndài yīnyuè?","vi":"Tôi cũng rất thích âm nhạc, có lẽ còn thích hơn thầy. Thầy thích nhạc cổ điển hay thích nhạc hiện đại?"},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"王老师","zh":"我喜欢古典音乐。喜欢听世界名曲，还喜欢听民歌。","py":"Wǒ xǐhuan gǔdiǎn yīnyuè. Xǐhuan tīng shìjiè míngqǔ, hái xǐhuan tīng míngē.","vi":"Tôi thích nhạc cổ điển. Thích nghe các bản nhạc nổi tiếng thế giới, còn thích nghe dân ca."},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"林老师","zh":"我也喜欢古典音乐。你喜欢流行歌曲吗？","py":"Wǒ yě xǐhuan gǔdiǎn yīnyuè. Nǐ xǐhuan liúxíng gēqǔ ma?","vi":"Tôi cũng thích nhạc cổ điển. Thầy có thích các bài hát thịnh hành không?"},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"王老师","zh":"怎么说呢？可能没有你们年轻人那么喜欢。我觉得流行歌曲的歌词没有民歌写得好。","py":"Zěnme shuō ne? Kěnéng méiyǒu nǐmen niánqīngrén nàme xǐhuan. Wǒ juéde liúxíng gēqǔ de gēcí méiyǒu míngē xiě de hǎo.","vi":"Nói thế nào nhỉ? Có lẽ không thích bằng những người trẻ như các cô. Tôi thấy lời các bài hát thịnh hành viết không hay bằng dân ca."},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"林老师","zh":"有些流行歌曲的歌词写得还是不错的。","py":"Yǒuxiē liúxíng gēqǔ de gēcí xiě de háishi búcuò de.","vi":"Lời của một số bài hát thịnh hành viết cũng khá hay đấy chứ."},{"section":"Bài khóa 2: 我比你更喜欢音乐","speaker":"王老师","zh":"可是，我还是觉得民歌的歌词好。你听咱们的民歌，“在那遥远的地方，……”，写得多好！","py":"Kěshì, wǒ háishi juéde míngē de gēcí hǎo. Nǐ tīng zánmen de míngē, “Zài nà yáoyuǎn de dìfang, ……”, xiě de duō hǎo!","vi":"Nhưng tôi vẫn thấy lời dân ca hay hơn. Cô nghe dân ca của chúng ta này: “Ở nơi xa xôi ấy, …”, viết hay biết bao!"}],"grammar":["Câu chữ 比 – A 比 B + tính từ: A so với B thì thế nào: 飞机比汽车快。西瓜比苹果大。大象比熊猫重。Trước tính từ không dùng các phó từ 很、真、非常…… (không nói 飞机比汽车很快。)","比 với động từ và bổ ngữ trạng thái: A 比 B + động từ + tân ngữ: 她比我喜欢音乐。Khi động từ mang bổ ngữ trạng thái, 比 đặt trước động từ hoặc trước bổ ngữ: 他比我考得好。= 他考得比我好。我今天比你来得早。= 我今天来得比你早。","Biểu đạt mức chênh lệch: chênh ít dùng 一点、一些; chênh nhiều dùng 多、很多、多了、得多 (得多 biểu thị chênh lệch rất lớn): 上海冬天是不是比北京暖和一点儿？这件比那件贵多了。她跑得比我快得多。Chênh lệch cụ thể dùng bổ ngữ số lượng A 比 B + tính từ + số lượng: 他比弟弟大两岁。罗兰比我跑得快五分钟。","Phủ định của câu chữ 比 – 没有 và 不比: A 比 B … (A > B) ⇒ B 没有 A … (B < A), không dùng 不比: 飞机比火车快。⇒ 火车没有飞机快。不比 dùng để phủ định hoặc phản bác lời đối phương: A：我看你比麦克高。B：我不比他高。我们俩差不多高。","A 有/没有 B (这么/那么) + tính từ: A bằng / không bằng B; 有 biểu thị đạt tới hoặc ước lượng. Khẳng định thường dùng trong câu hỏi, phủ định thường dùng trong câu trần thuật: 她有你（这么）高吗？——她没有我（这么）高。我没有你考得（那么）好。我们那儿冬天没有这儿（这么）冷。","更 và 最, câu cảm thán: 更 = càng, hơn nữa; 最 = nhất: 汽车比自行车快。飞机比汽车更快。飞机最快。Câu cảm thán: 太/真 + tính từ (太好了！这儿的风景真美！ – không dùng để miêu tả khách quan: không nói 他是一个真好的老师。mà nói 他是一个很好的老师。); 好/多 + tính từ + (啊): 这个公园好漂亮啊！他写得多好啊！"]},{"id":32,"hsk":3,"zh_title":"我们那儿的冬天跟北京一样冷","pinyin_title":"Wǒmen nàr de dōngtiān gēn Běijīng yíyàng lěng","title":"Mùa đông ở chỗ chúng tôi lạnh như ở Bắc Kinh","words":[{"id":"w_32_1","hsk":3,"lesson":32,"hanzi":"国家","pinyin":"guójiā","pos":"Danh từ","hanviet":"quốc gia","meaning":"quốc gia","example":"你暑假打算去哪个国家旅行？— Nghỉ hè bạn dự định đi nước nào du lịch?"},{"id":"w_32_2","hsk":3,"lesson":32,"hanzi":"国王","pinyin":"guówáng","pos":"Danh từ","hanviet":"quốc vương","meaning":"quốc vương, vua"},{"id":"w_32_3","hsk":3,"lesson":32,"hanzi":"一样","pinyin":"yíyàng","pos":"Tính từ","hanviet":"nhất dạng","meaning":"như nhau, giống nhau"},{"id":"w_32_4","hsk":3,"lesson":32,"hanzi":"时差","pinyin":"shíchā","pos":"Danh từ","hanviet":"thời sai","meaning":"sự chênh lệch thời gian","example":"中国和越南有一个小时的时差，中国比越南早一个小时。— Trung Quốc và Việt Nam lệch nhau 1 tiếng (có 1 tiếng chênh lệch múi giờ), Trung Quốc sớm hơn Việt Nam 1 tiếng."},{"id":"w_32_5","hsk":3,"lesson":32,"hanzi":"夜","pinyin":"yè","pos":"Danh từ","hanviet":"dạ","meaning":"đêm","example":"夜里气温比较低，感觉有点冷。— Nhiệt độ ban đêm khá là thấp, cảm giác hơi lạnh."},{"id":"w_32_6","hsk":3,"lesson":32,"hanzi":"季节","pinyin":"jìjié","pos":"Danh từ","hanviet":"quý tiết","meaning":"mùa, vụ, thời kỳ"},{"id":"w_32_7","hsk":3,"lesson":32,"hanzi":"春天","pinyin":"chūntiān","pos":"Danh từ","hanviet":"xuân thiên","meaning":"mùa xuân"},{"id":"w_32_8","hsk":3,"lesson":32,"hanzi":"夏天","pinyin":"xiàtiān","pos":"Danh từ","hanviet":"hạ thiên","meaning":"mùa hè","example":"越南夏天的时候，气温很高。所以，我不太喜欢夏天。— Việt Nam lúc vào mùa hè, nhiệt độ không khí rất cao. Nên tôi không thích mùa hè lắm."},{"id":"w_32_9","hsk":3,"lesson":32,"hanzi":"秋天","pinyin":"qiūtiān","pos":"Danh từ","hanviet":"thu thiên","meaning":"mùa thu","example":"一年有四季（四个季节）：春、夏、秋、冬。对我来说，我最喜欢春天。— Một năm có 4 mùa: Xuân, Hạ, Thu, Đông. Đối với tôi mà nói, tôi thích mùa xuân nhất."},{"id":"w_32_10","hsk":3,"lesson":32,"hanzi":"热","pinyin":"rè","pos":"Tính từ","hanviet":"nhiệt","meaning":"nóng","example":"在你们国家，夏天热不热？— Ở đất nước của các bạn, mùa hè nóng không?"},{"id":"w_32_11","hsk":3,"lesson":32,"hanzi":"冷","pinyin":"lěng","pos":"Tính từ","hanviet":"lãnh","meaning":"lạnh","example":"夏天的天气很热，冬天就很冷。— Thời tiết mùa hè rất nóng, mùa đông thì rất lạnh."},{"id":"w_32_12","hsk":3,"lesson":32,"hanzi":"刮风","pinyin":"guāfēng","pos":"Động từ ly hợp","hanviet":"quát phong","meaning":"gió thổi","example":"外面（刮）风刮得很大。— Bên ngoài gió thổi rất lớn."},{"id":"w_32_13","hsk":3,"lesson":32,"hanzi":"风","pinyin":"fēng","pos":"Danh từ","hanviet":"phong","meaning":"gió"},{"id":"w_32_14","hsk":3,"lesson":32,"hanzi":"雪","pinyin":"xuě","pos":"Danh từ","hanviet":"tuyết","meaning":"tuyết","example":"在我们这儿（这里）虽然不常下雪，但是天气很冷。— Chỗ của chúng tôi mặc dù không thường xuyên có tuyết, nhưng thời tiết rất lạnh."},{"id":"w_32_15","hsk":3,"lesson":32,"hanzi":"不但……而且……","pinyin":"búdàn… érqiě…","pos":"Liên từ","hanviet":"bất đán … nhi thả …","meaning":"không những … mà còn …","example":"这件衣服不但好看而且也很便宜。— Bộ quần áo này không những đẹp mà còn cũng rất rẻ."},{"id":"w_32_16","hsk":3,"lesson":32,"hanzi":"得","pinyin":"dé","pos":"Động từ","hanviet":"đắc","meaning":"đạt được (kết quả/thành tích); mắc (bệnh)","example":"我这次考得不太好，只得了70分。— Lần này tôi thi không tốt lắm, chỉ đạt được 70 điểm."},{"id":"w_32_17","hsk":3,"lesson":32,"hanzi":"分","pinyin":"fēn","pos":"Lượng từ","hanviet":"phân","meaning":"điểm (phút, xu)","example":"我这次考得不太好，只得了70分。— Lần này tôi thi không tốt lắm, chỉ đạt được 70 điểm."},{"id":"w_32_18","hsk":3,"lesson":32,"hanzi":"听写","pinyin":"tīngxiě","pos":"Động từ ghép","hanviet":"thính tả","meaning":"nghe viết, chính tả"},{"id":"w_32_19","hsk":3,"lesson":32,"hanzi":"周末","pinyin":"zhōumò","pos":"Danh từ","hanviet":"chu mạt","meaning":"cuối tuần","example":"你周末有什么打算？有时间我想请你去喝咖啡。— Cuối tuần bạn có dự định gì? Có thời gian tôi muốn mời bạn đi uống cà phê."},{"id":"w_32_20","hsk":3,"lesson":32,"hanzi":"出去","pinyin":"chūqu","pos":"Động từ + bổ ngữ xu hướng","hanviet":"xuất khứ","meaning":"đi ra"},{"id":"w_32_21","hsk":3,"lesson":32,"hanzi":"历史","pinyin":"lìshǐ","pos":"Danh từ","hanviet":"lịch sử","meaning":"lịch sử","example":"你对历史感兴趣吗？— Bạn có hứng thú với lịch sử không?"},{"id":"w_32_22","hsk":3,"lesson":32,"hanzi":"产生","pinyin":"chǎnshēng","pos":"Động từ","hanviet":"sản sinh","meaning":"sản sinh, nảy sinh, xuất hiện","example":"我对中国历史早已经产生了兴趣。— Tôi đã có hứng thú với lịch sử Trung Quốc từ sớm."},{"id":"w_32_23","hsk":3,"lesson":32,"hanzi":"画册","pinyin":"huàcè","pos":"Danh từ","hanviet":"họa sách","meaning":"tập tranh"},{"id":"w_32_24","hsk":3,"lesson":32,"hanzi":"研究","pinyin":"yánjiū","pos":"Động từ, Danh từ","hanviet":"nghiên cứu","meaning":"nghiên cứu","example":"他很喜欢中国，所以他花了很长时间去研究中国历史和文化。— Anh ấy rất thích Trung Quốc, nên đã dành thời gian rất dài đi nghiên cứu lịch sử và văn hóa Trung Quốc."},{"id":"w_32_25","hsk":3,"lesson":32,"hanzi":"只是","pinyin":"zhǐshì","pos":"Phó từ","hanviet":"chỉ thị","meaning":"chỉ là, có điều là","example":"我只是对历史感兴趣。— Chẳng qua tôi thích lịch sử."},{"id":"w_32_26","hsk":3,"lesson":32,"hanzi":"老","pinyin":"lǎo","pos":"Tính từ","hanviet":"lão","meaning":"già, cũ"},{"id":"w_32_27","hsk":3,"lesson":32,"hanzi":"改革","pinyin":"gǎigé","pos":"Động từ, Danh từ","hanviet":"cải cách","meaning":"cải cách, sửa đổi","example":"改革开放以后，越南经济发展得很快。— Sau khi cải cách mở cửa, kinh tế Việt Nam phát triển rất nhanh."},{"id":"w_32_28","hsk":3,"lesson":32,"hanzi":"开放","pinyin":"kāifàng","pos":"Động từ","hanviet":"khai phóng","meaning":"mở cửa, rộng mở","example":"改革开放以后，越南经济发展得很快。— Sau khi cải cách mở cửa, kinh tế Việt Nam phát triển rất nhanh."},{"id":"w_32_29","hsk":3,"lesson":32,"hanzi":"一切","pinyin":"yíqiè","pos":"Tính từ, Đại từ","hanviet":"nhất thiết","meaning":"tất cả","example":"我对中国改革开放以后的一切都很感兴趣。— Tôi rất có hứng thú đối với tất cả về Trung Quốc sau khi cải cách mở cửa."},{"id":"w_32_30","hsk":3,"lesson":32,"hanzi":"等","pinyin":"děng","pos":"Danh từ","hanviet":"đẳng","meaning":"đẳng cấp, cấp"},{"id":"w_32_31","hsk":3,"lesson":32,"hanzi":"上等","pinyin":"shàngděng","pos":"Tính từ","hanviet":"thượng đẳng","meaning":"thượng đẳng"},{"id":"w_32_32","hsk":3,"lesson":32,"hanzi":"中等","pinyin":"zhōngděng","pos":"Tính từ","hanviet":"trung đẳng","meaning":"trung đẳng"},{"id":"w_32_33","hsk":3,"lesson":32,"hanzi":"下等","pinyin":"xiàděng","pos":"Tính từ","hanviet":"hạ đẳng","meaning":"hạ đẳng"},{"id":"w_32_34","hsk":3,"lesson":32,"hanzi":"赛","pinyin":"sài","pos":"Động từ","hanviet":"tái","meaning":"thi đấu"},{"id":"w_32_35","hsk":3,"lesson":32,"hanzi":"马","pinyin":"mǎ","pos":"Danh từ","hanviet":"mã","meaning":"ngựa"}],"dialogue":[{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"罗兰，你们国家的时间跟北京不一样吧？","py":"Luólán, nǐmen guójiā de shíjiān gēn Běijīng bù yíyàng ba?","vi":"Roland, giờ ở nước bạn khác với Bắc Kinh nhỉ?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"当然不一样。我们那儿跟北京有七个小时的时差呢。","py":"Dāngrán bù yíyàng. Wǒmen nàr gēn Běijīng yǒu qī ge xiǎoshí de shíchā ne.","vi":"Đương nhiên là khác. Chỗ chúng tôi lệch với Bắc Kinh tới bảy tiếng đấy."},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"你们那儿早还是北京早？","py":"Nǐmen nàr zǎo háishi Běijīng zǎo?","vi":"Chỗ các bạn sớm hơn hay Bắc Kinh sớm hơn?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"北京比我们那儿早七个小时。现在北京是上午八点多，我们那儿才夜里一点多。","py":"Běijīng bǐ wǒmen nàr zǎo qī ge xiǎoshí. Xiànzài Běijīng shì shàngwǔ bā diǎn duō, wǒmen nàr cái yèli yī diǎn duō.","vi":"Bắc Kinh sớm hơn chỗ chúng tôi bảy tiếng. Bây giờ ở Bắc Kinh là hơn tám giờ sáng, chỗ chúng tôi mới hơn một giờ đêm."},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"季节跟北京一样吗？","py":"Jìjié gēn Běijīng yíyàng ma?","vi":"Các mùa có giống Bắc Kinh không?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"季节跟北京一样，也是春、夏、秋、冬四个季节。","py":"Jìjié gēn Běijīng yíyàng, yě shì chūn, xià, qiū, dōng sì ge jìjié.","vi":"Các mùa giống Bắc Kinh, cũng có bốn mùa xuân, hạ, thu, đông."},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"气候跟北京一样不一样？","py":"Qìhòu gēn Běijīng yíyàng bù yíyàng?","vi":"Khí hậu có giống Bắc Kinh không?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"不一样。北京的夏天很热，我们那儿夏天没有这么热。","py":"Bù yíyàng. Běijīng de xiàtiān hěn rè, wǒmen nàr xiàtiān méiyǒu zhème rè.","vi":"Không giống. Mùa hè Bắc Kinh rất nóng, mùa hè chỗ chúng tôi không nóng như thế này."},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"冬天冷不冷？","py":"Dōngtiān lěng bu lěng?","vi":"Mùa đông có lạnh không?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"冬天跟北京一样冷，但是不常刮大风。","py":"Dōngtiān gēn Běijīng yíyàng lěng, dànshì bù cháng guā dà fēng.","vi":"Mùa đông lạnh như Bắc Kinh, nhưng không hay có gió to."},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"常下雪吗？","py":"Cháng xià xuě ma?","vi":"Có hay có tuyết không?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"罗兰","zh":"不但常常下雪，而且下得很大。北京呢？","py":"Búdàn chángcháng xià xuě, érqiě xià de hěn dà. Běijīng ne?","vi":"Không những thường xuyên có tuyết mà tuyết còn rơi rất dày. Còn Bắc Kinh thì sao?"},{"section":"Bài khóa 1: 我们那儿的冬天跟北京一样冷","speaker":"田芳","zh":"北京冬天不常下雪。","py":"Běijīng dōngtiān bù cháng xià xuě.","vi":"Mùa đông ở Bắc Kinh không hay có tuyết."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"这次你考得怎么样？","py":"Zhè cì nǐ kǎo de zěnmeyàng?","vi":"Lần này bạn thi thế nào?"},{"section":"Bài khóa 2: 我跟你不一样","speaker":"玛丽","zh":"还可以，综合课考了95分，听力跟阅读一样，都是90分，口语考得不太好，只考了85分。你呢？","py":"Hái kěyǐ, zōnghé kè kǎole 95 fēn, tīnglì gēn yuèdú yíyàng, dōu shì 90 fēn, kǒuyǔ kǎo de bú tài hǎo, zhǐ kǎole 85 fēn. Nǐ ne?","vi":"Cũng được, môn tổng hợp được 95 điểm, nghe và đọc như nhau, đều 90 điểm, khẩu ngữ thi không tốt lắm, chỉ được 85 điểm. Còn bạn?"},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"你比我考得好。我的阅读跟你考得一样，综合课和听力课都没有你考得好，只得了80分。","py":"Nǐ bǐ wǒ kǎo de hǎo. Wǒ de yuèdú gēn nǐ kǎo de yíyàng, zōnghé kè hé tīnglì kè dōu méiyǒu nǐ kǎo de hǎo, zhǐ déle 80 fēn.","vi":"Bạn thi tốt hơn tôi. Môn đọc của tôi thi bằng bạn, môn tổng hợp và môn nghe đều không bằng bạn, chỉ được 80 điểm."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"玛丽","zh":"听写我没考好，有的汉字不会写。","py":"Tīngxiě wǒ méi kǎo hǎo, yǒude Hànzì bú huì xiě.","vi":"Phần nghe viết tôi thi không tốt, có những chữ Hán không biết viết."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"好了，不谈考试了。我问你，周末有什么打算？出去玩儿吗？","py":"Hǎo le, bù tán kǎoshì le. Wǒ wèn nǐ, zhōumò yǒu shénme dǎsuàn? Chūqu wánr ma?","vi":"Thôi được rồi, không nói chuyện thi cử nữa. Tôi hỏi bạn, cuối tuần có dự định gì không? Có ra ngoài chơi không?"},{"section":"Bài khóa 2: 我跟你不一样","speaker":"玛丽","zh":"出去。最近，我常到历史博物馆去参观。","py":"Chūqu. Zuìjìn, wǒ cháng dào lìshǐ bówùguǎn qù cānguān.","vi":"Có. Gần đây tôi hay đến bảo tàng lịch sử tham quan."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"是吗？你怎么对历史产生兴趣了？","py":"Shì ma? Nǐ zěnme duì lìshǐ chǎnshēng xìngqù le?","vi":"Thế à? Sao bạn lại có hứng thú với lịch sử vậy?"},{"section":"Bài khóa 2: 我跟你不一样","speaker":"玛丽","zh":"学了京剧以后，我就对中国历史产生了兴趣。有一天，我在书店买到了一本画册，是介绍中国历史的。看了以后，就想到历史博物馆去看看。","py":"Xuéle jīngjù yǐhòu, wǒ jiù duì Zhōngguó lìshǐ chǎnshēngle xìngqù. Yǒu yì tiān, wǒ zài shūdiàn mǎidàole yì běn huàcè, shì jièshào Zhōngguó lìshǐ de. Kànle yǐhòu, jiù xiǎng dào lìshǐ bówùguǎn qù kànkan.","vi":"Sau khi học Kinh kịch, tôi bắt đầu có hứng thú với lịch sử Trung Quốc. Có một hôm, tôi mua được một cuốn tập tranh ở hiệu sách, giới thiệu về lịch sử Trung Quốc. Xem xong, tôi liền muốn đến bảo tàng lịch sử xem thử."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"你打算研究中国历史吗？","py":"Nǐ dǎsuàn yánjiū Zhōngguó lìshǐ ma?","vi":"Bạn định nghiên cứu lịch sử Trung Quốc à?"},{"section":"Bài khóa 2: 我跟你不一样","speaker":"玛丽","zh":"不，我只是对中国历史感兴趣。","py":"Bù, wǒ zhǐshì duì Zhōngguó lìshǐ gǎn xìngqù.","vi":"Không, tôi chỉ là có hứng thú với lịch sử Trung Quốc thôi."},{"section":"Bài khóa 2: 我跟你不一样","speaker":"麦克","zh":"我跟你不一样，你喜欢老的，我喜欢新的。我对中国改革开放以后的一切都很感兴趣。","py":"Wǒ gēn nǐ bù yíyàng, nǐ xǐhuan lǎo de, wǒ xǐhuan xīn de. Wǒ duì Zhōngguó gǎigé kāifàng yǐhòu de yíqiè dōu hěn gǎn xìngqù.","vi":"Tôi khác bạn, bạn thích cái cũ, tôi thích cái mới. Tôi rất có hứng thú với tất cả những gì của Trung Quốc sau cải cách mở cửa."}],"grammar":["So sánh ngang bằng A 跟 B 一样 (+ thành phần khác): A giống B: 这件毛衣跟那件价钱一样。小王跟小张一样大。她跟我一样喜欢听音乐。","Phủ định A 跟 B 不一样 (+ thành phần khác): A không giống B: 这件毛衣跟那件价钱不一样。这双皮鞋跟那双不一样大。姐姐跟弟弟的爱好不一样。(= 姐姐的爱好跟弟弟不一样。) 跟……不一样 cũng có thể nói 不跟……一样: 我跟你不一样高。= 我不跟你一样高。","跟……一样/不一样 làm định ngữ: 他有一辆跟你这辆颜色一样的车。我买了一本跟你那本一样的词典。","Câu phức 不但……而且……: liên kết hai phân câu, biểu đạt ý tăng tiến. Hai phân câu cùng chủ ngữ thì 不但 đặt sau chủ ngữ của phân câu thứ nhất: 他不但会说英语，而且还会法语。她不但喜欢唱歌，而且唱得不错。Chủ ngữ khác nhau thì 不但 đặt trước chủ ngữ của phân câu thứ nhất: 不但她会说汉语，而且她妹妹也会说汉语。","好了 trong hội thoại: dùng để khuyên hoặc nhắc đối phương rằng mình muốn dừng cuộc nói chuyện (hay một hành động nào đó); phía sau thường có phân câu tương ứng: 好了，不谈这个了。我问你……好了，今天先讲到这儿吧。好了，我们该走了。"]},{"id":33,"hsk":3,"zh_title":"冬天快要到了","pinyin_title":"Dōngtiān kuàiyào dào le","title":"Mùa đông sắp đến rồi","words":[{"id":"w_33_1","hsk":3,"lesson":33,"hanzi":"爱","pinyin":"ài","pos":"Động từ","hanviet":"ái","meaning":"yêu, thích","example":"我爱看书。— Tôi thích đọc sách."},{"id":"w_33_2","hsk":3,"lesson":33,"hanzi":"哎呀","pinyin":"āiyā","pos":"Thán từ","hanviet":"ai a","meaning":"ái, ối, ái chà"},{"id":"w_33_3","hsk":3,"lesson":33,"hanzi":"滑","pinyin":"huá","pos":"Động từ, Tính từ","hanviet":"hoạt","meaning":"trượt, trơn trượt","example":"这儿（这里）很滑，你要小心（一）点儿。— Chỗ này rất trơn, bạn cần cẩn thận chút."},{"id":"w_33_4","hsk":3,"lesson":33,"hanzi":"滑冰","pinyin":"huábīng","pos":"Động từ ly hợp","hanviet":"hoạt băng","meaning":"trượt băng","example":"他滑冰滑得很厉害。— Anh ấy trượt băng rất đỉnh."},{"id":"w_33_5","hsk":3,"lesson":33,"hanzi":"滑雪","pinyin":"huáxuě","pos":"Động từ ly hợp","hanviet":"hoạt tuyết","meaning":"trượt tuyết","example":"我比他更喜欢滑雪。— Tôi thích trượt tuyết hơn anh ấy."},{"id":"w_33_6","hsk":3,"lesson":33,"hanzi":"家乡","pinyin":"jiāxiāng","pos":"Danh từ","hanviet":"gia hương","meaning":"quê hương","example":"你的家乡在哪儿？— Quê hương của bạn ở đâu?"},{"id":"w_33_7","hsk":3,"lesson":33,"hanzi":"有名","pinyin":"yǒumíng","pos":"Tính từ","hanviet":"hữu danh","meaning":"nổi tiếng","example":"这首中文歌曲在越南非常有名。— Bài hát tiếng Trung này ở Việt Nam rất nổi tiếng."},{"id":"w_33_8","hsk":3,"lesson":33,"hanzi":"风景","pinyin":"fēngjǐng","pos":"Danh từ","hanviet":"phong cảnh","meaning":"phong cảnh","example":"我家乡有很多很迷人的风景。— Quê tôi có rất nhiều phong cảnh rất mê người."},{"id":"w_33_9","hsk":3,"lesson":33,"hanzi":"区","pinyin":"qū","pos":"Danh từ","hanviet":"khu","meaning":"khu vực, vùng, nơi"},{"id":"w_33_10","hsk":3,"lesson":33,"hanzi":"旅游","pinyin":"lǚyóu","pos":"Danh từ, Động từ","hanviet":"lữ du","meaning":"du lịch","example":"我很喜欢去旅游，每年都去国外旅行。— Tôi rất thích đi du lịch, hằng năm đều đi nước ngoài du lịch."},{"id":"w_33_11","hsk":3,"lesson":33,"hanzi":"尤其","pinyin":"yóuqí","pos":"Phó từ","hanviet":"vưu kỳ","meaning":"đặc biệt là, nhất là","example":"我很喜欢去旅游，尤其是去西方国家旅游。— Tôi rất thích đi du lịch, đặc biệt là đi du lịch các nước phương Tây."},{"id":"w_33_12","hsk":3,"lesson":33,"hanzi":"凉快","pinyin":"liángkuai","pos":"Tính từ","hanviet":"lương khoái","meaning":"mát mẻ","example":"越南天气很舒服，尤其是秋天，这个时候的天气特别凉快。— Thời tiết Việt Nam rất dễ chịu, đặc biệt là mùa thu, thời tiết lúc này đặc biệt mát mẻ."},{"id":"w_33_13","hsk":3,"lesson":33,"hanzi":"避暑","pinyin":"bì shǔ","pos":"Động từ ly hợp","hanviet":"tị thử","meaning":"nghỉ mát, tránh nắng","example":"北京夏天太热了，我们找个地方去旅游吧，就是想去避一下暑。— Mùa hè Bắc Kinh nóng quá, chúng ta tìm 1 chỗ đi du lịch đi, chính là muốn đi tránh nóng 1 chút."},{"id":"w_33_14","hsk":3,"lesson":33,"hanzi":"人家","pinyin":"rénjiā","pos":"Danh từ","hanviet":"nhân gia","meaning":"người ta, hộ gia đình","example":"人家都不怕，你怕什么？— Người ta không sợ, bạn sợ cái gì?"},{"id":"w_33_15","hsk":3,"lesson":33,"hanzi":"靠","pinyin":"kào","pos":"Động từ","hanviet":"kháo","meaning":"tựa vào, dựa, trông vào","example":"靠人不如靠自己。— Dựa vào người khác không bằng dựa vào chính bản thân."},{"id":"w_33_16","hsk":3,"lesson":33,"hanzi":"经营","pinyin":"jīngyíng","pos":"Động từ","hanviet":"kinh doanh","meaning":"kinh doanh, vận hành","example":"我爸爸经营一家饭店。— Bố tôi kinh doanh một nhà hàng."},{"id":"w_33_17","hsk":3,"lesson":33,"hanzi":"发财","pinyin":"fā cái","pos":"Động từ ly hợp","hanviet":"phát tài","meaning":"phát tài","example":"恭喜发财！— Cung hỷ phát tài!"},{"id":"w_33_18","hsk":3,"lesson":33,"hanzi":"树叶","pinyin":"shùyè","pos":"Danh từ","hanviet":"thụ diệp","meaning":"lá cây","example":"这里的树叶还没落下。— Lá cây ở đây vẫn chưa rụng xuống."},{"id":"w_33_19","hsk":3,"lesson":33,"hanzi":"树","pinyin":"shù","pos":"Danh từ","hanviet":"thụ","meaning":"cây"},{"id":"w_33_20","hsk":3,"lesson":33,"hanzi":"叶","pinyin":"yè","pos":"Danh từ","hanviet":"diệp","meaning":"lá"},{"id":"w_33_21","hsk":3,"lesson":33,"hanzi":"红叶","pinyin":"hóngyè","pos":"Danh từ","hanviet":"hồng diệp","meaning":"lá đỏ","example":"红叶落下让这里的风景特别迷人。— Lá đỏ rụng xuống khiến phong cảnh ở đây đặc biệt mê hoặc lòng người."},{"id":"w_33_22","hsk":3,"lesson":33,"hanzi":"落","pinyin":"luò","pos":"Động từ","hanviet":"lạc","meaning":"rơi","example":"这里的树叶还没落下。— Lá cây ở đây vẫn chưa rụng xuống."},{"id":"w_33_23","hsk":3,"lesson":33,"hanzi":"捡","pinyin":"jiǎn","pos":"Động từ","hanviet":"kiểm","meaning":"nhặt, lượm","example":"我捡一些树上刚落下的红叶，打算送给我朋友。— Tôi nhặt một vài lá đỏ vừa rụng từ trên cây, định tặng cho bạn tôi."},{"id":"w_33_24","hsk":3,"lesson":33,"hanzi":"着急","pinyin":"zháojí","pos":"Tính từ","hanviet":"trước cấp","meaning":"lo lắng","example":"不要（不用）着急，慢慢来！我们还有很多时间。— Đừng lo lắng, cứ từ từ! Chúng ta vẫn còn rất nhiều thời gian."},{"id":"w_33_25","hsk":3,"lesson":33,"hanzi":"着呢","pinyin":"zhene","pos":"Trợ từ","hanviet":"trước ni","meaning":"rất, lắm"},{"id":"w_33_26","hsk":3,"lesson":33,"hanzi":"表","pinyin":"biǎo","pos":"Danh từ","hanviet":"biểu","meaning":"đồng hồ"},{"id":"w_33_27","hsk":3,"lesson":33,"hanzi":"坏","pinyin":"huài","pos":"Tính từ, Động từ","hanviet":"hoại","meaning":"hỏng, xấu xa, tồi","example":"我的手表坏了！— Đồng hồ của tôi hỏng rồi!"},{"id":"w_33_28","hsk":3,"lesson":33,"hanzi":"好事","pinyin":"hǎoshì","pos":"Danh từ","hanviet":"hảo sự","meaning":"việc tốt","example":"我有一件坏事和一件好事。你想先听哪件？— Tôi có 1 chuyện xấu và 1 chuyện tốt. Bạn muốn nghe chuyện nào trước?"},{"id":"w_33_29","hsk":3,"lesson":33,"hanzi":"坏事","pinyin":"huàishì","pos":"Danh từ","hanviet":"hoại sự","meaning":"việc xấu","example":"我有一件坏事和一件好事。你想先听哪件？— Tôi có 1 chuyện xấu và 1 chuyện tốt. Bạn muốn nghe chuyện nào trước?"},{"id":"w_33_30","hsk":3,"lesson":33,"hanzi":"停","pinyin":"tíng","pos":"Động từ","hanviet":"đình","meaning":"ngừng, dừng lại","example":"雨停了，快回吧！— Mưa tạnh rồi, về nhanh thôi!"},{"id":"w_33_31","hsk":3,"lesson":33,"hanzi":"该","pinyin":"gāi","pos":"Động từ năng nguyện","hanviet":"cai","meaning":"nên, cần phải","example":"该说的话要说出来，不该说的就不要说。— Lời nên nói thì phải nói ra, lời không nên nói thì đừng nói."},{"id":"w_33_32","hsk":3,"lesson":33,"hanzi":"电池","pinyin":"diànchí","pos":"Danh từ","hanviet":"điện trì","meaning":"pin","example":"你的手机电池坏了吗？是不是该换新的了？— Pin điện thoại của bạn hỏng rồi à? Có phải là nên thay cái mới rồi không?"},{"id":"w_33_33","hsk":3,"lesson":33,"hanzi":"迟到","pinyin":"chídào","pos":"Động từ","hanviet":"trì đáo","meaning":"đến muộn, trễ","example":"明天要开会，不要迟到！— Ngày mai phải họp, đừng đến muộn!"},{"id":"w_33_34","hsk":3,"lesson":33,"hanzi":"啦","pinyin":"la","pos":"Trợ từ","hanviet":"lạp","meaning":"trợ từ ngữ khí đặt cuối câu"},{"id":"w_33_35","hsk":3,"lesson":33,"hanzi":"母亲","pinyin":"mǔqin","pos":"Danh từ","hanviet":"mẫu thân","meaning":"mẹ"},{"id":"w_33_36","hsk":3,"lesson":33,"hanzi":"父亲","pinyin":"fùqin","pos":"Danh từ","hanviet":"phụ thân","meaning":"bố"},{"id":"w_33_37","hsk":3,"lesson":33,"hanzi":"地","pinyin":"de","pos":"Trợ từ","hanviet":"địa","meaning":"trợ từ kết cấu nối trạng ngữ và động từ"},{"id":"w_33_38","hsk":3,"lesson":33,"hanzi":"结婚","pinyin":"jié hūn","pos":"Động từ ly hợp","hanviet":"kết hôn","meaning":"kết hôn","example":"她还没结婚。— Cô ấy vẫn chưa kết hôn."},{"id":"w_33_39","hsk":3,"lesson":33,"hanzi":"离婚","pinyin":"lí hūn","pos":"Động từ ly hợp","hanviet":"li hôn","meaning":"li hôn"},{"id":"w_33_40","hsk":3,"lesson":33,"hanzi":"未婚夫","pinyin":"wèihūnfū","pos":"Danh từ","hanviet":"vị hôn phu","meaning":"chồng chưa cưới"},{"id":"w_33_41","hsk":3,"lesson":33,"hanzi":"未婚妻","pinyin":"wèihūnqī","pos":"Danh từ","hanviet":"vị hôn thê","meaning":"vợ chưa cưới"},{"id":"w_33_42","hsk":3,"lesson":33,"hanzi":"将来","pinyin":"jiānglái","pos":"Danh từ","hanviet":"tương lai","meaning":"tương lai","example":"将来你想成为怎么样的人？— Tương lai bạn muốn trở thành người như thế nào?"},{"id":"w_33_43","hsk":3,"lesson":33,"hanzi":"这样","pinyin":"zhèyàng","pos":"Đại từ","hanviet":"giá dạng","meaning":"như thế này","example":"这样也好！— Như thế này cũng tốt."},{"id":"w_33_44","hsk":3,"lesson":33,"hanzi":"那样","pinyin":"nàyàng","pos":"Đại từ","hanviet":"ná dạng","meaning":"như thế kia","example":"我不太喜欢那样的人。— Tôi không thích người như thế kia."}],"dialogue":[{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"Kể","zh":"去教室的路上……","py":"Qù jiàoshì de lù shang……","vi":"Trên đường đến lớp học…"},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"啊，刮风了。今天天气真冷。","py":"À, guā fēng le. Jīntiān tiānqì zhēn lěng.","vi":"Ôi, nổi gió rồi. Hôm nay trời lạnh thật."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"冬天快要到了。","py":"Dōngtiān kuàiyào dào le.","vi":"Mùa đông sắp đến rồi."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"我不喜欢冬天。","py":"Wǒ bù xǐhuan dōngtiān.","vi":"Tôi không thích mùa đông."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"我喜欢冬天。我爱滑冰，也爱滑雪。我们家乡有山有水，是有名的风景区。夏天可以游泳，冬天可以滑雪，一年四季都有去旅游的人，尤其是夏天，山里很凉快，去避暑的人特别多。很多人家都靠经营旅馆、饭店发了财。","py":"Wǒ xǐhuan dōngtiān. Wǒ ài huábīng, yě ài huáxuě. Wǒmen jiāxiāng yǒu shān yǒu shuǐ, shì yǒumíng de fēngjǐngqū. Xiàtiān kěyǐ yóuyǒng, dōngtiān kěyǐ huáxuě, yì nián sìjì dōu yǒu qù lǚyóu de rén, yóuqí shì xiàtiān, shān li hěn liángkuai, qù bìshǔ de rén tèbié duō. Hěn duō rénjiā dōu kào jīngyíng lǚguǎn, fàndiàn fāle cái.","vi":"Tôi thích mùa đông. Tôi thích trượt băng, cũng thích trượt tuyết. Quê tôi có núi có sông, là khu danh lam thắng cảnh nổi tiếng. Mùa hè có thể bơi, mùa đông có thể trượt tuyết, quanh năm bốn mùa đều có người đến du lịch, nhất là mùa hè, trong núi rất mát mẻ, người đến nghỉ mát đặc biệt đông. Nhiều gia đình nhờ kinh doanh nhà nghỉ, nhà hàng mà phát tài."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"我只会滑冰，不会滑雪。我真想到你们家乡去学学滑雪。你看，树叶都红了。红叶多漂亮。等一下，我去捡几片红叶。","py":"Wǒ zhǐ huì huábīng, bú huì huáxuě. Wǒ zhēn xiǎng dào nǐmen jiāxiāng qù xuéxue huáxuě. Nǐ kàn, shùyè dōu hóng le. Hóngyè duō piàoliang. Děng yíxià, wǒ qù jiǎn jǐ piàn hóngyè.","vi":"Tôi chỉ biết trượt băng, không biết trượt tuyết. Tôi thật muốn đến quê các bạn học trượt tuyết. Bạn xem, lá cây đều đỏ cả rồi. Lá đỏ đẹp biết bao. Đợi một chút, tôi đi nhặt mấy chiếc lá đỏ."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"别捡了，快走吧，要上课了。","py":"Bié jiǎn le, kuài zǒu ba, yào shàngkè le.","vi":"Đừng nhặt nữa, đi nhanh lên, sắp vào học rồi."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"着什么急，还早着呢。","py":"Zháo shénme jí, hái zǎo zhene.","vi":"Vội gì chứ, vẫn còn sớm lắm."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"你看看表，几点了？","py":"Nǐ kànkan biǎo, jǐ diǎn le?","vi":"Bạn xem đồng hồ đi, mấy giờ rồi?"},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"刚七点半。","py":"Gāng qī diǎn bàn.","vi":"Mới bảy giờ rưỡi."},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"什么？你的表是不是坏了？","py":"Shénme? Nǐ de biǎo shì bu shì huài le?","vi":"Cái gì? Đồng hồ của bạn có phải hỏng rồi không?"},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"田芳","zh":"哎呀，我的表停了，可能没电了，该换电池了。什么时间了？","py":"Āiyā, wǒ de biǎo tíng le, kěnéng méi diàn le, gāi huàn diànchí le. Shénme shíjiān le?","vi":"Ối, đồng hồ của tôi chết rồi, có lẽ hết pin, phải thay pin thôi. Mấy giờ rồi?"},{"section":"Bài khóa 1: 快走吧，要上课了","speaker":"张东","zh":"都七点五十了。快走吧，再不快点儿就迟到了。","py":"Dōu qī diǎn wǔshí le. Kuài zǒu ba, zài bú kuài diǎnr jiù chídào le.","vi":"Đã bảy giờ năm mươi rồi. Đi nhanh lên, không nhanh hơn nữa là muộn đấy."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"Kể","zh":"山本高兴地在网上读信。","py":"Shānběn gāoxìng de zài wǎngshang dú xìn.","vi":"Yamamoto vui vẻ đọc thư trên mạng."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"玛丽","zh":"山本，有什么好事啦？这么高兴。","py":"Shānběn, yǒu shénme hǎoshì la? Zhème gāoxìng.","vi":"Yamamoto, có chuyện gì vui thế? Trông bạn vui vậy."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"山本","zh":"我母亲来信了。她在信上高兴地说，我姐姐下个月就要结婚了。","py":"Wǒ mǔqin lái xìn le. Tā zài xìn shang gāoxìng de shuō, wǒ jiějie xià ge yuè jiù yào jiéhūn le.","vi":"Mẹ tôi gửi thư đến. Trong thư mẹ vui mừng nói chị gái tôi tháng sau sẽ kết hôn."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"玛丽","zh":"上次你说你姐姐刚找到工作，怎么这么快就要结婚了？","py":"Shàng cì nǐ shuō nǐ jiějie gāng zhǎodào gōngzuò, zěnme zhème kuài jiù yào jiéhūn le?","vi":"Lần trước bạn nói chị bạn vừa tìm được việc, sao nhanh thế đã sắp kết hôn rồi?"},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"山本","zh":"她未婚夫不愿意让她工作了。","py":"Tā wèihūnfū bú yuànyì ràng tā gōngzuò le.","vi":"Chồng chưa cưới của chị ấy không muốn để chị ấy đi làm nữa."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"玛丽","zh":"这么说，结婚以后她就不工作了？","py":"Zhème shuō, jiéhūn yǐhòu tā jiù bù gōngzuò le?","vi":"Nói vậy thì sau khi kết hôn chị ấy sẽ không đi làm nữa à?"},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"山本","zh":"对。","py":"Duì.","vi":"Đúng vậy."},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"玛丽","zh":"将来你也会这样吗？结了婚就不工作了吗？","py":"Jiānglái nǐ yě huì zhèyàng ma? Jiéle hūn jiù bù gōngzuò le ma?","vi":"Sau này bạn cũng sẽ như vậy à? Kết hôn rồi là không đi làm nữa sao?"},{"section":"Bài khóa 2: 我姐姐下个月就要结婚了","speaker":"山本","zh":"不。我喜欢工作。要是不让我工作，我就不结婚。","py":"Bù. Wǒ xǐhuan gōngzuò. Yàoshi bú ràng wǒ gōngzuò, wǒ jiù bù jiéhūn.","vi":"Không. Tôi thích làm việc. Nếu không cho tôi làm việc thì tôi sẽ không kết hôn."}],"grammar":["Trợ từ ngữ khí 了 biểu thị sự thay đổi: đặt cuối câu cho biết tình hình đã thay đổi: 树叶已经黄了。(秋天到了。) 他已经参加工作了。(以前上大学，没工作。) 这件衣服小了。不……了 cũng biểu thị sự thay đổi: 结婚后，她不工作了。我不回国了。我今天不发烧了。","Động tác sắp xảy ra 要……了 / 就要……了 / 快要……了 / 快……了: 要上课了。再有两个月就要放寒假了。快要下雪了。Chú ý: nếu trong câu có từ chỉ thời gian cụ thể làm trạng ngữ thì không dùng 快要（快）……了: không nói *下个月姐姐快要结婚了，mà nói 下个月姐姐就要结婚了。","Trạng ngữ và trợ từ kết cấu 地: tính từ + 地 + động từ – làm gì một cách như thế nào: 她高兴地告诉我，姐姐下个月就要结婚了。同学们都在努力地学习。","Câu không có chủ ngữ: dùng để nói về hiện tượng tự nhiên như thời tiết: 刮风了。下雨了。没下雪。; và để chúc tụng, cầu phúc: 祝你生日快乐！祝你新年快乐！","Tính từ/động từ tâm lý + 着呢: = 很, nhấn mạnh mức độ: 时间还早着呢。(= 时间还很早。) 今天外边冷着呢。A：你的肚子疼吗？B：疼着呢。","都 + từ chỉ thời gian/số lượng + 了: biểu thị thời gian đã muộn, tuổi đã lớn, số lượng nhiều; 都 ≈ 已经, có tác dụng nhấn mạnh: 都七点五十五了，快走吧。都二十岁了，自己的事情应该自己做了。"]},{"id":34,"hsk":3,"zh_title":"快上来吧，要开车了","pinyin_title":"Kuài shànglai ba, yào kāi chē le","title":"Nhanh lên, xe sắp chạy rồi","words":[{"id":"w_34_1","hsk":3,"lesson":34,"hanzi":"送","pinyin":"sòng","pos":"Động từ","hanviet":"tống","meaning":"tặng, đưa, tiễn","example":"我过生日的时候，爸爸妈妈送给我很多礼物。— Lúc tôi đón sinh nhật, bố mẹ tặng tôi rất nhiều quà."},{"id":"w_34_2","hsk":3,"lesson":34,"hanzi":"开会","pinyin":"kāi huì","pos":"Động từ ly hợp","hanviet":"khai hội","meaning":"họp"},{"id":"w_34_3","hsk":3,"lesson":34,"hanzi":"教学","pinyin":"jiàoxué","pos":"Danh từ","hanviet":"giáo học","meaning":"giảng dạy"},{"id":"w_34_4","hsk":3,"lesson":34,"hanzi":"研讨","pinyin":"yántǎo","pos":"Động từ","hanviet":"nghiên thảo","meaning":"nghiên cứu"},{"id":"w_34_5","hsk":3,"lesson":34,"hanzi":"研讨会","pinyin":"yántǎohuì","pos":"Danh từ","hanviet":"nghiên thảo hội","meaning":"hội thảo","example":"下个月我学校打算开一个教学研讨会，会请很多教授参加。— Tháng sau trường tôi dự định tổ chức 1 buổi hội thảo về việc dạy học, sẽ mời rất nhiều giáo sư tham dự."},{"id":"w_34_6","hsk":3,"lesson":34,"hanzi":"经过","pinyin":"jīngguò","pos":"Động từ","hanviet":"kinh quá","meaning":"trải qua, đi qua","example":"你飞回越南的时候，有没有经过北京？— Khi bạn bay về Việt Nam, có đi qua Bắc Kinh không?"},{"id":"w_34_7","hsk":3,"lesson":34,"hanzi":"向","pinyin":"xiàng","pos":"Giới từ","hanviet":"hướng","meaning":"hướng","example":"你一直向（往）前走就到。— Bạn cứ đi về phía trước sẽ tới."},{"id":"w_34_8","hsk":3,"lesson":34,"hanzi":"问好","pinyin":"wènhǎo","pos":"Động từ","hanviet":"vấn hảo","meaning":"hỏi thăm","example":"请替我向你父母问好。— Hãy thay tôi hỏi thăm sức khỏe bố mẹ bạn."},{"id":"w_34_9","hsk":3,"lesson":34,"hanzi":"捎","pinyin":"shāo","pos":"Động từ","hanviet":"sảo","meaning":"cầm hộ, mang hộ","example":"他让我向您问好，还让我给您捎来一些东西。— Anh ấy bảo tôi hỏi thăm ngài, còn nhờ tôi mang cho ngài 1 ít đồ."},{"id":"w_34_10","hsk":3,"lesson":34,"hanzi":"过去","pinyin":"guòqu","pos":"Động từ + bổ ngữ xu hướng","hanviet":"quá khứ","meaning":"đi qua, sang"},{"id":"w_34_11","hsk":3,"lesson":34,"hanzi":"过来","pinyin":"guòlai","pos":"Động từ + bổ ngữ xu hướng","hanviet":"quá lai","meaning":"đi đến, sang, qua"},{"id":"w_34_12","hsk":3,"lesson":34,"hanzi":"门口","pinyin":"ménkǒu","pos":"Danh từ","hanviet":"môn khẩu","meaning":"cổng","example":"明天我在学校门口等你。— Ngày mai tôi đợi bạn ở cổng trường."},{"id":"w_34_13","hsk":3,"lesson":34,"hanzi":"辛苦","pinyin":"xīnkǔ","pos":"Tính từ","hanviet":"tân khổ","meaning":"vất vả, cực nhọc","example":"他们的工作很辛苦。— Công việc của họ rất vất vả."},{"id":"w_34_14","hsk":3,"lesson":34,"hanzi":"麻烦","pinyin":"máfan","pos":"Động từ, Tính từ","hanviet":"ma phiền","meaning":"làm phiền, phiền toái","example":"可以麻烦你帮我一件事吗？— Có thể làm phiền bạn giúp tôi 1 việc được không?"},{"id":"w_34_15","hsk":3,"lesson":34,"hanzi":"趟","pinyin":"tàng","pos":"Lượng từ","hanviet":"thang","meaning":"lượt, đợt, chuyến","example":"真辛苦你了！还麻烦你跑一趟。— Thật là làm phiền bạn quá! Lại còn phiền bạn chạy 1 chuyến."},{"id":"w_34_16","hsk":3,"lesson":34,"hanzi":"爱人","pinyin":"àirén","pos":"Danh từ","hanviet":"ái nhân","meaning":"vợ, chồng, người yêu"},{"id":"w_34_17","hsk":3,"lesson":34,"hanzi":"办事","pinyin":"bànshì","pos":"Động từ ly hợp","hanviet":"biện sự","meaning":"làm việc","example":"麻烦你帮我办一件急事。— Làm phiền bạn giúp tôi xử lý (làm) 1 việc gấp."},{"id":"w_34_18","hsk":3,"lesson":34,"hanzi":"马上","pinyin":"mǎshàng","pos":"Phó từ","hanviet":"mã thượng","meaning":"lập tức","example":"麻烦你等一下，我马上过去。— Làm phiền bạn chờ chút, tôi qua ngay đây."},{"id":"w_34_19","hsk":3,"lesson":34,"hanzi":"慢","pinyin":"màn","pos":"Tính từ","hanviet":"mạn","meaning":"chậm","example":"慢慢来！不用这么着急。— Cứ từ từ! Không cần vội vàng như thế."},{"id":"w_34_20","hsk":3,"lesson":34,"hanzi":"展览馆","pinyin":"zhǎnlǎnguǎn","pos":"Danh từ","hanviet":"triển lãm quán","meaning":"phòng triển lãm"},{"id":"w_34_21","hsk":3,"lesson":34,"hanzi":"展览","pinyin":"zhǎnlǎn","pos":"Danh từ, Động từ","hanviet":"triển lãm","meaning":"triển lãm","example":"他们展览一些新产品。— Họ trưng bày một vài sản phẩm mới."},{"id":"w_34_22","hsk":3,"lesson":34,"hanzi":"上来","pinyin":"shànglai","pos":"Động từ + bổ ngữ xu hướng","hanviet":"thượng lai","meaning":"lên"},{"id":"w_34_23","hsk":3,"lesson":34,"hanzi":"开车","pinyin":"kāi chē","pos":"Động từ ly hợp","hanviet":"khai xa","meaning":"lái xe","example":"我爸爸开车到学校接我。— Bố tôi lái xe đến trường đón tôi."},{"id":"w_34_24","hsk":3,"lesson":34,"hanzi":"照相机","pinyin":"zhàoxiàngjī","pos":"Danh từ","hanviet":"chiếu tương cơ","meaning":"máy chụp ảnh","example":"这个旅游区的风景太美了，麻烦你用照相机（相机）帮我照几张相可以吗？— Phong cảnh ở khu du lịch này đẹp quá, nhờ bạn dùng máy ảnh chụp giúp tôi vài bức được không?"},{"id":"w_34_25","hsk":3,"lesson":34,"hanzi":"照相","pinyin":"zhàoxiàng","pos":"Động từ ly hợp","hanviet":"chiếu tương","meaning":"chụp ảnh","example":"这个旅游区的风景太美了，麻烦你用照相机（相机）帮我照几张相可以吗？— Phong cảnh ở khu du lịch này đẹp quá, nhờ bạn dùng máy ảnh chụp giúp tôi vài bức được không?"},{"id":"w_34_26","hsk":3,"lesson":34,"hanzi":"座位","pinyin":"zuòwèi","pos":"Danh từ","hanviet":"tọa vị","meaning":"chỗ ngồi","example":"那个座位有人坐了。— Chỗ đó có người ngồi rồi."},{"id":"w_34_27","hsk":3,"lesson":34,"hanzi":"注意","pinyin":"zhùyì","pos":"Động từ","hanviet":"chú ý","meaning":"chú ý","example":"下次要注意一点吧。— Lần sau phải chú ý hơn nhé."},{"id":"w_34_28","hsk":3,"lesson":34,"hanzi":"出土","pinyin":"chū tǔ","pos":"Động từ","hanviet":"xuất thổ","meaning":"khai quật, đào lên","example":"去年他们出土了很多文物。— Năm ngoái họ đã khai quật được rất nhiều hiện vật văn hóa."},{"id":"w_34_29","hsk":3,"lesson":34,"hanzi":"文物","pinyin":"wénwù","pos":"Danh từ","hanviet":"văn vật","meaning":"văn vật, hiện vật","example":"去年他们出土了很多文物。— Năm ngoái họ đã khai quật được rất nhiều hiện vật văn hóa."},{"id":"w_34_30","hsk":3,"lesson":34,"hanzi":"大约","pinyin":"dàyuē","pos":"Phó từ","hanviet":"đại ước","meaning":"khoảng","example":"从这里到展览馆大约要半个小时。— Từ đây đến nhà triển lãm mất khoảng nửa tiếng."},{"id":"w_34_31","hsk":3,"lesson":34,"hanzi":"要求","pinyin":"yāoqiú","pos":"Danh từ, Động từ","hanviet":"yêu cầu","meaning":"yêu cầu","example":"老师对我们的要求很高。— Yêu cầu của thầy giáo đối với chúng tôi rất cao."},{"id":"w_34_32","hsk":3,"lesson":34,"hanzi":"声","pinyin":"shēng","pos":"Lượng từ, Danh từ","hanviet":"thanh","meaning":"tiếng","example":"你小声一点吧！— Bạn nhỏ tiếng 1 chút đi!"},{"id":"w_34_33","hsk":3,"lesson":34,"hanzi":"清楚","pinyin":"qīngchu","pos":"Tính từ","hanviet":"thanh sở","meaning":"rõ ràng, thông suốt","example":"我刚刚听得不太清楚，你可以再说一遍吗？— Vừa nãy tôi nghe không rõ lắm, bạn nói lại 1 lần nữa được không?"},{"id":"w_34_34","hsk":3,"lesson":34,"hanzi":"师傅","pinyin":"shīfu","pos":"Danh từ","hanviet":"sư phụ","meaning":"sư phụ; bác tài, thợ"},{"id":"w_34_35","hsk":3,"lesson":34,"hanzi":"大使馆","pinyin":"dàshǐguǎn","pos":"Danh từ","hanviet":"đại sứ quán","meaning":"đại sứ quán"},{"id":"w_34_36","hsk":3,"lesson":34,"hanzi":"大使","pinyin":"dàshǐ","pos":"Danh từ","hanviet":"đại sứ","meaning":"đại sứ"},{"id":"w_34_37","hsk":3,"lesson":34,"hanzi":"台湾","pinyin":"Táiwān","pos":"Danh từ","hanviet":"Đài Loan","meaning":"Đài Loan"},{"id":"w_34_38","hsk":3,"lesson":34,"hanzi":"香港","pinyin":"Xiānggǎng","pos":"Danh từ","hanviet":"Hương Cảng","meaning":"Hồng Kông"},{"id":"w_34_39","hsk":3,"lesson":34,"hanzi":"赵","pinyin":"Zhào","pos":"Danh từ","hanviet":"Triệu","meaning":"(họ) Triệu"}],"dialogue":[{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"Kể","zh":"王老师和林老师都住在学校里。林老师给王老师打来了个电话，说她从台湾回来了，还给王老师带来一些东西，要给王老师送来……","py":"Wáng lǎoshī hé Lín lǎoshī dōu zhù zài xuéxiào li. Lín lǎoshī gěi Wáng lǎoshī dǎláile ge diànhuà, shuō tā cóng Táiwān huílai le, hái gěi Wáng lǎoshī dàilai yìxiē dōngxi, yào gěi Wáng lǎoshī sònglai……","vi":"Thầy Vương và cô Lâm đều sống trong trường. Cô Lâm gọi điện cho thầy Vương, nói cô ấy từ Đài Loan về rồi, còn mang về cho thầy Vương một ít đồ, muốn đem sang cho thầy…"},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"王老师吗？我是小林。","py":"Wáng lǎoshī ma? Wǒ shì Xiǎo Lín.","vi":"Thầy Vương phải không ạ? Em là Tiểu Lâm đây."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"啊，小林。你不是到台湾开汉语教学研讨会去了吗？","py":"À, Xiǎo Lín. Nǐ bú shì dào Táiwān kāi Hànyǔ jiàoxué yántǎohuì qù le ma?","vi":"À, Tiểu Lâm. Chẳng phải cô đi Đài Loan dự hội thảo giảng dạy tiếng Hán rồi sao?"},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"我开完会回来了。昨天晚上刚到家。我回来的时候，经过香港，到小赵家去看了看。","py":"Wǒ kāiwán huì huílai le. Zuótiān wǎnshang gāng dào jiā. Wǒ huílai de shíhou, jīngguò Xiānggǎng, dào Xiǎo Zhào jiā qù kànle kàn.","vi":"Em họp xong về rồi ạ. Tối qua mới về đến nhà. Lúc về em có đi qua Hồng Kông, ghé nhà Tiểu Triệu thăm một chút."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"是吗？小赵好吗？","py":"Shì ma? Xiǎo Zhào hǎo ma?","vi":"Thế à? Tiểu Triệu có khỏe không?"},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"挺好的。她让我向您问好，还让我给您捎来一些东西。我想给您送去。","py":"Tǐng hǎo de. Tā ràng wǒ xiàng nín wènhǎo, hái ràng wǒ gěi nín shāolai yìxiē dōngxi. Wǒ xiǎng gěi nín sòngqu.","vi":"Khỏe lắm ạ. Cô ấy nhờ em gửi lời hỏi thăm thầy, còn nhờ em mang cho thầy một ít đồ. Em muốn mang sang cho thầy."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"我过去取吧。","py":"Wǒ guòqu qǔ ba.","vi":"Để tôi qua lấy nhé."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"不用。我正好要下楼去，顺便就给您带去了。","py":"Búyòng. Wǒ zhènghǎo yào xià lóu qù, shùnbiàn jiù gěi nín dàiqu le.","vi":"Không cần đâu ạ. Em đang định xuống lầu, tiện thể mang sang cho thầy luôn."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"那好，你过来吧。","py":"Nà hǎo, nǐ guòlai ba.","vi":"Vậy được, cô qua đây đi."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"Kể","zh":"王老师家门口","py":"Wáng lǎoshī jiā ménkǒu","vi":"Trước cửa nhà thầy Vương"},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"辛苦了！还麻烦你跑一趟。外边冷，快进屋来坐吧。","py":"Xīnkǔ le! Hái máfan nǐ pǎo yí tàng. Wàibian lěng, kuài jìn wū lái zuò ba.","vi":"Vất vả cho cô quá! Còn phiền cô chạy một chuyến. Bên ngoài lạnh, mau vào nhà ngồi đi."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"不进去了。我爱人还在楼下等我呢，我们要出去办点儿事。","py":"Bú jìnqu le. Wǒ àirén hái zài lóu xià děng wǒ ne, wǒmen yào chūqu bàn diǎnr shì.","vi":"Em không vào đâu ạ. Chồng em còn đang đợi dưới lầu, bọn em phải ra ngoài làm chút việc."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"我送送你。","py":"Wǒ sòngsong nǐ.","vi":"Để tôi tiễn cô."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"林老师","zh":"不用送了，请回吧。","py":"Búyòng sòng le, qǐng huí ba.","vi":"Không cần tiễn đâu ạ, thầy vào nhà đi."},{"section":"Bài khóa 1: 我给您捎来了一些东西","speaker":"王老师","zh":"慢走！","py":"Màn zǒu!","vi":"Đi cẩn thận nhé!"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"Kể","zh":"林老师和同学们一起坐车去展览馆参观。车就要开了，林老师在车上叫同学们快上车……","py":"Lín lǎoshī hé tóngxuémen yìqǐ zuò chē qù zhǎnlǎnguǎn cānguān. Chē jiù yào kāi le, Lín lǎoshī zài chē shang jiào tóngxuémen kuài shàng chē……","vi":"Cô Lâm cùng các bạn học đi xe đến nhà triển lãm tham quan. Xe sắp chạy rồi, cô Lâm ở trên xe gọi các bạn mau lên xe…"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"下边的同学快上来吧，要开车了。","py":"Xiàbian de tóngxué kuài shànglai ba, yào kāi chē le.","vi":"Các em ở dưới mau lên đi, xe sắp chạy rồi."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"麦克","zh":"老师，我不上去了，我到后边的五号车去可以吗？我朋友在那儿。","py":"Lǎoshī, wǒ bú shàngqu le, wǒ dào hòubian de wǔ hào chē qù kěyǐ ma? Wǒ péngyou zài nàr.","vi":"Thưa cô, em không lên đâu, em sang xe số 5 phía sau được không ạ? Bạn em ở đó."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"你过去吧。玛丽怎么还没上来呢？","py":"Nǐ guòqu ba. Mǎlì zěnme hái méi shànglai ne?","vi":"Em qua đi. Sao Mary vẫn chưa lên nhỉ?"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"山本","zh":"她忘带照相机了，又回宿舍去拿了，一会儿就回来。啊，她跑来了。","py":"Tā wàng dài zhàoxiàngjī le, yòu huí sùshè qù ná le, yíhuìr jiù huílai. À, tā pǎolai le.","vi":"Bạn ấy quên mang máy ảnh, lại quay về ký túc xá lấy rồi, lát nữa sẽ quay lại. A, bạn ấy chạy đến rồi."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"Kể","zh":"玛丽上来了","py":"Mǎlì shànglai le","vi":"Mary lên xe rồi"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"玛丽","zh":"对不起，我来晚了。","py":"Duìbuqǐ, wǒ lái wǎn le.","vi":"Xin lỗi, em đến muộn."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"山本","zh":"玛丽，这儿还有座位，你过来吧。","py":"Mǎlì, zhèr hái yǒu zuòwèi, nǐ guòlai ba.","vi":"Mary, ở đây còn chỗ ngồi, bạn qua đây đi."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"请大家注意，我先说一件事。我们今天去参观出土文物展览。这个展览大约要参观两个半小时。参观完以后，四点钟开车回来。要求大家四点准时上车。不回来的同学跟我说一声。听清楚了没有？","py":"Qǐng dàjiā zhùyì, wǒ xiān shuō yí jiàn shì. Wǒmen jīntiān qù cānguān chūtǔ wénwù zhǎnlǎn. Zhège zhǎnlǎn dàyuē yào cānguān liǎng ge bàn xiǎoshí. Cānguān wán yǐhòu, sì diǎn zhōng kāi chē huílai. Yāoqiú dàjiā sì diǎn zhǔnshí shàng chē. Bù huílai de tóngxué gēn wǒ shuō yì shēng. Tīng qīngchu le méiyǒu?","vi":"Mọi người chú ý, cô nói trước một việc. Hôm nay chúng ta đi tham quan triển lãm văn vật khai quật. Triển lãm này tham quan mất khoảng hai tiếng rưỡi. Tham quan xong, bốn giờ xe chạy về. Yêu cầu mọi người bốn giờ lên xe đúng giờ. Em nào không về thì báo với cô một tiếng. Nghe rõ chưa?"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"留学生","zh":"听清楚了。","py":"Tīng qīngchu le.","vi":"Nghe rõ rồi ạ."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"要记住开车的时间。都上来了吗？好，师傅，开车吧。","py":"Yào jìzhù kāi chē de shíjiān. Dōu shànglai le ma? Hǎo, shīfu, kāi chē ba.","vi":"Phải nhớ giờ xe chạy nhé. Mọi người lên hết chưa? Được rồi, bác tài, cho xe chạy đi."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"Kể","zh":"山本站起来给老师让座位","py":"Shānběn zhàn qilai gěi lǎoshī ràng zuòwèi","vi":"Yamamoto đứng dậy nhường chỗ cho cô giáo"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"山本","zh":"老师，您到这儿来坐吧。","py":"Lǎoshī, nín dào zhèr lái zuò ba.","vi":"Thưa cô, cô đến đây ngồi đi ạ."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"我不过去了，就坐这儿了，你快坐下吧。","py":"Wǒ bú guòqu le, jiù zuò zhèr le, nǐ kuài zuòxia ba.","vi":"Cô không qua đâu, cô ngồi luôn ở đây, em mau ngồi xuống đi."},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"Kể","zh":"到了展览馆门前","py":"Dàole zhǎnlǎnguǎn mén qián","vi":"Đến trước cửa nhà triển lãm"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"玛丽","zh":"老师，参观完以后，我想到大使馆去看朋友，不回学校去了，可以吗？","py":"Lǎoshī, cānguān wán yǐhòu, wǒ xiǎng dào dàshǐguǎn qù kàn péngyou, bù huí xuéxiào qù le, kěyǐ ma?","vi":"Thưa cô, tham quan xong em muốn đến đại sứ quán thăm bạn, không về trường nữa, có được không ạ?"},{"section":"Bài khóa 2: 快上来吧，要开车了","speaker":"林老师","zh":"可以。","py":"Kěyǐ.","vi":"Được."}],"grammar":["Bổ ngữ xu hướng đơn – động từ + 来/去: 来 biểu thị hướng đến gần người nói, 去 biểu thị hướng đi xa người nói: 上来吧。(người nói ở trên) 上课了，快进来吧。(người nói ở trong) 他回家去了。(người nói ở ngoài nhà)","Tân ngữ chỉ địa điểm với 来/去: động từ + tân ngữ chỉ địa điểm + 来/去 (tân ngữ chỉ nơi chốn đứng trước 来/去): 我到小赵家去了。我正好要下楼去。我们进教室去吧。","Tân ngữ chỉ sự vật với 来/去: có thể đặt sau 来/去 hoặc trước 来/去: 他带了一个照相机来。= 他带来了一个照相机。他买来了一本《英汉词典》。= 他买了一本《英汉词典》来。我给你带来了一些东西。= 我给你带了一些东西来。","Câu phản vấn 不是……吗: nhấn mạnh ngữ khí khẳng định hoặc phủ định, hoặc cố ý hỏi để dẫn ra lời phía sau: 你不是到台湾开教学研讨会去了吗？你不是北京人吗？为什么不知道这个地方？昨天你不是去了吗？为什么说不知道？你不是不喜欢吃米饭吗？","Động lượng từ 趟 và lượng từ 声: 趟 biểu thị số lần đi lại: 还麻烦你跑一趟。声 biểu thị số lần âm thanh được phát ra: 不回来的同学跟我说一声。"]},{"id":35,"hsk":3,"zh_title":"我听过钢琴协奏曲《黄河》","pinyin_title":"Wǒ tīngguo gāngqín xiézòuqǔ 《Huánghé》","title":"Tôi đã nghe bản hòa tấu piano “Hoàng Hà”","words":[{"id":"w_35_1","hsk":3,"lesson":35,"hanzi":"经历","pinyin":"jīnglì","pos":"Danh từ/ Động từ","hanviet":"kinh lịch","meaning":"trải qua, kinh nghiệm","example":"他经历过了很多事情。 — Anh ấy đã trải qua rất nhiều chuyện."},{"id":"w_35_2","hsk":3,"lesson":35,"hanzi":"过","pinyin":"guò","pos":"Động từ/ Trợ từ động thái","hanviet":"quá","meaning":"qua, từng","example":"你去过北京了吗？我没去过北京。 — Bạn đã từng đi Bắc Kinh chưa? Tôi chưa từng đi Bắc Kinh."},{"id":"w_35_3","hsk":3,"lesson":35,"hanzi":"住院","pinyin":"zhù yuàn","pos":"Động từ ly hợp","hanviet":"trú viện","meaning":"nằm viện"},{"id":"w_35_4","hsk":3,"lesson":35,"hanzi":"中医","pinyin":"zhōngyī","pos":"Danh từ","hanviet":"trung y","meaning":"đông y, y học cổ truyền","example":"我对中医非常感兴趣。 — Tôi vô cùng có hứng thú với y học cổ truyền."},{"id":"w_35_5","hsk":3,"lesson":35,"hanzi":"苦","pinyin":"kǔ","pos":"Tính từ","hanviet":"khổ","meaning":"đắng","example":"这种药很苦，我不爱吃。我想吃甜的。 — Loại thuốc này rất đắng, tôi không thích uống. Tôi muốn uống thuốc ngọt."},{"id":"w_35_6","hsk":3,"lesson":35,"hanzi":"甜","pinyin":"tián","pos":"Tính từ","hanviet":"điềm","meaning":"ngọt","example":"这种药很苦，我不爱吃。我想吃甜的。 — Loại thuốc này rất đắng, tôi không thích uống. Tôi muốn uống thuốc ngọt."},{"id":"w_35_7","hsk":3,"lesson":35,"hanzi":"中成药","pinyin":"zhōngchéngyào","pos":"Danh từ","hanviet":"trung thành dược","meaning":"thuốc Đông y đã làm sẵn thành viên, thuốc nước"},{"id":"w_35_8","hsk":3,"lesson":35,"hanzi":"药方","pinyin":"yàofāng","pos":"Danh từ","hanviet":"dược phương","meaning":"đơn thuốc","example":"医生给我开了个药方。 — Bác sĩ kê cho tôi một đơn thuốc."},{"id":"w_35_9","hsk":3,"lesson":35,"hanzi":"摸","pinyin":"mō","pos":"Động từ","hanviet":"mô, mạc","meaning":"sờ, mó, xoa, bắt (mạch)","example":"今天我去医院看病，医生已经给我摸脉。 — Hôm nay tôi đi bệnh viện khám, bác sĩ đã bắt mạch cho tôi."},{"id":"w_35_10","hsk":3,"lesson":35,"hanzi":"脉","pinyin":"mài","pos":"Danh từ","hanviet":"mạch","meaning":"mạch","example":"今天我去医院看病，医生已经给我摸脉。 — Hôm nay tôi đi bệnh viện khám, bác sĩ đã bắt mạch cho tôi."},{"id":"w_35_11","hsk":3,"lesson":35,"hanzi":"按摩","pinyin":"ànmó","pos":"Động từ","hanviet":"án ma","meaning":"mát xa","example":"我这里有点疼，你帮我按摩一下吧！ — Tôi chỗ này hơi đau, bạn giúp tôi massage chút đi."},{"id":"w_35_12","hsk":3,"lesson":35,"hanzi":"针灸","pinyin":"zhēnjiǔ","pos":"Danh từ, Động từ","hanviet":"châm cứu","meaning":"châm cứu","example":"我听说针灸很有用。 — Tôi nghe nói châm cứu rất hữu dụng."},{"id":"w_35_13","hsk":3,"lesson":35,"hanzi":"方法","pinyin":"fāngfǎ","pos":"Danh từ","hanviet":"phương pháp","meaning":"phương pháp","example":"我要想一想解决这个问题的方法。 — Tôi phải nghĩ cách giải quyết vấn đề này."},{"id":"w_35_14","hsk":3,"lesson":35,"hanzi":"治","pinyin":"zhì","pos":"Động từ","hanviet":"trị","meaning":"điều trị","example":"你怎么生病了呢？快找医生给你看病和治病吧。 — Bạn tại sao bị bệnh rồi vậy? Mau tìm bác sĩ khám và chữa bệnh cho bạn đi."},{"id":"w_35_15","hsk":3,"lesson":35,"hanzi":"扎针","pinyin":"zhā zhēn","pos":"Động từ ly hợp","hanviet":"trát châm","meaning":"châm kim"},{"id":"w_35_16","hsk":3,"lesson":35,"hanzi":"细","pinyin":"xì","pos":"Tính từ","hanviet":"tế","meaning":"mảnh, nhỏ (dùng cho đồ vật dạng sợi)","example":"针灸用的针是非常细的。 — Kim dùng trong châm cứu là cái vô cùng mảnh."},{"id":"w_35_17","hsk":3,"lesson":35,"hanzi":"曾经","pinyin":"céngjīng","pos":"Phó từ","hanviet":"tằng kinh","meaning":"đã từng","example":"你曾经去过北京了吗？ — Bạn đã từng đi qua Bắc Kinh chưa?"},{"id":"w_35_18","hsk":3,"lesson":35,"hanzi":"烤鸭","pinyin":"kǎoyā","pos":"Danh từ","hanviet":"khảo áp","meaning":"vịt quay","example":"我想吃北京烤鸭，半只多少钱？ — Tôi muốn ăn vịt quay Bắc Kinh, nửa con bao nhiêu tiền?"},{"id":"w_35_19","hsk":3,"lesson":35,"hanzi":"烤","pinyin":"kǎo","pos":"Động từ","hanviet":"khảo","meaning":"quay, nướng","example":"我想吃北京烤鸭，半只多少钱？ — Tôi muốn ăn vịt quay Bắc Kinh, nửa con bao nhiêu tiền?"},{"id":"w_35_20","hsk":3,"lesson":35,"hanzi":"第","pinyin":"dì","pos":"Tiền tố","hanviet":"đệ","meaning":"thứ (thêm trước số đếm để tạo số thứ tự)"},{"id":"w_35_21","hsk":3,"lesson":35,"hanzi":"中餐","pinyin":"zhōngcān","pos":"Danh từ","hanviet":"trung xan","meaning":"các món ăn Trung Quốc hoặc bữa ăn kiểu Trung Quốc"},{"id":"w_35_22","hsk":3,"lesson":35,"hanzi":"白薯","pinyin":"báishǔ","pos":"Danh từ","hanviet":"bạch thự","meaning":"khoai lang ruột trắng"},{"id":"w_35_23","hsk":3,"lesson":35,"hanzi":"糖","pinyin":"táng","pos":"Danh từ","hanviet":"đường","meaning":"đường, kẹo"},{"id":"w_35_24","hsk":3,"lesson":35,"hanzi":"糖葫芦","pinyin":"tánghúlu","pos":"Danh từ","hanviet":"đường hồ lô","meaning":"kẹo hồ lô","example":"你喜欢吃糖果还是糖葫芦？ — Bạn thích ăn kẹo hay là kẹo hồ lô?"},{"id":"w_35_25","hsk":3,"lesson":35,"hanzi":"什么的","pinyin":"shénmede","pos":"Trợ từ","hanviet":"thập ma đích","meaning":"vân vân","example":"想买苹果、香蕉什么的。 — Muốn mua táo, chuối,…"},{"id":"w_35_26","hsk":3,"lesson":35,"hanzi":"亲耳","pinyin":"qīn'ěr","pos":"Phó từ","hanviet":"thân nhĩ","meaning":"tận tai, trực tiếp nghe","example":"这件事我亲耳听到的，不会错。 — Chuyện này là chính tai tôi nghe thấy, không sai được."},{"id":"w_35_27","hsk":3,"lesson":35,"hanzi":"钢琴","pinyin":"gāngqín","pos":"Danh từ","hanviet":"cương cầm","meaning":"đàn piano","example":"听说你会弹琴？是会弹钢琴还是小提琴的？ — Nghe nói bạn biết đánh đàn? Là biết đánh piano hay violon?"},{"id":"w_35_28","hsk":3,"lesson":35,"hanzi":"小提琴","pinyin":"xiǎotíqín","pos":"Danh từ","hanviet":"tiểu đề cầm","meaning":"violon","example":"听说你会弹琴？是会弹钢琴还是小提琴的？ — Nghe nói bạn biết đánh đàn? Là biết đánh piano hay violon?"},{"id":"w_35_29","hsk":3,"lesson":35,"hanzi":"演奏","pinyin":"yǎnzòu","pos":"Động từ","hanviet":"diễn tấu","meaning":"biểu diễn (nhạc cụ)","example":"我姐姐会演奏小提琴。 — Chị tôi biết chơi violin."},{"id":"w_35_30","hsk":3,"lesson":35,"hanzi":"…家","pinyin":"jiā","pos":"Hậu tố","hanviet":"gia","meaning":"nhà (chỉ người)"},{"id":"w_35_31","hsk":3,"lesson":35,"hanzi":"极了","pinyin":"jí le","pos":"Trợ từ","hanviet":"cực liễu","meaning":"cực kỳ","example":"这里的风景美极了。 — Phong cảnh ở đây đẹp tuyệt."},{"id":"w_35_32","hsk":3,"lesson":35,"hanzi":"协奏曲","pinyin":"xiézòuqǔ","pos":"Danh từ","hanviet":"hiệp tấu khúc","meaning":"bản hòa tấu","example":"这是一首有名的钢琴协奏曲。 — Đây là 1 bản hòa tấu piano nổi tiếng."},{"id":"w_35_33","hsk":3,"lesson":35,"hanzi":"曲","pinyin":"qǔ","pos":"Danh từ","hanviet":"khúc","meaning":"bản hòa nhạc"},{"id":"w_35_34","hsk":3,"lesson":35,"hanzi":"好听","pinyin":"hǎotīng","pos":"Tính từ","hanviet":"hảo thính","meaning":"dễ nghe, hay"},{"id":"w_35_35","hsk":3,"lesson":35,"hanzi":"还","pinyin":"huán","pos":"Động từ","hanviet":"hoàn","meaning":"trả lại","example":"可以借我你的车吗？我明天还给你。 — Có thể cho tôi mượn xe của bạn không? Ngày mai tôi trả cho bạn."},{"id":"w_35_36","hsk":3,"lesson":35,"hanzi":"嘛","pinyin":"ma","pos":"Trợ từ","hanviet":"ma","meaning":"đi, mà (trợ từ)"},{"id":"w_35_37","hsk":3,"lesson":35,"hanzi":"哈尔滨","pinyin":"Hā'ěrbīn","pos":"Danh từ riêng","hanviet":"Cáp Nhĩ Tân","meaning":"Cáp Nhĩ Tân"},{"id":"w_35_38","hsk":3,"lesson":35,"hanzi":"海南岛","pinyin":"Hǎinán Dǎo","pos":"Danh từ riêng","hanviet":"Hải Nam đảo","meaning":"Đảo Hải Nam"},{"id":"w_35_39","hsk":3,"lesson":35,"hanzi":"泰山","pinyin":"Tài Shān","pos":"Danh từ riêng","hanviet":"Thái Sơn","meaning":"Thái Sơn"},{"id":"w_35_40","hsk":3,"lesson":35,"hanzi":"西安","pinyin":"Xī'ān","pos":"Danh từ riêng","hanviet":"Tây An","meaning":"Tây An"},{"id":"w_35_41","hsk":3,"lesson":35,"hanzi":"敦煌","pinyin":"Dūnhuáng","pos":"Danh từ riêng","hanviet":"Đôn Hoàng","meaning":"Đôn Hoàng"},{"id":"w_35_42","hsk":3,"lesson":35,"hanzi":"颐和园","pinyin":"Yíhéyuán","pos":"Danh từ riêng","hanviet":"Di Hòa Viên","meaning":"Di Hòa Viên"},{"id":"w_35_43","hsk":3,"lesson":35,"hanzi":"故宫","pinyin":"Gùgōng","pos":"Danh từ riêng","hanviet":"Cố Cung","meaning":"Cố Cung (Tử Cấm Thành)"},{"id":"w_35_44","hsk":3,"lesson":35,"hanzi":"长城","pinyin":"Chángchéng","pos":"Danh từ riêng","hanviet":"Trường Thành","meaning":"Trường Thành"},{"id":"w_35_45","hsk":3,"lesson":35,"hanzi":"黄河","pinyin":"Huáng Hé","pos":"Danh từ riêng","hanviet":"Hoàng Hà","meaning":"sông Hoàng Hà; bản hòa tấu piano 《黄河》"},{"id":"w_35_46","hsk":3,"lesson":35,"hanzi":"梁祝","pinyin":"Liáng Zhù","pos":"Danh từ riêng","hanviet":"Lương Chúc","meaning":"Lương Chúc (bản hòa tấu violon 《梁祝》)"}],"dialogue":[{"section":"Bài khóa 1: 我吃过中药","speaker":"Kể","zh":"山本和爱德华谈来中国后的经历……","py":"Shānběn hé Àidéhuá tán lái Zhōngguó hòu de jīnglì……","vi":"Yamamoto và Edward nói chuyện về những trải nghiệm sau khi đến Trung Quốc…"},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"山本，你的感冒好了吗？","py":"Shānběn, nǐ de gǎnmào hǎo le ma?","vi":"Yamamoto, cậu khỏi cảm chưa?"},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"好了。来中国以后我已经得过三次感冒了。","py":"Hǎo le. Lái Zhōngguó yǐhòu wǒ yǐjīng déguo sān cì gǎnmào le.","vi":"Khỏi rồi. Từ khi đến Trung Quốc, tớ đã bị cảm ba lần rồi."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"我一次病也没有得过。","py":"Wǒ yí cì bìng yě méiyǒu déguo.","vi":"Tớ chưa ốm lần nào cả."},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"你身体真不错。我还住过一次院呢，看过中医，也吃过中药。","py":"Nǐ shēntǐ zhēn búcuò. Wǒ hái zhùguo yí cì yuàn ne, kànguo zhōngyī, yě chīguo zhōngyào.","vi":"Sức khỏe cậu tốt thật. Tớ còn từng nằm viện một lần đấy, đã từng khám Đông y, cũng uống thuốc Đông y rồi."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"听说中药很苦，是吗？","py":"Tīngshuō zhōngyào hěn kǔ, shì ma?","vi":"Nghe nói thuốc Đông y rất đắng, phải không?"},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"有的苦，有的不苦。我喝的是中成药，甜甜的，一点儿也不苦。吃了这些中药我的病就好了。","py":"Yǒude kǔ, yǒude bù kǔ. Wǒ hē de shì zhōngchéngyào, tiántián de, yìdiǎnr yě bù kǔ. Chī le zhèxiē zhōngyào wǒ de bìng jiù hǎo le.","vi":"Có loại đắng, có loại không đắng. Tớ uống thuốc Đông y bào chế sẵn, ngọt ngọt, chẳng đắng chút nào. Uống mấy thuốc này xong là tớ khỏi bệnh."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"我听说中医看病很有意思。","py":"Wǒ tīngshuō zhōngyī kànbìng hěn yǒu yìsi.","vi":"Tớ nghe nói Đông y khám bệnh rất thú vị."},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"中医看病不化验，只用手摸一摸脉就给你开药方。还用按摩、针灸等方法给病人治病。","py":"Zhōngyī kànbìng bú huàyàn, zhǐ yòng shǒu mō yi mō mài jiù gěi nǐ kāi yàofāng. Hái yòng ànmó, zhēnjiǔ děng fāngfǎ gěi bìngrén zhìbìng.","vi":"Đông y khám bệnh không xét nghiệm, chỉ dùng tay bắt mạch một chút là kê đơn thuốc cho cậu. Họ còn dùng các phương pháp như xoa bóp, châm cứu để chữa bệnh cho người bệnh."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"是打针吗？","py":"Shì dǎzhēn ma?","vi":"Là tiêm à?"},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"不是打针，是扎针。","py":"Bú shì dǎzhēn, shì zhāzhēn.","vi":"Không phải tiêm, mà là châm kim."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"你针灸过吗？","py":"Nǐ zhēnjiǔguo ma?","vi":"Cậu đã từng châm cứu chưa?"},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"我按摩过，没有针灸过，但是见过。","py":"Wǒ ànmóguo, méiyǒu zhēnjiǔguo, dànshì jiànguo.","vi":"Tớ từng được xoa bóp, chưa châm cứu bao giờ, nhưng đã từng thấy rồi."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"是什么样的针呢？","py":"Shì shénmeyàng de zhēn ne?","vi":"Kim như thế nào vậy?"},{"section":"Bài khóa 1: 我吃过中药","speaker":"山本","zh":"是一种很细很细的针。","py":"Shì yì zhǒng hěn xì hěn xì de zhēn.","vi":"Là một loại kim rất rất mảnh."},{"section":"Bài khóa 1: 我吃过中药","speaker":"爱德华","zh":"没见过。","py":"Méi jiànguo.","vi":"Tớ chưa thấy bao giờ."},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"山本，听说你曾经来过中国，是吗？","py":"Shānběn, tīngshuō nǐ céngjīng láiguo Zhōngguó, shì ma?","vi":"Yamamoto, nghe nói trước đây cậu đã từng đến Trung Quốc, phải không?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"是啊，来过一次。你呢？","py":"Shì a, láiguo yí cì. Nǐ ne?","vi":"Đúng vậy, đến một lần rồi. Còn cậu?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"我没有来过，这是第一次。你都去过什么地方？","py":"Wǒ méiyǒu láiguo, zhè shì dì yī cì. Nǐ dōu qùguo shénme dìfang?","vi":"Tớ chưa đến bao giờ, đây là lần đầu tiên. Cậu đã đi những nơi nào rồi?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"我已经去过好多地方了。北边去过哈尔滨，南边到过海南岛，东边上过泰山，西边去过西安和敦煌。","py":"Wǒ yǐjīng qùguo hǎoduō dìfang le. Běibian qùguo Hā'ěrbīn, nánbian dàoguo Hǎinán Dǎo, dōngbian shàngguo Tài Shān, xībian qùguo Xī'ān hé Dūnhuáng.","vi":"Tớ đã đi rất nhiều nơi rồi. Phía bắc thì đã đến Cáp Nhĩ Tân, phía nam đến đảo Hải Nam, phía đông đã leo núi Thái Sơn, phía tây đã đến Tây An và Đôn Hoàng."},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"你去过的地方真不少。来中国以后，我只去过颐和园、故宫和长城。","py":"Nǐ qùguo de dìfang zhēn bù shǎo. Lái Zhōngguó yǐhòu, wǒ zhǐ qùguo Yíhéyuán, Gùgōng hé Chángchéng.","vi":"Những nơi cậu đã đến thật không ít. Từ khi đến Trung Quốc, tớ mới chỉ đi Di Hòa Viên, Cố Cung và Trường Thành."},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"习惯吃中餐了吗？","py":"Xíguàn chī zhōngcān le ma?","vi":"Cậu quen ăn đồ ăn Trung Quốc chưa?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"早就习惯了。","py":"Zǎo jiù xíguàn le.","vi":"Quen từ lâu rồi."},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"你吃过哪些中国菜？","py":"Nǐ chīguo nǎxiē Zhōngguó cài?","vi":"Cậu đã ăn những món Trung Quốc nào rồi?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"吃过很多。最喜欢吃的是北京烤鸭。你爱吃什么？","py":"Chīguo hěn duō. Zuì xǐhuan chī de shì Běijīng kǎoyā. Nǐ ài chī shénme?","vi":"Ăn nhiều lắm. Món tớ thích nhất là vịt quay Bắc Kinh. Cậu thích ăn gì?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"中国菜我都爱吃。还爱吃烤白薯、糖葫芦什么的。","py":"Zhōngguó cài wǒ dōu ài chī. Hái ài chī kǎo báishǔ, tánghúlu shénmede.","vi":"Món Trung Quốc nào tớ cũng thích. Tớ còn thích ăn khoai lang nướng, kẹo hồ lô các thứ."},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"罗兰","zh":"看过京剧吗？","py":"Kànguo jīngjù ma?","vi":"Cậu xem Kinh kịch bao giờ chưa?"},{"section":"Bài khóa 2: 你以前来过中国吗","speaker":"山本","zh":"没看过。听说京剧很有意思，我很想去看看。","py":"Méi kànguo. Tīngshuō jīngjù hěn yǒu yìsi, wǒ hěn xiǎng qù kànkan.","vi":"Chưa xem bao giờ. Nghe nói Kinh kịch rất hay, tớ rất muốn đi xem thử."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"爱德华，你说你是个音乐迷，你听过中国音乐吗？","py":"Àidéhuá, nǐ shuō nǐ shì ge yīnyuèmí, nǐ tīngguo Zhōngguó yīnyuè ma?","vi":"Edward, cậu nói cậu là người mê âm nhạc, cậu đã từng nghe nhạc Trung Quốc chưa?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"当然听过！","py":"Dāngrán tīngguo!","vi":"Tất nhiên là nghe rồi!"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"听过什么？","py":"Tīngguo shénme?","vi":"Nghe bài gì rồi?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"在加拿大时，我亲耳听过一位中国钢琴家演奏的《黄河》。","py":"Zài Jiānádà shí, wǒ qīn'ěr tīngguo yí wèi Zhōngguó gāngqínjiā yǎnzòu de 《Huánghé》.","vi":"Hồi ở Canada, tớ đã tận tai nghe một nghệ sĩ piano Trung Quốc biểu diễn bản 《Hoàng Hà》."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"你觉得怎么样？","py":"Nǐ juéde zěnmeyàng?","vi":"Cậu thấy thế nào?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"好极了，真想再听一遍。","py":"Hǎo jí le, zhēn xiǎng zài tīng yí biàn.","vi":"Hay tuyệt, thật muốn nghe lại một lần nữa."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"听过小提琴协奏曲《梁祝》吗？","py":"Tīngguo xiǎotíqín xiézòuqǔ 《Liáng Zhù》 ma?","vi":"Cậu đã nghe bản hòa tấu violon 《Lương Chúc》 chưa?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"听说过，但是没听过。好听吗？","py":"Tīngshuōguo, dànshì méi tīngguo. Hǎotīng ma?","vi":"Có nghe nói đến, nhưng chưa nghe bao giờ. Có hay không?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"你听了就知道了。","py":"Nǐ tīng le jiù zhīdào le.","vi":"Cậu nghe rồi sẽ biết."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"我很想听听，你这儿有光盘吗？","py":"Wǒ hěn xiǎng tīngting, nǐ zhèr yǒu guāngpán ma?","vi":"Tớ rất muốn nghe thử, chỗ cậu có đĩa CD không?"},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"有。","py":"Yǒu.","vi":"Có."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"借给我听听吧。","py":"Jiè gěi wǒ tīngting ba.","vi":"Cho tớ mượn nghe thử nhé."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"田芳","zh":"你拿去吧。听完就还给我。","py":"Nǐ ná qù ba. Tīng wán jiù huán gěi wǒ.","vi":"Cậu cầm đi. Nghe xong thì trả lại tớ nhé."},{"section":"Bài khóa 3: 我听过钢琴协奏曲《黄河》","speaker":"爱德华","zh":"一定。好借好还，再借不难嘛。","py":"Yídìng. Hǎo jiè hǎo huán, zài jiè bù nán ma.","vi":"Nhất định rồi. Có mượn có trả, lần sau mượn lại chẳng khó mà."}],"grammar":["Động từ + 过: Biểu thị động tác đã từng xảy ra trong quá khứ nhưng không tiếp diễn đến hiện tại, nhấn mạnh sự từng trải. Khẳng định: Động từ + 过 (我听过中国音乐。); Phủ định: 没（有）+ Động từ + 过 (我没打过针。); Nghi vấn: Động từ + 过 + Tân ngữ + 没有 (你以前来过中国没有？)","Bổ ngữ động lượng: Số từ + động lượng từ (次、遍、声、趟、下) nói rõ số lần của động tác; 了/过 đặt sau động từ, trước bổ ngữ động lượng (他来过两次中国。他敲了一下儿门。). Tân ngữ chỉ sự vật thường đặt sau bổ ngữ (她住过一次医院。); tân ngữ là đại từ nhân xưng bắt buộc đặt trước (他找过你一次。, không nói *他找过一次你); với địa danh có thể nói cả hai cách (山本以前来过一次中国。/ 山本以前来过中国一次。)","次 và 遍: Đều biểu đạt số lần của động tác; 遍 nhấn mạnh cả quá trình từ khi bắt đầu đến khi kết thúc (这本书很好，我已经看过两遍了。这个电影我看了三次也没看完一遍。)","过 và 了: Phủ định khác nhau — 没（有）+ Động từ + 过 (这个电影我没看过，不知道好不好。) còn 没（有）+ Động từ, không thêm 了 (昨天晚上的电影我没看。); ý nghĩa khác nhau — 我学了一年汉语了。(vẫn đang học) / 我学过一年汉语。(không học nữa)","一……也没/不……: 一 + lượng từ (+ danh từ) + 也 + 没/不 + động từ, phủ định hoàn toàn, nhấn mạnh “không… chút nào/lần nào” (他一次也没来过。这个星期他一天课也没上。我喝的中药一点儿也不苦。)","……极了: Đặt sau tính từ và một số động từ (tâm lý), biểu thị mức độ cao nhất (大极了、冷极了、美极了、高兴极了、关心极了、喜欢极了)"]},{"id":36,"hsk":3,"zh_title":"我是跟旅游团一起来的","pinyin_title":"Wǒ shì gēn lǚyóutuán yìqǐ lái de","title":"Tôi đến cùng đoàn du lịch","words":[{"id":"w_36_1","hsk":3,"lesson":36,"hanzi":"前天","pinyin":"qiántiān","pos":"Danh từ","hanviet":"tiền thiên","meaning":"ngày hôm kia"},{"id":"w_36_2","hsk":3,"lesson":36,"hanzi":"后天","pinyin":"hòutiān","pos":"Danh từ","hanviet":"hậu thiên","meaning":"ngày kia"},{"id":"w_36_3","hsk":3,"lesson":36,"hanzi":"导游","pinyin":"dǎoyóu","pos":"Danh từ","hanviet":"đạo du","meaning":"hướng dẫn viên du lịch","example":"他是我们旅游团的导游。 — Anh ấy là hướng dẫn viên của đoàn du lịch chúng tôi."},{"id":"w_36_4","hsk":3,"lesson":36,"hanzi":"研究生","pinyin":"yánjiūshēng","pos":"Danh từ","hanviet":"nghiên cứu sinh","meaning":"nghiên cứu sinh","example":"我现在在中国读研，是研二。 — Tôi đang học cao học (thạc sĩ) ở Trung Quốc, là học viên năm thứ hai."},{"id":"w_36_5","hsk":3,"lesson":36,"hanzi":"打工","pinyin":"dǎgōng","pos":"Động từ ly hợp","hanviet":"đả công","meaning":"làm thuê, đi làm"},{"id":"w_36_6","hsk":3,"lesson":36,"hanzi":"利用","pinyin":"lìyòng","pos":"Động từ","hanviet":"lợi dụng","meaning":"tận dụng, lợi dụng","example":"我们要利用时间学习中文。 — Chúng ta phải tận dụng thời gian để học tiếng Trung."},{"id":"w_36_7","hsk":3,"lesson":36,"hanzi":"假期","pinyin":"jiàqī","pos":"Danh từ","hanviet":"giả kỳ","meaning":"kỳ nghỉ","example":"这个假期你有什么打算吗？ — Kỳ nghỉ này bạn có dự định gì không?"},{"id":"w_36_8","hsk":3,"lesson":36,"hanzi":"旅行社","pinyin":"lǚxíngshè","pos":"Danh từ","hanviet":"lữ hành xã","meaning":"công ty du lịch","example":"他现在在一家旅行社（旅行公司）当导游。 — Anh ấy đang làm hướng dẫn viên tại một công ty du lịch."},{"id":"w_36_9","hsk":3,"lesson":36,"hanzi":"组织","pinyin":"zǔzhī","pos":"Danh từ/ Động từ","hanviet":"tổ chức","meaning":"tổ chức","example":"学校给我们组织一个晚会。 — Trường tổ chức cho chúng tôi một buổi tiệc tối."},{"id":"w_36_10","hsk":3,"lesson":36,"hanzi":"老板","pinyin":"lǎobǎn","pos":"Danh từ","hanviet":"lão bản","meaning":"ông chủ, bà chủ, sếp","example":"他是我们公司的大老板。 — Anh ấy là sếp lớn của công ty chúng tôi."},{"id":"w_36_11","hsk":3,"lesson":36,"hanzi":"需要","pinyin":"xūyào","pos":"Danh từ/ Động từ","hanviet":"nhu yếu","meaning":"nhu cầu, yêu cầu","example":"你还需要什么吗？ — Bạn còn cần gì không?"},{"id":"w_36_12","hsk":3,"lesson":36,"hanzi":"经常","pinyin":"jīngcháng","pos":"Phó từ","hanviet":"kinh thường","meaning":"thường xuyên","example":"你经常去图书馆查资料吗？ — Bạn có thường xuyên đi thư viện tra cứu tài liệu không?"},{"id":"w_36_13","hsk":3,"lesson":36,"hanzi":"收集","pinyin":"shōují","pos":"Động từ","hanviet":"thâu tập","meaning":"thu thập","example":"我很喜欢收集邮票。 — Tôi rất thích thu thập tem thư."},{"id":"w_36_14","hsk":3,"lesson":36,"hanzi":"一…就…","pinyin":"yī…jiù…","pos":"Kết cấu","hanviet":"nhất…tựu…","meaning":"vừa… liền…","example":"今天我一下课就去看你。 — Hôm nay tôi vừa tan học là đi thăm bạn ngay."},{"id":"w_36_15","hsk":3,"lesson":36,"hanzi":"安排","pinyin":"ānpái","pos":"Danh từ/ Động từ","hanviet":"an bài","meaning":"sắp xếp","example":"他正在给老板安排下周的工作。 — Anh ấy đang sắp xếp công việc tuần sau cho sếp."},{"id":"w_36_16","hsk":3,"lesson":36,"hanzi":"帮助","pinyin":"bāngzhù","pos":"Danh từ/ Động từ","hanviet":"bang trợ","meaning":"giúp đỡ","example":"我需要你的帮助。 — Tôi cần sự giúp đỡ của bạn."},{"id":"w_36_17","hsk":3,"lesson":36,"hanzi":"希望","pinyin":"xīwàng","pos":"Động từ/ Danh từ","hanviet":"hi vọng","meaning":"hi vọng","example":"我希望你能来参加我组织的生日晚会。 — Tôi hy vọng bạn có thể đến tham gia bữa tiệc sinh nhật tôi tổ chức."},{"id":"w_36_18","hsk":3,"lesson":36,"hanzi":"铁路","pinyin":"tiělù","pos":"Danh từ","hanviet":"thiết lộ","meaning":"đường sắt"},{"id":"w_36_19","hsk":3,"lesson":36,"hanzi":"风光","pinyin":"fēngguāng","pos":"Danh từ","hanviet":"phong quang","meaning":"phong cảnh"},{"id":"w_36_20","hsk":3,"lesson":36,"hanzi":"商量","pinyin":"shāngliang","pos":"Động từ","hanviet":"thương lượng","meaning":"thương lượng","example":"我觉得这件事我们要先商量然后才决定。 — Tôi nghĩ việc này chúng ta cần phải thương lượng trước rồi mới quyết định."},{"id":"w_36_21","hsk":3,"lesson":36,"hanzi":"故乡","pinyin":"gùxiāng","pos":"Danh từ","hanviet":"cố hương","meaning":"quê hương"},{"id":"w_36_22","hsk":3,"lesson":36,"hanzi":"自由","pinyin":"zìyóu","pos":"Tính từ","hanviet":"tự do","meaning":"tự do","example":"我最近生活特别自由。 — Cuộc sống của tôi gần đây đặc biệt tự do."},{"id":"w_36_23","hsk":3,"lesson":36,"hanzi":"活动","pinyin":"huódòng","pos":"Động từ/ Danh từ","hanviet":"hoạt động","meaning":"hoạt động","example":"我们一起报名参加学校组织的课外活动吧！ — Chúng ta cùng nhau báo danh tham gia hoạt động ngoại khóa mà trường tổ chức đi."},{"id":"w_36_24","hsk":3,"lesson":36,"hanzi":"互相","pinyin":"hùxiāng","pos":"Phó từ","hanviet":"hỗ tương","meaning":"lẫn nhau"},{"id":"w_36_25","hsk":3,"lesson":36,"hanzi":"老外","pinyin":"lǎowài","pos":"Danh từ","hanviet":"lão ngoại","meaning":"người nước ngoài"},{"id":"w_36_26","hsk":3,"lesson":36,"hanzi":"呀","pinyin":"ya","pos":"Trợ từ ngữ khí","hanviet":"nha","meaning":"trợ từ"},{"id":"w_36_27","hsk":3,"lesson":36,"hanzi":"鼻子","pinyin":"bízi","pos":"Danh từ","hanviet":"tị tử","meaning":"mũi","example":"你的鼻子好高啊！太好看了！ — Mũi bạn cao quá! Đẹp quá!"},{"id":"w_36_28","hsk":3,"lesson":36,"hanzi":"头发","pinyin":"tóufa","pos":"Danh từ","hanviet":"đầu phát","meaning":"tóc","example":"我的头发有点长了，我要去剪一剪头发（剪发）。 — Tóc tôi hơi dài rồi, tôi phải đi cắt."},{"id":"w_36_29","hsk":3,"lesson":36,"hanzi":"眼睛","pinyin":"yǎnjing","pos":"Danh từ","hanviet":"nhãn tình","meaning":"mắt"},{"id":"w_36_30","hsk":3,"lesson":36,"hanzi":"声调","pinyin":"shēngdiào","pos":"Danh từ","hanviet":"thanh điệu","meaning":"thanh điệu","example":"汉语有几个声调？ — Tiếng Hán có mấy thanh điệu?"},{"id":"w_36_31","hsk":3,"lesson":36,"hanzi":"孔子","pinyin":"Kǒngzǐ","pos":"Danh từ riêng","hanviet":"Khổng Tử","meaning":"Khổng Tử"},{"id":"w_36_32","hsk":3,"lesson":36,"hanzi":"丹尼丝","pinyin":"Dānnísī","pos":"Danh từ riêng","hanviet":"Đan Ni Ti","meaning":"Denise"},{"id":"w_36_33","hsk":3,"lesson":36,"hanzi":"深圳","pinyin":"Shēnzhèn","pos":"Danh từ riêng","hanviet":"Thâm Quyến","meaning":"Thâm Quyến"}],"dialogue":[{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"Kể","zh":"丹尼丝是王老师两年前的学生，她带了一个旅游团来中国旅游，今天她来看王老师……","py":"Dānnísī shì Wáng lǎoshī liǎng nián qián de xuésheng, tā dài le yí ge lǚyóutuán lái Zhōngguó lǚyóu, jīntiān tā lái kàn Wáng lǎoshī……","vi":"Denise là học trò của thầy Vương từ hai năm trước, cô ấy dẫn một đoàn du lịch đến Trung Quốc tham quan, hôm nay cô ấy đến thăm thầy Vương…"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"王老师，您好！好久不见了。","py":"Wáng lǎoshī, nín hǎo! Hǎojiǔ bú jiàn le.","vi":"Em chào thầy Vương ạ! Lâu lắm rồi không gặp thầy."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"你好！丹尼丝，你是什么时候来的？","py":"Nǐ hǎo! Dānnísī, nǐ shì shénme shíhou lái de?","vi":"Chào em! Denise, em đến khi nào thế?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"前天刚到的。","py":"Qiántiān gāng dào de.","vi":"Hôm kia em vừa mới đến ạ."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"是来学习的吗？","py":"Shì lái xuéxí de ma?","vi":"Em đến để học à?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"不是，是来旅行的。","py":"Bú shì, shì lái lǚxíng de.","vi":"Không ạ, em đến để du lịch."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"一个人来的吗？","py":"Yí ge rén lái de ma?","vi":"Em đến một mình à?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"不是，我是跟旅游团一起来的。我当翻译，也是导游。","py":"Bú shì, wǒ shì gēn lǚyóutuán yìqǐ lái de. Wǒ dāng fānyì, yě shì dǎoyóu.","vi":"Không ạ, em đi cùng đoàn du lịch. Em làm phiên dịch, cũng là hướng dẫn viên."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"你已经工作了？","py":"Nǐ yǐjīng gōngzuò le?","vi":"Em đã đi làm rồi à?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"没有，我还在读研究生。","py":"Méiyǒu, wǒ hái zài dú yánjiūshēng.","vi":"Chưa ạ, em vẫn đang học cao học."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"是在打工吗？","py":"Shì zài dǎgōng ma?","vi":"Vậy là em đang làm thêm à?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"是的，利用假期到一家旅行社打工。他们组织了一个旅游团，老板就让我陪他们来了。他知道我需要来中国收集资料，所以，一有来中国的旅游团，他就安排我陪团来。","py":"Shì de, lìyòng jiàqī dào yì jiā lǚxíngshè dǎgōng. Tāmen zǔzhī le yí ge lǚyóutuán, lǎobǎn jiù ràng wǒ péi tāmen lái le. Tā zhīdào wǒ xūyào lái Zhōngguó shōují zīliào, suǒyǐ, yì yǒu lái Zhōngguó de lǚyóutuán, tā jiù ānpái wǒ péi tuán lái.","vi":"Vâng ạ, em tận dụng kỳ nghỉ để làm thêm ở một công ty du lịch. Họ tổ chức một đoàn du lịch, ông chủ liền để em đi cùng họ. Ông ấy biết em cần đến Trung Quốc thu thập tài liệu, nên hễ có đoàn du lịch sang Trung Quốc là ông ấy sắp xếp cho em đi theo đoàn."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"这个老板还真不错。","py":"Zhège lǎobǎn hái zhēn búcuò.","vi":"Ông chủ này tốt thật đấy."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"是。他给了我很多帮助。","py":"Shì. Tā gěi le wǒ hěn duō bāngzhù.","vi":"Vâng. Ông ấy đã giúp đỡ em rất nhiều."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"去别的地方了吗？","py":"Qù bié de dìfang le ma?","vi":"Em đã đi những nơi khác chưa?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"去了。我们先在香港玩了三天，又去了深圳，是从深圳过来的。","py":"Qù le. Wǒmen xiān zài Xiānggǎng wán le sān tiān, yòu qù le Shēnzhèn, shì cóng Shēnzhèn guòlái de.","vi":"Đi rồi ạ. Chúng em chơi ở Hồng Kông ba ngày trước, rồi đi Thâm Quyến, và từ Thâm Quyến đến đây."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"坐飞机来的吗？","py":"Zuò fēijī lái de ma?","vi":"Các em đi máy bay đến à?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"不是，坐火车来的。旅游团的人都想坐坐中国的火车，看看铁路两边的风光。","py":"Bú shì, zuò huǒchē lái de. Lǚyóutuán de rén dōu xiǎng zuòzuo Zhōngguó de huǒchē, kànkan tiělù liǎngbiān de fēngguāng.","vi":"Không ạ, chúng em đi tàu hỏa đến. Người trong đoàn đều muốn đi thử tàu hỏa Trung Quốc, ngắm phong cảnh hai bên đường sắt."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"什么时候回去？","py":"Shénme shíhou huíqù?","vi":"Khi nào các em về?"},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"丹尼丝","zh":"旅游团后天就回去了。我跟老板商量好了，晚回去几天，我要到孔子的故乡去一趟。今天下午是自由活动时间，所以来看看老师。","py":"Lǚyóutuán hòutiān jiù huíqù le. Wǒ gēn lǎobǎn shāngliang hǎo le, wǎn huíqù jǐ tiān, wǒ yào dào Kǒngzǐ de gùxiāng qù yí tàng. Jīntiān xiàwǔ shì zìyóu huódòng shíjiān, suǒyǐ lái kànkan lǎoshī.","vi":"Ngày kia đoàn du lịch về rồi ạ. Em đã thỏa thuận xong với ông chủ, sẽ về muộn vài ngày, em muốn đến quê hương của Khổng Tử một chuyến. Chiều nay là thời gian hoạt động tự do, nên em đến thăm thầy."},{"section":"Bài khóa 1: 我是跟旅游团一起来的","speaker":"王老师","zh":"在这儿吃了晚饭再走吧。","py":"Zài zhèr chī le wǎnfàn zài zǒu ba.","vi":"Ở đây ăn tối rồi hẵng về nhé."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"麦克，你的汉语是在哪儿学的？","py":"Màikè, nǐ de Hànyǔ shì zài nǎr xué de?","vi":"Mike, tiếng Hán của cậu học ở đâu thế?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"在美国学的。","py":"Zài Měiguó xué de.","vi":"Tớ học ở Mỹ."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"学了多长时间了？","py":"Xué le duō cháng shíjiān le?","vi":"Cậu học được bao lâu rồi?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"我是从去年暑假才开始学习汉语的，学了一年多了。","py":"Wǒ shì cóng qùnián shǔjià cái kāishǐ xuéxí Hànyǔ de, xué le yì nián duō le.","vi":"Tớ mới bắt đầu học tiếng Hán từ kỳ nghỉ hè năm ngoái, học được hơn một năm rồi."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"是在大学学的吗？","py":"Shì zài dàxué xué de ma?","vi":"Cậu học ở trường đại học à?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"不是。是在一个语言学校学的。","py":"Bú shì. Shì zài yí ge yǔyán xuéxiào xué de.","vi":"Không phải. Tớ học ở một trường ngôn ngữ."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"是中国老师教的吗？","py":"Shì Zhōngguó lǎoshī jiāo de ma?","vi":"Là giáo viên Trung Quốc dạy à?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"有中国老师，也有美国老师。你觉得我的汉语说得怎么样？","py":"Yǒu Zhōngguó lǎoshī, yě yǒu Měiguó lǎoshī. Nǐ juéde wǒ de Hànyǔ shuō de zěnmeyàng?","vi":"Có giáo viên Trung Quốc, cũng có giáo viên Mỹ. Cậu thấy tớ nói tiếng Hán thế nào?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"马马虎虎。中国人一听就知道你是老外。","py":"Mǎmahūhū. Zhōngguórén yì tīng jiù zhīdào nǐ shì lǎowài.","vi":"Tàm tạm. Người Trung Quốc vừa nghe là biết ngay cậu là người nước ngoài."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"一看也知道我是老外呀，高鼻子，黄头发，蓝眼睛。我知道，我的发音和声调都不太好。","py":"Yí kàn yě zhīdào wǒ shì lǎowài ya, gāo bízi, huáng tóufa, lán yǎnjing. Wǒ zhīdào, wǒ de fāyīn hé shēngdiào dōu bú tài hǎo.","vi":"Vừa nhìn cũng biết tớ là người nước ngoài mà, mũi cao, tóc vàng, mắt xanh. Tớ biết, phát âm và thanh điệu của tớ đều chưa tốt lắm."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"我们互相帮助好不好？我帮你练汉语，希望你帮我练练英语。","py":"Wǒmen hùxiāng bāngzhù hǎo bu hǎo? Wǒ bāng nǐ liàn Hànyǔ, xīwàng nǐ bāng wǒ liànlian Yīngyǔ.","vi":"Chúng mình giúp đỡ lẫn nhau được không? Tớ giúp cậu luyện tiếng Hán, mong cậu giúp tớ luyện tiếng Anh."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"好啊。不过，我的英语也马马虎虎。","py":"Hǎo a. Búguò, wǒ de Yīngyǔ yě mǎmahūhū.","vi":"Được thôi. Nhưng tiếng Anh của tớ cũng tàm tạm thôi."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"什么？你不是美国人吗？","py":"Shénme? Nǐ bú shì Měiguórén ma?","vi":"Cái gì? Cậu chẳng phải là người Mỹ sao?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"我爸爸是美国人，妈妈是意大利人，我十岁才到的美国。可以当你的老师吗？","py":"Wǒ bàba shì Měiguórén, māma shì Yìdàlìrén, wǒ shí suì cái dào de Měiguó. Kěyǐ dāng nǐ de lǎoshī ma?","vi":"Bố tớ là người Mỹ, mẹ là người Ý, mười tuổi tớ mới đến Mỹ. Tớ có thể làm thầy của cậu được không?"},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"田芳","zh":"马马虎虎吧。","py":"Mǎmahūhū ba.","vi":"Tạm được thôi."},{"section":"Bài khóa 2: 你的汉语是在哪儿学的","speaker":"麦克","zh":"不，不能马马虎虎，我们都要认真学习。","py":"Bù, bù néng mǎmahūhū, wǒmen dōu yào rènzhēn xuéxí.","vi":"Không, không được qua loa, chúng ta đều phải học hành nghiêm túc."}],"grammar":["Câu 是……的 (khẳng định): Nhấn mạnh thời gian, địa điểm, phương thức, mục đích, đối tượng… của động tác đã xảy ra hoặc đã hoàn thành; trong câu khẳng định có thể bỏ 是 (我(是)去年九月来中国的。我们(是)从美国来的。他(是)坐飞机来的。)","Câu 是……的 (phủ định): Dùng 不是……的 và KHÔNG được bỏ 是 (我不是来旅行的，我是来留学的。她不是一个人来的，是跟朋友一起来的。)","Vị trí tân ngữ trong câu 是……的: Khi động từ mang tân ngữ là danh từ, tân ngữ thường đặt sau 的 (你是在哪儿学的汉语？— 在北京学的。我坐飞机去的上海。)","Kết cấu 一……就……: (1) Động tác thứ hai xảy ra liền sau động tác thứ nhất (今天我一下课就去看你。他一到中国就给我来了个电话。); (2) Hành động thứ nhất là điều kiện dẫn đến kết quả tất yếu (中国人一听就知道你是老外。我一感冒就咳嗽。她一喝酒就脸红。)","Lặp lại tính từ: Biểu thị mức độ cao. Đơn âm tiết AA, trong khẩu ngữ âm tiết thứ hai có thể uốn lưỡi (好好儿、慢慢儿、早早儿、远远儿; 别着急，你慢慢儿说。); hai âm tiết AABB, âm tiết thứ hai có thể đọc thanh nhẹ (高高兴兴、漂漂亮亮、马马虎虎); khi làm trạng ngữ nói chung phải kèm 地 (她高高兴兴地对我说，下个月就要结婚了。)","马马虎虎: (1) Tàm tạm, không tốt cũng không xấu (我汉语说得马马虎虎，中国人一听就知道我是老外。); (2) Tùy tiện, không chăm chỉ (我们不能马马虎虎，要认真学习。)"]},{"id":37,"hsk":3,"zh_title":"我的护照你找到了没有","pinyin_title":"Wǒ de hùzhào nǐ zhǎodào le méiyǒu","title":"Hộ chiếu của tôi bạn tìm thấy chưa?","words":[{"id":"w_37_1","hsk":3,"lesson":37,"hanzi":"放","pinyin":"fàng","pos":"Động từ","hanviet":"phóng","meaning":"để, đặt","example":"放在桌子上 — Đặt ở trên bàn."},{"id":"w_37_2","hsk":3,"lesson":37,"hanzi":"半天","pinyin":"bàntiān","pos":"Danh từ","hanviet":"bán thiên","meaning":"nửa ngày, hồi lâu","example":"我都找了你半天，你去哪儿了？ — Tôi đã tìm bạn cả nửa ngày trời rồi, bạn đã đi đâu vậy?"},{"id":"w_37_3","hsk":3,"lesson":37,"hanzi":"着","pinyin":"zháo","pos":"Bổ ngữ kết quả","hanviet":"trước","meaning":"(đặt sau động từ) biểu thị mục đích của động tác đã đạt được"},{"id":"w_37_4","hsk":3,"lesson":37,"hanzi":"签证","pinyin":"qiānzhèng","pos":"Danh từ","hanviet":"thiêm chứng","meaning":"visa","example":"我的签证到期了，要办新的。 — Visa của tôi đến hạn rồi, phải đi làm cái mới."},{"id":"w_37_5","hsk":3,"lesson":37,"hanzi":"手提包","pinyin":"shǒutíbāo","pos":"Danh từ","hanviet":"thủ đề bao","meaning":"túi xách"},{"id":"w_37_6","hsk":3,"lesson":37,"hanzi":"交","pinyin":"jiāo","pos":"Động từ","hanviet":"giao","meaning":"nộp, giao","example":"写完作业就交给班长吧。 — Làm xong bài tập thì nộp cho lớp trưởng nhé."},{"id":"w_37_7","hsk":3,"lesson":37,"hanzi":"好好儿","pinyin":"hǎohāor","pos":"Phó từ","hanviet":"hảo hảo nhi","meaning":"cẩn thận, hết lòng, tử tế","example":"快要考试了，我要好好儿学习。 — Sắp thi rồi, tôi phải học hành cẩn thận."},{"id":"w_37_8","hsk":3,"lesson":37,"hanzi":"大衣","pinyin":"dàyī","pos":"Danh từ","hanviet":"đại y","meaning":"áo khoác","example":"这件大衣比较贵。 — Chiếc áo khoác này khá đắt."},{"id":"w_37_9","hsk":3,"lesson":37,"hanzi":"口袋","pinyin":"kǒudai","pos":"Danh từ","hanviet":"khẩu đại","meaning":"túi áo","example":"再好好儿找一找在口袋里有没有。 — Tìm lại cẩn thận ở trong túi áo khoác xem có hay không."},{"id":"w_37_10","hsk":3,"lesson":37,"hanzi":"丢三落四","pinyin":"diū sān là sì","pos":"Thành ngữ","hanviet":"đu tam lạc tứ","meaning":"hay quên","example":"我怎么总是丢三落四呀？ — Tôi sao mà cứ suốt ngày đãng trí vậy nhỉ?"},{"id":"w_37_11","hsk":3,"lesson":37,"hanzi":"丢","pinyin":"diū","pos":"Động từ","hanviet":"đu","meaning":"mất","example":"我手机丢了。 — Điện thoại tôi mất rồi."},{"id":"w_37_12","hsk":3,"lesson":37,"hanzi":"落","pinyin":"là","pos":"Động từ","hanviet":"lạc","meaning":"rơi"},{"id":"w_37_13","hsk":3,"lesson":37,"hanzi":"发现","pinyin":"fāxiàn","pos":"Động từ","hanviet":"phát hiện","meaning":"phát hiện","example":"你发现了吗？他比以前瘦了。 — Bạn có nhận ra không? Anh ấy gầy hơn trước đây rồi."},{"id":"w_37_14","hsk":3,"lesson":37,"hanzi":"球迷","pinyin":"qiúmí","pos":"Danh từ","hanviet":"cầu mê","meaning":"người hâm mộ bóng đá","example":"我爸爸是个老球迷。 — Bố tôi là một người hâm mộ bóng đá lâu năm."},{"id":"w_37_15","hsk":3,"lesson":37,"hanzi":"可","pinyin":"kě","pos":"Phó từ","hanviet":"khả","meaning":"dùng để nhấn mạnh","example":"他可是一个球迷。 — Anh ấy quả thực là một fan hâm mộ bóng đá."},{"id":"w_37_16","hsk":3,"lesson":37,"hanzi":"程度","pinyin":"chéngdù","pos":"Danh từ","hanviet":"trình độ","meaning":"trình độ","example":"你喜欢到什么程度？ — Bạn thích đến mức độ nào?"},{"id":"w_37_17","hsk":3,"lesson":37,"hanzi":"为了","pinyin":"wèile","pos":"Giới từ","hanviet":"vị liễu","meaning":"vì, để","example":"为了身体健康，他每天都去跑步。 — Để tốt cho sức khỏe, ngày nào anh ấy cũng đi chạy bộ."},{"id":"w_37_18","hsk":3,"lesson":37,"hanzi":"正常","pinyin":"zhèngcháng","pos":"Tính từ","hanviet":"chính thường","meaning":"bình thường","example":"这种药吃了以后会想睡觉，很正常。 — Uống thuốc này xong sẽ buồn ngủ, rất bình thường thôi."},{"id":"w_37_19","hsk":3,"lesson":37,"hanzi":"承认","pinyin":"chéngrèn","pos":"Động từ","hanviet":"thừa nhận","meaning":"thừa nhận","example":"没有人愿意承认这个错误。 — Không có ai tình nguyện thừa nhận sai lầm này cả."},{"id":"w_37_20","hsk":3,"lesson":37,"hanzi":"发狂","pinyin":"fā kuáng","pos":"Động từ","hanviet":"phát cuồng","meaning":"cuồng, phát cuồng","example":"快考试了，学生们都忙得要发狂。 — Sắp thi rồi, học sinh đều bận đến phát điên."},{"id":"w_37_21","hsk":3,"lesson":37,"hanzi":"锦标赛","pinyin":"jǐnbiāosài","pos":"Danh từ","hanviet":"cẩm tiêu trại","meaning":"thi đấu tranh giải"},{"id":"w_37_22","hsk":3,"lesson":37,"hanzi":"期间","pinyin":"qījiān","pos":"Danh từ","hanviet":"kỳ gian","meaning":"trong khoảng thời gian, thời kỳ (sự kiện)","example":"会议期间，请大家关机。 — Trong thời gian họp, xin mọi người hãy tắt máy."},{"id":"w_37_23","hsk":3,"lesson":37,"hanzi":"像","pinyin":"xiàng","pos":"Động từ","hanviet":"tượng","meaning":"giống","example":"你长得好像你妈妈。 — Bạn rất giống với mẹ bạn."},{"id":"w_37_24","hsk":3,"lesson":37,"hanzi":"生病","pinyin":"shēng bìng","pos":"Động từ ly hợp","hanviet":"sinh bệnh","meaning":"ốm, bị bệnh","example":"上个星期我生了几天病。 — Tuần trước tôi bị ốm mấy ngày."},{"id":"w_37_25","hsk":3,"lesson":37,"hanzi":"白天","pinyin":"báitiān","pos":"Danh từ","hanviet":"bạch thiên","meaning":"ban ngày","example":"那个老外白天睡觉，晚上看球赛。 — Người nước ngoài kia ban ngày ngủ, tối xem đá bóng."},{"id":"w_37_26","hsk":3,"lesson":37,"hanzi":"精神","pinyin":"jīngshen","pos":"Danh từ","hanviet":"tinh thần","meaning":"tinh thần","example":"虽然生病了，但他的精神还不错。 — Tuy bị ốm nhưng tinh thần anh ấy vẫn khá tốt."},{"id":"w_37_27","hsk":3,"lesson":37,"hanzi":"贴","pinyin":"tiē","pos":"Động từ","hanviet":"thiếp","meaning":"dán","example":"他们在门口上贴了一张通知。 — Họ đã dán một tờ thông báo trên cửa."},{"id":"w_37_28","hsk":3,"lesson":37,"hanzi":"通知","pinyin":"tōngzhī","pos":"Động từ/ Danh từ","hanviet":"thông tri","meaning":"thông báo","example":"我们昨天发的通知，你收到了吗？ — Thông báo chúng tôi gửi hôm qua, bạn nhận được chưa?"},{"id":"w_37_29","hsk":3,"lesson":37,"hanzi":"暂停","pinyin":"zàntíng","pos":"Động từ","hanviet":"tạm đình","meaning":"tạm dừng","example":"比赛暂停了十分钟。 — Trận đấu đã tạm dừng mười phút."},{"id":"w_37_30","hsk":3,"lesson":37,"hanzi":"营业","pinyin":"yíngyè","pos":"Động từ","hanviet":"doanh nghiệp","meaning":"kinh doanh","example":"这家超市的营业时间是早上八点到晚上十点。 — Thời gian mở cửa kinh doanh của siêu thị này là từ 8 giờ sáng đến 10 giờ tối."},{"id":"w_37_31","hsk":3,"lesson":37,"hanzi":"够","pinyin":"gòu","pos":"Tính từ","hanviet":"cấu","meaning":"đủ, đạt được","example":"这些菜够五个人吃吗？ — Chỗ thức ăn này có đủ cho 5 người ăn không?"},{"id":"w_37_32","hsk":3,"lesson":37,"hanzi":"算","pinyin":"suàn","pos":"Động từ","hanviet":"toán","meaning":"coi như, tính như","example":"他算是我最好的朋友。 — Anh ấy coi như/được xem là người bạn thân nhất của tôi."},{"id":"w_37_33","hsk":3,"lesson":37,"hanzi":"多的是","pinyin":"duō de shì","pos":"Cụm từ","hanviet":"đa đích thị","meaning":"nhiều lắm, đầy ra, thiếu gì","example":"这种水果，超市里多的是。 — Loại trái cây này, trong siêu thị có đầy ra đấy."},{"id":"w_37_34","hsk":3,"lesson":37,"hanzi":"亲眼","pinyin":"qīnyǎn","pos":"Phó từ","hanviet":"thân nhãn","meaning":"tận mắt","example":"这是我亲眼看见的，不会错。 — Đây là tôi tận mắt nhìn thấy, không sai được đâu."},{"id":"w_37_35","hsk":3,"lesson":37,"hanzi":"世界杯","pinyin":"Shìjièbēi","pos":"Danh từ","hanviet":"thế giới bôi","meaning":"World Cup"},{"id":"w_37_36","hsk":3,"lesson":37,"hanzi":"准","pinyin":"zhǔn","pos":"Tính từ/ Động từ","hanviet":"chuẩn","meaning":"cho phép","example":"他的发音很准。 — Phát âm của anh ấy rất chuẩn."},{"id":"w_37_37","hsk":3,"lesson":37,"hanzi":"辞职","pinyin":"cí zhí","pos":"Động từ ly hợp","hanviet":"từ chức","meaning":"từ chức, thôi việc","example":"他已经辞职好几天了，现在在家里休息。 — Anh ấy đã nghỉ việc mấy ngày rồi, giờ đang ở nhà nghỉ ngơi."},{"id":"w_37_38","hsk":3,"lesson":37,"hanzi":"最后","pinyin":"zuìhòu","pos":"Danh từ","hanviet":"tối hậu","meaning":"cuối cùng","example":"这是我最后一次帮助你。 — Đây là lần cuối cùng tôi giúp bạn."},{"id":"w_37_39","hsk":3,"lesson":37,"hanzi":"成","pinyin":"chéng","pos":"Động từ/ BN kết quả","hanviet":"thành","meaning":"thành, trở thành","example":"未来我想成为一名医生。 — Tương lai tôi muốn trở thành bác sĩ."},{"id":"w_37_40","hsk":3,"lesson":37,"hanzi":"佩服","pinyin":"pèifú","pos":"Động từ","hanviet":"bội phục","meaning":"bái phục","example":"他一分钟能写五十个汉字，真让人佩服。 — Một phút anh ấy có thể viết 50 chữ Hán, thật khiến người ta khâm phục."},{"id":"w_37_41","hsk":3,"lesson":37,"hanzi":"棒","pinyin":"bàng","pos":"Tính từ","hanviet":"bổng","meaning":"giỏi, cừ khôi","example":"你的汉语说得真棒！ — Tiếng Trung của bạn nói thật là tuyệt!"},{"id":"w_37_42","hsk":3,"lesson":37,"hanzi":"欧洲","pinyin":"Ōuzhōu","pos":"Danh từ riêng","hanviet":"Âu Châu","meaning":"Châu Âu"},{"id":"w_37_43","hsk":3,"lesson":37,"hanzi":"夏雨","pinyin":"Xià Yǔ","pos":"Danh từ riêng","hanviet":"Hạ Vũ","meaning":"Hạ Vũ (tên người)"}],"dialogue":[{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"Kể","zh":"关经理的护照不知道放在什么地方了，他要妻子夏雨帮他找……","py":"Guān jīnglǐ de hùzhào bù zhīdào fàng zài shénme dìfang le, tā yào qīzi Xià Yǔ bāng tā zhǎo……","vi":"Giám đốc Quan không biết đã để hộ chiếu ở đâu, anh ấy nhờ vợ là Hạ Vũ tìm giúp…"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"我的护照你找到了没有？","py":"Wǒ de hùzhào nǐ zhǎodào le méiyǒu?","vi":"Hộ chiếu của anh em tìm thấy chưa?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"没有，我找了半天也没找着。你是不是放在办公室了？","py":"Méiyǒu, wǒ zhǎo le bàntiān yě méi zhǎozháo. Nǐ shì bu shì fàng zài bàngōngshì le?","vi":"Chưa, em tìm mãi mà vẫn không thấy. Có phải anh để ở văn phòng rồi không?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"护照我从来不往办公室里放。","py":"Hùzhào wǒ cónglái bù wǎng bàngōngshì lǐ fàng.","vi":"Hộ chiếu thì anh xưa nay chưa bao giờ để ở văn phòng."},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"昨天你办完签证放在什么地方了？","py":"Zuótiān nǐ bàn wán qiānzhèng fàng zài shénme dìfang le?","vi":"Hôm qua làm xong visa anh để nó ở đâu?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"放在我的手提包里了。","py":"Fàng zài wǒ de shǒutíbāo lǐ le.","vi":"Để trong túi xách của anh."},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"你的包呢？","py":"Nǐ de bāo ne?","vi":"Thế túi của anh đâu?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"我一回到家不是就交给你了吗？","py":"Wǒ yì huí dào jiā bú shì jiù jiāo gěi nǐ le ma?","vi":"Chẳng phải anh vừa về đến nhà là đưa cho em rồi sao?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"对。我再好好儿找找。啊，找到了！","py":"Duì. Wǒ zài hǎohāor zhǎozhao. À, zhǎodào le!","vi":"Đúng rồi. Để em tìm lại kỹ xem. A, tìm thấy rồi!"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"是在包里找到的吗？","py":"Shì zài bāo lǐ zhǎodào de ma?","vi":"Tìm thấy trong túi à?"},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"不是，在你的大衣口袋里找到的。","py":"Bú shì, zài nǐ de dàyī kǒudai lǐ zhǎodào de.","vi":"Không, tìm thấy trong túi áo khoác của anh."},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"关","zh":"啊，我忘了。是我昨天晚上放到口袋里的。","py":"À, wǒ wàng le. Shì wǒ zuótiān wǎnshang fàng dào kǒudai lǐ de.","vi":"À, anh quên mất. Là tối qua anh cho vào túi áo."},{"section":"Bài khóa 1: 我的护照你找到了没有","speaker":"夏","zh":"你最近总是丢三落四的。","py":"Nǐ zuìjìn zǒngshì diūsān-làsì de.","vi":"Dạo này anh cứ hay quên trước quên sau."},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"你喜欢足球吗？","py":"Nǐ xǐhuan zúqiú ma?","vi":"Bạn có thích bóng đá không?"},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"一般，你呢？","py":"Yìbān, nǐ ne?","vi":"Bình thường thôi, còn bạn?"},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"你没发现吗？我可是个球迷。","py":"Nǐ méi fāxiàn ma? Wǒ kě shì ge qiúmí.","vi":"Bạn không nhận ra à? Tôi đúng là một fan bóng đá đấy."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"迷到什么程度？","py":"Mí dào shénme chéngdù?","vi":"Mê đến mức nào?"},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"为了看球，饭我可以不吃，觉我可以不睡，工作我可以不干。","py":"Wèile kàn qiú, fàn wǒ kěyǐ bù chī, jiào wǒ kěyǐ bú shuì, gōngzuò wǒ kěyǐ bú gàn.","vi":"Để xem bóng đá, cơm tôi có thể không ăn, ngủ tôi có thể không ngủ, việc tôi có thể không làm."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"我看球迷一个个都有点儿不正常。","py":"Wǒ kàn qiúmí yí gègè dōu yǒudiǎnr bú zhèngcháng.","vi":"Tôi thấy các fan bóng đá ai nấy đều hơi không bình thường."},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"我也承认。有时候迷到了发狂的程度。欧锦赛（欧洲足球锦标赛）期间，我像生了病一样。白天想睡觉，一到晚上就特别有精神。","py":"Wǒ yě chéngrèn. Yǒushíhou mí dào le fākuáng de chéngdù. Ōujǐnsài (Ōuzhōu zúqiú jǐnbiāosài) qījiān, wǒ xiàng shēng le bìng yíyàng. Báitiān xiǎng shuìjiào, yí dào wǎnshang jiù tèbié yǒu jīngshen.","vi":"Tôi cũng thừa nhận. Có lúc mê đến mức phát cuồng. Trong thời gian diễn ra Euro (Giải vô địch bóng đá châu Âu), tôi như người bị ốm vậy. Ban ngày thì buồn ngủ, cứ đến tối là đặc biệt tỉnh táo."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"你白天不工作吗？","py":"Nǐ báitiān bù gōngzuò ma?","vi":"Ban ngày bạn không làm việc à?"},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"这个商店是我自己开的，我在门上贴了一张通知：“暂停营业”。","py":"Zhège shāngdiàn shì wǒ zìjǐ kāi de, wǒ zài mén shang tiē le yì zhāng tōngzhī: “Zàntíng yíngyè”.","vi":"Cửa hàng này là tôi tự mở, tôi dán lên cửa một tờ thông báo: “Tạm ngừng kinh doanh”."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"你可真够迷的。","py":"Nǐ kě zhēn gòu mí de.","vi":"Bạn đúng là mê thật đấy."},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"我还不算最迷的。","py":"Wǒ hái bú suàn zuì mí de.","vi":"Tôi vẫn chưa phải là người mê nhất đâu."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"还有比你更迷的吗？","py":"Hái yǒu bǐ nǐ gèng mí de ma?","vi":"Còn có người mê hơn cả bạn à?"},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"有，多的是。我有一个朋友，在一家外国公司工作，为了能去国外亲眼看看世界杯足球赛，他向老板请假，老板不准，他就辞职不干了。","py":"Yǒu, duō de shì. Wǒ yǒu yí ge péngyou, zài yì jiā wàiguó gōngsī gōngzuò, wèile néng qù guówài qīnyǎn kànkan Shìjièbēi zúqiúsài, tā xiàng lǎobǎn qǐngjià, lǎobǎn bù zhǔn, tā jiù cízhí bú gàn le.","vi":"Có chứ, nhiều lắm. Tôi có một người bạn làm việc ở một công ty nước ngoài, để có thể ra nước ngoài tận mắt xem World Cup, anh ấy xin sếp nghỉ phép, sếp không cho, thế là anh ấy nghỉ việc luôn."},{"section":"Bài khóa 2: 我是球迷","speaker":"B","zh":"最后去成了吗？","py":"Zuìhòu qù chéng le ma?","vi":"Cuối cùng có đi được không?"},{"section":"Bài khóa 2: 我是球迷","speaker":"A","zh":"去成了。我真佩服他。能去亲眼看看世界杯赛，太棒了。","py":"Qù chéng le. Wǒ zhēn pèifú tā. Néng qù qīnyǎn kànkan Shìjièbēi sài, tài bàng le.","vi":"Đi được rồi. Tôi thật sự phục anh ấy. Được tận mắt xem World Cup, tuyệt quá."}],"grammar":["Câu vị ngữ chủ vị: Câu có cụm chủ – vị làm vị ngữ: Chủ ngữ lớn (Danh từ 1) + [Chủ ngữ nhỏ (Danh từ 2) + Động từ] (足球你喜欢吗？饭我可以不吃，觉我可以不睡，工作我可以不干。我的护照你找到了没有？)","Bổ ngữ kết quả 在: Động từ + 在 + Tân ngữ (nơi chốn) biểu thị thông qua động tác khiến người hoặc vật ở một vị trí nhất định (我的词典你放在哪儿了？— 就放在你的口袋里了。这张画我们挂在哪儿呢？— 挂在这儿吧。)","Bổ ngữ kết quả 着 (zháo): Động từ + 着 biểu thị mục đích của động tác đã đạt được hoặc có kết quả (你要的那本书我给你买着了。我的护照你给我找着了没有？你睡着了吗？)","Bổ ngữ kết quả 好: Động từ + 好 biểu thị động tác đã hoàn thành và đạt đến mức hoàn thiện, khiến người ta hài lòng — xong và tốt (你的衣服洗好了吗？昨天晚上我没有睡好。我跟老板商量好了。)","Bổ ngữ kết quả 成: Động từ + 成 biểu thị động tác hoàn thành, đạt được mục đích, hoặc khiến sự vật thay đổi, hoặc dẫn đến kết quả sai sót (最后去成了吗？— 去成了。这篇故事他翻译成了英语。这个“我”字你写成“找”字了。)","Chú thích 半天 và 我看: 半天 trong 我找了半天也没找着 cho thấy người nói cảm thấy thời gian khá dài; 我看 trong 我看球迷一个个都有点儿不正常 nghĩa là “tôi cho rằng, tôi nghĩ”, biểu thị câu phía sau là quan điểm, ý kiến của mình"]},{"id":38,"hsk":3,"zh_title":"我的眼镜摔坏了","pinyin_title":"Wǒ de yǎnjìng shuāihuài le","title":"Kính của tôi rơi hỏng rồi","words":[{"id":"w_38_1","hsk":3,"lesson":38,"hanzi":"照","pinyin":"zhào","pos":"Động từ","hanviet":"chiếu","meaning":"chụp (ảnh), soi (gương), chiếu sáng"},{"id":"w_38_2","hsk":3,"lesson":38,"hanzi":"洗","pinyin":"xǐ","pos":"Động từ","hanviet":"tẩy","meaning":"giặt, rửa","example":"洗照片 — Rửa ảnh."},{"id":"w_38_3","hsk":3,"lesson":38,"hanzi":"闭","pinyin":"bì","pos":"Động từ","hanviet":"bế","meaning":"đóng, nhắm (mắt), ngậm (miệng)","example":"照相的时候请不要闭眼睛。 — Khi chụp ảnh xin vui lòng đừng nhắm mắt."},{"id":"w_38_4","hsk":3,"lesson":38,"hanzi":"油画","pinyin":"yóuhuà","pos":"Danh từ","hanviet":"du họa","meaning":"tranh sơn dầu"},{"id":"w_38_5","hsk":3,"lesson":38,"hanzi":"放大","pinyin":"fàngdà","pos":"Động từ","hanviet":"phóng đại","meaning":"phóng to","example":"这张照片太小了，我想放大。 — Tấm ảnh này nhỏ quá, tôi muốn phóng to nó ra."},{"id":"w_38_6","hsk":3,"lesson":38,"hanzi":"倍","pinyin":"bèi","pos":"Lượng từ","hanviet":"bội","meaning":"lần","example":"放大一倍？ — Phóng to gấp đôi?"},{"id":"w_38_7","hsk":3,"lesson":38,"hanzi":"公分","pinyin":"gōngfēn","pos":"Lượng từ","hanviet":"công phần","meaning":"cm (xen-ti-mét)"},{"id":"w_38_8","hsk":3,"lesson":38,"hanzi":"差一点儿","pinyin":"chàyīdiǎnr","pos":"Phó từ","hanviet":"sai nhất điểm nhi","meaning":"kém một chút, suýt"},{"id":"w_38_9","hsk":3,"lesson":38,"hanzi":"碰","pinyin":"pèng","pos":"Động từ","hanviet":"bàng","meaning":"va, chạm, gặp, đâm","example":"头碰了一下桌子，好疼啊！ — Đầu va vào cái bàn một cái, đau quá!"},{"id":"w_38_10","hsk":3,"lesson":38,"hanzi":"起","pinyin":"qǐ","pos":"Lượng từ","hanviet":"khởi","meaning":"vụ"},{"id":"w_38_11","hsk":3,"lesson":38,"hanzi":"事故","pinyin":"shìgù","pos":"Danh từ","hanviet":"sự cố","meaning":"sự cố, tai nạn","example":"这里的交通很安全，很少出事故。 — Giao thông ở đây rất an toàn, hiếm khi xảy ra tai nạn."},{"id":"w_38_12","hsk":3,"lesson":38,"hanzi":"整","pinyin":"zhěng","pos":"Tính từ/ Phó từ","hanviet":"chỉnh","meaning":"chẵn, tròn, đúng","example":"为了看世界杯，他整天不睡觉。 — Để xem World Cup, anh ta cả ngày không ngủ."},{"id":"w_38_13","hsk":3,"lesson":38,"hanzi":"眼镜","pinyin":"yǎnjìng","pos":"Danh từ","hanviet":"nhãn kính","meaning":"kính, kính mắt","example":"我想去眼镜店换一个新眼镜。 — Tôi muốn đến cửa hàng kính để đổi một chiếc kính mới."},{"id":"w_38_14","hsk":3,"lesson":38,"hanzi":"别提了","pinyin":"bié tí le","pos":"Cụm giao tiếp","hanviet":"biệt đề liễu","meaning":"đừng nhắc đến nữa"},{"id":"w_38_15","hsk":3,"lesson":38,"hanzi":"倒霉","pinyin":"dǎoméi","pos":"Tính từ","hanviet":"đảo mai","meaning":"đen đủi, xui xẻo","example":"今天太倒霉了，一出门就下大雨，大衣都湿了。 — Hôm nay xui xẻo quá, vừa ra cửa là mưa to, áo khoác ướt hết sạch rồi."},{"id":"w_38_16","hsk":3,"lesson":38,"hanzi":"摔跤","pinyin":"shuāi jiāo","pos":"Động từ ly hợp","hanviet":"suất giao","meaning":"ngã, té","example":"她跑得太快，结果摔了跤。 — Cô ấy chạy quá nhanh, kết quả là bị ngã."},{"id":"w_38_17","hsk":3,"lesson":38,"hanzi":"摔","pinyin":"shuāi","pos":"Động từ","hanviet":"suất","meaning":"rơi, ném, quăng"},{"id":"w_38_18","hsk":3,"lesson":38,"hanzi":"掉","pinyin":"diào","pos":"Động từ","hanviet":"điệu","meaning":"rơi","example":"我的手机不知道掉在哪儿了。 — Điện thoại của tôi không biết rơi ở đâu mất rồi."},{"id":"w_38_19","hsk":3,"lesson":38,"hanzi":"地上","pinyin":"dìshang","pos":"Danh từ","hanviet":"địa thượng","meaning":"trên mặt đất, trên sàn nhà","example":"地上有一张放假通知，是谁掉的？ — Trên mặt đất có một tờ thông báo nghỉ lễ, là ai làm rơi thế?"},{"id":"w_38_20","hsk":3,"lesson":38,"hanzi":"上班","pinyin":"shàng bān","pos":"Động từ ly hợp","hanviet":"thượng ban","meaning":"đi làm","example":"我爸爸每天早上八点上班，下午五点下班。 — Bố tôi ngày nào cũng đi làm lúc 8 giờ sáng, tan làm lúc 5 giờ chiều."},{"id":"w_38_21","hsk":3,"lesson":38,"hanzi":"下班","pinyin":"xià bān","pos":"Động từ ly hợp","hanviet":"hạ ban","meaning":"tan ca, tan làm","example":"我爸爸每天早上八点上班，下午五点下班。 — Bố tôi ngày nào cũng đi làm lúc 8 giờ sáng, tan làm lúc 5 giờ chiều."},{"id":"w_38_22","hsk":3,"lesson":38,"hanzi":"保证","pinyin":"bǎozhèng","pos":"Động từ","hanviet":"bảo chứng","meaning":"bảo đảm","example":"我保证，以后再也不迟到了。 — Tôi bảo đảm/hứa, từ nay về sau sẽ không đến muộn nữa."},{"id":"w_38_23","hsk":3,"lesson":38,"hanzi":"遵守","pinyin":"zūnshǒu","pos":"Động từ","hanviet":"tuân thủ","meaning":"tuân thủ","example":"开车的时候，一定要遵守交通规则。 — Khi lái xe, nhất định phải tuân thủ luật giao thông."},{"id":"w_38_24","hsk":3,"lesson":38,"hanzi":"规则","pinyin":"guīzé","pos":"Danh từ","hanviet":"quy tắc","meaning":"quy tắc, luật"},{"id":"w_38_25","hsk":3,"lesson":38,"hanzi":"造成","pinyin":"zàochéng","pos":"Động từ","hanviet":"tạo thành","meaning":"gây ra, dẫn đến (kết quả xấu)","example":"刚才那场大雨，给交通造成了很大的麻烦。 — Cơn mưa lớn vừa nãy đã gây ra rắc rối lớn cho giao thông."},{"id":"w_38_26","hsk":3,"lesson":38,"hanzi":"拥挤","pinyin":"yōngjǐ","pos":"Động từ/ Tính từ","hanviet":"ủng tễ","meaning":"chen chúc, chật chội","example":"世界杯期间，体育场附近总是非常拥挤。 — Trong thời gian diễn ra World Cup, xung quanh sân vận động luôn luôn cực kỳ đông đúc."},{"id":"w_38_27","hsk":3,"lesson":38,"hanzi":"主要","pinyin":"zhǔyào","pos":"Tính từ","hanviet":"chủ yếu","meaning":"chủ yếu, chính","example":"这本书的主要内容是写中国经济的发展。 — Nội dung chính của cuốn sách này là viết về sự phát triển kinh tế của Trung Quốc."},{"id":"w_38_28","hsk":3,"lesson":38,"hanzi":"原因","pinyin":"yuányīn","pos":"Danh từ","hanviet":"nguyên nhân","meaning":"nguyên nhân","example":"这就是他不去中国留学的主要原因。 — Đây chính là nguyên nhân chính anh ấy không đi Trung Quốc du học."},{"id":"w_38_29","hsk":3,"lesson":38,"hanzi":"之一","pinyin":"zhī yī","pos":"Cụm từ","hanviet":"chi nhất","meaning":"một trong những","example":"深圳是中国最现代化的城市之一。 — Thâm Quyến là một trong những thành phố hiện đại hóa nhất của Trung Quốc."},{"id":"w_38_30","hsk":3,"lesson":38,"hanzi":"引起","pinyin":"yǐnqǐ","pos":"Động từ","hanviet":"dẫn khởi","meaning":"gây ra, dẫn tới","example":"这件事情引起了大家的注意。 — Sự việc này đã thu hút/gây ra sự chú ý của mọi người."},{"id":"w_38_31","hsk":3,"lesson":38,"hanzi":"赶快","pinyin":"gǎnkuài","pos":"Phó từ","hanviet":"cảm khoái","meaning":"mau chóng, khẩn trương","example":"要下雨了，我们赶快回家吧。 — Trời sắp mưa rồi, chúng ta mau chóng về nhà thôi."},{"id":"w_38_32","hsk":3,"lesson":38,"hanzi":"发展","pinyin":"fāzhǎn","pos":"Động từ/ Danh từ","hanviet":"phát triển","meaning":"phát triển","example":"这些年，越南的经济发展得特别快。 — Những năm gần đây, kinh tế của Việt Nam phát triển đặc biệt nhanh."}],"dialogue":[{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"Kể","zh":"（玛丽和麦克在看刚洗好的照片……）","py":"(Mǎlì hé Màikè zài kàn gāng xǐhǎo de zhàopiàn……)","vi":"(Mary và Mike đang xem những tấm ảnh vừa rửa xong…)"},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"玛丽","zh":"我们在长城照的照片洗好了吗？","py":"Wǒmen zài Chángchéng zhào de zhàopiàn xǐhǎo le ma?","vi":"Ảnh chúng mình chụp ở Vạn Lý Trường Thành rửa xong chưa?"},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"麦克","zh":"洗好了。","py":"Xǐhǎo le.","vi":"Rửa xong rồi."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"玛丽","zh":"照得怎么样？快让我看看。","py":"Zhào de zěnmeyàng? Kuài ràng wǒ kànkan.","vi":"Chụp thế nào? Mau cho tớ xem với."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"麦克","zh":"这些照得非常好，张张都很漂亮。这些照得不太好。","py":"Zhèxiē zhào de fēicháng hǎo, zhāngzhāng dōu hěn piàoliang. Zhèxiē zhào de bú tài hǎo.","vi":"Mấy tấm này chụp rất đẹp, tấm nào cũng đẹp. Mấy tấm này chụp không đẹp lắm."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"玛丽","zh":"这张也没照好，人照小了，一点儿也不清楚。你再看看这张，眼睛都闭上了，像睡着了一样。","py":"Zhè zhāng yě méi zhàohǎo, rén zhào xiǎo le, yìdiǎnr yě bù qīngchu. Nǐ zài kànkan zhè zhāng, yǎnjing dōu bìshang le, xiàng shuìzháo le yíyàng.","vi":"Tấm này cũng chụp không đẹp, người bị chụp nhỏ quá, chẳng rõ chút nào. Cậu xem tiếp tấm này, mắt nhắm tịt cả lại, giống như đang ngủ vậy."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"麦克","zh":"这张怎么样？","py":"Zhè zhāng zěnmeyàng?","vi":"Tấm này thế nào?"},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"玛丽","zh":"不怎么样。洗得不太好，颜色深了一点儿。这两张洗得最好，像油画一样。","py":"Bù zěnmeyàng. Xǐ de bú tài hǎo, yánsè shēnle yìdiǎnr. Zhè liǎng zhāng xǐ de zuì hǎo, xiàng yóuhuà yíyàng.","vi":"Chẳng ra sao cả. Rửa không đẹp lắm, màu hơi đậm một chút. Hai tấm này rửa đẹp nhất, giống như tranh sơn dầu vậy."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"麦克","zh":"再放大两张吧。","py":"Zài fàngdà liǎng zhāng ba.","vi":"Phóng to thêm hai tấm nữa đi."},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"玛丽","zh":"放成多大的？放大一倍怎么样？","py":"Fàngchéng duō dà de? Fàngdà yí bèi zěnmeyàng?","vi":"Phóng thành cỡ bao nhiêu? Phóng to gấp đôi thì sao?"},{"section":"Bài khóa 1: 我们的照片洗好了","speaker":"麦克","zh":"放成十公分的就行了。","py":"Fàngchéng shí gōngfēn de jiù xíng le.","vi":"Phóng thành cỡ mười xen-ti-mét là được rồi."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"Kể","zh":"（一个下雪天的早上，在办公室里，两个人在说城市交通问题……）","py":"(Yí ge xià xuě tiān de zǎoshang, zài bàngōngshì li, liǎng ge rén zài shuō chéngshì jiāotōng wèntí……)","vi":"(Một buổi sáng tuyết rơi, trong văn phòng, hai người đang nói chuyện về vấn đề giao thông thành phố…)"},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小白","zh":"哎呀，差点儿迟到。","py":"Āiyā, chàdiǎnr chídào.","vi":"Ôi chao, suýt nữa thì muộn."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小黄","zh":"是开车来的吗？","py":"Shì kāi chē lái de ma?","vi":"Cậu lái xe đến à?"},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小白","zh":"是，一下雪就堵车，又碰上一起交通事故，我的车在路上整整堵了二十分钟。","py":"Shì, yí xià xuě jiù dǔchē, yòu pèngshang yì qǐ jiāotōng shìgù, wǒ de chē zài lù shang zhěngzhěng dǔle èrshí fēnzhōng.","vi":"Ừ, hễ tuyết rơi là tắc đường, lại còn gặp phải một vụ tai nạn giao thông, xe tớ bị kẹt trên đường suốt hai mươi phút."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小黄","zh":"你的眼镜怎么了？","py":"Nǐ de yǎnjìng zěnme le?","vi":"Kính của cậu làm sao thế?"},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小白","zh":"别提了，今天倒霉得很。掉在地上摔坏了。","py":"Bié tí le, jīntiān dǎoméi de hěn. Diào zài dì shang shuāihuài le.","vi":"Đừng nhắc nữa, hôm nay xui xẻo lắm. Rơi xuống đất vỡ hỏng rồi."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小黄","zh":"几点从家里出来的？","py":"Jǐ diǎn cóng jiā li chūlai de?","vi":"Mấy giờ cậu ra khỏi nhà?"},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小白","zh":"六点钟就从家里出来了，你看，快八点了才到。","py":"Liù diǎn zhōng jiù cóng jiā li chūlai le, nǐ kàn, kuài bā diǎn le cái dào.","vi":"Sáu giờ đã ra khỏi nhà rồi, cậu xem, gần tám giờ mới tới nơi."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小黄","zh":"所以，我还是愿意骑车上班，骑车能保证时间，还可以锻炼身体。","py":"Suǒyǐ, wǒ háishi yuànyì qí chē shàngbān, qí chē néng bǎozhèng shíjiān, hái kěyǐ duànliàn shēntǐ.","vi":"Vì thế tớ vẫn thích đạp xe đi làm hơn, đạp xe đảm bảo được giờ giấc, lại còn rèn luyện được sức khỏe."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小白","zh":"可是，你别忘了，骑车的人太多，有的人又不遵守交通规则，也是造成交通拥挤的主要原因之一。今天的事故就是一辆自行车引起的。","py":"Kěshì, nǐ bié wàng le, qí chē de rén tài duō, yǒude rén yòu bù zūnshǒu jiāotōng guīzé, yě shì zàochéng jiāotōng yōngjǐ de zhǔyào yuányīn zhī yī. Jīntiān de shìgù jiù shì yí liàng zìxíngchē yǐnqǐ de.","vi":"Nhưng cậu đừng quên, người đi xe đạp quá đông, có người lại không tuân thủ luật giao thông, đó cũng là một trong những nguyên nhân chính gây ùn tắc giao thông. Vụ tai nạn hôm nay chính là do một chiếc xe đạp gây ra."},{"section":"Bài khóa 2: 我的眼镜摔坏了","speaker":"小黄","zh":"有汽车的人也一年比一年多，城市交通是一个大问题。我看最好还是赶快发展地铁。","py":"Yǒu qìchē de rén yě yì nián bǐ yì nián duō, chéngshì jiāotōng shì yí ge dà wèntí. Wǒ kàn zuìhǎo háishi gǎnkuài fāzhǎn dìtiě.","vi":"Người có ô tô cũng mỗi năm một nhiều hơn, giao thông thành phố là một vấn đề lớn. Tớ thấy tốt nhất vẫn là nhanh chóng phát triển tàu điện ngầm."}],"grammar":["Câu bị động ý nghĩa: Chủ ngữ là đối tượng tiếp nhận động tác + Động từ + thành phần khác, dùng để nhấn mạnh vào chủ ngữ (không cần 被). Ví dụ: 我的眼镜摔坏了。照片洗好了。我的护照找到了吗？她的字写得真不错。","Lặp lại lượng từ: Cả danh lượng từ và động lượng từ đều có thể lặp lại để biểu thị ý “mỗi”, “từng / mọi / tất cả”. Ví dụ: 这些照片张张照得都很好。我们班的同学个个都很努力。他们跟我们班赛足球场场输。","一年比一年 / 一天比一天: Diễn đạt mức độ thay đổi tăng dần của sự vật, sự việc theo thời gian (mỗi năm một… hơn / năm sau… hơn năm trước). Ví dụ: 有汽车的人一年比一年多。来中国以后，我一天比一天胖。","差（一）点儿 – suýt nữa: Với việc không tốt, động từ phía sau dù khẳng định hay phủ định đều có nghĩa là việc đó không xảy ra, mang ý may mắn (今天早上，我差点儿迟到。= 今天早上我差点儿没迟到。都是没有迟到). Với việc tốt: dạng phủ định là cuối cùng đã đạt được, mừng rỡ (我差点儿没考上大学。– đã đỗ); dạng khẳng định là cuối cùng không đạt được, tiếc nuối (去年，他差点儿就考上了。– không đỗ).","不怎么样 và Tính từ + 了（一）点儿: 不怎么样 nghĩa là không tốt, chẳng ra sao, biểu thị không vừa ý; Tính từ + 了（一）点儿 biểu thị so với một tiêu chuẩn nào đó thì mức độ không thích hợp, biểu thị không hài lòng. Ví dụ: 这条裤子长了一点儿。这本书贵了一点儿。颜色深了一点儿。","Tính từ + 得很: Phó từ 很 làm bổ ngữ (đứng sau 得) biểu thị mức độ cực kỳ cao. Ví dụ: 今天倒霉得很。听说北京的冬天冷得很。昨天的晚会开得好得很。"]},{"id":39,"hsk":3,"zh_title":"钥匙忘拔下来了","pinyin_title":"Yàoshi wàng bá xiàlai le","title":"Chìa khóa quên rút ra rồi","words":[{"id":"w_39_1","hsk":3,"lesson":39,"hanzi":"图书城","pinyin":"túshūchéng","pos":"Danh từ","hanviet":"đồ thư thành","meaning":"siêu thị sách"},{"id":"w_39_2","hsk":3,"lesson":39,"hanzi":"图书","pinyin":"túshū","pos":"Danh từ","hanviet":"đồ thư","meaning":"sách"},{"id":"w_39_3","hsk":3,"lesson":39,"hanzi":"进去","pinyin":"jìnqu","pos":"Bổ ngữ xu hướng kép","hanviet":"tiến khứ","meaning":"đi vào"},{"id":"w_39_4","hsk":3,"lesson":39,"hanzi":"各","pinyin":"gè","pos":"Đại từ","hanviet":"các","meaning":"các","example":"请各位同学注意，明天九点考试。 — Xin mời các bạn học sinh chú ý, ngày mai 9 giờ thi."},{"id":"w_39_5","hsk":3,"lesson":39,"hanzi":"各种各样","pinyin":"gè zhǒng gè yàng","pos":"Thành ngữ","hanviet":"các chủng các dạng","meaning":"đủ mọi loại, đa dạng, phong phú","example":"超市里有各种各样的水果。 — Trong siêu thị có đủ các loại trái cây."},{"id":"w_39_6","hsk":3,"lesson":39,"hanzi":"兴奋","pinyin":"xīngfèn","pos":"Tính từ","hanviet":"hưng phấn","meaning":"vui vẻ, hào hứng","example":"听到这个好消息，大家都非常兴奋。 — Nghe được tin tốt này, mọi người đều vô cùng hào hứng."},{"id":"w_39_7","hsk":3,"lesson":39,"hanzi":"书架","pinyin":"shūjià","pos":"Danh từ","hanviet":"thư giá","meaning":"giá sách","example":"书架上有很多各种各样的书。 — Trên giá sách có rất nhiều các loại sách khác nhau."},{"id":"w_39_8","hsk":3,"lesson":39,"hanzi":"下来","pinyin":"xiàlai","pos":"Bổ ngữ xu hướng kép","hanviet":"hạ lai","meaning":"xuống"},{"id":"w_39_9","hsk":3,"lesson":39,"hanzi":"回去","pinyin":"huíqu","pos":"Bổ ngữ xu hướng kép","hanviet":"hồi khứ","meaning":"về, quay về"},{"id":"w_39_10","hsk":3,"lesson":39,"hanzi":"抽","pinyin":"chōu","pos":"Động từ","hanviet":"trừu","meaning":"rút","example":"他从书架上抽出来一本书。 — Anh ấy rút ra từ giá sách một cuốn sách."},{"id":"w_39_11","hsk":3,"lesson":39,"hanzi":"挑","pinyin":"tiāo","pos":"Động từ","hanviet":"khiêu","meaning":"nhặt, kén, lựa chọn","example":"网上的商品太多了，真难挑。 — Hàng hóa trên mạng nhiều quá, thật khó chọn."},{"id":"w_39_12","hsk":3,"lesson":39,"hanzi":"选","pinyin":"xuǎn","pos":"Động từ","hanviet":"tuyển","meaning":"lựa chọn","example":"A：你选哪件衣服？B：两件都很漂亮。 — A: Bạn chọn bộ quần áo nào? B: Hai bộ đều rất đẹp."},{"id":"w_39_13","hsk":3,"lesson":39,"hanzi":"小说","pinyin":"xiǎoshuō","pos":"Danh từ","hanviet":"tiểu thuyết","meaning":"tiểu thuyết"},{"id":"w_39_14","hsk":3,"lesson":39,"hanzi":"除了…（以外）","pinyin":"chúle…yǐwài","pos":"Giới từ","hanviet":"trừ liễu… dĩ ngoại","meaning":"ngoài… ra","example":"除了英语以外，我还会说汉语。 — Ngoài tiếng Anh ra, tôi còn biết nói tiếng Trung."},{"id":"w_39_15","hsk":3,"lesson":39,"hanzi":"于是","pinyin":"yúshì","pos":"Liên từ","hanviet":"vu thị","meaning":"thế nên, thế là","example":"医生说他生病了不能去上班，于是他向公司请假了。 — Bác sĩ nói anh ấy bị ốm không thể đi làm, thế là anh ấy xin công ty nghỉ phép."},{"id":"w_39_16","hsk":3,"lesson":39,"hanzi":"音像","pinyin":"yīnxiàng","pos":"Danh từ","hanviet":"âm tượng","meaning":"media (nghe nhìn)"},{"id":"w_39_17","hsk":3,"lesson":39,"hanzi":"这里","pinyin":"zhèli","pos":"Đại từ chỉ nơi chốn","hanviet":"giá lý","meaning":"ở đây"},{"id":"w_39_18","hsk":3,"lesson":39,"hanzi":"那里","pinyin":"nàli","pos":"Đại từ chỉ nơi chốn","hanviet":"na lý","meaning":"ở kia"},{"id":"w_39_19","hsk":3,"lesson":39,"hanzi":"根据","pinyin":"gēnjù","pos":"Giới từ/ Danh từ","hanviet":"căn cứ","meaning":"căn cứ","example":"根据学校的放假通知，我们下个星期不用上课。 — Căn cứ vào thông báo nghỉ lễ của trường, chúng ta tuần sau không phải lên lớp."},{"id":"w_39_20","hsk":3,"lesson":39,"hanzi":"拍","pinyin":"pāi","pos":"Động từ","hanviet":"phách","meaning":"chụp, quay (phim)"},{"id":"w_39_21","hsk":3,"lesson":39,"hanzi":"盒","pinyin":"hé","pos":"Lượng từ/ Danh từ","hanviet":"hạp","meaning":"hộp","example":"这盒饭是谁的？ — Hộp cơm này là của ai vậy?"},{"id":"w_39_22","hsk":3,"lesson":39,"hanzi":"学期","pinyin":"xuéqī","pos":"Danh từ","hanviet":"học kỳ","meaning":"học kỳ"},{"id":"w_39_23","hsk":3,"lesson":39,"hanzi":"纸箱","pinyin":"zhǐxiāng","pos":"Danh từ","hanviet":"chỉ tương","meaning":"thùng giấy"},{"id":"w_39_24","hsk":3,"lesson":39,"hanzi":"纸","pinyin":"zhǐ","pos":"Danh từ","hanviet":"chỉ","meaning":"giấy"},{"id":"w_39_25","hsk":3,"lesson":39,"hanzi":"饭馆","pinyin":"fànguǎn","pos":"Danh từ","hanviet":"phạn quán","meaning":"nhà hàng, quán ăn (quy mô vừa và nhỏ)"},{"id":"w_39_26","hsk":3,"lesson":39,"hanzi":"盘","pinyin":"pán","pos":"Danh từ/ Lượng từ","hanviet":"bàn","meaning":"cái đĩa, khay"},{"id":"w_39_27","hsk":3,"lesson":39,"hanzi":"累","pinyin":"lèi","pos":"Tính từ","hanviet":"lụy","meaning":"mệt"},{"id":"w_39_28","hsk":3,"lesson":39,"hanzi":"困","pinyin":"kùn","pos":"Tính từ","hanviet":"khốn","meaning":"buồn ngủ"},{"id":"w_39_29","hsk":3,"lesson":39,"hanzi":"电梯","pinyin":"diàntī","pos":"Danh từ","hanviet":"điện thê","meaning":"thang máy"},{"id":"w_39_30","hsk":3,"lesson":39,"hanzi":"修","pinyin":"xiū","pos":"Động từ","hanviet":"tu","meaning":"sửa","example":"我的电脑坏了，我要去修一下。 — Máy tính tôi hỏng rồi, tôi phải đi sửa."},{"id":"w_39_31","hsk":3,"lesson":39,"hanzi":"维修","pinyin":"wéixiū","pos":"Động từ","hanviet":"duy tu","meaning":"sửa chữa, bảo trì","example":"门口贴着一张通知：电梯正在维修，请走楼梯。 — Trên cửa dán một tờ thông báo: Thang máy đang bảo trì, mời đi thang bộ."},{"id":"w_39_32","hsk":3,"lesson":39,"hanzi":"楼梯","pinyin":"lóutī","pos":"Danh từ","hanviet":"lâu thê","meaning":"cầu thang"},{"id":"w_39_33","hsk":3,"lesson":39,"hanzi":"只好","pinyin":"zhǐhǎo","pos":"Phó từ","hanviet":"chỉ hảo","meaning":"đành phải, chỉ có thể","example":"这家饭馆人太多，我们只好换一家。 — Quán ăn này đông quá, chúng tôi đành phải đổi quán."},{"id":"w_39_34","hsk":3,"lesson":39,"hanzi":"提","pinyin":"tí","pos":"Động từ","hanviet":"đề","meaning":"nhấc, xách; đề cập"},{"id":"w_39_35","hsk":3,"lesson":39,"hanzi":"步","pinyin":"bù","pos":"Lượng từ/ Danh từ","hanviet":"bộ","meaning":"bước"},{"id":"w_39_36","hsk":3,"lesson":39,"hanzi":"钥匙","pinyin":"yàoshi","pos":"Danh từ","hanviet":"thược thi","meaning":"chìa khóa"},{"id":"w_39_37","hsk":3,"lesson":39,"hanzi":"却","pinyin":"què","pos":"Phó từ","hanviet":"khước","meaning":"nhưng, lại","example":"虽然遇到了很多问题，他却一点儿也不担心。 — Mặc dù gặp phải rất nhiều vấn đề, anh ấy lại chẳng lo lắng chút nào."},{"id":"w_39_38","hsk":3,"lesson":39,"hanzi":"忽然","pinyin":"hūrán","pos":"Phó từ","hanviet":"hốt nhiên","meaning":"bỗng nhiên, đột nhiên","example":"天气刚才还是很好，忽然下雨下得很大。 — Thời tiết vừa nãy còn rất tốt, bỗng nhiên lại đổ mưa to."},{"id":"w_39_39","hsk":3,"lesson":39,"hanzi":"想起来","pinyin":"xiǎng qǐlai","pos":"Động từ + BN kết quả","hanviet":"tưởng khởi lai","meaning":"nhớ ra, nhớ lại","example":"看到在门口贴的通知，我才想起来今天电梯维修。 — Nhìn thấy tờ thông báo dán ở cửa, tôi mới nhớ ra hôm nay thang máy bảo trì."},{"id":"w_39_40","hsk":3,"lesson":39,"hanzi":"插","pinyin":"chā","pos":"Động từ","hanviet":"tháp","meaning":"cắm vào, chêm vào"},{"id":"w_39_41","hsk":3,"lesson":39,"hanzi":"拔","pinyin":"bá","pos":"Động từ","hanviet":"bạt","meaning":"nhổ, lấy, rút","example":"门开了以后，别忘了把钥匙拔下来。 — Sau khi cửa mở rồi, đừng quên rút chìa khóa ra đấy."},{"id":"w_39_42","hsk":3,"lesson":39,"hanzi":"哭笑不得","pinyin":"kū xiào bù dé","pos":"Thành ngữ","hanviet":"khốc tiếu bất đắc","meaning":"dở khóc dở cười"},{"id":"w_39_43","hsk":3,"lesson":39,"hanzi":"鲁迅","pinyin":"Lǔ Xùn","pos":"Danh từ riêng","hanviet":"Lỗ Tấn","meaning":"Lỗ Tấn"},{"id":"w_39_44","hsk":3,"lesson":39,"hanzi":"《药》","pinyin":"Yào","pos":"Danh từ riêng","hanviet":"Dược","meaning":"Thuốc (tên tác phẩm)"},{"id":"w_39_45","hsk":3,"lesson":39,"hanzi":"《祝福》","pinyin":"Zhùfú","pos":"Danh từ riêng","hanviet":"Chúc phúc","meaning":"Chúc phúc (tên tác phẩm)"}],"dialogue":[{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"星期天，我和麦克一起骑车到图书城去买书。图书城离我们学校比较远。那天刮风，我们骑了一个多小时才骑到。","py":"Xīngqītiān, wǒ hé Màikè yìqǐ qí chē dào túshūchéng qù mǎi shū. Túshūchéng lí wǒmen xuéxiào bǐjiào yuǎn. Nà tiān guā fēng, wǒmen qíle yí ge duō xiǎoshí cái qídào.","vi":"Chủ nhật, tôi và Mike cùng đạp xe đến siêu thị sách mua sách. Siêu thị sách cách trường chúng tôi khá xa. Hôm đó trời nổi gió, chúng tôi đạp hơn một tiếng đồng hồ mới tới nơi."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"图书城很大，里边有很多书店。每个书店我都想进去看看。我们从一个书店走出来，又走进另一个书店。","py":"Túshūchéng hěn dà, lǐbian yǒu hěn duō shūdiàn. Měi ge shūdiàn wǒ dōu xiǎng jìnqu kànkan. Wǒmen cóng yí ge shūdiàn zǒu chūlai, yòu zǒujìn lìng yí ge shūdiàn.","vi":"Siêu thị sách rất lớn, bên trong có rất nhiều hiệu sách. Hiệu sách nào tôi cũng muốn vào xem thử. Chúng tôi vừa từ hiệu sách này đi ra lại bước vào một hiệu sách khác."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"看到书店里有各种各样的书，我很兴奋。从这个书架上拿下来一本看看，再放上去，又从另一个书架上抽出来一本看看。","py":"Kàndào shūdiàn li yǒu gè zhǒng gè yàng de shū, wǒ hěn xīngfèn. Cóng zhège shūjià shang ná xiàlai yì běn kànkan, zài fàng shangqu, yòu cóng lìng yí ge shūjià shang chōu chūlai yì běn kànkan.","vi":"Thấy trong hiệu sách có đủ các loại sách, tôi rất hào hứng. Lấy một cuốn trên giá sách này xuống xem, rồi đặt lên lại, lại rút một cuốn ở giá sách khác ra xem."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"我挑了几本历史书，麦克选了一些中文小说。我们都想买一些书带回国去，因为中国的书比我们国家的便宜得多。","py":"Wǒ tiāole jǐ běn lìshǐ shū, Màikè xuǎnle yìxiē Zhōngwén xiǎoshuō. Wǒmen dōu xiǎng mǎi yìxiē shū dài huí guó qu, yīnwèi Zhōngguó de shū bǐ wǒmen guójiā de piányi de duō.","vi":"Tôi chọn mấy cuốn sách lịch sử, Mike chọn một ít tiểu thuyết tiếng Trung. Chúng tôi đều muốn mua ít sách mang về nước, vì sách của Trung Quốc rẻ hơn sách nước chúng tôi nhiều."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"除了买书以外，我还想买一些电影光盘。于是我们又走进一家音像书店。我问营业员，这里有没有根据鲁迅小说拍成的电影DVD。","py":"Chúle mǎi shū yǐwài, wǒ hái xiǎng mǎi yìxiē diànyǐng guāngpán. Yúshì wǒmen yòu zǒujìn yì jiā yīnxiàng shūdiàn. Wǒ wèn yíngyèyuán, zhèli yǒu méiyǒu gēnjù Lǔ Xùn xiǎoshuō pāichéng de diànyǐng DVD.","vi":"Ngoài mua sách ra, tôi còn muốn mua một ít đĩa phim. Thế là chúng tôi lại bước vào một hiệu sách băng đĩa. Tôi hỏi cô nhân viên bán hàng ở đây có DVD phim dựng theo tiểu thuyết của Lỗ Tấn không."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"她说，有，我给你找。不一会儿，她拿过来几盒光盘对我说，这些都是根据鲁迅小说拍成的电影。","py":"Tā shuō, yǒu, wǒ gěi nǐ zhǎo. Bù yíhuìr, tā ná guòlai jǐ hé guāngpán duì wǒ shuō, zhèxiē dōu shì gēnjù Lǔ Xùn xiǎoshuō pāichéng de diànyǐng.","vi":"Cô ấy nói: có, để tôi tìm cho bạn. Một lát sau, cô ấy mang lại mấy hộp đĩa và nói với tôi rằng đây đều là phim dựng theo tiểu thuyết của Lỗ Tấn."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"我对麦克说，下学期我就要学习鲁迅的小说了，我想买回去看看。我和麦克买了《药》和《祝福》等，还买了不少新电影的光盘。","py":"Wǒ duì Màikè shuō, xià xuéqī wǒ jiù yào xuéxí Lǔ Xùn de xiǎoshuō le, wǒ xiǎng mǎi huíqu kànkan. Wǒ hé Màikè mǎile《Yào》hé《Zhùfú》děng, hái mǎile bù shǎo xīn diànyǐng de guāngpán.","vi":"Tôi nói với Mike, học kỳ sau tôi sẽ học tiểu thuyết của Lỗ Tấn, tôi muốn mua về xem. Tôi và Mike mua “Thuốc”, “Chúc phúc”…, còn mua khá nhiều đĩa phim mới."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"小姐见我们买的书和光盘太多，不好拿，就给我们俩一人找了一个小纸箱。我们买的书和光盘正好都能放进去。","py":"Xiǎojiě jiàn wǒmen mǎi de shū hé guāngpán tài duō, bù hǎo ná, jiù gěi wǒmen liǎ yì rén zhǎole yí ge xiǎo zhǐxiāng. Wǒmen mǎi de shū hé guāngpán zhènghǎo dōu néng fàng jìnqu.","vi":"Cô nhân viên thấy chúng tôi mua quá nhiều sách và đĩa, khó cầm, liền tìm cho hai chúng tôi mỗi người một thùng giấy nhỏ. Sách và đĩa chúng tôi mua vừa khít bỏ vào được hết."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"从图书城出来，已经十二点多了。我和麦克走进一个小饭馆去吃午饭。我们要了一盘饺子，几个菜和两瓶啤酒，吃得很舒服。","py":"Cóng túshūchéng chūlai, yǐjīng shí'èr diǎn duō le. Wǒ hé Màikè zǒujìn yí ge xiǎo fànguǎn qù chī wǔfàn. Wǒmen yàole yì pán jiǎozi, jǐ ge cài hé liǎng píng píjiǔ, chī de hěn shūfu.","vi":"Ra khỏi siêu thị sách thì đã hơn mười hai giờ. Tôi và Mike vào một quán ăn nhỏ ăn trưa. Chúng tôi gọi một đĩa sủi cảo, mấy món ăn và hai chai bia, ăn rất ngon miệng."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"吃完饭，我们就骑车回来了。回到学校，我又累又困，想赶快回到宿舍去洗个澡，休息休息。我从车上拿下小纸箱。","py":"Chīwán fàn, wǒmen jiù qí chē huílai le. Huídào xuéxiào, wǒ yòu lèi yòu kùn, xiǎng gǎnkuài huídào sùshè qu xǐ ge zǎo, xiūxi xiūxi. Wǒ cóng chē shang náxia xiǎo zhǐxiāng.","vi":"Ăn xong, chúng tôi đạp xe về. Về đến trường, tôi vừa mệt vừa buồn ngủ, muốn mau chóng về ký túc xá tắm một cái rồi nghỉ ngơi. Tôi lấy thùng giấy nhỏ trên xe xuống."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"走进楼来，看见电梯门口贴了张通知：“电梯维修，请走楼梯。”我住十层，没办法，只好爬上去。","py":"Zǒujìn lóu lai, kànjiàn diàntī ménkǒu tiēle zhāng tōngzhī: “Diàntī wéixiū, qǐng zǒu lóutī.” Wǒ zhù shí céng, méi bànfǎ, zhǐhǎo pá shangqu.","vi":"Bước vào tòa nhà, tôi thấy trước cửa thang máy dán một tờ thông báo: “Thang máy đang sửa chữa, xin đi thang bộ.” Tôi ở tầng mười, không còn cách nào khác, đành phải leo lên."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"我手里提着一箱子书，一步一步地往上爬。爬了半天才爬到十层。","py":"Wǒ shǒu li tízhe yì xiāngzi shū, yí bù yí bù de wǎng shàng pá. Pále bàntiān cái pádào shí céng.","vi":"Tay tôi xách một thùng sách, từng bước từng bước leo lên. Leo mãi mới lên tới tầng mười."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"到了门口，我放下箱子，要拿出钥匙开门的时候，却发现钥匙不见了，找了半天也没有找到。","py":"Dàole ménkǒu, wǒ fàngxia xiāngzi, yào náchu yàoshi kāi mén de shíhou, què fāxiàn yàoshi bú jiàn le, zhǎole bàntiān yě méiyǒu zhǎodào.","vi":"Đến trước cửa, tôi đặt thùng xuống, lúc định lấy chìa khóa ra mở cửa thì lại phát hiện chìa khóa biến đâu mất, tìm mãi cũng không thấy."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"啊！我忽然想起来了，钥匙还在楼下自行车上插着呢，我忘了拔下来了。这时，我真是哭笑不得。","py":"Ā! Wǒ hūrán xiǎng qǐlai le, yàoshi hái zài lóu xià zìxíngchē shang chāzhe ne, wǒ wàngle bá xiàlai le. Zhè shí, wǒ zhēn shì kū xiào bù dé.","vi":"A! Tôi chợt nhớ ra rồi, chìa khóa vẫn còn cắm trên chiếc xe đạp dưới tầng, tôi quên rút ra. Lúc ấy, tôi thật là dở khóc dở cười."},{"section":"Bài khóa 1: 钥匙忘拔下来了","speaker":"Kể","zh":"我刚要跑下楼去，就看见麦克也爬上来了，他手里拿的正是我的钥匙。","py":"Wǒ gāng yào pǎo xià lóu qu, jiù kànjiàn Màikè yě pá shanglai le, tā shǒu li ná de zhèng shì wǒ de yàoshi.","vi":"Tôi vừa định chạy xuống tầng dưới thì thấy Mike cũng leo lên, thứ cậu ấy cầm trên tay chính là chìa khóa của tôi."}],"grammar":["Bổ ngữ xu hướng kép: Các động từ xu hướng 上、下、进、出、回、过、起 thêm 来 hoặc 去, đặt sau động từ khác làm bổ ngữ, biểu thị xu hướng của động tác (上来/上去, 下来/下去, 进来/进去, 出来/出去, 回来/回去, 过来/过去, 起来). 来/去 dùng giống bổ ngữ xu hướng đơn. Ví dụ: 她走出学校去了。他跑回家来了。我买回来一本书。我们买的书和光盘正好都能放进去。","Vị trí tân ngữ với bổ ngữ xu hướng kép: Động từ + 进/出/上/下/回 + Địa điểm + 来/去 – tân ngữ chỉ địa điểm bắt buộc đứng trước 来/去 (我看见他走进图书馆去了。không nói *我看见他走进去图书馆了。; 汽车开上山去了。). Tân ngữ chỉ sự vật có thể đứng sau hoặc trước 来/去: 他从国外给我带回来一件礼物。= 他从国外给我带回一件礼物来。","Vị trí của 了 với bổ ngữ xu hướng kép: Không có tân ngữ → 了 đặt ngay sau động từ hoặc cuối câu (刚一下课，同学们就都跑了出去。= ……跑出去了。); có tân ngữ chỉ nơi chốn → 了 bắt buộc ở cuối câu (他们都爬上山去了。他们走下楼去了。); có tân ngữ chỉ sự vật → 了 đặt sau bổ ngữ xu hướng kép, trước tân ngữ (我给你买回来了一件羽绒服。我给朋友寄过去了一本介绍中国的书。)."]},{"id":40,"hsk":3,"zh_title":"会议厅的门开着呢","pinyin_title":"Huìyìtīng de mén kāizhe ne","title":"Cửa phòng họp vẫn đang mở","words":[{"id":"w_40_1","hsk":3,"lesson":40,"hanzi":"厅","pinyin":"tīng","pos":"Danh từ","hanviet":"sảnh","meaning":"đại sảnh, phòng lớn","example":"这套房子有客厅、厨房等等。 — Căn nhà này có phòng khách, nhà bếp,…"},{"id":"w_40_2","hsk":3,"lesson":40,"hanzi":"会议厅","pinyin":"huìyìtīng","pos":"Danh từ","hanviet":"hội nghị sảnh","meaning":"phòng hội nghị, phòng họp"},{"id":"w_40_3","hsk":3,"lesson":40,"hanzi":"中心","pinyin":"zhōngxīn","pos":"Danh từ","hanviet":"trung tâm","meaning":"trung tâm"},{"id":"w_40_4","hsk":3,"lesson":40,"hanzi":"服务员","pinyin":"fúwùyuán","pos":"Danh từ","hanviet":"phục vụ viên","meaning":"nhân viên phục vụ","example":"服务员，再来一杯咖啡。 — Phục vụ, cho thêm 1 cốc cà phê."},{"id":"w_40_5","hsk":3,"lesson":40,"hanzi":"长","pinyin":"zhǎng","pos":"Động từ","hanviet":"trưởng","meaning":"phát triển, lớn lên","example":"那个服务员长得很漂亮。 — Người phục vụ kia rất đẹp."},{"id":"w_40_6","hsk":3,"lesson":40,"hanzi":"个子","pinyin":"gèzi","pos":"Danh từ","hanviet":"cá tử","meaning":"thân hình, vóc dáng","example":"他的个子很高，大概有一米八五。 — Vóc dáng của anh ấy rất cao, khoảng 1m85."},{"id":"w_40_7","hsk":3,"lesson":40,"hanzi":"左右","pinyin":"zuǒyòu","pos":"Trợ từ","hanviet":"tả hữu","meaning":"xấp xỉ, khoảng","example":"那个服务员的个子不矮，一米七五左右。 — Cậu nhân viên phục vụ kia vóc dáng không thấp, tầm 1m75 khoảng đó."},{"id":"w_40_8","hsk":3,"lesson":40,"hanzi":"戴","pinyin":"dài","pos":"Động từ","hanviet":"đới","meaning":"đội, đeo, mang (trang sức, phụ kiện)"},{"id":"w_40_9","hsk":3,"lesson":40,"hanzi":"着","pinyin":"zhe","pos":"Trợ từ","hanviet":"trước","meaning":"đang"},{"id":"w_40_10","hsk":3,"lesson":40,"hanzi":"副","pinyin":"fù","pos":"Lượng từ/ Tính từ","hanviet":"phó","meaning":"chiếc, cặp, đôi","example":"他不是校长，他是副校长。 — Anh ấy không phải là hiệu trưởng, anh ấy là hiệu phó."},{"id":"w_40_11","hsk":3,"lesson":40,"hanzi":"穿","pinyin":"chuān","pos":"Động từ","hanviet":"xuyên","meaning":"mặc","example":"这里的冬天不太冷，不用穿太厚的大衣。 — Mùa đông ở đây không lạnh lắm, không cần mặc áo khoác quá dày."},{"id":"w_40_12","hsk":3,"lesson":40,"hanzi":"西服","pinyin":"xīfú","pos":"Danh từ","hanviet":"tây phục","meaning":"âu phục, comple, vest","example":"她穿上这套西服真好看。 — Cô ấy mặc bộ vest này lên thật đẹp."},{"id":"w_40_13","hsk":3,"lesson":40,"hanzi":"裙子","pinyin":"qúnzi","pos":"Danh từ","hanviet":"quần tử","meaning":"váy"},{"id":"w_40_14","hsk":3,"lesson":40,"hanzi":"干","pinyin":"gàn","pos":"Động từ","hanviet":"can","meaning":"làm"},{"id":"w_40_15","hsk":3,"lesson":40,"hanzi":"主持人","pinyin":"zhǔchírén","pos":"Danh từ","hanviet":"chủ trì nhân","meaning":"người dẫn chương trình"},{"id":"w_40_16","hsk":3,"lesson":40,"hanzi":"主持","pinyin":"zhǔchí","pos":"Động từ","hanviet":"chủ trì","meaning":"dẫn chương trình"},{"id":"w_40_17","hsk":3,"lesson":40,"hanzi":"小伙子","pinyin":"xiǎohuǒzi","pos":"Danh từ","hanviet":"tiểu hỏa tử","meaning":"chàng trai","example":"那个小伙子长得很高，大概有一米八五左右。 — Vóc dáng của chàng trai kia rất cao, khoảng 1m85."},{"id":"w_40_18","hsk":3,"lesson":40,"hanzi":"扛","pinyin":"káng","pos":"Động từ","hanviet":"giang","meaning":"vác"},{"id":"w_40_19","hsk":3,"lesson":40,"hanzi":"摄像机","pinyin":"shèxiàngjī","pos":"Danh từ","hanviet":"nhiếp tượng cơ","meaning":"máy quay phim"},{"id":"w_40_20","hsk":3,"lesson":40,"hanzi":"麦克风","pinyin":"màikèfēng","pos":"Danh từ","hanviet":"mạch khắc phong","meaning":"micro"},{"id":"w_40_21","hsk":3,"lesson":40,"hanzi":"讲话","pinyin":"jiǎnghuà","pos":"Động từ ly hợp","hanviet":"giảng thoại","meaning":"nói, nói chuyện","example":"主持人请副校长上台讲话。 — Người dẫn chương trình mời thầy hiệu phó lên sân khấu phát biểu."},{"id":"w_40_22","hsk":3,"lesson":40,"hanzi":"墙","pinyin":"qiáng","pos":"Danh từ","hanviet":"tường","meaning":"tường","example":"老师把大家的作业贴在墙上。 — Thầy/cô giáo dán bài tập của mọi người lên trên tường."},{"id":"w_40_23","hsk":3,"lesson":40,"hanzi":"喜","pinyin":"xǐ","pos":"Tính từ","hanviet":"hỉ","meaning":"vui"},{"id":"w_40_24","hsk":3,"lesson":40,"hanzi":"婚礼","pinyin":"hūnlǐ","pos":"Danh từ","hanviet":"hôn lễ","meaning":"hôn lễ, đám cưới"},{"id":"w_40_25","hsk":3,"lesson":40,"hanzi":"热闹","pinyin":"rènao","pos":"Tính từ","hanviet":"náo nhiệt","meaning":"náo nhiệt"},{"id":"w_40_26","hsk":3,"lesson":40,"hanzi":"挂","pinyin":"guà","pos":"Động từ","hanviet":"quải","meaning":"treo","example":"你把这个灯笼挂上去吧。 — Bạn đem cái đèn lồng này treo lên đi."},{"id":"w_40_27","hsk":3,"lesson":40,"hanzi":"灯笼","pinyin":"dēnglong","pos":"Danh từ","hanviet":"đăng lung","meaning":"đèn lồng","example":"婚礼大厅的门口挂着一对大红灯笼。 — Trên cổng của sảnh chính hôn lễ đang treo một đôi đèn lồng đỏ."},{"id":"w_40_28","hsk":3,"lesson":40,"hanzi":"摆","pinyin":"bǎi","pos":"Động từ","hanviet":"bài","meaning":"bày, sắp xếp","example":"桌子上摆着各种各样的水果。 — Trên bàn đang bày đủ loại hoa quả."},{"id":"w_40_29","hsk":3,"lesson":40,"hanzi":"新郎","pinyin":"xīnláng","pos":"Danh từ","hanviet":"tân lang","meaning":"chú rể"},{"id":"w_40_30","hsk":3,"lesson":40,"hanzi":"新娘","pinyin":"xīnniáng","pos":"Danh từ","hanviet":"tân nương","meaning":"cô dâu"},{"id":"w_40_31","hsk":3,"lesson":40,"hanzi":"棉袄","pinyin":"mián'ǎo","pos":"Danh từ","hanviet":"miên áo","meaning":"áo bông"},{"id":"w_40_32","hsk":3,"lesson":40,"hanzi":"帅","pinyin":"shuài","pos":"Tính từ","hanviet":"soái","meaning":"đẹp trai","example":"那个穿西服的小伙子长得真帅！ — Chàng trai mặc vest kia thật đẹp trai!"},{"id":"w_40_33","hsk":3,"lesson":40,"hanzi":"领带","pinyin":"lǐngdài","pos":"Danh từ","hanviet":"lãnh đới","meaning":"cà vạt","example":"新郎今天穿着一身帅气的西服，还打着一条红色的领带。 — Hôm nay chú rể mặc một bộ vest bảnh bao, còn thắt một chiếc cà vạt màu đỏ."},{"id":"w_40_34","hsk":3,"lesson":40,"hanzi":"热情","pinyin":"rèqíng","pos":"Tính từ","hanviet":"nhiệt tình","meaning":"nhiệt tình","example":"那家饭馆的服务员对客人非常热情。 — Nhân viên phục vụ của quán ăn kia đối xử với khách hàng cực kỳ nhiệt tình."},{"id":"w_40_35","hsk":3,"lesson":40,"hanzi":"客人","pinyin":"kèrén","pos":"Danh từ","hanviet":"khách nhân","meaning":"khách, khách khứa"},{"id":"w_40_36","hsk":3,"lesson":40,"hanzi":"倒","pinyin":"dào","pos":"Động từ","hanviet":"đảo","meaning":"rót"},{"id":"w_40_37","hsk":3,"lesson":40,"hanzi":"不停","pinyin":"bùtíng","pos":"Phó từ","hanviet":"bất đình","meaning":"không dừng, không ngừng","example":"听到这个让人发狂的好消息，大家都不停地拍手。 — Nghe được tin vui khiến người ta phát cuồng này, mọi người đều không ngừng vỗ tay."},{"id":"w_40_38","hsk":3,"lesson":40,"hanzi":"气氛","pinyin":"qìfēn","pos":"Danh từ","hanviet":"khí phân","meaning":"bầu không khí","example":"门口挂着红灯笼，家里充满了节日的气氛。 — Cửa treo đèn lồng đỏ, trong nhà tràn ngập không khí ngày lễ."}],"dialogue":[{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"Kể","zh":"（玛丽和麦克到会议中心去找一个朋友，他们在前台问服务员……）","py":"(Mǎlì hé Màikè dào huìyì zhōngxīn qù zhǎo yí ge péngyou, tāmen zài qiántái wèn fúwùyuán……)","vi":"(Mary và Mike đến trung tâm hội nghị tìm một người bạn, họ hỏi nhân viên phục vụ ở quầy lễ tân…)"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"请问，刚才进去一位小姐，你看见没有？","py":"Qǐngwèn, gāngcái jìnqu yí wèi xiǎojiě, nǐ kànjiàn méiyǒu?","vi":"Xin hỏi, vừa nãy có một cô gái đi vào, anh có thấy không?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"什么小姐？长得什么样？","py":"Shénme xiǎojiě? Zhǎng de shénme yàng?","vi":"Cô gái nào? Trông như thế nào?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"她个子高高的，大概有一米七左右，黄头发，眼睛大大的，戴着一副眼镜。上身穿着一件红色的西服，下边穿着一条黑色的裙子。","py":"Tā gèzi gāogāo de, dàgài yǒu yì mǐ qī zuǒyòu, huáng tóufa, yǎnjing dàdà de, dàizhe yí fù yǎnjìng. Shàngshēn chuānzhe yí jiàn hóngsè de xīfú, xiàbian chuānzhe yì tiáo hēisè de qúnzi.","vi":"Cô ấy dáng cao cao, khoảng chừng 1m70, tóc vàng, mắt to to, đeo một cặp kính. Bên trên mặc một chiếc áo vest màu đỏ, bên dưới mặc một chiếc váy màu đen."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"是干什么的？","py":"Shì gàn shénme de?","vi":"Cô ấy làm nghề gì?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"是电视台的主持人。","py":"Shì diànshìtái de zhǔchírén.","vi":"Là người dẫn chương trình của đài truyền hình."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"后边是不是还跟着两个小伙子，扛着摄像机？","py":"Hòubian shì bu shì hái gēnzhe liǎng ge xiǎohuǒzi, kángzhe shèxiàngjī?","vi":"Phía sau có phải còn có hai chàng trai đi theo, vác máy quay phim không?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"对。","py":"Duì.","vi":"Đúng vậy."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"会议厅的门开着呢，你们进去找吧。","py":"Huìyìtīng de mén kāizhe ne, nǐmen jìnqu zhǎo ba.","vi":"Cửa phòng hội nghị đang mở đấy, các bạn vào tìm đi."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"里边正开着会吗？","py":"Lǐbian zhèng kāizhe huì ma?","vi":"Bên trong đang họp à?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"没有。你们看，是不是手里拿着麦克风，对着摄像机讲话的那位？","py":"Méiyǒu. Nǐmen kàn, shì bu shì shǒu li názhe màikèfēng, duìzhe shèxiàngjī jiǎnghuà de nà wèi?","vi":"Không có. Các bạn xem, có phải là người tay cầm micro, đang nói trước máy quay kia không?"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"对，就是她。他们正等着我们呢。","py":"Duì, jiù shì tā. Tāmen zhèng děngzhe wǒmen ne.","vi":"Đúng, chính là cô ấy. Họ đang đợi chúng tôi đấy."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"你们进去吧。","py":"Nǐmen jìnqu ba.","vi":"Các bạn vào đi."},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"玛丽","zh":"谢谢啦！","py":"Xièxie la!","vi":"Cảm ơn nhé!"},{"section":"Bài khóa 1: 会议厅的门开着呢","speaker":"服务员","zh":"不客气。","py":"Bú kèqi.","vi":"Không có gì."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"Kể","zh":"（麦克参加了一个中国朋友的婚礼……）","py":"(Màikè cānjiāle yí ge Zhōngguó péngyou de hūnlǐ……)","vi":"(Mike đã đi dự đám cưới của một người bạn Trung Quốc…)"},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"玛丽","zh":"你昨天去哪儿了？","py":"Nǐ zuótiān qù nǎr le?","vi":"Hôm qua cậu đi đâu thế?"},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"麦克","zh":"张东带我去参加了一个中国人的婚礼。","py":"Zhāng Dōng dài wǒ qù cānjiāle yí ge Zhōngguórén de hūnlǐ.","vi":"Trương Đông dẫn tớ đi dự đám cưới của một người Trung Quốc."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"玛丽","zh":"怎么样？听说中国人的婚礼很热闹。","py":"Zěnmeyàng? Tīngshuō Zhōngguórén de hūnlǐ hěn rènao.","vi":"Thế nào? Nghe nói đám cưới của người Trung Quốc rất náo nhiệt."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"麦克","zh":"是！我是第一次看到这样的婚礼。屋子里挂着大红灯笼，墙上贴着一个很大的红双喜字。桌子上摆着很多酒和菜。","py":"Shì! Wǒ shì dì-yī cì kàndào zhèyàng de hūnlǐ. Wūzi li guàzhe dà hóng dēnglong, qiáng shang tiēzhe yí ge hěn dà de hóng shuāngxǐ zì. Zhuōzi shang bǎizhe hěn duō jiǔ hé cài.","vi":"Đúng thế! Đây là lần đầu tiên tớ thấy một đám cưới như vậy. Trong nhà treo đèn lồng đỏ thật to, trên tường dán một chữ song hỷ đỏ rất lớn. Trên bàn bày rất nhiều rượu và thức ăn."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"麦克","zh":"新娘长得很漂亮，穿着一件红棉袄，头上还戴着红花。新郎是一个帅小伙儿，穿着一身深蓝色的西服，打着红领带。他们笑着对我们说“欢迎，欢迎”。","py":"Xīnniáng zhǎng de hěn piàoliang, chuānzhe yí jiàn hóng mián'ǎo, tóu shang hái dàizhe hóng huā. Xīnláng shì yí ge shuài xiǎohuǒr, chuānzhe yì shēn shēnlánsè de xīfú, dǎzhe hóng lǐngdài. Tāmen xiàozhe duì wǒmen shuō “huānyíng, huānyíng”.","vi":"Cô dâu rất xinh, mặc một chiếc áo bông đỏ, trên đầu còn cài hoa đỏ. Chú rể là một chàng trai đẹp trai, mặc một bộ vest xanh đậm, thắt cà vạt đỏ. Họ cười nói với chúng tớ: “Hoan nghênh, hoan nghênh”."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"麦克","zh":"新娘热情地请客人吃糖，新郎忙着给客人倒喜酒。孩子们不停地说着笑着，热热闹闹的，气氛非常好。","py":"Xīnniáng rèqíng de qǐng kèrén chī táng, xīnláng mángzhe gěi kèrén dào xǐjiǔ. Háizimen bù tíng de shuōzhe xiàozhe, rèrenàonào de, qìfēn fēicháng hǎo.","vi":"Cô dâu nhiệt tình mời khách ăn kẹo, chú rể tất bật rót rượu mừng cho khách. Bọn trẻ không ngừng nói nói cười cười, náo nhiệt vô cùng, bầu không khí rất tuyệt."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"玛丽","zh":"“喜酒”是什么酒？","py":"“Xǐjiǔ” shì shénme jiǔ?","vi":"“Rượu mừng” là rượu gì?"},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"麦克","zh":"结婚时喝的酒中国人叫喜酒，吃的糖叫喜糖。所以，中国人要问：“什么时候吃你的喜糖啊”，就是问你什么时候结婚。","py":"Jiéhūn shí hē de jiǔ Zhōngguórén jiào xǐjiǔ, chī de táng jiào xǐtáng. Suǒyǐ, Zhōngguórén yào wèn: “Shénme shíhou chī nǐ de xǐtáng a”, jiù shì wèn nǐ shénme shíhou jiéhūn.","vi":"Rượu uống lúc cưới người Trung Quốc gọi là rượu mừng, kẹo ăn lúc cưới gọi là kẹo mừng. Cho nên người Trung Quốc mà hỏi: “Bao giờ được ăn kẹo mừng của cậu đây?” tức là hỏi cậu bao giờ kết hôn."},{"section":"Bài khóa 2: 墙上贴着红双喜字","speaker":"玛丽","zh":"是吗？","py":"Shì ma?","vi":"Thế à?"}],"grammar":["Động từ + 着 (khẳng định): Biểu thị sự tiếp diễn của động tác hoặc trạng thái – động tác đang diễn ra và kéo dài (同学们走着，说着，笑着，可热闹啦。他正在往墙上贴着红双喜字。), hoặc trạng thái tồn tại sau khi động tác xảy ra (墙上贴着红双喜字。她穿着一件红西服。).","Phủ định và nghi vấn của 着: Phủ định dùng 没（有）+ Động từ + 着, nhưng rất ít dùng trong giao tiếp (老师没在前面坐着，他站着呢。教室的门没开着。书上没写着名字，不知道是谁的书。). Câu hỏi: Động từ + 着 + 没有？ (里边开着会没有？墙上挂着地图没有？)","Động từ 1 + 着 + Động từ 2: Động từ + 着 đứng trước động từ thứ hai của câu liên động, nói rõ trạng thái hoặc phương thức tiến hành của hành động thứ hai. Ví dụ: 她正在前边站着讲话呢。她笑着对我说：“欢迎！欢迎！”那里离这儿不远，我们走着去吧。","Động từ + 着 với 正在 / 正 / 在 / 呢: Động từ + 着 thường dùng liền với các từ 正在、正、在、呢. Ví dụ: 里边正上着课呢。她来时，我正在躺着看书呢。"]}];
  extra.forEach((l) => { if (!D.lessons.some((x) => x.id === l.id)) D.lessons.push(l); });
  D.lessons.sort((a, b) => a.id - b.id);
  D.all_words = D.lessons.reduce((acc, l) => acc.concat(l.words || []), []);
  D.total_words = D.all_words.length;
  D.total_lessons = D.lessons.length;
})();
