window.LESSON_NOTES = {"words":{"w_1_15":[{"c":"chiet_tu","t":"Chiết tự 天","x":"Hán Việt: Thiên (trời).\nBộ thành phần: 一 Nhất + 大 Đại.","s":"HSK1_01#8"}],"w_1_1":[{"c":"chiet_tu","t":"Chiết tự 你","x":"Bộ thành phần: 亻 Nhân đứng + 冖 Mịch (trùm đậy) + 小 Tiểu.","s":"HSK1_01#21"}],"w_1_2":[{"c":"chiet_tu","t":"Chiết tự 好","x":"Bộ thành phần: 女 Nữ + 子 Tử.","s":"HSK1_01#21"}],"w_1_8":[{"c":"cau_vi_du","t":"不 + tính từ","x":"不白 — Không trắng\n不好 — Không tốt/không khỏe","s":"HSK1_01#23"}],"w_1_12":[{"c":"tu_mo_rong","t":"Cụm từ với 大, 马","x":"不大: Không lớn\n白马: Bạch mã (con ngựa trắng)\n大马: Đại mã (con ngựa lớn)","s":"HSK1_01#24"}],"w_1_13":[{"c":"tu_mo_rong","t":"妈 – mẹ","x":"妈 (mā): Mẹ","s":"HSK1_01#25"}],"w_2_1":[{"c":"chiet_tu","t":"Chiết tự 忙","x":"Bộ thành phần: 忄 Tâm đứng + 亡 Vong.","s":"HSK1_02#4"}],"w_2_2":[{"c":"chiet_tu","t":"Chiết tự 很","x":"Cách dùng: 很 + tính từ = rất…\nBộ thành phần: 彳 Nhân kép (Xích) + Cấn (cứng rắn).\n很忙 — Rất bận\n很好 — Rất tốt/rất khỏe","s":"HSK1_02#6"}],"w_2_3":[{"c":"chiet_tu","t":"Chiết tự 汉语","x":"汉 (hàn): Hán (người Hán, tiếng Hán). Bộ thành phần: 氵 Thủy (ba chấm thủy) + 又 Hựu (lặp đi lặp lại).\n语 (yǔ): Ngữ (ngôn ngữ). Bộ thành phần: 讠 Ngôn + 五 Ngũ + 口 Khẩu.\nMẹo nhớ: Ngôn ngữ là lời nói của 5 châu lục và được nói ra từ miệng.","s":"HSK1_02#7"}],"w_2_4":[{"c":"chiet_tu","t":"Chiết tự 难","x":"Hán Việt: Nan.\nBộ thành phần: 又 Hựu (làm đi làm lại) + 隹 Chuy (chim đuôi ngắn).\nMẹo nhớ: con chim đậu cạnh cái lồng.\n汉语很难 — Tiếng Trung rất khó","s":"HSK1_02#8"}],"w_2_6":[{"c":"cach_dung","t":"不 + 太 + tính từ: không… lắm","x":"太 (tài, phó từ chỉ mức độ): biểu thị mức độ cao, mang ngữ khí cảm thán.\n不 + tính từ: không…\n不 + 太 + tính từ: không… lắm (giảm mức độ phủ định, ngữ khí nhẹ nhàng hơn).\n汉语不太难 — Tiếng Trung không khó lắm\n不太好 — Không khỏe lắm","s":"HSK1_02#9"}],"w_2_14":[{"c":"chiet_tu","t":"Chiết tự 男","x":"Bộ thành phần: 田 Điền + 力 Lực.\nMẹo nhớ: Đàn ông phải dùng sức lực để cày ruộng.","s":"HSK1_02#10"}],"w_2_7":[{"c":"chiet_tu","t":"Chiết tự 爸, 妈","x":"爸 (bà): Bộ thành phần: 父 Phụ + 巴 Ba.\n妈 (mā): Bộ thành phần: 女 Nữ + 马 Mã.","s":"HSK1_02#11"}],"w_2_8":[{"c":"chiet_tu","t":"Chiết tự 哥 & từ 大哥","x":"Hán Việt: Ca ca.\nBộ thành phần: 可 Khả.\n大哥 (dàgē): Đại ca, anh cả.","s":"HSK1_02#12"}],"w_2_9":[{"c":"chiet_tu","t":"Chiết tự 弟","x":"Hán Việt: Đệ đệ.\nBộ thành phần: 弓 Cung.","s":"HSK1_02#13"}],"w_2_10":[{"c":"chiet_tu","t":"Chiết tự 妹","x":"Hán Việt: Muội muội.\nBộ thành phần: 女 Nữ + 未 Vị.","s":"HSK1_02#14"}],"w_2_12":[{"c":"chiet_tu","t":"Chiết tự 他 (anh ấy)","x":"Bộ thành phần: 亻 Nhân + 也 Dã.","s":"HSK1_02#16"}],"w_2_13":[{"c":"chiet_tu","t":"Chiết tự 她 (cô ấy)","x":"Bộ thành phần: 女 Nữ + 也 Dã.","s":"HSK1_02#16"}],"w_3_1":[{"c":"chiet_tu","t":"Chiết tự 学","x":"Bộ thành phần: 冖 Mịch + 子 Tử (đứa con trai).","s":"HSK1_03#4"},{"c":"cau_vi_du","t":"Câu ví dụ: 学 + ngoại ngữ","x":"我妈妈学汉语。 — Mẹ tôi học tiếng Trung.\n我哥哥学英语。 — Anh trai tôi học tiếng Anh.\n我学日语。 — Tôi học tiếng Nhật.","s":"HSK1_03#11"}],"w_3_2":[{"c":"chiet_tu","t":"Chiết tự 英","x":"英 (yīng): Anh.\nBộ thành phần: 艹 Thảo đầu + 央 Ương.\n学英语 — Học tiếng Anh","s":"HSK1_03#6"},{"c":"tu_mo_rong","t":"英国 – nước Anh","x":"英国 (Yīngguó): Nước Anh","s":"HSK1_03#6"}],"w_3_4":[{"c":"chiet_tu","t":"Chiết tự 德 (câu vè)","x":"德 (dé): đạo đức.\nBộ thành phần: 彳 Nhân kép + 心 Tâm (nằm ngang).\nMẹo nhớ: “Chim chích mà đậu cành tre, thập ngang tứ dưới nhất đè chữ tâm.”","s":"HSK1_03#7"},{"c":"tu_mo_rong","t":"德国 – nước Đức","x":"德国 (Déguó): Nước Đức","s":"HSK1_03#7"}],"w_3_6":[{"c":"chiet_tu","t":"Chiết tự 法","x":"法 (fǎ): Pháp (pháp luật).\nBộ thành phần: 氵 Thủy (ba chấm thủy) + 去 (đi).\nMẹo nhớ: Người Pháp đi được trên nước.","s":"HSK1_03#8"},{"c":"tu_mo_rong","t":"法国 – nước Pháp","x":"法国 (Fǎguó): Nước Pháp","s":"HSK1_03#8"}],"w_3_8":[{"c":"tu_mo_rong","t":"日, 日本 – Nhật Bản","x":"日 (rì): Ngày, mặt trời (bộ Nhật)\n日本 (Rìběn): Nhật Bản\n本 (běn): Bản, gốc","s":"HSK1_03#9"}],"w_3_5":[{"c":"chiet_tu","t":"Chiết tự 俄","x":"Bộ thành phần: 亻 Nhân + 我 (tôi).","s":"HSK1_03#10"},{"c":"tu_mo_rong","t":"Nước Nga: 俄国, 俄罗斯","x":"俄国 (Éguó): Nước Nga\n俄罗斯 (Éluósī): Nước Nga","s":"HSK1_03#10"}],"w_3_10":[{"c":"chiet_tu","t":"Chiết tự 对","x":"Bộ thành phần: 又 Hựu + 寸 Thốn (đơn vị đo, khoảng 3,33 cm).\nMẹo nhớ: Tính đi tính lại vẫn bằng 1 thốn thì chắc chắn là đúng.","s":"HSK1_03#12"},{"c":"tu_mo_rong","t":"不对, 不太对","x":"不对: Không đúng\n不太对: Không đúng lắm","s":"HSK1_03#12"}],"w_3_13":[{"c":"chiet_tu","t":"Chiết tự 去","x":"Bộ thành phần: 土 Thổ + 厶 Khư (riêng tư).\nMẹo nhớ: Đi thì đi trên đất và đi làm việc riêng tư.\n她去英国学英语。 — Cô ấy đi nước Anh học tiếng Anh.","s":"HSK1_03#13"}],"w_3_14":[{"c":"chiet_tu","t":"Mẹo nhớ 邮局","x":"Bộ thành phần: bộ Ấp.\nMẹo nhớ: Hộp quà bê ra bưu điện để gửi.","s":"HSK1_03#14"}],"w_3_15":[{"c":"chiet_tu","t":"Chiết tự 寄","x":"Hán Việt: Ký (ký gửi).\nBộ thành phần: 宀 Miên + 奇 Kì.","s":"HSK1_03#15"}],"w_3_16":[{"c":"chiet_tu","t":"Chiết tự 信","x":"Hán Việt: Tín (thư tín, uy tín).\nBộ thành phần: 亻 Nhân + 言/讠 Ngôn.\nMẹo nhớ: Con người dùng ngôn ngữ để viết thư.\n他去邮局寄信。 — Anh ấy đi bưu cục gửi thư.","s":"HSK1_03#16"}],"w_3_17":[{"c":"chiet_tu","t":"Chiết tự 银行","x":"银 (yín): Ngân. Bộ thành phần: 钅 Kim + 艮 Cấn (cứng).\n行 (háng): Hành (lưu hành).\nMẹo nhớ: Ngân hàng thì có tiền cứng để lưu hành.","s":"HSK1_03#17"}],"w_3_18":[{"c":"chiet_tu","t":"Chiết tự 取","x":"Bộ thành phần: 耳 Nhĩ (tai) + 又 Hựu.","s":"HSK1_03#18"}],"w_3_19":[{"c":"chiet_tu","t":"Chiết tự 钱","x":"Bộ thành phần: 钅 Kim.\n他去银行取钱吗？ — Anh ấy đi ngân hàng rút tiền à?\n不，他去邮局寄信。 — Không, anh ấy đi bưu cục gửi thư.","s":"HSK1_03#19"}],"w_3_11":[{"c":"chiet_tu","t":"Chiết tự 明 (明天)","x":"明 (míng): Minh, sáng.\nBộ thành phần: 日 Nhật + 月 Nguyệt.\nMẹo nhớ: Ngày mai là một ngày tươi sáng.","s":"HSK1_03#20"}],"w_3_12":[{"c":"chiet_tu","t":"Mẹo nhớ 见","x":"Hán Việt: Kiến (“Nhất kiến chung tình”).\nBộ: 见 Kiến.\n明天见！ — Ngày mai gặp!","s":"HSK1_03#21"}],"w_3_23":[{"c":"chiet_tu","t":"Chiết tự 京","x":"京 (jīng): Kinh (kinh đô, kinh thành).\nBộ thành phần: 口 Khẩu + 小 Tiểu.\n我去北京学汉语。 — Tôi đi Bắc Kinh học tiếng Trung.","s":"HSK1_03#25"}],"w_4_1":[{"c":"chiet_tu","t":"Chiết tự 今","x":"Bộ thành phần: 人 Nhân.\n今天他去银行取钱。 — Hôm nay anh ấy đi ngân hàng rút tiền.","s":"HSK1_04#4"}],"w_4_2":[{"c":"chiet_tu","t":"Chiết tự 昨","x":"Bộ thành phần: 日 Nhật + 乍 Sạ.\n昨天我爸爸去邮局寄信。 — Hôm qua bố tôi đi bưu cục gửi thư.","s":"HSK1_04#5"}],"w_4_3":[{"c":"chiet_tu","t":"Chiết tự 星期","x":"Hán Việt: Tinh kỳ.\n星 (xīng): Tinh (ngôi sao). Bộ thành phần: 日 Nhật + 生 Sinh.\n期 (qī): Kỳ. Bộ thành phần: 其 Kỳ + 月 Nguyệt.","s":"HSK1_04#7"},{"c":"cau_vi_du","t":"Hỏi – đáp thứ mấy với 几","x":"星期几？ — Thứ mấy?\n今天星期几？ — Hôm nay là thứ mấy?\n昨天星期几？ — Hôm qua là thứ mấy?\n明天星期几？ — Ngày mai là thứ mấy?\n今天星期一。 — Hôm nay là thứ 2.\n昨天星期天（日）。 — Hôm qua là chủ nhật.\n明天星期二。 — Ngày mai là thứ 3.","s":"HSK1_04#9"}],"w_4_15":[{"c":"cach_dung","t":"Đại từ + 那儿 = chỗ của ai","x":"那儿 (nàr): ở kia, đó, chỗ đó; dùng trong câu trần thuật, chỉ một địa điểm cụ thể mà người nói và người nghe đều biết hoặc đã được nhắc đến.\n我那儿 — Chỗ tôi; 你那儿 — Chỗ bạn; 他那儿 — Chỗ anh ấy; 她那儿 — Chỗ cô ấy.\n你去哪儿？ — Bạn đi đâu vậy?\n我去他那儿。你去吗？ — Tôi đi chỗ anh ấy. Bạn đi không?","s":"HSK1_04#11"}],"w_4_17":[{"c":"chiet_tu","t":"Chiết tự 校","x":"校 (xiào): Hán Việt: Hiệu.\nBộ thành phần: 木 Mộc + 交 Giao.\n昨天你去哪儿？ — Hôm qua bạn đi đâu vậy?\n昨天我回学校。 — Hôm qua tôi quay về trường.","s":"HSK1_04#14"}],"w_4_18":[{"c":"cach_dung","t":"再 + động từ: lại, lần nữa","x":"再 (zài, phó từ): lại, lần nữa. Hán Việt: Tái.\nCấu trúc: 再 + động từ.\n昨天，今天我去银行。 — Hôm qua, hôm nay tôi đi ngân hàng.\n明天我再去银行。 — Ngày mai tôi lại đi ngân hàng.\nTừ mở rộng: 再来 (zàilái).","s":"HSK1_04#15"}],"w_4_19":[{"c":"chiet_tu","t":"Chiết tự 起 (对不起)","x":"起 (qǐ): Hán Việt: Khởi.\nBộ thành phần: 走 Tẩu + 己 Kỉ.","s":"HSK1_04#17"}],"w_4_20":[{"c":"chiet_tu","t":"Chiết tự 没关系","x":"没: Bộ thành phần: 氵 Ba chấm thủy + 又 Hựu.\n关: Hán Việt: Quan (đóng). Bộ thành phần: 天 Thiên.\n系: Hán Việt: Hệ. Bộ thành phần: 糸 Mịch (sợi tơ).\n关系 (guānxi, danh từ): Quan hệ.","s":"HSK1_04#18"},{"c":"tu_mo_rong","t":"没 – không có","x":"没 (méi): Không có, không sở hữu\n没钱: Không có tiền","s":"HSK1_04#18"}],"w_5_1":[{"c":"chiet_tu","t":"Chiết tự 这","x":"这 (zhè): đây, này – chỉ người, sự vật hoặc địa điểm ở gần người nói/người nghe.\nBộ thành phần: 辶 Quai xước (sước) + 文 Văn.","s":"HSK1_05#4"}],"w_5_2":[{"c":"chiet_tu","t":"Chiết tự 是","x":"Bộ thành phần: 日 Nhật.\nMẫu câu: 这是…… — Đây là…\n这是我爸爸。 — Đây là bố tôi.","s":"HSK1_05#5"}],"w_5_3":[{"c":"cau_vi_du","t":"Câu ví dụ với 老师","x":"他是老师吗？ — Anh ấy là giáo viên à?\n我妈妈是老师。 — Mẹ tôi là giáo viên.","s":"HSK1_05#6"}],"w_5_4":[{"c":"chiet_tu","t":"Chiết tự 您","x":"您 (nín): ngài/ông/bà – xưng hô mang ngữ khí kính trọng.\nBộ thành phần: 心 Tâm.\n您好！ — Chào ông/bà/ngài!\n老师，您好！ — Chào thầy/cô ạ!","s":"HSK1_05#8"}],"w_5_5":[{"c":"chiet_tu","t":"Chiết tự 请","x":"Bộ thành phần: 讠 Ngôn + 青 Thanh.\nCấu trúc: 请 + động từ (mời…, xin…).","s":"HSK1_05#9"}],"w_5_6":[{"c":"chiet_tu","t":"Chiết tự 进","x":"Bộ thành phần: 辶 Quai xước + 井 Tỉnh.\n请进 — Mời vào","s":"HSK1_05#10"}],"w_5_7":[{"c":"chiet_tu","t":"Chiết tự 坐","x":"Hán Việt: Tọa.\nBộ thành phần: 人 Nhân + 土 Thổ.\nMẹo nhớ: Hai người ngồi trên đất.\n请坐 — Mời ngồi","s":"HSK1_05#11"}],"w_5_8":[{"c":"chiet_tu","t":"Chiết tự 喝","x":"Bộ thành phần: 口 Khẩu.\n好喝 (hǎohē, tính từ): ngon (dùng cho đồ uống).","s":"HSK1_05#12"}],"w_5_9":[{"c":"chiet_tu","t":"Chiết tự 茶","x":"Bộ thành phần: 艹 Thảo đầu.\n请喝茶。 — Mời uống trà.\n茶好喝吗？ — Trà ngon không?\n茶很好喝。 — Trà rất ngon.","s":"HSK1_05#13"}],"w_5_10":[{"c":"chiet_tu","t":"Chiết tự 谢","x":"Hán Việt: Tạ.\nBộ thành phần: 讠 Ngôn + 身 Thân + 寸 Thốn.\nMẹo nhớ: Cảm ơn thì dùng lời nói và gập thân xuống 1 thốn để thể hiện lòng biết ơn.","s":"HSK1_05#14"}],"w_5_12":[{"c":"chiet_tu","t":"Chiết tự 客气","x":"客: Hán Việt: Khách. Bộ thành phần: 宀 Miên + 各 Các.\n气: Hán Việt: Khí (không khí).\n客气 (kèqi, tính từ): khách khí, khách sáo.\n不客气 (bú kèqi): Không có gì, không cần khách sáo.","s":"HSK1_05#15"}],"w_5_14":[{"c":"chiet_tu","t":"Chiết tự 体","x":"Hán Việt: Thân thể (身体 – sức khỏe).\n体: Bộ thành phần: 亻 Nhân + 本 Bổn/Bản.\n你姐姐身体好吗？ — Sức khỏe chị gái bạn tốt không?\n我姐姐身体很好。 — Sức khỏe chị gái tôi rất tốt.","s":"HSK1_05#17"}],"w_6_2":[{"c":"chiet_tu","t":"Chiết tự 问","x":"Hán Việt: Vấn.\nBộ thành phần: 门 Môn + 口 Khẩu.\nMẹo nhớ: Muốn hỏi thì phải gõ cửa và dùng miệng để hỏi.","s":"HSK1_06#5"}],"w_6_3":[{"c":"chiet_tu","t":"Chiết tự 贵 (đắt)","x":"贵 (guì, tính từ): đắt. Hán Việt: Quý.\nBộ thành phần: 中 Trung (ở giữa) + 一 Nhất + 贝 Bối.\nMẹo nhớ: Ở giữa một đống vật báu thì được mọi người yêu quý, mà cái gì quý thì cũng đắt.","s":"HSK1_06#6"},{"c":"cach_dung","t":"Khi nào dùng 贵姓","x":"贵姓 (guìxìng): quý danh, quý tính (họ) – kính ngữ, dùng khi lần đầu gặp mặt hỏi họ tên của đối phương.\n请问，您贵姓？ — Xin hỏi, ngài họ gì?\n我姓阮（ruǎn）。 — Tôi họ Nguyễn.","s":"HSK1_06#8"}],"w_6_4":[{"c":"chiet_tu","t":"Chiết tự 姓","x":"Hán Việt: Tính.\nBộ thành phần: 女 Nữ + 生 Sinh.\nMẹo nhớ: Họ tên do người phụ nữ sinh ra mình đặt cho.","s":"HSK1_06#7"}],"w_6_17":[{"c":"chiet_tu","t":"Chiết tự 什 (什么)","x":"什: Bộ thành phần: 亻 Nhân + 十 Thập.\n这是什么？ — Đây là cái gì?\n你学习什么？ — Bạn học cái gì?","s":"HSK1_06#9"}],"w_6_5":[{"c":"chiet_tu","t":"Chiết tự 叫","x":"Bộ thành phần: 口 Khẩu.\nMẹo nhớ: Gọi thì dùng miệng và gọi 4 lần mới thưa.\n你叫我吗？ — Bạn gọi tôi à?","s":"HSK1_06#10"}],"w_6_6":[{"c":"chiet_tu","t":"Chiết tự 名","x":"名 (míng): Hán Việt: Danh.\nBộ thành phần: 夕 Tịch (đêm khuya) + 口 Khẩu.\nMẹo nhớ: Đêm khuya không nhìn thấy nên phải dùng miệng để gọi tên.","s":"HSK1_06#11"},{"c":"cach_dung","t":"Hỏi tên và hai cách nói tên","x":"你叫什么名字？ — Bạn tên là gì?\nTôi tên là…: 我叫…… hoặc 我的名字是……","s":"HSK1_06#13"}],"w_6_15":[{"c":"chiet_tu","t":"Chiết tự 字","x":"字 (zì): chữ. Hán Việt: Tự.\nBộ thành phần: 宀 Miên + 子 Tử.\nMẹo nhớ: Đứa con trai ngồi trong nhà viết chữ.\n汉字: Hán tự, chữ Hán.\n汉字不太难。 — Chữ Hán không khó lắm.","s":"HSK1_06#12"}],"w_6_13":[{"c":"tu_mo_rong","t":"Từ ghép với 人","x":"人 (rén): Người – Hán Việt: Nhân\n男人: Nam nhân\n女人: Nữ nhân\n大人: Đại nhân, người lớn\n客人: Khách","s":"HSK1_06#15"},{"c":"tu_mo_rong","t":"Người các nước","x":"中国人: Người Trung Quốc\n德国人: Người Đức\n俄国人: Người Nga\n法国人: Người Pháp\n韩国人: Người Hàn Quốc\n美国人: Người Mỹ\n日本人: Người Nhật\n英国人: Người Anh","s":"HSK1_06#21"}],"w_6_7":[{"c":"cach_dung","t":"Phân biệt 哪儿 / 哪 / 那儿 / 那","x":"哪儿 (nǎr, đại từ nghi vấn): đâu? — 你去哪儿？ Bạn đi đâu đấy?\n哪 (nǎ, đại từ nghi vấn): nào – dùng trong câu hỏi để đưa ra sự lựa chọn. — 你是哪国人？ Bạn là người nước nào?\n那儿 (nàr, đại từ chỉ nơi chốn): ở kia, đó, chỗ đó; dùng trong câu trần thuật, chỉ địa điểm cụ thể đã biết/đã nhắc đến. Cấu trúc: đại từ/danh từ + 那儿. — 我去她那儿。 Tôi đi đến chỗ cô ấy.\n那 (nà, đại từ chỉ thị): kia, đó – chỉ người, sự vật, địa điểm ở xa người nói/người nghe. — 那是王老师。 Kia là thầy giáo Vương. 这是我妈妈，那是我爸爸。 Đây là mẹ tôi, kia là bố tôi.\nMẹo: có bộ Khẩu 口 là để hỏi, có bộ Nhi 儿 thì chỉ nơi chốn.","s":"HSK1_06#29"},{"c":"cau_vi_du","t":"哪国 – nước nào","x":"哪 (nǎ): nào – dùng trong câu hỏi để đưa ra sự lựa chọn; có bộ Khẩu 口.\n哪国？ — Nước nào?\n哪国人？ — Người nước nào?\n你是哪国人？ — Bạn là người nước nào?","s":"HSK1_06#16"}],"w_6_9":[{"c":"van_hoa","t":"Ý nghĩa tên 中国","x":"中 (zhōng): Hán Việt: Trung (trung tâm).\nTrung Quốc luôn xem mình là trung tâm của thế giới.","s":"HSK1_06#17"}],"w_6_10":[{"c":"chiet_tu","t":"Chiết tự 美","x":"美 (měi): Hán Việt: Mỹ (đẹp).\nBộ thành phần: 王 Vương + 大 Đại.\nMẹo nhớ: Mỹ là quốc gia tươi đẹp.\nTừ mở rộng: 美女 — Mỹ nữ; 美人 — Mỹ nhân.","s":"HSK1_06#18"}],"w_6_12":[{"c":"chiet_tu","t":"Chiết tự 越南","x":"越: Hán Việt: Việt (vượt). Bộ thành phần: 走 Tẩu (đi).\n南: Hán Việt: Nam (hướng nam).\n越南人 — Người Việt Nam\nA: 你是哪国人？ — Bạn là người nước nào?\nB: 我是越南人。 — Tôi là người Việt Nam.","s":"HSK1_06#20"}],"w_6_16":[{"c":"chiet_tu","t":"Chiết tự 发音","x":"音: Hán Việt: Âm. Bộ thành phần: 立 Lập + 日 Nhật.\n发: Bộ thành phần: 又 Hựu.","s":"HSK1_06#23"}],"w_6_19":[{"c":"chiet_tu","t":"Chiết tự 谁","x":"Bộ thành phần: 讠 Ngôn + 隹 Chuy.\n她是谁？ — Cô ấy là ai?\n她是我妹妹。 — Cô ấy là em gái tôi.","s":"HSK1_06#25"}],"w_6_20":[{"c":"ngu_phap","t":"Định ngữ + 的 + trung tâm ngữ","x":"的 (de, trợ từ kết cấu): của. Cấu trúc: Định ngữ + 的 + trung tâm ngữ.\nĐịnh ngữ: bổ sung ý nghĩa cho danh từ (sở hữu, trạng thái, tính chất); có thể là danh từ, đại từ, tính từ hay cụm chủ-vị.\nTrung tâm ngữ: đối tượng chính được nhắc đến, đứng sau 的.\n我的书 — Sách của tôi; 谁的书 — Sách của ai; 王老师的书 — Sách của thầy giáo Vương; 我的妈妈 — Mẹ của tôi.\nVới quan hệ họ hàng, thân thiết có thể bỏ 的 cho gần gũi hơn: 我爸爸、我妈妈、我姐姐…\nA：这是谁的书？ — Đây là sách của ai?\nB：这是我妹妹的书。 — Đây là sách của em gái tôi.","s":"HSK1_06#26"}],"w_6_21":[{"c":"chiet_tu","t":"Chiết tự 志; phân biệt 土/士","x":"志 (zhì): Hán Việt: Chí.\nBộ thành phần: 士 Sĩ + 心 Tâm.\nMẹo nhớ: Kẻ sĩ có tấm lòng ham học hỏi, ý chí vươn lên thì là người có chí.\nPhân biệt: bộ Thổ 土 (nét trên ngắn, dưới dài); bộ Sĩ 士 (nét trên dài, dưới ngắn).\n这是我弟弟的杂志。 — Đây là tạp chí của em trai tôi.","s":"HSK1_06#30"}],"w_6_22":[{"c":"cach_dung","t":"中文 và 汉语","x":"文 (wén): Văn.\n中文: tiếng Trung. 文 mang nghĩa rộng, gồm cả văn nói (语) và văn viết (字).\n中文 = 汉语 + 汉字","s":"HSK1_06#32"}],"w_6_23":[{"c":"cau_vi_du","t":"Câu ví dụ với 朋友","x":"A：他是谁？ — Anh ấy là ai?\nB：他是我（的）朋友。 — Anh ấy là bạn tôi.\n朋友那儿 — Chỗ bạn tôi","s":"HSK1_06#33"}],"w_7_1":[{"c":"chiet_tu","t":"Mẹo nhớ 午","x":"午 (wǔ): Hán Việt: Ngọ.\nMẹo nhớ: Người nằm ra ngủ, 10 giờ trưa mới dậy.","s":"HSK1_07#4"}],"w_7_4":[{"c":"chiet_tu","t":"Chiết tự 食","x":"食 (shí): Hán Việt: Thực (thực phẩm).\nBộ thành phần: 人 Nhân + 良 Lương.\nMẹo nhớ: Người lương thiện sẽ làm ra được thực phẩm ngon.","s":"HSK1_07#5"},{"c":"chiet_tu","t":"Chiết tự 堂","x":"堂 (táng): Hán Việt: Đường (phòng lớn).\nBộ thành phần: 口 Khẩu + 土 Thổ.\n食堂 (shítáng): nhà ăn, canteen – Hán Việt: Thực đường.","s":"HSK1_07#6"}],"w_7_2":[{"c":"chiet_tu","t":"Chiết tự 吃","x":"Bộ thành phần: 口 Khẩu.\n好吃 (hǎochī, tính từ): ngon (dùng cho đồ ăn).","s":"HSK1_07#7"}],"w_7_3":[{"c":"chiet_tu","t":"Chiết tự 饭","x":"Bộ thành phần: 饣 Thực + 反 Phản.\n吃饭 — Ăn cơm\n今天中午我去食堂吃饭。 — Trưa nay tôi đi canteen ăn cơm.","s":"HSK1_07#8"}],"w_7_5":[{"c":"chiet_tu","t":"Mẹo nhớ 馒头","x":"Hán Việt: Màn thầu.\n馒: bộ Thực.\n头 (tóu): Đầu. Mẹo nhớ: Đầu lớn có 2 sợi tóc.","s":"HSK1_07#9"}],"w_7_6":[{"c":"cau_vi_du","t":"Câu ví dụ với 米饭","x":"你吃米饭吗？ — Bạn ăn cơm không?","s":"HSK1_07#11"},{"c":"tu_mo_rong","t":"米 – gạo","x":"米 (mǐ): Gạo – Hán Việt: Mễ; bản thân 米 là bộ Mễ","s":"HSK1_07#10"}],"w_7_7":[{"c":"cach_dung","t":"Hai cách dùng 要","x":"要 (yào, động từ): muốn, cần, phải. Có bộ Nữ.\n1. Làm động từ chính: 你要吗？ — Bạn cần/muốn không?\n2. 要 + động từ: 我要学中文。 — Tôi cần/phải/muốn học tiếng Trung.\n明天中午我要去食堂吃饭。 — Trưa mai tôi muốn đi canteen ăn cơm.","s":"HSK1_07#12"}],"w_7_8":[{"c":"ngu_phap","t":"Lượng từ 个 – lượng từ vạn năng","x":"个 (gè): cái, chiếc – dùng cho người và vật, phổ biến nhất (lượng từ vạn năng).\n1. Số từ + lượng từ + danh từ: 一个人 — Một người; 一个馒头 — Một cái màn thầu.\n2. Đại từ chỉ thị (这、那) + lượng từ + danh từ: 这个人 — Người này; 那个馒头 — Cái màn thầu kia.\n几个？ — Mấy cái?  哪个？ — Cái nào?","s":"HSK1_07#13"}],"w_7_9":[{"c":"chiet_tu","t":"Chiết tự 碗","x":"Bộ thành phần: 石 Thạch + 宀 Miên + 夕 Tịch + 卩 Tiết (đốt tre).\nA：你吃几碗米饭？ — Bạn ăn mấy bát cơm?\nB：我吃一碗米饭。 — Tôi ăn 1 bát cơm.","s":"HSK1_07#14"}],"w_7_10":[{"c":"chiet_tu","t":"Chiết tự 鸡蛋","x":"鸡: Hán Việt: Kê. Bộ thành phần: 又 Hựu + 鸟 Điểu.\nMẹo nhớ: Con gà cũng thuộc họ nhà chim.\n蛋: Hán Việt: Đản. Bộ thành phần: 虫 Trùng.\n我要吃五个鸡蛋。 — Tôi muốn ăn 5 quả trứng gà.","s":"HSK1_07#15"}],"w_7_11":[{"c":"cach_dung","t":"Canh thì “uống”: 喝汤","x":"汤 (tāng): canh. Bộ thành phần: 氵 Ba chấm thủy.\n鸡蛋汤 — Canh trứng gà\n喝汤 — Uống canh (ăn canh)\n这碗鸡蛋汤很好喝。 — Bát canh trứng gà này rất ngon.\n我要喝一碗鸡蛋汤。 — Tôi muốn uống 1 bát canh trứng gà.","s":"HSK1_07#16"}],"w_7_12":[{"c":"cau_vi_du","t":"Câu ví dụ với 啤酒","x":"我不喝酒，我喝啤酒。 — Tôi không uống rượu, tôi uống bia.","s":"HSK1_07#18"},{"c":"tu_mo_rong","t":"酒 – rượu","x":"酒 (jiǔ): Rượu – Hán Việt: Tửu\n喝酒: Uống rượu","s":"HSK1_07#17"}],"w_7_15":[{"c":"cach_dung","t":"Lượng từ 些","x":"些 (xiē, lượng từ): một số, một vài.\n一些 — Một vài; 一些人 — Một vài người\n这些 — Những cái này; 这些人 — Những người này\n那些 — Những cái kia; 那些人 — Những người kia\n哪些 — Những cái nào; 哪些人 — Những người nào\nLưu ý: 些 chỉ kết hợp với số từ 一, không kết hợp với số từ khác.","s":"HSK1_07#19"}],"w_7_16":[{"c":"cau_vi_du","t":"Câu ví dụ với 包子","x":"A：你要吃几个包子？ — Bạn muốn ăn mấy cái bánh bao?\nB：我要吃四个包子。 — Tôi muốn ăn 4 cái bánh bao.","s":"HSK1_07#21"}],"w_7_18":[{"c":"tu_mo_rong","t":"Phân biệt 面条 / 包子 / 面包","x":"面条: Mỳ\n包子: Bánh bao\n面包 (miànbāo): Bánh mỳ\n这碗面不太好吃。 — Bát mỳ này không ngon lắm.","s":"HSK1_07#22"}],"w_8_1":[{"c":"chiet_tu","t":"Chiết tự 买 và 卖","x":"买 (mǎi – động từ): Mua – Hán Việt: Mãi\nBộ thành phần: 头 Đầu\n卖 (mài – động từ): Bán – Hán Việt: Mại\nBộ thành phần: 十 Thập + 买\nMẹo nhớ: 10 người mua thì mới có 1 người bán.","s":"HSK1_08#4"},{"c":"cau_vi_du","t":"Câu ví dụ 买, 卖","x":"你要买什么？ — Bạn cần mua cái gì?\n我要买一碗面条，一碗鸡蛋汤。 — Tôi cần mua 1 bát mỳ, 1 bát canh trứng gà.\n这些人卖什么？ — Những người này bán cái gì vậy?","s":"HSK1_08#5"}],"w_8_3":[{"c":"chiet_tu","t":"Chiết tự 果 (水果)","x":"水果 (shuǐguǒ – danh từ): Hoa quả\n果 – Hán Việt: Quả\nBộ thành phần: 田 Điền + 木 Mộc. Mẹo nhớ: Trong ruộng có cây mọc ra quả.\n水 (shuǐ): Thủy (nước) => Hoa quả thì có nhiều nước.","s":"HSK1_08#6"},{"c":"cau_vi_du","t":"Câu ví dụ 水果","x":"我要买一些水果。 — Tôi muốn mua một ít hoa quả.","s":"HSK1_08#6"}],"w_8_4":[{"c":"chiet_tu","t":"Chiết tự 苹 (苹果)","x":"苹果 (píngguǒ – danh từ): Quả táo\n苹 – Hán Việt: Bình\nBộ thành phần: 艹 Thảo + 平 Bình","s":"HSK1_08#7"}],"w_8_5":[{"c":"cau_vi_du","t":"Câu ví dụ 斤, 公斤","x":"一斤 — Một cân (0,5 kg)\n一公斤 — Một kg\n几斤？ — Mấy cân?\n几公斤？ — Mấy kg?\n你要买几斤苹果？ — Bạn muốn mua mấy cân táo?","s":"HSK1_08#11"}],"w_8_7":[{"c":"chiet_tu","t":"Chiết tự 贵","x":"贵 (guì – tính từ): Đắt – Hán Việt: Quý\nBộ thành phần: 中 Trung (ở giữa) + 一 Nhất + 贝 Bối. Mẹo nhớ: Ở giữa 1 đống vật báu thì sẽ được mọi người yêu quý, mà cái gì quý thì cũng đắt.","s":"HSK1_08#12"}],"w_8_9":[{"c":"cau_vi_du","t":"Câu ví dụ 了 (đã, rồi) và câu hỏi 了吗","x":"我买水果了。 — Tôi mua hoa quả rồi.\n你买水果了吗？ — Bạn mua hoa quả chưa?\nA：你吃饭了吗？ — Bạn ăn cơm chưa?\nB：我吃饭了。 — Tôi ăn cơm rồi.","s":"HSK1_08#13"}],"w_8_8":[{"c":"cau_vi_du","t":"Câu cảm thán 太 + tính từ + 了","x":"Cấu trúc: 太 + hình dung từ + 了！ (Quá … rồi!)\n太贵了！我不买。 — Đắt quá! Tôi không mua đâu.\n太好了！ — Tốt quá!\n太难了！ — Khó quá!\n太忙了！ — Bận quá!\n太好吃（好喝）了！ — Ngon quá!","s":"HSK1_08#14"}],"w_8_11":[{"c":"chiet_tu","t":"Chiết tự 多","x":"多 (duō – tính từ): Nhiều – Hán Việt: Đa\nBộ thành phần: 夕 Tịch (x2). Mẹo nhớ: Một đêm đã nhiều rồi, hai đêm thì càng nhiều.\nVí dụ: 他买很多水果。 — Anh ấy mua rất nhiều hoa quả.","s":"HSK1_08#16"}],"w_8_12":[{"c":"chiet_tu","t":"Chiết tự 少","x":"少 (shǎo – tính từ): Ít – Hán Việt: Thiểu/Thiếu\nBộ thành phần: 小 Tiểu (nhỏ)\nVí dụ: 太少了！ — Ít quá!","s":"HSK1_08#17"}],"w_8_13":[{"c":"cau_vi_du","t":"Câu ví dụ 多少","x":"多少 (duōshǎo): Bao nhiêu\n多少人？ — Bao nhiêu người?\n多少钱？ — Bao nhiêu tiền?\n苹果一斤多少钱？ — Táo 1 cân bao nhiêu tiền?","s":"HSK1_08#18"}],"w_8_14":[{"c":"cach_dung","t":"Văn nói và văn viết: 块/元, 毛/角","x":"块 (kuài): Đồng – thường dùng trong văn nói\n元 (yuán): Đồng – thường dùng trong văn viết\n毛 (máo): Hào – thường dùng trong văn nói\n角 (jiǎo): Hào – thường dùng trong văn viết\n10 角（毛）= 1 元（块）","s":"HSK1_08#19"}],"w_8_16":[{"c":"cau_vi_du","t":"Đơn vị 分 và cách nói giá","x":"分 (fēn): Xu. 100 分 = 1 元（块）\n苹果一斤四块（元）五毛（角）。 — Táo 1 cân 4 đồng 5 hào.","s":"HSK1_08#21"}],"w_8_17":[{"c":"chiet_tu","t":"Chiết tự và cách dùng 吧","x":"吧 (ba – trợ từ): Nào, nhé, chứ, thôi đi – đặt ở cuối câu, dùng để rủ rê, đưa ra lời khuyên…\nBộ thành phần: 口 Khẩu + 巴 Ba\n你去吧！ — Bạn đi đi!\n你去买水果吧！ — Bạn đi mua hoa quả đi!","s":"HSK1_08#23"}],"w_8_18":[{"c":"chiet_tu","t":"Chiết tự 橘 (橘子)","x":"橘子 (júzi – danh từ): Quả quýt\nBộ thành phần 橘: 木 Mộc + 矛 Mâu (mâu thuẫn)","s":"HSK1_08#24"}],"w_8_19":[{"c":"cach_dung","t":"Chiết tự và cách dùng 还 + động từ / tính từ","x":"还 (hái – phó từ): Còn, vẫn còn – Hán Việt: Hoàn\nBộ thành phần: 辶 Quai xước + 不 Bất\n1. 还 + Động từ: 还要 – còn cần, còn muốn\n你还要吃水果吗？ — Bạn còn muốn ăn hoa quả không?\n2. 还 + Tính từ:\n你还好吗？ — Bạn còn khỏe/ổn chứ?\n他还忙吗？ — Anh ấy còn bận không?","s":"HSK1_08#25"}],"w_8_21":[{"c":"chiet_tu","t":"Chiết tự 别 (别的)","x":"别 (bié): Hán Việt: Biệt\nBộ thành phần: 口 Khẩu + 力 Lực + 刂 Đao đứng\n别的 (bié de): Khác, cái khác\n你还要别的吗？ — Bạn còn cần gì khác không?","s":"HSK1_08#26"}],"w_8_22":[{"c":"cach_dung","t":"怎么 + động từ: hỏi cách làm","x":"怎么 (zěnme – đại từ nghi vấn): Như thế nào\n怎么 + Động từ: Làm như thế nào (hỏi về cách làm một việc gì đó)\n怎么卖？ — Bán như thế nào?\n橘子怎么卖？ — Quýt bán như thế nào?","s":"HSK1_08#27"}],"w_8_24":[{"c":"cau_vi_du","t":"Câu ví dụ 一共","x":"一共几个？ — Tổng cộng mấy cái?\n一共两个。 — Tổng cộng hai cái.\n一共多少钱？ — Tổng cộng bao nhiêu tiền?\n一共两块五（毛）。 — Tổng cộng 2 đồng rưỡi.","s":"HSK1_08#29"}],"w_8_25":[{"c":"chiet_tu","t":"Chiết tự 给","x":"给 (gěi – động từ): Đưa – Hán Việt: Cấp\nBộ thành phần: 纟 Mịch + 合 Hợp","s":"HSK1_08#30"},{"c":"ngu_phap","t":"Cấu trúc 给 + người nhận + vật","x":"Động từ 给: Đưa, tặng, cung cấp\nCấu trúc: 给 + người nhận + vật được đưa/tặng\n妈妈给我一个苹果。 — Mẹ tôi đưa tôi một quả táo.\n一共三十六块五（毛）。你给我三十六块吧。 — Tổng cộng 36 đồng rưỡi. Bạn đưa tôi 36 đồng nhé.","s":"HSK1_08#30"}],"w_8_26":[{"c":"cach_dung","t":"找: trả tiền thừa / tìm kiếm","x":"找 (zhǎo – động từ) – Bộ thành phần: 扌 Thủ (tay)\n1. Trả lại tiền thừa:\n我找你一块。 — Trả lại bạn 1 đồng.\n一共三十六块。你给我五十块，我找你十四块。 — Tổng cộng 36 đồng. Bạn đưa tôi 50 đồng, tôi trả lại bạn 14 đồng.\n2. Tìm kiếm:\n你找什么？ — Bạn tìm cái gì?","s":"HSK1_08#31"}],"w_9_1":[{"c":"cau_vi_du","t":"Câu ví dụ 上午, 下午","x":"昨天上午我去买水果，今天下午我回学校。 — Sáng hôm qua tôi đi mua hoa quả, chiều nay tôi quay về trường.","s":"HSK1_09#5"},{"c":"tu_mo_rong","t":"上 (trên), 下 (dưới)","x":"上 (shàng): Trên – Hán Việt: Thượng\n下 (xià): Dưới – Hán Việt: Hạ","s":"HSK1_09#4"}],"w_9_3":[{"c":"chiet_tu","t":"Chiết tự 早, 晚","x":"早 – Hán Việt: Tảo\nBộ thành phần: 日 Nhật + 十 Thập\n早上 (zǎoshang – danh từ): Buổi sáng sớm\n晚 – Hán Việt: Vãn\nBộ thành phần: 日 Nhật + 免 Miễn\n晚上 (wǎnshang – danh từ): Buổi tối","s":"HSK1_09#6"},{"c":"cach_dung","t":"Buổi + 好: câu chào","x":"Buổi + 好: Chào…\n早上好 — Chào buổi sáng (hoặc: 早安)\n晚安 — Chúc ngủ ngon","s":"HSK1_09#7"}],"w_9_5":[{"c":"chiet_tu","t":"Chiết tự 换","x":"换 (huàn – động từ): Đổi – Hán Việt: Hoán (hoán đổi)\nBộ thành phần: 扌 Thủ (bộ tài gảy) + 奂 Hoán\n换钱: Đổi tiền\n星期五下午我要去银行换钱。 — Chiều thứ 6 tôi phải đi ngân hàng đổi tiền.","s":"HSK1_09#12"}],"w_9_6":[{"c":"cach_dung","t":"Lưu ý khi dùng 小姐","x":"小姐 (xiǎojiě – danh từ): Tiểu thư\nLưu ý: 小姐 vẫn được dùng trong tiếng Trung hiện đại, nhưng cần thận trọng vì từ này có thể mang nghĩa tích cực hoặc tiêu cực tùy ngữ cảnh.","s":"HSK1_09#14"}],"w_9_9":[{"c":"chiet_tu","t":"Chiết tự 营业员","x":"营业员 (yíngyèyuán – danh từ): Nhân viên bán hàng, nhân viên giao dịch\n营 (yíng): Doanh (kinh doanh)\nBộ thành phần: 艹 Thảo + 冖 Mịch + 口 Khẩu (x2). Mẹo nhớ: Trên bãi cỏ đang che đậy 2 cái miệng đang bàn chuyện kinh doanh.\n业 (yè): Nghiệp (doanh nghiệp, sự nghiệp)\n员 – Hán Việt: Viên (nhân viên)\nBộ thành phần: 口 Khẩu + 贝 Bối. Mẹo nhớ: Nhân viên thì miệng lúc nào cũng nhắc đến tiền.","s":"HSK1_09#17"}],"w_9_10":[{"c":"cau_vi_du","t":"币 (tệ) và 人民币","x":"币 (bì – danh từ): Tệ (tiền tệ)\n人民 (rénmín): Nhân dân\n人民币 (Rénmínbì): Nhân dân tệ (tiền Trung Quốc)\n我要换人民币。 — Tôi cần đổi nhân dân tệ.","s":"HSK1_09#22"}],"w_9_11":[{"c":"chiet_tu","t":"Chiết tự 港","x":"港 (gǎng – danh từ): Cảng\nBộ thành phần: 氵 Ba chấm thủy + 巷 Hạng","s":"HSK1_09#23"},{"c":"tu_mo_rong","t":"香港 (Hương Cảng) và 港币","x":"香港: Hồng Kông (Hương Cảng)\n港币: Đô la Hồng Kông","s":"HSK1_09#25"}],"w_9_13":[{"c":"chiet_tu","t":"Chiết tự 欧 (欧元)","x":"欧 (ōu): Âu (châu Âu)\nBộ thành phần: 区 Khu (khu vực) + 欠 Khiếm (thiếu thốn). Mẹo nhớ: Châu Âu là khu vực thiếu thốn.\n欧元 (ōuyuán): Đồng euro","s":"HSK1_09#27"}],"w_9_17":[{"c":"chiet_tu","t":"Chiết tự 盾 và cách gọi tắt 越盾","x":"盾 (dùn): Đồng – đơn vị tiền tệ của Việt Nam\nBộ thành phần: 目 Mục (mắt). Mẹo nhớ: Tiền Việt Nam được giấu ở sườn núi, 10 con mắt tìm mới ra.\n越南盾 (Yuènán dùn – danh từ): Việt Nam đồng (VNĐ), gọi tắt: 越盾","s":"HSK1_09#28"}],"w_9_18":[{"c":"chiet_tu","t":"Chiết tự 百 và cách đọc hàng trăm","x":"百 (bǎi – số từ): Trăm – Hán Việt: Bách\nBộ thành phần: 一 Nhất + 白 Bạch\n100: 一百\n200: 二百（两百）\nLuyện đọc: 136, 247, 956, 999…","s":"HSK1_09#29"}],"w_9_19":[{"c":"chiet_tu","t":"Mẹo nhớ 千","x":"千 (qiān – số từ): Nghìn, ngàn\nMẹo nhớ: Số 10 (十) mà phẩy một nét bên trên thì thành 1000.\n1111: 一千一百一十一\n2000: 两千（二千）","s":"HSK1_09#31"}],"w_9_20":[{"c":"chiet_tu","t":"Mẹo nhớ 万","x":"万 (wàn – số từ): Vạn, chục nghìn\nMẹo nhớ: Trông giống chữ h in thường.\n10.000: 一万\n100.000: 十万\n20.000: 两万（二万）","s":"HSK1_09#32"}],"w_9_21":[{"c":"chiet_tu","t":"Chiết tự 等","x":"等 (děng – động từ): Chờ đợi – Hán Việt: Đẳng\nBộ thành phần: ⺮ Trúc + 土 Thổ + 寸 Thốn. Mẹo nhớ: Đợi cây trúc trồng trên đất cao lên bằng 1 thốn thì bẻ măng về ăn.","s":"HSK1_09#34"}],"w_9_22":[{"c":"chiet_tu","t":"Chiết tự 会 (一会儿)","x":"会 (huì): Hội\nBộ thành phần: 人 Nhân + 二 Nhị + 厶 Tư. Mẹo nhớ: Người làm 2 việc riêng tư thì mất 1 lát.\n一会儿 (yíhuìr): Một chút, một lát\n再等一会（儿） — Chờ thêm một lát\n请等一会（儿） — Vui lòng chờ 1 lát","s":"HSK1_09#35"}],"w_9_23":[{"c":"chiet_tu","t":"Chiết tự 数","x":"数 (shǔ – động từ): Đếm\nBộ thành phần: 米 Mễ + 女 Nữ + 攵 Phộc (roi, dùng gậy để đánh). Mẹo nhớ: Ngày xưa người phụ nữ phải ngồi đếm từng hạt gạo, tay cầm cây gậy/cái roi để đánh dấu.","s":"HSK1_09#37"}],"w_10_2":[{"c":"chiet_tu","t":"Chiết tự 公 (办公)","x":"办公 (bàngōng – động từ): Làm việc (văn phòng). Mẹo nhớ: Làm việc 8 tiếng và làm bằng sức của mình.\n公 (gōng): Công (công cộng)\nBộ thành phần: 八 Bát + 厶 Khư (riêng tư)","s":"HSK1_10#4"}],"w_10_1":[{"c":"chiet_tu","t":"Chiết tự 室 (办公室)","x":"室 (shì – danh từ): Phòng, buồng\nBộ thành phần: 宀 Miên + 一 Nhất + 厶 Khư + 土 Thổ. Mẹo nhớ: Căn phòng ở dưới mái nhà là 1 chỗ riêng tư được xây trên đất.\n办公室 (bàngōngshì): Văn phòng làm việc","s":"HSK1_10#5"},{"c":"cau_vi_du","t":"Câu ví dụ 办公室 (2 cách hỏi)","x":"A：请问，这是不是王老师的办公室？（请问，这是王老师的办公室吗？） — Cho hỏi, đây có phải là văn phòng của thầy giáo Vương không?\nB：是（对）。 — Phải/Đúng.","s":"HSK1_10#5"}],"w_10_3":[{"c":"chiet_tu","t":"Chiết tự 职, 员","x":"职员 (zhíyuán – danh từ): Nhân viên, viên chức\n职 – Hán Việt: Chức (chức vụ)\nBộ thành phần: 耳 Nhĩ + 只 Chỉ. Mẹo nhớ: Chỉ có người tai to mới làm được chức lớn.\n员 – Hán Việt: Viên\nBộ thành phần: 口 Khẩu + 贝 Bối","s":"HSK1_10#6"}],"w_10_4":[{"c":"cach_dung","t":"找 có 2 nghĩa","x":"找 (zhǎo – động từ) – Bộ thành phần: 扌 Thủ (tay)\n1. Trả lại tiền thừa\n2. Tìm kiếm","s":"HSK1_10#7"}],"w_10_5":[{"c":"ngu_phap","t":"2 cách dùng 在: ở/tại và đang","x":"在 (zài): Tại – Bộ thành phần: 土 Thổ. Mẹo nhớ: Tại góc nhà có 1 đống đất.\n1. Giới từ – ở, tại: chỉ địa điểm hoặc vị trí của một sự việc, hành động. 在 + địa điểm\n他在学校。 — Anh ấy ở trường.\n你在哪儿？ — Bạn ở đâu?\n2. Trạng từ – đang: diễn tả hành động đang diễn ra tại thời điểm nói. 在 + động từ\n我在吃饭。 — Tôi đang ăn cơm.","s":"HSK1_10#8"}],"w_10_7":[{"c":"ngu_phap","t":"2 cách dùng 呢","x":"呢 (ne – trợ từ ngữ khí)\n1. Dùng để đặt câu hỏi: đặt cuối câu để hỏi về vị trí, tình trạng hoặc thông tin liên quan đến chủ đề đã nhắc đến trước đó, tương đương 'còn… thì sao?'\n你是哪国人？——我是越南人，你呢？（你是哪国人？）\n2. Nhấn mạnh hoặc kéo dài ý: thêm vào cuối câu để làm mềm câu nói, tạo cảm giác thân thiện hoặc nhấn mạnh trạng thái đang tiếp diễn\n我在吃饭呢。","s":"HSK1_10#10"}],"w_10_8":[{"c":"ngu_phap","t":"Chiết tự 住 và cấu trúc 住（在）+ địa điểm","x":"住 (zhù – động từ): Ở, cư trú – Hán Việt: Trú\nBộ thành phần: 亻 Nhân + 主 Chủ. Mẹo nhớ: Người thì làm chủ chỗ mình cư trú.\n住 +（在）+ địa điểm: Sống ở đâu đó\n我住在北京。 — Tôi sống ở Bắc Kinh.","s":"HSK1_10#11"}],"w_10_9":[{"c":"chiet_tu","t":"Chiết tự 楼","x":"楼 (lóu – danh từ): Nhà lầu, tòa nhà, tầng – Hán Việt: Lâu\nBộ thành phần: 木 Mộc + 米 Mễ + 女 Nữ. Mẹo nhớ: Nhà lầu thì làm bằng gỗ, trong nhà lầu có người phụ nữ và gạo.\n我住在十楼。 — Tôi sống ở tầng 10.","s":"HSK1_10#12"}],"w_10_11":[{"c":"chiet_tu","t":"Chiết tự 房, 间 (房间)","x":"房 (fáng) – Hán Việt: Phòng\nBộ thành phần: 户 Hộ (hộ dân) + 方 Phương (hình vuông). Mẹo nhớ: Căn phòng ở hộ dân có hình vuông.\n书房 (thư phòng): Phòng đọc, phòng để sách\n间 (jiān) – Hán Việt: Gian (không gian, gian phòng)\nBộ thành phần: 门 Môn + 日 Nhật. Mẹo nhớ: Mở cửa gian phòng ra đón ánh nắng mặt trời.\n房间 (fángjiān): Phòng, căn phòng\n我住的房间不太大。 — Căn phòng mà tôi ở không lớn lắm.","s":"HSK1_10#13"}],"w_10_12":[{"c":"chiet_tu","t":"Mẹo nhớ 号","x":"号 (hào – danh từ): Số, con số – Hán Việt: Hiệu\nMẹo nhớ: Miệng (口) thì đang đọc con số 5.\n你的房间号是多少？ — Số phòng của bạn là bao nhiêu?","s":"HSK1_10#16"}],"w_10_15":[{"c":"chiet_tu","t":"Chiết tự 码; 号码 = 号","x":"码 (mǎ) – Hán Việt: Mã (mã số)\nBộ thành phần: 石 Thạch + 马 Mã\n号码 = 号\nSố phòng: 房间号 / 房间号码","s":"HSK1_10#17"}],"w_10_6":[{"c":"chiet_tu","t":"Chiết tự 家","x":"家 (jiā – danh từ): Nhà – Hán Việt: Gia\nBộ thành phần: 宀 Miên + 豕 Thỉ (con lợn). Mẹo nhớ: Ngày xưa, mỗi gia đình đều nuôi lợn trong nhà.\n今天你回不回家（你回家吗）？ — Hôm nay bạn về nhà không?","s":"HSK1_10#18"}],"w_10_13":[{"c":"chiet_tu","t":"Chiết tự 知, 道","x":"知 (zhī): Tri (tri thức)\nBộ thành phần: 矢 Thỉ (mũi tên) + 口 Khẩu. Mẹo nhớ: Tri thức thể hiện qua việc luôn có mục đích trong lời nói.\n道 (dào): Đạo (con đường)\nBộ thành phần: 首 Thủ (đầu, đầu tiên) + 辶 Sước (bước đi). Mẹo nhớ: Bước đi trên con đường đầu tiên trong đời.\n知道 (zhīdào): Biết\n请问，你知道王老师住在哪儿吗？ — Xin hỏi, bạn biết thầy giáo Vương sống ở đâu không?","s":"HSK1_10#19"}],"w_10_14":[{"c":"chiet_tu","t":"Chiết tự 话 (电话)","x":"电 (diàn): Điện\n话 (huà): Thoại (lời nói)\nBộ thành phần: 讠 Ngôn + 舌 Thiệt (lưỡi). Mẹo nhớ: Cần phải uốn lưỡi trước khi nói ra lời nói nào đó.\n你知道他的电话号（号码）是多少吗？ — Bạn biết số điện thoại của anh ấy là bao nhiêu không?","s":"HSK1_10#23"}],"w_10_16":[{"c":"chiet_tu","t":"Chiết tự 零","x":"零 (líng – số từ): Không (số 0)\nBộ thành phần: 雨 Vũ (mưa) + 令 Lệnh. Mẹo nhớ: Mưa rơi xuống lệnh bằng 0.\n101: 一百零一","s":"HSK1_10#25"}],"w_10_17":[{"c":"chiet_tu","t":"Chiết tự 手机","x":"手机 (shǒujī): Điện thoại di động\n手 (shǒu) – Hán Việt: Thủ – Nghĩa: Tay\n机 (jī) – Hán Việt: Cơ (máy móc)\nBộ thành phần: 木 Mộc + 几 Kỷ. Mẹo nhớ: Ngày xưa, máy móc được làm từ mấy cái cây.","s":"HSK1_10#26"}],"w_10_18":[{"c":"chiet_tu","t":"Chiết tự 李","x":"李 (lǐ – danh từ): Cây mận, họ Lý\nBộ thành phần: 木 Mộc + 子 Tử. Mẹo nhớ: Mận là cây mà đứa con họ Lý trồng.","s":"HSK1_10#27"}],"w_11_1":[{"c":"chiet_tu","t":"Chiết tự 秘 (秘书)","x":"秘 (mì): Bí (bí mật)\nBộ thành phần: 禾 Hòa + 必 Tất (tất nhiên, tất yếu). Mẹo nhớ: Số lúa ở trong kho tất nhiên phải giữ bí mật.\n秘书 (mìshū): Thư ký (Hán Việt: Bí thư)\n她是您的秘书吗？ — Cô ấy là thư ký của ngài à?","s":"HSK1_11#4"}],"w_11_2":[{"c":"ngu_phap","t":"先 + động từ: làm gì trước","x":"先 (xiān – phó từ): Trước (tiên)\n先 + động từ: Làm gì trước\n你先吃饭吧！ — Bạn ăn cơm trước đi nhé!","s":"HSK1_11#6"}],"w_11_3":[{"c":"chiet_tu","t":"Chiết tự 介, 绍","x":"介 (jiè): Giới (giới thiệu). Mẹo nhớ: 1 người giới thiệu cho 2 người.\n绍 (shào): Thiệu\nBộ thành phần: 纟 Mịch (sợi tơ) + 召 Triệu (triệu tập). Mẹo nhớ: Dùng sợi tơ để triệu tập mọi người lại với nhau để giới thiệu.\n介绍 (jièshào): Giới thiệu","s":"HSK1_11#7"}],"w_11_4":[{"c":"cach_dung","t":"Phân biệt 一下 và 一会（儿）","x":"Động từ + 一下（儿） (yíxiàr): Nhấn mạnh hành động diễn ra trong thời gian ngắn, hành động nhanh\n一下: Một chút – nhấn mạnh vào hành động, ví dụ: 介绍一下\n一会（儿）: Một lát – nhấn mạnh vào thời gian thực hiện hành động, ví dụ: 等一会\n✗ 介绍一会 (không nói)","s":"HSK1_11#9"}],"w_11_5":[{"c":"cach_dung","t":"位: lượng từ trang trọng","x":"位 (wèi – lượng từ): Vị (quý vị) – dùng cho người, trong ngữ cảnh trang trọng\nBộ thành phần: 亻 Nhân + 立 Lập\n一位老师 — Một vị giáo viên\n请问，几位？（几位？= 几个人？） — Xin hỏi, bao nhiêu người?","s":"HSK1_11#10"}],"w_11_6":[{"c":"chiet_tu","t":"Chiết tự 教, 授","x":"教 (jiào): Giáo (giáo dục, dạy dỗ)\nBộ thành phần: 孝 Hiếu (耂 Lão + 子 Tử) + 攵 Phộc. Mẹo nhớ: Người già cầm gậy dạy dỗ đứa trẻ.\n授 (shòu): Thụ (truyền thụ, giảng dạy)\nBộ thành phần: 扌 Thủ + 受 Thụ (nhận). Mẹo nhớ: Dùng tay viết lại những kiến thức đã nhận được để dạy lại.\n我先介绍一下，这位是张教授。 — Tôi giới thiệu trước 1 chút, vị này là giáo sư Trương.","s":"HSK1_11#11"}],"w_11_7":[{"c":"cau_vi_du","t":"长 (trưởng) và 校长","x":"长 (zhǎng): Trưởng, cả\n校长 (xiàozhǎng): Hiệu trưởng\n校长在办公室吗？ — Hiệu trưởng có ở văn phòng không?","s":"HSK1_11#13"}],"w_11_8":[{"c":"chiet_tu","t":"Chiết tự 欢, 迎","x":"欢 (huān): Hoan (hoan hỷ, vui mừng)\nBộ thành phần: 又 Hựu + 欠 Khiếm (thiếu thốn, nợ). Mẹo nhớ: Lại đòi được nợ rồi nên rất hoan hỷ.\n迎 (yíng): Nghênh (nghênh đón, tiếp đón, chào đón)\nBộ thành phần: 辶 Sước + 卬 Ngang (ngẩng đầu). Mẹo nhớ: Ngẩng đầu đi ra nghênh đón khách.\n北京欢迎你。 — Bắc Kinh chào đón bạn.","s":"HSK1_11#14"}],"w_11_9":[{"c":"chiet_tu","t":"Chiết tự 留 (留学, 留学生)","x":"留 (liú): Lưu (lưu lại, lưu giữ)\nBộ thành phần: 卯 Mão + 田 Điền. Mẹo nhớ: Con mèo đi ra ngoài ruộng và lưu lại dấu chân ở đó.\n留学 (liúxué – động từ): Du học\n学生 (xuésheng): Học sinh\n留学生 (liúxuéshēng): Du học sinh\nCâu hỏi: Học sinh Việt Nam du học tại Trung Quốc là 越南留学生 hay 中国留学生？\nĐáp án: （在中国留学）的越南留学生","s":"HSK1_11#17"}],"w_11_11":[{"c":"cau_vi_du","t":"Ví dụ phân biệt 也 và 都","x":"也 (yě – phó từ): Cũng\n都 (dōu – phó từ): Đều\nA：我学汉语。 — Tôi học tiếng Trung.\nB：我也学汉语。 — Tôi cũng học tiếng Trung.\n=> 他们都学汉语。 — Họ đều học tiếng Trung.","s":"HSK1_11#20"}],"w_11_12":[{"c":"cach_dung","t":"Cách dùng 俩","x":"俩 (liǎ – lượng từ): Hai người, hai cái\n俩 thường được dùng trong văn nói; 俩 không đi kèm với lượng từ.\n你们 / 他们 / 我们 + 俩\n我们俩 = 我们两个人 — Hai người chúng tôi\n他们俩都不是留学生。 — Hai người họ đều không phải là du học sinh.","s":"HSK1_11#22"}],"w_11_16":[{"c":"chiet_tu","t":"Chiết tự 经, 理","x":"经 (jīng): Kinh (kinh qua, trải qua)\nBộ thành phần: 纟 Mịch + 一 Nhất + 人 Nhân + 工 Công. Mẹo nhớ: 1 người thợ trải qua công việc dệt tơ.\n理 (lǐ): Lý (quản lý)\nBộ thành phần: 王 Vương + 田 Điền + 土 Thổ. Mẹo nhớ: Ruộng và đất do vua quản lý.\n经理 (jīnglǐ): Giám đốc – người đã trải qua nhiều chuyện và có kinh nghiệm quản lý.","s":"HSK1_11#29"}],"w_11_15":[{"c":"chiet_tu","t":"Chiết tự 护 (护士)","x":"护 (hù): Hộ (bảo hộ, bảo vệ)\nBộ thành phần: 扌 Thủ (tay) + 户 Hộ. Mẹo nhớ: Dùng chính đôi bàn tay của mình để bảo vệ gia đình mình.\n护士 (hùshi): Hộ sĩ, y tá","s":"HSK1_11#31"}],"w_11_17":[{"c":"chiet_tu","t":"Chiết tự 律 (律师)","x":"律 (lǜ): Luật (pháp luật)\nBộ thành phần: 彳 Xích + 聿 Duật (bút). Mẹo nhớ: Luật là do hai người (thuộc hai phe) dùng bút viết ra.\n律师 (lǜshī): Luật sư","s":"HSK1_11#32"}],"w_11_19":[{"c":"chiet_tu","t":"Chiết tự 记, 者","x":"记 (jì): Ký (ghi chép)\nBộ thành phần: 讠 Ngôn + 己 Kỷ. Mẹo nhớ: Ghi chép lại lời nói của chính mình.\n者 (zhě): Giả (tác giả)\nBộ thành phần: 耂 Lão + 日 Nhật. Mẹo nhớ: Tác giả là người già và sáng tác ở ngoài trời.\n记者 (jìzhě): Ký giả, phóng viên","s":"HSK1_11#34"}],"w_12_1":[{"c":"cau_vi_du","t":"Ví dụ 语言 và 北京语言大学","x":"语言 (yǔyán – danh từ): Ngôn ngữ (言 – Ngôn)\nA：你在学什么语言？ — Bạn đang học ngôn ngữ gì vậy?\nB：我学汉语。 — Tôi đang học tiếng Trung.\n北京语言大学 — Đại học Ngôn ngữ Bắc Kinh, gọi tắt: 北语 (Bắc Ngữ)","s":"HSK1_12#5"}],"w_12_2":[{"c":"tu_mo_rong","t":"大学一年级 và cách gọi tắt 大一","x":"大学一年级 (dàxué yī niánjí): Năm nhất đại học\n大学一年级的学生 / 大一的学生: Sinh viên năm nhất đại học\nViết tắt: 大一","s":"HSK1_12#6"}],"w_12_3":[{"c":"chiet_tu","t":"Chiết tự 觉, 得 (觉得)","x":"觉 (jué): Giác (cảm giác)\nBộ thành phần: 𭕄 + 冖 Mịch + 见 Kiến. Mẹo nhớ: Cảm giác nhìn thấy vật gì đó bị che đậy lại phát sáng.\n得 (de / dé / děi): Đắc (đạt được)\nBộ thành phần: 彳 Xích + 日 Nhật + 一 Nhất + 寸 Thốn. Mẹo nhớ: Hai người mỗi ngày đi được 1 thốn cũng xem như đạt được thành tựu nhỏ.\n得 có 3 cách đọc: de, dé, děi (trong 觉得 đọc là juéde).","s":"HSK1_12#9"},{"c":"cach_dung","t":"2 nghĩa của 觉得","x":"觉得 (juéde – động từ)\n1. Cảm thấy (dựa trên cảm giác, cảm nhận) – nói về trạng thái thể chất, tinh thần hoặc cảm xúc:\n我觉得很累。 — Tôi cảm thấy rất mệt. (累 lèi: mệt)\n2. Nghĩ rằng (dựa trên suy nghĩ, đánh giá) – đưa ra suy nghĩ cá nhân về một sự việc:\nA：你觉得学习汉语怎么样？ — Bạn cảm thấy học tiếng Trung như thế nào?\nB：我觉得学习汉语很难。 — Tôi cảm thấy học tiếng Trung rất khó.","s":"HSK1_12#11"}],"w_12_6":[{"c":"chiet_tu","t":"Chiết tự 听","x":"听 (tīng – động từ): Nghe – Hán Việt: Thính\nBộ thành phần: 口 Khẩu + 斤 Cân. Mẹo nhớ: Phải cân nhắc trước khi nói thì người khác mới nghe.","s":"HSK1_12#13"}],"w_12_7":[{"c":"chiet_tu","t":"Chiết tự 说","x":"说 (shuō – động từ): Nói – Hán Việt: Thuyết\nBộ thành phần: 讠 Ngôn + 兑 Đoái (trao đổi). Mẹo nhớ: Nói là trao đổi ngôn từ.\n我觉得听和说不太难。 — Tôi cảm thấy nghe và nói không khó lắm.","s":"HSK1_12#14"}],"w_12_8":[{"c":"chiet_tu","t":"Chiết tự 读","x":"读 (dú – động từ): Đọc (đọc hiểu)\nBộ thành phần: 讠 Ngôn + 卖 Mại. Mẹo nhớ: Dùng lời nói đọc to lên để bán hàng.\n我在读中文杂志。 — Tôi đang đọc tạp chí tiếng Trung.","s":"HSK1_12#16"}],"w_12_9":[{"c":"chiet_tu","t":"Mẹo nhớ 写","x":"写 (xiě – động từ): Viết – Hán Việt: Tả\nMẹo nhớ: Trùm chăn lên tập viết 5 năm mới được 1 chữ.","s":"HSK1_12#17"}],"w_12_10":[{"c":"ngu_phap","t":"Chiết tự 较 và cấu trúc 比较 + tính từ","x":"比 (bǐ): Tỷ (so sánh)\n较 (jiào): Giảo (so sánh) – Bộ thành phần: 车 Xa (xe) + 交 Giao\n比较 (bǐjiào – phó từ chỉ mức độ): Tương đối, khá là, hơi\nCấu trúc: 比较 + Hình dung từ\n我觉得听和说比较难。 — Tôi cảm thấy nghe và nói hơi khó.","s":"HSK1_12#18"}],"w_12_11":[{"c":"chiet_tu","t":"Chiết tự 容, 易","x":"容 (róng): Dung (chứa đựng)\nBộ thành phần: 宀 Miên + 谷 Cốc (thung lũng). Mẹo nhớ: Trong nhà chứa lương thực cho cả một cốc ăn.\n易 (yì): Dị (dễ, dễ dàng)\nBộ thành phần: 日 Nhật + 勿 Vật. Mẹo nhớ: Phơi vật cả ngày dưới ánh mặt trời nó dễ dàng bị biến dị.\nA：你觉得英语容易吗？ — Bạn cảm thấy tiếng Anh dễ không?\nB：读和写比较容易。听和说太难了。 — Đọc và viết khá là dễ. Nghe và nói khó lắm.","s":"HSK1_12#19"}],"w_12_12":[{"c":"ngu_phap","t":"Cấu trúc 但是 và chiết tự 但","x":"但是 (dànshì – liên từ): Nhưng, tuy nhiên – chỉ sự tương phản giữa hai ý trong câu; phần sau 但是 thường phủ định hoặc trái ngược với phần trước.\nCấu trúc: Mệnh đề 1，但是 + Mệnh đề 2\n听和写很容易，但是语法很难。 — Nghe và viết rất dễ, nhưng mà ngữ pháp rất khó.\n但 (dàn) – Bộ thành phần: 亻 Nhân đứng + 日 Nhật + 一 Nhất","s":"HSK1_12#21"}],"w_12_14":[{"c":"tu_mo_rong","t":"新 – 旧 (mới – cũ)","x":"新 (xīn – tính từ): Mới – Hán Việt: Tân\nBộ thành phần: 亲 Thân + 斤 Cân\n旧 (jiù – tính từ): Cũ – Hán Việt: Cựu\nBộ thành phần: 日 Nhật\n我的手机太旧了！我要买一个新的（手机）。 — Điện thoại di động của tôi cũ quá rồi! Tôi muốn mua 1 cái (điện thoại) mới.","s":"HSK1_12#22"}],"w_12_15":[{"c":"chiet_tu","t":"Chiết tự 同 (同学)","x":"同 (tóng): Đồng (cùng, giống nhau)\nBộ thành phần: 冂 Quynh + 一 Nhất + 口 Khẩu. Mẹo nhớ: Trong vùng biên giới có 1 cái miệng nghĩa là cùng chung tiếng nói.\n同学 (tóngxué): Bạn học, bạn cùng lớp","s":"HSK1_12#23"}],"w_12_16":[{"c":"cach_dung","t":"Phân biệt 屋 và 室; chiết tự 屋","x":"同屋 (tóngwū): Bạn cùng phòng\n屋 (wū): chỉ ngôi nhà, căn nhà nói chung\n室 (shì): chỉ 'phòng' – một không gian cụ thể bên trong nhà hoặc tòa nhà\n屋 – Hán Việt: Ốc\nBộ thành phần: 尸 Thi (thi thể) + 至 Chí (đến). Mẹo nhớ: Thi thể nằm ở một chỗ riêng tư trên mặt đất trong phòng ốc.","s":"HSK1_12#24"}],"w_12_17":[{"c":"chiet_tu","t":"Chiết tự 班; 同班同学, 班长","x":"班 (bān – danh từ): Lớp\nBộ thành phần: 王 Vương (x2) + 刂 Đao đứng. Mẹo nhớ: Trong lớp có 2 ông vua cầm đao đánh nhau.\n同班同学: Bạn học cùng lớp\n班长 (bānzhǎng): Lớp trưởng\n你们班有多少学生？ — Lớp các bạn có bao nhiêu học sinh?","s":"HSK1_12#25"}],"w_12_18":[{"c":"chiet_tu","t":"Chiết tự 历, 史","x":"历 (lì): Lịch\nBộ thành phần: 力 Lực. Mẹo nhớ: Leo lên sườn núi dùng sức lực để khắc lịch.\n史 (shǐ): Sử\nBộ thành phần: 口 Khẩu. Mẹo nhớ: Lịch sử truyền miệng qua 10 (X) đời.\n历史 (lìshǐ): Lịch sử","s":"HSK1_12#28"}],"w_12_19":[{"c":"chiet_tu","t":"Chiết tự 济 (经济)","x":"济 (jì): Tế (kinh tế)\nBộ thành phần: 氵 Ba chấm thủy + 齐 Tề. Mẹo nhớ: Thủy Tề dùng thủy điện làm kinh tế.\n经济 (jīngjì): Kinh tế","s":"HSK1_12#31"}],"w_12_13":[{"c":"ngu_phap","t":"Giới từ 给: A + 给 + B + động từ","x":"Giới từ 给 (gěi) – chỉ đối tượng\nCấu trúc: A + 给 + B + Động từ: A làm gì cho B (B là đối tượng)","s":"HSK1_12#32"}],"w_13_3":[{"c":"ngu_phap","t":"Chiết tự 有 và hình thức chính phản 有没有","x":"有 (yǒu – động từ): Có – Hán Việt: Hữu\nBộ thành phần: 月 Nguyệt. Mẹo nhớ: Góc nhà có ánh trăng.\n没有 (méiyǒu): Không có\nHình thức chính phản: 有没有 = 有……吗？ (Có … không?)\nA：你有没有钱？ — Bạn có tiền không?\nB：我没有钱。 — Tôi không có tiền.","s":"HSK1_13#4"}],"w_13_2":[{"c":"chiet_tu","t":"Chiết tự 箱","x":"箱 (xiāng – danh từ): Rương, hòm, vali – Hán Việt: Tương\nBộ thành phần: ⺮ Trúc + 相 Tương (木 Mộc + 目 Mục). Mẹo nhớ: Cái hòm mà được làm bằng tre hoặc gỗ thì rất đẹp mắt.","s":"HSK1_13#5"},{"c":"tu_mo_rong","t":"行李箱 thay cho 箱子","x":"箱子 (xiāngzi): Thùng, hộp, rương, vali\nHiện nay từ này không còn phổ biến để chỉ vali nữa, thay vào đó người ta dùng 行李箱 (xínglǐxiāng).","s":"HSK1_13#6"}],"w_13_4":[{"c":"chiet_tu","t":"Chiết tự 重","x":"重 (zhòng – tính từ): Nặng – Hán Việt: Trọng\nBộ thành phần: 千 Thiên (nghìn) + 里 Lí (bên trong). Mẹo nhớ: Nghìn cân ở bên trong nên rất nặng.","s":"HSK1_13#8"}],"w_13_5":[{"c":"chiet_tu","t":"Chiết tự 轻","x":"轻 (qīng – tính từ): Nhẹ – Hán Việt: Khinh\nBộ thành phần: 车 Xa (xe) + 一 Nhất + 人 Nhân + 工 Công. Mẹo nhớ: Xe mà chỉ chở 1 người thì là công việc nhẹ nhàng.\n我的行李箱（箱子）很轻，我爸爸妈妈的（行李箱/箱子）比较重。 — Vali của tôi nhẹ lắm, (vali) của bố mẹ tôi khá là nặng.","s":"HSK1_13#9"}],"w_13_6":[{"c":"chiet_tu","t":"Chiết tự 黑","x":"黑 (hēi – tính từ): Đen – Hán Việt: Hắc\nBộ thành phần: 里 Lý + 灬 Hỏa","s":"HSK1_13#10"}],"w_13_7":[{"c":"chiet_tu","t":"Chiết tự 红","x":"红 (hóng – tính từ): Đỏ – Hán Việt: Hồng\nBộ thành phần: 纟 Mịch + 工 Công. Mẹo nhớ: Công việc dệt sợi tơ màu đỏ.\n我的行李箱是红的。他的是黑的。 — Vali của tôi là cái màu đỏ. Của anh ấy là cái màu đen.","s":"HSK1_13#11"}],"w_13_8":[{"c":"chiet_tu","t":"Chiết tự 药","x":"药 (yào – danh từ): Thuốc – Hán Việt: Dược\nBộ thành phần: 艹 Thảo + 纟 Mịch + 勺 Thược (thìa). Mẹo nhớ: Thuốc được làm từ cỏ, được cuốn tơ bên ngoài và dùng thìa để uống.","s":"HSK1_13#12"}],"w_13_9":[{"c":"cau_vi_du","t":"Ví dụ 中药","x":"A：这些黑的是什么？ — Những cái màu đen này là gì?\nB：都是中药。 — Đều là thuốc bắc.","s":"HSK1_13#13"}],"w_13_11":[{"c":"chiet_tu","t":"Chiết tự 叶 (茶叶)","x":"叶 (yè – danh từ): Lá – Hán Việt: Diệp\nBộ thành phần: 口 Khẩu + 十 Thập\n茶叶 (cháyè): Lá trà","s":"HSK1_13#14"}],"w_13_12":[{"c":"ngu_phap","t":"Chiết tự 里 và cấu trúc danh từ + 里","x":"里 (lǐ – danh từ): Trong, bên trong\nBộ thành phần: 田 Điền + 土 Thổ\nTrong cái gì: Danh từ + 里\n家里 — Trong nhà\n书里 — Trong sách\n行李箱（箱子）里 — Trong vali","s":"HSK1_13#15"}],"w_13_13":[{"c":"tu_mo_rong","t":"用, 品 (日用品)","x":"用 (yòng – động từ): Dùng, sử dụng – Hán Việt: Dụng\nBộ thành phần: 月 Nguyệt. Mẹo nhớ: Cắt đôi mặt trăng ra để sử dụng.\n品 (pǐn – danh từ): Sản phẩm – Hán Việt: Phẩm\nBộ thành phần: 口 Khẩu (x3)\n日用品 (rìyòngpǐn): Đồ dùng hàng ngày (Hán Việt: Nhật dụng phẩm)","s":"HSK1_13#16"}],"w_13_15":[{"c":"chiet_tu","t":"Chiết tự 服 (衣服)","x":"衣服 (yīfu): Quần áo – Hán Việt: Y phục (衣 – Y; 服 – Phục)\nBộ thành phần 服: 月 Nguyệt/Nhục + 卩 Tiết + 又 Hựu\n我的衣服都很旧了。 — Quần áo của tôi đều rất cũ rồi.","s":"HSK1_13#19"}],"w_13_14":[{"c":"chiet_tu","t":"Chiết tự 件","x":"件 (jiàn – lượng từ): Kiện, bộ (lượng từ của quần áo, sự việc)\nBộ thành phần: 亻 Nhân đứng + 牛 Ngưu\n一件新买的衣服 — Một bộ quần áo mới mua","s":"HSK1_13#20"}],"w_13_19":[{"c":"chiet_tu","t":"Chiết tự 把","x":"把 (bǎ – lượng từ): Cây, chiếc (dùng cho vật có tay cầm, có cán)\nBộ thành phần: 扌 Thủ + 巴 Ba\n他给我买一把雨伞。 — Anh ấy mua cho tôi 1 chiếc ô.","s":"HSK1_13#22"}],"w_13_20":[{"c":"chiet_tu","t":"Chiết tự 瓶","x":"瓶 (píng – lượng từ/danh từ): Bình, chai, lọ\nBộ thành phần: 并 Tịnh (八 Bát + 开 Khai) + 瓦 Ngõa (ngói). Mẹo nhớ: Cái bình được làm từ gạch ngói và dùng sức 8 lần thì mới mở được.\n一瓶水 — Một bình/chai nước\n一瓶香水 — Một bình nước hoa","s":"HSK1_13#24"}],"w_13_22":[{"c":"chiet_tu","t":"Chiết tự 词, 典","x":"词 (cí): Từ\nBộ thành phần: 讠 Ngôn + 司 Tư/Ti. Mẹo nhớ: Phát ngôn phải có tôn ti thì mới là ngôn từ.\n典 (diǎn): Điển\nBộ thành phần: 曲 Khúc + 八 Bát. Mẹo nhớ: Có 8 ca khúc kinh điển.\n词典 (cídiǎn): Từ điển","s":"HSK1_13#25"}],"w_13_23":[{"c":"cau_vi_du","t":"Ví dụ lượng từ 本","x":"本 (běn – lượng từ): Cuốn, quyển, tập (dùng cho sách vở, sổ sách)\n一本汉英词典 — Một quyển từ điển Hán-Anh\n一本英文（英语）书 — Một quyển sách tiếng Anh\n两本中文杂志 — Hai quyển tạp chí tiếng Trung","s":"HSK1_13#26"}],"w_13_24":[{"c":"chiet_tu","t":"Chiết tự 优, 盘 (优盘)","x":"优盘 (yōupán – danh từ): USB. Hiện nay người Trung Quốc thường dùng U盘 thay vì 优盘.\n优 (yōu): Ưu (ưu điểm, ưu tú)\nBộ thành phần: 亻 Nhân + 尤 Vưu (nổi bật). Mẹo nhớ: Người nổi bật thường ưu tú.\n盘 (pán): Bàn (đĩa, mâm, khay)\nBộ thành phần: 舟 Châu (thuyền) + 皿 Mãnh (đĩa). Mẹo nhớ: Trên đĩa in hình con thuyền.\n光盘 (guāngpán): Đĩa CD","s":"HSK1_13#27"}],"w_13_25":[{"c":"chiet_tu","t":"Chiết tự 张","x":"张 (zhāng – lượng từ): Dùng cho những vật mỏng (giấy, báo, tranh…) – Hán Việt: Trương\nBộ thành phần: 弓 Cung + 长 Trường\n两张光盘 — 2 cái đĩa CD","s":"HSK1_13#28"}],"w_13_28":[{"c":"chiet_tu","t":"Chiết tự 笔; 毛笔, 一支笔","x":"笔 (bǐ – danh từ): Bút\nBộ thành phần: ⺮ Trúc + 毛 Mao. Mẹo nhớ: Bút có đầu lông và thân bằng tre.\n毛 (máo): Lông (Mao); 毛笔 (máobǐ): Bút lông\n支 (zhī – lượng từ): Cây, cán (dùng cho vật có hình cán dài)\n一支（毛）笔 — Một cái bút (lông)","s":"HSK1_13#29"}],"w_13_32":[{"c":"chiet_tu","t":"Chiết tự 平, 板 (平板电脑)","x":"平板电脑 (píngbǎn diànnǎo): Máy tính bảng, gọi tắt: 平板\n平 (píng): Bình (bình yên, bằng phẳng)\nBộ thành phần: 八 Bát + 干 Can. Mẹo nhớ: Làm 18 chuyện tốt thì cuộc đời bình an.\n板 (bǎn): Bản (tấm, bảng)\nBộ thành phần: 木 Mộc + 反 Phản. Mẹo nhớ: Phản đối chặt cây lấy gỗ làm bảng.","s":"HSK1_13#32"}],"w_14_3":[{"c":"ngu_phap","t":"久, 好久 và 好 + tính từ","x":"久 (jiǔ – tính từ): Lâu, thời gian dài – Hán Việt: Cửu\n我等你太久了！ — Tôi đợi bạn lâu lắm rồi!\n好久 (hǎojiǔ): Đã lâu, rất lâu rồi\n好久不见 — Đã lâu không gặp\n好 + Tính từ = 很 + Tính từ: Rất…\n我觉得学习汉语很难。= 我觉得学习汉语好难。","s":"HSK1_14#5"}],"w_14_28":[{"c":"ngu_phap","t":"Trợ từ ngữ khí và thán từ 啊","x":"啊 (a – trợ từ ngữ khí): A, à\n1. Biểu đạt sự ngạc nhiên, kinh ngạc:\n你会说中文啊！(Nǐ huì shuō Zhōngwén a!) — Bạn biết nói tiếng Trung à!\n2. Nhấn mạnh cảm xúc, làm câu nói sinh động hơn:\n太好了啊！(Tài hǎo le a!) — Tuyệt quá đi à!\nÂm cuối của 啊 có thể thay đổi (thành ya, wa, na…) tùy theo âm tiết đứng trước: 太贵啊！(Tài guì ya!)\nThán từ 啊 khi đọc thanh 4 (à) mang nghĩa 'rõ rồi, hiểu rồi': 啊！知道了！","s":"HSK1_14#6"}],"w_14_4":[{"c":"tu_mo_rong","t":"虎 (hổ) và 马马虎虎","x":"虎 (hǔ – danh từ): Hổ\n马马虎虎 (mǎmahūhu): Tàm tạm, bình thường thôi\n你最近好吗？——马马虎虎。 — Dạo này bạn thế nào? – Bình thường.","s":"HSK1_14#7"}],"w_14_5":[{"c":"cach_dung","t":"Vị trí của 最近; chiết tự 近","x":"最近 (zuìjìn – danh từ chỉ thời gian): Gần đây – có thể đứng trước hoặc sau chủ ngữ\n你最近怎么样？ — Bạn gần đây như thế nào?\n近 (jìn – tính từ): Gần – Hán Việt: Cận\nBộ thành phần: 辶 Sước + 斤 Cân","s":"HSK1_14#9"},{"c":"ngu_phap","t":"最 + tính từ: … nhất","x":"最 (zuì – phó từ): Nhất – Hán Việt: Tối\nBộ thành phần: 日 Nhật + 取 Thủ. Mẹo nhớ: Khó nhất là lấy mặt trời xuống.\n最 + tính từ: … nhất\n我觉得汉字最难。 — Tôi cảm thấy chữ Hán khó nhất.","s":"HSK1_14#8"}],"w_14_7":[{"c":"cau_vi_du","t":"Ví dụ 开学","x":"他的学校昨天刚开学。我的学校今天也刚开学。 — Trường của anh ấy hôm qua vừa mới khai giảng. Trường tôi hôm nay cũng vừa mới khai giảng.","s":"HSK1_14#11"}],"w_14_9":[{"c":"chiet_tu","t":"Chiết tự 点 và 点 chỉ giờ","x":"点 (diǎn – danh từ): Điểm, chấm, giờ\nBộ thành phần: 占 Chiếm + 灬 Hỏa. Mẹo nhớ: Chiếm thời giờ chứ đừng đốt thời giờ.\n晚上八点 — 8 giờ tối\n几点了？——下午五点。 — Mấy giờ rồi? – 5 giờ chiều.","s":"HSK1_14#12"}],"w_14_10":[{"c":"cach_dung","t":"Phân biệt 一点 + danh từ và 有（一）点儿 + tính từ","x":"一点 + Danh từ không đếm được: một chút, một ít … (chỉ số lượng ít)\n你给我一点水吧！ — Bạn đưa tôi 1 ít nước nhé!\n有（一）点儿 + Tính từ: có (một) chút … (mức độ thấp, đôi khi thể hiện thái độ không vừa ý)\n我最近有（一）点儿忙。 — Tôi gần đây hơi bận.\n这个行李箱有（一）点儿大。 — Cái vali này hơi to.","s":"HSK1_14#13"}],"w_14_11":[{"c":"cau_vi_du","t":"Câu hỏi lựa chọn với 还是","x":"还是 (háishì – liên từ): Hoặc, hay là – dùng trong câu hỏi để đưa ra sự lựa chọn: A 还是 B？\n你要买苹果还是橘子？ — Bạn muốn mua táo hay là quýt?\n明天中午你们要吃面条还是饺子？ — Trưa mai các bạn muốn ăn mỳ hay là sủi cảo?","s":"HSK1_14#14"}],"w_14_12":[{"c":"chiet_tu","t":"Chiết tự 咖, 啡","x":"咖啡 (kāfēi): Cà phê\n咖 – Bộ thành phần: 口 Khẩu + 力 Lực (加)\n啡 – Bộ thành phần: 口 Khẩu + 非 Phi\nMẹo nhớ: Anh Lực đi uống cà phê cùng anh Phi.","s":"HSK1_14#15"}],"w_14_13":[{"c":"chiet_tu","t":"Chiết tự 杯","x":"杯 (bēi – danh từ): Cốc, ly – Hán Việt: Bôi\nBộ thành phần: 木 Mộc + 不 Bất. Mẹo nhớ: Cốc không phải làm từ cây.\n今天上午她给我买一杯咖啡。 — Sáng nay cô ấy mua cho tôi 1 cốc cà phê.","s":"HSK1_14#16"}],"w_14_14":[{"c":"tu_mo_rong","t":"Cụm từ với 车","x":"车 (chē – danh từ): Xe\n开车 (lái xe – xe 4 bánh trở lên)\n上车: Lên xe\n下车: Xuống xe","s":"HSK1_14#17"}],"w_14_15":[{"c":"tu_mo_rong","t":"自, 自我介绍, 自行车","x":"自 (zì – đại từ): Tự, tự mình, bản thân – Hán Việt: Tự\n自我: Bản thân tôi\n大家好！我先自我介绍一下！ — Xin chào mọi người! Trước tiên tôi giới thiệu về bản thân 1 chút!\n自行车 (zìxíngchē): Xe đạp – Hán Việt: Tự hành xa","s":"HSK1_14#18"}],"w_14_20":[{"c":"chiet_tu","t":"Chiết tự 骑","x":"骑 (qí – động từ): Cưỡi (ngựa), đi xe (2 bánh) – Hán Việt: Kỵ\nBộ thành phần: 马 Mã + 奇 Kỳ (大 Đại + 可 Khả). Mẹo nhớ: Chỉ có người lớn mới có khả năng cưỡi ngựa.\n我弟弟骑自行车回家。 — Em trai tôi đạp xe đạp về nhà.","s":"HSK1_14#19"}],"w_14_16":[{"c":"chiet_tu","t":"Chiết tự 摩, 托 (摩托车)","x":"摩 (mó – động từ): Mài, ma sát – Hán Việt: Ma\nBộ thành phần: 麻 Ma (cây gai) + 手 Thủ\n托 (tuō): Thác\nBộ thành phần: 扌 Thủ + 乇 Thác\n摩托车 (mótuōchē): Xe máy, xe mô tô\nĐi/lái xe máy: 骑摩托车","s":"HSK1_14#20"}],"w_14_17":[{"c":"chiet_tu","t":"Chiết tự 汽 (汽车)","x":"汽 (qì – danh từ): Hơi nước – Hán Việt: Khí\nBộ thành phần: 氵 Ba chấm thủy + 气 Khí. Mẹo nhớ: Nước sau khi bốc hơi thành dạng khí thì gọi là hơi nước.\n汽车 (qìchē): Ô tô, xe hơi\nLái xe ô tô: 开汽车（开车）","s":"HSK1_14#21"}],"w_14_29":[{"c":"chiet_tu","t":"Chiết tự 出, 租 (出租车)","x":"出 (chū – động từ): Ra (từ trong ra ngoài) – Hán Việt: Xuất\nBộ thành phần: 山 Sơn. Mẹo nhớ: Ra núi này đến núi cao hơn.\n租 (zū – động từ): Thuê\nBộ thành phần: 禾 Hòa + 且 Thả. Mẹo nhớ: Đã thuê thì thư thả mà trả bằng lúa.\n出租 (chūzū): Cho thuê\n出租车 (chūzūchē): Xe taxi. Đi xe taxi: 坐出租车","s":"HSK1_14#22"}],"w_14_22":[{"c":"chiet_tu","t":"Chiết tự 辆","x":"辆 (liàng – lượng từ): Chiếc (dùng cho xe cộ) – Hán Việt: Lượng\nBộ thành phần: 车 Xa + 两 Lưỡng. Mẹo nhớ: 1 chiếc xe 2 người đi.\n我家有一辆自行车，两辆摩托车和一辆汽车。 — Nhà tôi có 1 chiếc xe đạp, 2 chiếc xe máy và 1 chiếc xe hơi.","s":"HSK1_14#23"}],"w_14_23":[{"c":"chiet_tu","t":"Chiết tự 颜 (颜色)","x":"颜 (yán): Màu sắc – Hán Việt: Nhan\nBộ thành phần: 彦 Ngạn + 页 Hiệt. Mẹo nhớ: Nhan sắc bị hủy hoại với 3 vết sẹo, cô ấy đứng trên vách núi viết giấy từ biệt.\n色 (sè): Sắc\n颜色 (yánsè): Màu sắc\n你知道她喜欢什么颜色吗？ — Bạn biết cô ấy thích màu gì không? (喜欢 xǐhuan: thích)","s":"HSK1_14#24"}],"w_14_24":[{"c":"cach_dung","t":"Chiết tự 蓝 và cách nói màu … + 色","x":"蓝 (lán – tính từ): Màu xanh dương – Hán Việt: Lam\nBộ thành phần: 艹 Thảo + 监 Giám (刂 Đao đứng + ⺮ Trúc + 皿 Mãnh). Mẹo nhớ: Thảo cầm dao chặt trúc bỏ trên đĩa màu xanh lam.\n… + 色: Màu …\n红色、黑色、蓝色、白色","s":"HSK1_14#25"}],"w_15_1":[{"c":"chiet_tu","t":"Chiết tự 全 và cấu trúc 全 + danh từ","x":"全 (quán – tính từ/phó từ): Đầy đủ, toàn bộ – Hán Việt: Toàn\nBộ thành phần: 人 Nhân + 王 Vương. Mẹo nhớ: Toàn bộ người dân phải nghe lệnh nhà vua.\n全 + Danh từ: Tất cả …\n全家 — Cả nhà\n全国 — Cả nước\n全班 — Cả lớp","s":"HSK1_15#4"}],"w_15_3":[{"c":"chiet_tu","t":"Chiết tự 照, 片 (照片)","x":"照 (zhào – động từ): Soi chiếu, quay chụp – Hán Việt: Chiếu\nBộ thành phần: 日 Nhật + 召 Triệu + 灬 Hỏa. Mẹo nhớ: Ở ngoài trời triệu tập mọi người lại bên đống lửa để chụp ảnh.\n片 (piàn – danh từ): Tấm, mảnh, miếng – Hán Việt: Phiến\n照片: Ảnh; lượng từ: 张\n这是一张我全家的照片。 — Đây là 1 bức ảnh cả gia đình tôi.","s":"HSK1_15#5"}],"w_15_4":[{"c":"chiet_tu","t":"Chiết tự 看; 好看","x":"看 (kàn – động từ): Nhìn, xem – Hán Việt: Khán\nBộ thành phần: 手 Thủ + 目 Mục. Mẹo nhớ: Lấy tay che mắt để nhìn.\n我给你看我新买的衣服。 — Tôi cho bạn xem bộ quần áo mới mua của tôi.\n好看 (hǎokàn): Đẹp, ưa nhìn\n你觉得这件衣服好看吗？ — Bạn cảm thấy bộ quần áo này có đẹp không?","s":"HSK1_15#7"}],"w_15_6":[{"c":"cau_vi_du","t":"Ví dụ 只","x":"只看一下 — Chỉ nhìn/xem 1 chút\n我没有弟弟，我只有一个姐姐。 — Tôi không có em trai, tôi chỉ có 1 chị gái.","s":"HSK1_15#8"}],"w_15_7":[{"c":"chiet_tu","t":"Chiết tự 做","x":"做 (zuò – động từ): Làm, thực hiện – Hán Việt: Tố\nBộ thành phần: 亻 Nhân + 十 Thập + 口 Khẩu + ⺙ Phộc. Mẹo nhớ: 1 người làm mà 10 miệng ăn, ăn không đủ thì đánh nhau.\n你做什么工作？ — Bạn làm công việc gì?","s":"HSK1_15#9"}],"w_15_9":[{"c":"chiet_tu","t":"Chiết tự 医 (医生)","x":"医 (yī – danh từ): Y (y tế, y học)\nBộ thành phần: 匚 Phương + 矢 Thỉ (mũi tên). Mẹo nhớ: Chữa bệnh bằng cách lấy mũi tên ra và cho vào tủ.\n你爸爸做什么工作？——我爸爸是（做）医生。 — Bố bạn làm nghề gì? – Bố tôi là (làm) bác sĩ.\n大夫 có thể thay bằng 医生.","s":"HSK1_15#11"}],"w_15_10":[{"c":"chiet_tu","t":"Chiết tự 院 (医院, 学院)","x":"院 (yuàn – danh từ): Sân, viện – Hán Việt: Viện\nBộ thành phần: 阝 Phụ + 宀 Miên + 元 Nguyên. Mẹo nhớ: Viện là vùng đất mà chui vào mái nhà đó là mất tiền.\n医院 (yīyuàn): Bệnh viện (Y viện)\n我妈妈是医生，她在医院工作。 — Mẹ tôi là bác sĩ, bà ấy làm việc ở bệnh viện.\n学院: Học viện","s":"HSK1_15#12"}],"w_15_11":[{"c":"cach_dung","t":"Lượng từ 家 cho 公司; 司机","x":"公司 (gōngsī): Công ty – lượng từ cho công ty: 家\n我爸爸是这家公司的经理。 — Bố tôi là giám đốc của công ty này.\n司 (sī): Tư/Ti\n司机 (sījī): Tài xế","s":"HSK1_15#13"}],"w_15_12":[{"c":"chiet_tu","t":"Chiết tự 商, 店 (商店)","x":"商 (shāng): Thương (thương lượng) – Bộ thành phần: 立 Lập\n店 (diàn): Quán, cửa hàng – Hán Việt: Điếm\nBộ thành phần: 广 Quảng (rộng rãi) + 占 Chiếm. Mẹo nhớ: Chiếm chỗ rộng rãi để mở cửa hàng.\n商店: Cửa hàng, cửa tiệm (Thương điếm) – lượng từ: 家\n我妈妈是营业员，她在一家商店工作。 — Mẹ tôi là nhân viên bán hàng, bà ấy làm việc ở 1 cửa tiệm.","s":"HSK1_15#15"}],"w_15_14":[{"c":"chiet_tu","t":"Chiết tự 贸 (外贸)","x":"贸 (mào): Mậu (mậu dịch, thương mại, giao dịch, trao đổi)\nBộ thành phần: 卯 Mão + 贝 Bối. Mẹo nhớ: Con mèo được xem như bảo bối để đem đi trao đổi.\n外贸 (wàimào): Thương mại quốc tế, ngoại thương\n越南外贸大学 — Đại học Ngoại thương (Việt Nam)","s":"HSK1_15#17"},{"c":"tu_mo_rong","t":"Chiết tự 外; 外国","x":"外 (wài): Ngoại (bên ngoài)\nBộ thành phần: 夕 Tịch (đêm khuya) + 卜 Bốc (xem bói). Mẹo nhớ: Đêm khuya mà muốn đi xem bói thì phải đi ra ngoài.\n外国: Nước ngoài (ngoại quốc)\n他不是中国人，他是外国人。 — Anh ấy không phải người Trung Quốc, anh ấy là người nước ngoài.\n他在一家外国公司工作。 — Anh ấy làm việc ở 1 công ty nước ngoài.","s":"HSK1_15#16"}],"w_15_15":[{"c":"cau_vi_du","t":"Ví dụ 小 với 有点","x":"我觉得这个房间有点小。 — Tôi cảm thấy căn phòng này hơi nhỏ.","s":"HSK1_15#19"}],"w_15_16":[{"c":"cach_dung","t":"员工 = 人员 = 职员","x":"员工 (yuángōng): Nhân viên (Viên công)\n员工 = 人员 = 职员\n我哥哥是一家外贸公司的员工（人员）。 — Anh trai tôi là nhân viên của 1 công ty thương mại quốc tế.","s":"HSK1_15#20"}],"w_15_17":[{"c":"chiet_tu","t":"Chiết tự 概 (大概)","x":"概 (gài): Khái (đại khái, khoảng chừng)\nBộ thành phần: 木 Mộc + 既 Ký. Mẹo nhớ: Đại khái là gỗ có cứng hay không?\n大概 (dàgài – phó từ): Khoảng chừng, xấp xỉ, đại khái\n你们公司大概有多少员工？ — Công ty các bạn có khoảng bao nhiêu nhân viên?","s":"HSK1_15#21"}],"w_15_18":[{"c":"ngu_phap","t":"Số + 多; phân biệt 多少 và 几","x":"1. Số + 多: biểu thị con số vượt quá mức đã nêu nhưng không xác định chính xác là bao nhiêu\n十多个人 — Hơn mười người\n2. 多少 (bao nhiêu) và 几 (mấy):\n多少: dùng cho số > 10 – 你们公司大概有多少员工？ — Công ty các bạn có khoảng bao nhiêu nhân viên?\n几: dùng cho số < 10 – 你家有几口人？ — Nhà bạn có mấy người?","s":"HSK1_15#25"}],"w_16_1":[{"c":"chiet_tu","t":"Chiết tự 现","x":"现 (xiàn) – Hán Việt: Hiện (hiện tại).\nBộ thành phần: 王 Vương + 见 Kiến.\nMẹo nhớ: Ông vua chứng kiến tình hình hiện tại của đất nước.","s":"HSK2_16#5"}],"w_16_2":[{"c":"chiet_tu","t":"Chiết tự 跟","x":"Bộ thành phần: 足 Túc (chân) + 艮 Cấn.","s":"HSK2_16#7"},{"c":"cach_dung","t":"Cấu trúc A 跟 B + động từ","x":"A 跟 B + động từ: A làm gì cùng với B.\n明天我跟他去银行换钱。— Ngày mai tôi cùng anh ấy đi ngân hàng đổi tiền.","s":"HSK2_16#7"}],"w_16_3":[{"c":"chiet_tu","t":"Chiết tự 起 (一起)","x":"起 (qǐ) – Hán Việt: Khởi (dậy, bắt đầu).\nBộ thành phần: 走 Tẩu + 己 Kỉ (chính mình).","s":"HSK2_16#8"},{"c":"cau_vi_du","t":"A 跟/和 B 一起 + động từ","x":"A 跟/和 B 一起 + động từ: A và B cùng nhau làm gì.\n我跟/和我朋友一起走回家。— Tôi đi bộ về nhà cùng với bạn tôi.","s":"HSK2_16#8"}],"w_16_4":[{"c":"chiet_tu","t":"Chiết tự 咱","x":"咱 (zán) – Nghĩa: Ta (chúng ta).\nBộ thành phần: 口 Khẩu + 自 Tự.\nMẹo nhớ: Cái miệng tự nói mình là chúng ta.","s":"HSK2_16#9"},{"c":"cach_dung","t":"Phân biệt 咱们 và 我们","x":"咱们: chúng ta (bao gồm người nghe).\n我们: chúng ta (bao gồm người nghe) hoặc chúng tôi (không bao gồm người nghe).\n晚上咱们（我们）一起去吧。\n你们是留学生，我们是中国学生，咱们是朋友。","s":"HSK2_16#10"}],"w_16_5":[{"c":"cach_dung","t":"Hai nghĩa của 走","x":"1. Đi, bước đi, đi bộ: 我走回家。— Tôi đi bộ về nhà.\n2. Đi khỏi, rời khỏi: 我先走了！— Tôi đi trước đây!","s":"HSK2_16#11"},{"c":"cach_dung","t":"Phân biệt 走 và 去","x":"Giống: đều thể hiện sự di chuyển, sự rời đi: 你走/去吧！\n走: đi bộ, quãng đường ngắn (我走回家。); KHÔNG đi với tân ngữ chỉ địa điểm – không nói: 你走哪儿？/ 你走北京。\n去: có điểm đến – 我去北京。","s":"HSK2_16#12"}],"w_16_6":[{"c":"chiet_tu","t":"Chiết tự 常","x":"Bộ thành phần: 小 Tiểu + 冖 Mịch + 口 Khẩu + 巾 Cân (khăn).","s":"HSK2_16#13"},{"c":"cau_vi_du","t":"Ví dụ 常（常常）","x":"常（常常）+ động từ: thường xuyên làm gì.\n我们常常一起去图书馆学习。— Chúng tôi thường xuyên đi thư viện học bài cùng nhau.","s":"HSK2_16#13"}],"w_16_7":[{"c":"cau_vi_du","t":"Ví dụ 借 (mượn sách)","x":"我常去图书馆借书。— Tôi thường đi thư viện mượn sách.","s":"HSK2_16#15"}],"w_16_8":[{"c":"tu_mo_rong","t":"上网 / 网课","x":"上网: lên mạng (động từ)\n网课 (wǎngkè): lớp học, khóa học online (danh từ)","s":"HSK2_16#16"}],"w_16_9":[{"c":"chiet_tu","t":"Chiết tự 查","x":"Bộ thành phần: 木 Mộc + 日 Nhật + 一 Nhất.\nMẹo nhớ: Trồng 1 cái cây và hằng ngày ra kiểm tra cây đó.","s":"HSK2_16#17"}],"w_16_10":[{"c":"cach_dung","t":"Cấu trúc 总（总是）","x":"总（总是）+ động từ/tính từ: luôn luôn.\n晚上我总/总是在家学习汉语。— Buổi tối tôi luôn học tiếng Trung ở nhà.","s":"HSK2_16#19"}],"w_16_12":[{"c":"chiet_tu","t":"Chiết tự 复","x":"复 (fù) – Hán Việt: Phục (hồi phục); phúc (làm đi làm lại).\nBộ thành phần: 人 Nhân + 日 Nhật + 夂 Truy (sau).","s":"HSK2_16#23"}],"w_16_13":[{"c":"chiet_tu","t":"Chiết tự 课","x":"课 (kè) – Hán Việt: Khóa (khóa học).\nBộ thành phần: 讠 Ngôn + 田 Điền + 木 Mộc.\nMẹo nhớ: Trong giờ học mà nói chuyện thì về cày ruộng trồng cây.","s":"HSK2_16#24"}],"w_16_14":[{"c":"chiet_tu","t":"Chiết tự 预","x":"预 (yù) – Hán Việt: Dự (dự báo, dự phòng).\nBộ thành phần: 予 Dữ (cho) + 页 Hiệt (trang giấy).\nMẹo nhớ: Cho xin một trang giấy để làm trước.","s":"HSK2_16#25"},{"c":"cau_vi_du","t":"Cụm 复习课文，预习生词","x":"复习课文，预习生词。— Ôn tập bài khóa, chuẩn bị từ mới.","s":"HSK2_16#26"}],"w_16_17":[{"c":"cau_vi_du","t":"Ví dụ 或者 và 还是","x":"或者: dùng trong câu trần thuật; 还是: dùng trong câu hỏi.\nA: 你喝茶还是喝咖啡？ B: 我喝咖啡。\nA: 你上午去还是下午去？ B: 下午去。\nA: 星期天，你做什么？ B: 我常常在宿舍看书或者跟朋友聊天儿。\n晚上我常常听音乐或者看电视。","s":"HSK2_16#28"}],"w_16_18":[{"c":"chiet_tu","t":"Chiết tự 聊","x":"聊 (liáo) – Hán Việt: Liêu (nói chuyện).\nBộ thành phần: 耳 Nhĩ + 卯 Mão.\nMẹo nhớ: Dùng tai nghe những con mèo nói chuyện.","s":"HSK2_16#29"},{"c":"cau_vi_du","t":"Ví dụ 聊天儿","x":"我常常跟他聊天（儿）。— Tôi thường xuyên trò chuyện cùng anh ấy.","s":"HSK2_16#29"}],"w_16_19":[{"c":"cau_vi_du","t":"Cụm 收资料","x":"收资料 — Nhận tài liệu","s":"HSK2_16#30"},{"c":"tu_mo_rong","t":"收发 thu phát","x":"收发: thu phát, nhận và chuyển đi","s":"HSK2_16#31"}],"w_16_21":[{"c":"tu_mo_rong","t":"邮件 – từ thay thế 伊妹儿","x":"邮件 (yóujiàn): email (từ thay thế cho 伊妹儿)\n我给老师发邮件（我发邮件给老师）。— Tôi gửi email cho giáo viên.","s":"HSK2_16#32"}],"w_16_22":[{"c":"chiet_tu","t":"Chiết tự 影","x":"影 (yǐng) – Hán Việt: Ảnh (phim ảnh).\nBộ thành phần: 日 Nhật + 京 Kinh + 彡 Sam.\nMẹo nhớ: Phim ảnh quay cảnh mặt trời ở Bắc Kinh và có các cô gái tết tóc đuôi sam.","s":"HSK2_16#33"}],"w_16_23":[{"c":"chiet_tu","t":"Chiết tự 视","x":"视 (shì) – Hán Việt: Thị (nhìn, thị giác).\nBộ thành phần: 礻 Thị + 见 Kiến.\nXem tivi: 看电视.","s":"HSK2_16#34"}],"w_16_24":[{"c":"chiet_tu","t":"Chiết tự 剧","x":"剧 (jù) – Hán Việt: Kịch.\nBộ thành phần: 居 Cư + 刂 Đao đứng.\nMẹo nhớ: Vở kịch người dùng dao đánh nhau để giành lấy chỗ cư trú.","s":"HSK2_16#35"}],"w_16_25":[{"c":"chiet_tu","t":"Chiết tự 宿 và 舍","x":"宿 (sù) – Hán Việt: Túc (ký túc xá).\nBộ thành phần: 宀 Miên + 亻 Nhân + 百 Bách.\nMẹo nhớ: Nơi có 100 người ở dưới 1 mái nhà là KTX.\n舍 (shè) – Hán Việt: Xá.\nBộ thành phần: 人 Nhân + 舌 Thiệt (lưỡi).\nMẹo nhớ: Người quản lý KTX là người có miệng lưỡi khôn khéo.","s":"HSK2_16#37"}],"w_16_27":[{"c":"cau_vi_du","t":"Ví dụ 东西","x":"我去超市买东西。— Tôi đi siêu thị mua đồ.","s":"HSK2_16#41"}],"w_17_1":[{"c":"cach_dung","t":"Các cách dùng của 在","x":"1. Ở, tại – 在 + địa điểm: ở đâu. 她在家。— Cô ấy ở nhà.\n2. Đang – 在 + động từ: đang làm gì. 我在吃饭。— Tôi đang ăn cơm.\n在 + địa điểm + động từ: làm gì ở đâu. 今天她在图书馆学习中文。— Hôm nay cô ấy học tiếng Trung ở thư viện.","s":"HSK2_17#4"}],"w_17_2":[{"c":"ngu_phap","t":"Phân biệt 正, 在, 正在","x":"Giống: đều đi với động từ, thể hiện hành động đang xảy ra; cuối câu có thể thêm 呢.\nKhác: 正 nhấn mạnh thời điểm; 在 nhấn mạnh sự tiếp diễn; 正在 nhấn mạnh cả sự tiếp diễn và thời điểm.\nA：他们正做什么呢？ B：他们正上课呢。\nA：你在做什么呢？ B：我在听录音呢。\nA：麦克正在做什么呢？ B：他正在看电视呢。","s":"HSK2_17#6"}],"w_17_3":[{"c":"cau_vi_du","t":"Ví dụ 音乐","x":"我很喜欢听音乐。— Tôi rất thích nghe nhạc.","s":"HSK2_17#10"}],"w_17_5":[{"c":"cau_vi_du","t":"Ví dụ 没有","x":"没钱（没有钱）。— Không có tiền.","s":"HSK2_17#12"}],"w_17_6":[{"c":"chiet_tu","t":"Chiết tự 事","x":"事 (shì) – danh từ: Sự, sự việc.\nBộ thành phần: 一 Nhất + 口 Khẩu + 彐 Kệ (con nhím).\nMẹo nhớ: Sự việc 1 con nhím bị móc mồm lên.\nLượng từ đi kèm: 件 (jiàn).","s":"HSK2_17#13"},{"c":"cau_vi_du","t":"Thêm ví dụ 事","x":"我有事要做。— Tôi có việc phải làm.\n我有一件事要跟你说。— Tôi có một việc cần nói với bạn.","s":"HSK2_17#14"}],"w_17_7":[{"c":"chiet_tu","t":"Chiết tự 店","x":"店 (diàn) – danh từ: cửa hàng, cửa tiệm. Hán Việt: Điếm.\nBộ thành phần: 广 Quảng (rộng rãi) + 占 Chiếm.\nMẹo nhớ: Mở cửa tiệm phải chiếm nơi rộng rãi.","s":"HSK2_17#15"},{"c":"cau_vi_du","t":"Ví dụ 书店","x":"我今天下午去书店买书。— Chiều nay tôi đi hiệu sách mua sách.","s":"HSK2_17#15"}],"w_17_8":[{"c":"cach_dung","t":"Hai nghĩa của 坐","x":"1. Ngồi: 请坐 — Mời ngồi.\n2. Đi (bằng phương tiện công cộng): 我们坐车去书店吧。— Chúng ta đi xe đến hiệu sách nhé.","s":"HSK2_17#19"}],"w_17_9":[{"c":"cach_dung","t":"骑 + phương tiện","x":"骑 (động từ): cưỡi (ngựa); đi (xe máy, xe đạp).\n骑马: cưỡi ngựa\n骑摩托车: đi xe máy\n骑自行车: đi xe đạp","s":"HSK2_17#20"}],"w_17_11":[{"c":"cach_dung","t":"课: môn học (门) và tiết học (节)","x":"1. Môn học – lượng từ 门: 我要学十门课。— Tôi phải học 10 môn.\n2. Tiết học – lượng từ 节 (jié): 今天上午有三节英文课。— Sáng nay có 3 tiết tiếng Anh.","s":"HSK2_17#23"}],"w_17_16":[{"c":"chiet_tu","t":"Chiết tự 育","x":"育 (yù) – Hán Việt: Dục (thể dục).\nBộ thành phần: 亠 Đầu + 厶 Khư + 月 Nguyệt.\nMẹo nhớ: Người gập đầu riêng tư dưới trăng để tập thể dục.","s":"HSK2_17#29"}],"w_17_17":[{"c":"cach_dung","t":"Cấu trúc 教 + 2 tân ngữ","x":"Chủ ngữ + 教 + tân ngữ (người) + tân ngữ (môn học, kiến thức).\n老师教我们中文。— Thầy giáo dạy chúng tôi tiếng Trung.\nTừ liên quan: 教授.","s":"HSK2_17#30"}],"w_18_1":[{"c":"chiet_tu","t":"Chiết tự 裹","x":"裹 (guǒ) – Hán Việt: Khỏa (bọc, cuốn).\nBộ thành phần: 亠 Đầu + 果 Quả + 𧘇.","s":"HSK2_18#5"},{"c":"cau_vi_du","t":"Ví dụ 包裹","x":"我去邮局寄包裹。— Tôi đi bưu điện gửi bưu phẩm.","s":"HSK2_18#5"}],"w_18_2":[{"c":"chiet_tu","t":"Chiết tự 替","x":"Bộ thành phần: 夫 Phu + 日 Nhật.\nMẹo nhớ: Thay 2 đời chồng phải mất 1 ngày.","s":"HSK2_18#6"},{"c":"cach_dung","t":"Cấu trúc (A) + 替 + B + động từ","x":"(A) + 替 + B + động từ: (A) thay/giúp B làm gì.\n你跟他见面的时候，替我谢谢他吧！— Lúc bạn gặp anh ấy, thay tôi cảm ơn anh ấy nhé!","s":"HSK2_18#6"}],"w_18_3":[{"c":"chiet_tu","t":"Chiết tự 顺 và 便","x":"顺 (shùn) – Hán Việt: Thuận (thuận lợi, thuận tiện).\nBộ thành phần: 川 Xuyên (dòng sông) + 页 Hiệt (trang giấy).\nMẹo nhớ: Thả đèn hoa đăng bằng giấy xuống sông để cầu mong thuận lợi.\n便 (biàn) – Hán Việt: Tiện.\nBộ thành phần: 亻 Nhân + 更 Canh (càng).\nMẹo nhớ: Thêm người thì càng tiện hơn.","s":"HSK2_18#7"}],"w_18_4":[{"c":"chiet_tu","t":"Chiết tự 票","x":"票 (piào) – Hán Việt: Phiếu.\nBộ thành phần: 西 Tây + 二 Nhị + 小 Tiểu.\nMẹo nhớ: Đi về hướng tây mua 2 cái tem phiếu nhỏ.\nLượng từ đi kèm: 张 (zhāng).","s":"HSK2_18#9"}],"w_18_6":[{"c":"chiet_tu","t":"Chiết tự 报","x":"Bộ thành phần: 扌 Thủ + 卩 Tiết (đốt tre) + 又 Hựu.\nMẹo nhớ: Cậu bé bán báo tay cầm báo, tay thì cầm đốt tre đi qua đi lại.","s":"HSK2_18#11"}],"w_18_5":[{"c":"tu_mo_rong","t":"青年报 Báo Thanh Niên","x":"青年报: Báo Thanh Niên","s":"HSK2_18#11"}],"w_18_7":[{"c":"chiet_tu","t":"Chiết tự 纸","x":"纸 (zhǐ) – Hán Việt: Chỉ (giấy).\nBộ thành phần: 纟 Mịch + 氏 Thị.\nMẹo nhớ: Dùng giấy nhà họ Thị để dệt tơ.","s":"HSK2_18#12"}],"w_18_8":[{"c":"chiet_tu","t":"Chiết tự 份","x":"份 (fèn) – lượng từ: phần, bản, số.\nBộ thành phần: 亻 Nhân + 分 Phân (phân chia).\nMẹo nhớ: Người phân chia mọi thứ ra thành các phần.","s":"HSK2_18#13"},{"c":"cach_dung","t":"Lượng từ 份 dùng cho gì","x":"Dùng cho tài liệu, báo, hợp đồng (资料, 报纸).\n你顺便替我买一份青年报。— Bạn tiện thể mua giúp tôi 1 tờ báo Thanh Niên nhé.","s":"HSK2_18#14"}],"w_18_9":[{"c":"chiet_tu","t":"Chiết tự 拿","x":"Bộ thành phần: 合 Hợp + 手 Thủ (tay).\nMẹo nhớ: Cái gì hợp với tay mình mới cầm.","s":"HSK2_18#15"},{"c":"cau_vi_du","t":"Ví dụ 拿","x":"替我拿那本书。— Lấy giúp tôi quyển sách kia.","s":"HSK2_18#15"}],"w_18_10":[{"c":"cau_vi_du","t":"Hội thoại 用 / 不用","x":"A: 用我的钱替我买一份青年报吧！— Dùng tiền của tôi mua giúp tôi 1 tờ báo Thanh Niên nhé.\nB: 不用，先用我的吧。— Không cần, dùng tiền của tôi trước đi.","s":"HSK2_18#16"}],"w_18_11":[{"c":"cau_vi_du","t":"Ví dụ 旅行","x":"我喜欢（xǐhuan: thích）去中国旅行。— Tôi thích đi Trung Quốc du lịch.","s":"HSK2_18#17"}],"w_18_13":[{"c":"chiet_tu","t":"Chiết tự 团","x":"Bộ thành phần: 囗 Vi (vây) + 才 Tài.\nMẹo nhớ: 1 đoàn vây quanh người tài.","s":"HSK2_18#19"},{"c":"tu_mo_rong","t":"旅行团 / 代表团","x":"旅行团: đoàn du lịch\n代表团: đoàn đại biểu","s":"HSK2_18#19"}],"w_18_14":[{"c":"chiet_tu","t":"Chiết tự 参 và 观","x":"参 (cān) – Hán Việt: Tham (tham quan, tham gia).\nBộ thành phần: 厶 Khư/Tư + 大 Đại + 彡 Sam.\n观 (guān) – Hán Việt: Quan (quan sát).\nBộ thành phần: 又 Hựu + 见 Kiến.","s":"HSK2_18#20"}],"w_18_17":[{"c":"chiet_tu","t":"Chiết tự 翻 và 译","x":"翻 (fān) – Hán Việt: Phiên (phiên dịch).\nBộ thành phần: 番 Phiên (nét phẩy + 米 Mễ + 田 Điền) + 羽 Vũ (lông).\n译 (yì) – Hán Việt: Dịch (phiên dịch).\nBộ thành phần: 讠 Ngôn + 又 Hựu + ≠.","s":"HSK2_18#23"},{"c":"cau_vi_du","t":"Ví dụ 当翻译","x":"我当翻译。— Tôi làm phiên dịch.","s":"HSK2_18#24"}],"w_18_19":[{"c":"cach_dung","t":"坐 + phương tiện công cộng; vé máy bay","x":"Đi các phương tiện công cộng (bản thân không điều khiển) dùng 坐.\n我坐飞机去北京。— Tôi đi máy bay đến Bắc Kinh.\n飞机票: vé máy bay","s":"HSK2_18#26"}],"w_18_20":[{"c":"cau_vi_du","t":"Ví dụ 火车; vé tàu","x":"火 (huǒ): Hỏa.\n我坐火车去上海。— Tôi đi tàu hỏa đến Thượng Hải.\n火车票: vé tàu hỏa","s":"HSK2_18#27"}],"w_18_21":[{"c":"cach_dung","t":"Phân biệt 回来 và 回去","x":"回来: quay về nơi người nói đang ở (hướng về người nói) – 他回来了。\n回去: quay về nơi khác (đi xa người nói) – 他明天回去。","s":"HSK2_18#28"}],"w_18_22":[{"c":"cau_vi_du","t":"Ví dụ 办","x":"你替我办一件事，好吗？— Bạn giúp tôi làm 1 việc được không?","s":"HSK2_18#29"}],"w_18_23":[{"c":"cach_dung","t":"Cấu trúc (A) + 帮 + (B) + động từ","x":"(A) + 帮 + (B) + động từ: (A) giúp B làm gì.\n你去商店顺便帮我买两斤水果。— Bạn đi cửa hàng tiện thể mua giúp tôi 2 cân hoa quả.","s":"HSK2_18#30"}],"w_18_24":[{"c":"chiet_tu","t":"Chiết tự 浇","x":"Bộ thành phần: 氵 Ba chấm thủy + 尧 Nghiêu.","s":"HSK2_18#31"},{"c":"tu_mo_rong","t":"浇花 tưới hoa","x":"浇花: tưới hoa, tưới nước cho hoa","s":"HSK2_18#32"}],"w_18_25":[{"c":"chiet_tu","t":"Chiết tự 花","x":"Bộ thành phần: 艹 Thảo đầu + 亻 Nhân + 七.","s":"HSK2_18#32"}],"w_18_26":[{"c":"chiet_tu","t":"Chiết tự 题","x":"题 (tí) – Hán Việt: Đề (vấn đề).\nBộ thành phần: 是 Là + 页 Hiệt (trang giấy).\nMẹo nhớ: Vấn đề là gì? Hãy viết nó lên giấy.","s":"HSK2_18#33"},{"c":"tu_mo_rong","t":"没问题 = 没事; ví dụ 问题","x":"没问题 (méi wèntí): không việc gì, không sao = 没事\n你还有别的问题吗？— Bạn còn câu hỏi nào khác không?","s":"HSK2_18#34"}],"w_19_1":[{"c":"chiet_tu","t":"Nghĩa chữ 羽 và 绒","x":"羽 (yǔ) – Hán Việt: Vũ (lông vũ, lông chim).\n绒 (róng) – Hán Việt: Nhung (vải nhung, sợi tơ).","s":"HSK2_19#4"},{"c":"cach_dung","t":"Lượng từ của 羽绒服","x":"Lượng từ đi kèm: 件","s":"HSK2_19#5"}],"w_19_4":[{"c":"chiet_tu","t":"Chiết tự 短","x":"短 (duǎn) – Hán Việt: Đoản (ngắn).\nBộ thành phần: 矢 Thỉ (mũi tên) + 豆 Đậu.\nMẹo nhớ: Ngắn như mũi tên và hạt đậu.","s":"HSK2_19#8"}],"w_19_5":[{"c":"chiet_tu","t":"Chiết tự 点","x":"点 (diǎn) – Hán Việt: Điểm.\nBộ thành phần: 占 Chiếm + 灬 Hỏa.","s":"HSK2_19#9"},{"c":"cach_dung","t":"Phân biệt 一会, 一下, 一点","x":"一会 (một lúc, một lát): đứng sau động từ, nhấn mạnh thời gian thực hiện – 等一会\n一下 (một chút): đứng sau động từ, nhấn mạnh hành động ngắn, nhanh – 介绍一下, 试一下\n一点 (một chút): + danh từ chỉ số lượng – 一点钱; tính từ + 一点 để so sánh – 太贵了，便宜一点吧","s":"HSK2_19#35"},{"c":"ngu_phap","t":"Phân biệt 一点儿 và 有（一）点儿","x":"一点（儿）+ danh từ không đếm được: một ít… (làm định ngữ) – 他会一点儿汉语。请给我（一）点儿啤酒。\nTính từ + 一点: …hơn một chút (so sánh) – 有没有长一点的？这件颜色有点儿深，我要浅一点儿的。\n有（一）点儿 + tính từ: có chút… (biểu đạt sự không mong muốn) – 这件有（一）点儿长。这件颜色有（一）点儿深，有没有浅一点儿的？这件羽绒服有点儿不合适。","s":"HSK2_19#34"}],"w_19_6":[{"c":"chiet_tu","t":"Chiết tự 深","x":"Bộ thành phần: 氵 Ba chấm thủy + 冖 Mịch + 八 Bát + 木 Mộc.\nMẹo nhớ: Màu đậm của nước bao trùm lên 8 cái cây.","s":"HSK2_19#10"},{"c":"cach_dung","t":"深 dùng để miêu tả","x":"Dùng để miêu tả:\n– Màu sắc: 深色, 深蓝色, 深黄色…\n– Mực nước\n– Tình cảm","s":"HSK2_19#10"}],"w_19_7":[{"c":"cach_dung","t":"浅色 và ví dụ chọn màu","x":"Bộ thủ: 氵 Ba chấm thủy.\n浅色: màu nhạt\n你要浅色的还是深色的？— Bạn muốn chiếc màu nhạt hay chiếc màu đậm?","s":"HSK2_19#11"}],"w_19_8":[{"c":"chiet_tu","t":"Chiết tự 试","x":"Bộ thành phần: 讠 Ngôn + 式 Thức.","s":"HSK2_19#12"},{"c":"tu_mo_rong","t":"试衣服 / 试衣间","x":"试衣服: thử quần áo\n试衣间: phòng thử đồ\n我觉得这件衣服很好看，你试一下吧。— Tôi thấy bộ quần áo này rất đẹp, bạn thử xem.","s":"HSK2_19#12"}],"w_19_9":[{"c":"cach_dung","t":"可以 + động từ (được phép)","x":"可以 + động từ: có thể làm gì (được phép).\n我想试一下，可以吗？— Tôi muốn thử một chút được không?\n可不可以？= 可以吗？","s":"HSK2_19#13"}],"w_19_10":[{"c":"chiet_tu","t":"Chiết tự 然","x":"然 (rán) – Hán Việt: Nhiên (đương nhiên, tất nhiên).\nBộ thành phần: 月 Nguyệt (nghiêng) + 犬 Khuyển + 灬 Hỏa.","s":"HSK2_19#14"},{"c":"cau_vi_du","t":"Ví dụ 当然","x":"A: 我可以进来吗？— Tôi có thể vào được không?\nB: 当然可以，请进。— Tất nhiên là được! Mời vào.\n当然了！— Tất nhiên rồi!","s":"HSK2_19#15"}],"w_19_11":[{"c":"chiet_tu","t":"Chiết tự 肥","x":"Bộ thành phần: 月 Nguyệt (Nhục) + 巴 Ba.","s":"HSK2_19#16"},{"c":"cach_dung","t":"肥 dùng để miêu tả","x":"Dùng để miêu tả:\n– Quần áo: rộng\n– Đất đai: màu mỡ, phì nhiêu\n– Thịt: nhiều mỡ","s":"HSK2_19#16"},{"c":"tu_mo_rong","t":"减肥 giảm cân","x":"减肥 (jiǎnféi): giảm cân\n我觉得我最近比较胖，想减肥。— Tôi cảm thấy gần đây tôi hơi béo, muốn giảm cân.","s":"HSK2_19#17"}],"w_19_12":[{"c":"chiet_tu","t":"Chiết tự 胖","x":"Bộ thành phần: 月 Nguyệt (Nhục) + 半 Bán (một nửa).","s":"HSK2_19#17"}],"w_19_13":[{"c":"chiet_tu","t":"Chiết tự 瘦","x":"Bộ thành phần: 疒 Nạch (bệnh tật) + 又 Hựu.","s":"HSK2_19#18"},{"c":"cau_vi_du","t":"Ví dụ 瘦","x":"谁说你胖？我觉得你很瘦。— Ai bảo bạn béo? Tôi thấy bạn rất gầy.\n这件衣服太肥了！有没有瘦一点（的）？— Bộ quần áo này rộng quá! Có cái nào nhỏ hơn không?","s":"HSK2_19#18"}],"w_19_14":[{"c":"chiet_tu","t":"Chiết tự 适 (合适)","x":"Bộ thành phần: 舌 Thiệt (lưỡi) + 辶 Quai xước.","s":"HSK2_19#19"},{"c":"cau_vi_du","t":"Ví dụ 正合适","x":"这件衣服不大不小，颜色不深也不浅，正合适。— Bộ quần áo này không to không nhỏ, màu sắc không đậm cũng không nhạt, vừa khít.","s":"HSK2_19#19"}],"w_19_15":[{"c":"chiet_tu","t":"Chiết tự 看","x":"看 (kàn): xem, nhìn.\nBộ thành phần: 手 Thủ (tay) + 目 Mục (mắt).","s":"HSK2_19#20"}],"w_19_16":[{"c":"chiet_tu","t":"Chiết tự 种","x":"Bộ thành phần: 禾 Hòa + 中 Trung.","s":"HSK2_19#21"},{"c":"cau_vi_du","t":"Ví dụ 种","x":"这种花很好看。— Loại hoa này rất đẹp.","s":"HSK2_19#21"}],"w_19_17":[{"c":"chiet_tu","t":"Chiết tự 打 và 折","x":"打 (dǎ) – Hán Việt: Đả (đánh).\nBộ thành phần: 扌 Thủ + 丁 Đinh.\n折 (zhé) – Hán Việt: Chiết.\nBộ thành phần: 扌 Thủ + 斤 Cân.","s":"HSK2_19#22"},{"c":"cach_dung","t":"Cách tính 打 + [số] + 折","x":"打 + [số] + 折: con số giữa 打 và 折 là số tiền còn lại phải trả (tính theo phần mười), không phải số tiền được giảm.\n打九折: trả 9 phần = giảm 10%\n打七折: giảm 30%\n打一折: giảm 90%","s":"HSK2_19#23"},{"c":"cau_vi_du","t":"Ví dụ 打折","x":"那家商店正在打折，咱们去看看吧！— Cửa hàng kia đang giảm giá, chúng ta đi xem xem đi!","s":"HSK2_19#22"}],"w_19_2":[{"c":"ngu_phap","t":"Cấu trúc 又…又…","x":"又 + tính từ + 又 + tính từ; 又 + động từ + 又 + động từ: biểu thị hai tình huống/trạng thái cùng tồn tại.\n这件羽绒服又好又便宜。\n我们房间又安静又干净（gānjìng: sạch sẽ）。\n那个箱子又小又旧。\n他去银行又取钱又换钱。","s":"HSK2_19#33"}],"w_20_1":[{"c":"tu_mo_rong","t":"去年 / 今年 / 明年","x":"去年: năm ngoái\n今年: năm nay\n明年: năm sau","s":"HSK2_20#4"},{"c":"tu_mo_rong","t":"前年 / 后年","x":"前年: năm trước (năm kia)\n后年: năm sau nữa","s":"HSK2_20#5"},{"c":"tu_mo_rong","t":"Đối chiếu năm – ngày","x":"今年 năm nay – 今天 hôm nay\n去年 năm ngoái – 昨天 hôm qua\n明年 năm sau – 明天 ngày mai\n前年 năm kia – 前天 hôm kia\n后年 năm sau nữa – 后天 ngày kia","s":"HSK2_20#6"}],"w_20_4":[{"c":"chiet_tu","t":"Chiết tự 毕","x":"毕 (bì) – Hán Việt: Tất (hoàn tất, hoàn thành).\nBộ thành phần: 比 Tỉ + 十 Thập.\nMẹo nhớ: So sánh thêm 10 lần nữa là hoàn tất.","s":"HSK2_20#7"},{"c":"cau_vi_du","t":"Hội thoại 有的…有的…","x":"A：你们都是今年毕业吗？— Các bạn đều tốt nghiệp năm nay à?\nB：不都是，有的今年，有的明年。— Không phải tất cả, có người năm nay, có người năm sau.","s":"HSK2_20#7"}],"w_20_5":[{"c":"cach_dung","t":"Hai nghĩa của 多大","x":"1. Hỏi tuổi: 你今年多大？— Bạn năm nay bao nhiêu tuổi?\n2. Hỏi kích thước, độ lớn (vật thể): 这个房间多大？— Căn phòng này rộng bao nhiêu?","s":"HSK2_20#8"}],"w_20_6":[{"c":"chiet_tu","t":"Chiết tự 岁","x":"Bộ thành phần: 山 Sơn + 夕 Tịch.","s":"HSK2_20#9"},{"c":"cach_dung","t":"万岁; 几岁 hỏi trẻ nhỏ","x":"万岁 (wànsuì): vạn tuế, muôn năm – hàm ý chúc sống lâu, trường tồn.\n你几岁？— dùng để hỏi tuổi trẻ nhỏ.","s":"HSK2_20#9"}],"w_20_7":[{"c":"tu_mo_rong","t":"Tháng trước / tháng này / tháng sau","x":"上个月: tháng trước\n这个月: tháng này\n下个月: tháng sau\n你什么时候毕业？— 今年5月。— Bạn bao giờ tốt nghiệp? – Tháng 5 năm nay.","s":"HSK2_20#10"}],"w_20_8":[{"c":"chiet_tu","t":"Chiết tự 属","x":"Bộ thành phần: 尸 Thi + nét phẩy + 虫 Trùng + 冂 Quynh.","s":"HSK2_20#13"}],"w_20_9":[{"c":"chiet_tu","t":"Chiết tự 狗","x":"Bộ thành phần: 犭 Khuyển (犬) + 句 Câu (cú).\nMẹo nhớ: Con chó bị rọ mõm.","s":"HSK2_20#14"},{"c":"cau_vi_du","t":"Ví dụ 属狗","x":"我属狗的。— Tôi tuổi Tuất.","s":"HSK2_20#14"}],"w_20_10":[{"c":"cau_vi_du","t":"Hỏi – đáp ngày sinh nhật","x":"你的生日是几月几号（什么时候）？— 9月27号。— Sinh nhật của bạn là ngày mấy tháng mấy (lúc nào)? – Ngày 27 tháng 9.","s":"HSK2_20#17"}],"w_20_34":[{"c":"cach_dung","t":"出生 và cách nói năm sinh","x":"出生 (chūshēng – động từ): sinh ra, ra đời.\n我是2000年（00年）出生，属龙。\nNói tắt năm sinh: 99年、98年、00年、01年、02年.\n00后: thế hệ sinh sau năm 2000.","s":"HSK2_20#17"}],"w_20_11":[{"c":"cach_dung","t":"Nghĩa của 正好","x":"正好 (zhènghǎo – phó từ/tính từ): vừa đúng lúc; tình cờ, trùng hợp; vừa đủ, vừa vặn.\n今天正好是我妈妈的生日。— Hôm nay vừa đúng là sinh nhật của mẹ tôi.","s":"HSK2_20#18"}],"w_20_12":[{"c":"chiet_tu","t":"Chiết tự 打 và 算","x":"打 (dǎ) – động từ: Đả (đánh).\nBộ thành phần: 扌 Tay + 丁 Đinh.\n算 (suàn) – động từ: Toán (tính toán).\nBộ thành phần: ⺮ Trúc + 目 Mục.","s":"HSK2_20#19"},{"c":"cach_dung","t":"Cấu trúc 打算; 有/没有打算","x":"打算 + động từ/cụm động từ: dự định làm gì.\n有打算 / 没（有）打算 (+ động từ): có/không có kế hoạch làm gì.\n你今天有什么打算吗？（你今天有没有什么打算？）— Hôm nay bạn có kế hoạch gì không?","s":"HSK2_20#20"},{"c":"tu_mo_rong","t":"打字 / 打车","x":"打字: đánh máy (gõ chữ bằng điện thoại, máy tính)\n打车: gọi xe, bắt xe","s":"HSK2_20#19"}],"w_20_13":[{"c":"chiet_tu","t":"Chiết tự 过","x":"Bộ thành phần: 辶 Quai xước + 寸 Thốn.\nNghĩa: qua, đi qua, trải qua; đón (lễ, tết).","s":"HSK2_20#21"},{"c":"cach_dung","t":"过: trải qua; động từ + 过 (đã từng)","x":"1. Qua, đi qua, trải qua.\n过日子 (guòrìzi): sống qua ngày (cuộc sống diễn ra bình thường).\nĐộng từ + 过: đã từng làm gì.\n你去过北京吗？—— 我没有去过。— Bạn đã từng đi Bắc Kinh chưa? – Tôi chưa từng đi.\n我吃过了。— Tôi ăn rồi.","s":"HSK2_20#22"},{"c":"cach_dung","t":"过: đón (lễ, sinh nhật); 过节, 过年","x":"2. Đón (lễ, sinh nhật).\n过生日: đón sinh nhật – 今年的生日你想怎么过呢？\n节 (jié – danh từ): lễ, tiết – 今年我打算回家过节。— Năm nay tôi định về nhà đón lễ.\n过年: ăn Tết, đón năm mới.","s":"HSK2_20#23"}],"w_20_16":[{"c":"chiet_tu","t":"Chiết tự 准 và 备","x":"准 (zhǔn) – tính từ: Chuẩn.\nBộ thành phần: 冫 Hai chấm thủy (băng) + 隹 Chuy (chim đuôi ngắn).\n备 (bèi) – Hán Việt: Bị (chuẩn bị).\nBộ thành phần: 夂 Truy (phía sau) + 田 Điền.","s":"HSK2_20#24"},{"c":"cach_dung","t":"Các cách dùng 准备","x":"准备 + động từ: chuẩn bị/sắp làm gì – 我准备上课。\n准备 + danh từ: chuẩn bị cái gì – 我妈妈正在准备晚饭。— Mẹ tôi đang chuẩn bị bữa tối.\nSẵn sàng (chuẩn bị tinh thần) – 你准备好了吗？— Bạn đã sẵn sàng chưa?","s":"HSK2_20#25"}],"w_20_17":[{"c":"chiet_tu","t":"Chiết tự 举","x":"举 (jǔ) – Hán Việt: Cử (cử hành).\nBộ thành phần: 兴 Hưng + dấu ≠.","s":"HSK2_20#26"}],"w_20_18":[{"c":"cach_dung","t":"Nghĩa của 晚会","x":"晚会: sự kiện diễn ra vào buổi tối (thường là giải trí, biểu diễn nghệ thuật, lễ hội…).","s":"HSK2_20#27"}],"w_20_19":[{"c":"chiet_tu","t":"Chiết tự 参 và 加","x":"参 (cān) – Hán Việt: Tham (tham gia, tham quan).\nBộ thành phần: 厶 Khư/Tư + 大 Đại + 彡 Sam.\n加 (jiā) – Hán Việt: Gia (cộng, thêm).\nBộ thành phần: 力 Lực + 口 Khẩu.","s":"HSK2_20#28"}],"w_20_20":[{"c":"cach_dung","t":"Phân biệt 时间 và 时候","x":"时间: khoảng thời gian – 有时间: có thời gian, rảnh (你有时间吗？); 没（有）时间: không có thời gian, bận.\n时候: mốc thời gian – 小时候: lúc nhỏ; 有时候: đôi lúc, đôi khi (有时候我晚上不吃饭。).\n什么时候 ~ 什么时间: lúc nào.","s":"HSK2_20#29"}],"w_20_21":[{"c":"chiet_tu","t":"Chiết tự 钟","x":"钟 (zhōng) – Hán Việt: Chung (giờ, đồng hồ).\nBộ thành phần: 钅 Kim + 中 Trung.","s":"HSK2_20#30"},{"c":"cau_vi_du","t":"Số giờ + 点（钟）","x":"Số giờ + 点（钟）: … giờ.\n现在几点？——现在是晚上八点（钟）。— Bây giờ là mấy giờ? – Bây giờ là 8 giờ tối.","s":"HSK2_20#30"}],"w_20_22":[{"c":"chiet_tu","t":"Chiết tự 就","x":"Bộ thành phần: 京 Kinh + 尤 Vưu (ưu).\nMẹo nhớ: Kinh đô chính là nơi có nhiều người ưu tú.","s":"HSK2_20#31"},{"c":"cach_dung","t":"就 biểu thị nhấn mạnh","x":"就在我房间 — Ở ngay trong phòng tớ\n就是你 — Chính là bạn","s":"HSK2_20#31"}],"w_20_23":[{"c":"cach_dung","t":"一定（要）+ động từ; 不一定","x":"Thể hiện quyết tâm hoặc điều chắc chắn sẽ xảy ra.\n一定 +（要）động từ: chắc chắn làm gì.\n不一定 + động từ/tính từ: chưa chắc.\n他不一定来参加我的生日晚会。— Anh ấy chưa chắc đến dự tiệc sinh nhật tôi.","s":"HSK2_20#32"}],"w_20_24":[{"c":"chiet_tu","t":"Chiết tự 祝","x":"Bộ thành phần: 礻 Thị (hiển thị) + 兄 Huynh.\nMẹo nhớ: Lời chúc biểu thị tấm lòng huynh đệ.","s":"HSK2_20#33"}],"w_20_25":[{"c":"chiet_tu","t":"Chiết tự 快","x":"快 (kuài) – tính từ: nhanh.\nBộ thành phần: 忄 Tâm đứng + 夬 Quái (quyết).\nMẹo nhớ: Có quyết tâm thì làm gì cũng nhanh. 太快了！","s":"HSK2_20#34"},{"c":"cau_vi_du","t":"Các lời chúc với 快乐","x":"祝你生日快乐 — Chúc bạn sinh nhật vui vẻ\n毕业快乐 — Tốt nghiệp vui vẻ\n新年快乐 — Chúc mừng năm mới","s":"HSK2_20#35"},{"c":"ngu_am","t":"乐 hai cách đọc: yuè / lè","x":"yuè – Nhạc: 音乐 (âm nhạc)\nlè – Lạc: 快乐 (khoái lạc, vui vẻ)","s":"HSK2_20#34"}],"w_20_29":[{"c":"khac","t":"Phiên âm đúng của 健康","x":"健康 (jiànkāng): khỏe mạnh.","s":"HSK2_20#36"}],"w_21_1":[{"c":"chiet_tu","t":"Chiết tự 每","x":"Bộ thành phần: 人 Nhân + 母 Mẫu (mẹ).","s":"HSK2_21#5"},{"c":"cach_dung","t":"每 + lượng từ + danh từ","x":"每天: mỗi ngày\n每 + lượng từ + danh từ: 每个人 — mỗi người","s":"HSK2_21#5"}],"w_21_2":[{"c":"cach_dung","t":"半天, 一半, 半个, …点半","x":"半天: nửa ngày (khẩu ngữ còn có nghĩa \"rất lâu\")\n一半: một nửa\n我吃半个苹果。— Tôi ăn nửa quả táo.\n下午三点半: 15:30; 晚上七点半: 19:30","s":"HSK2_21#7"}],"w_21_3":[{"c":"chiet_tu","t":"Chiết tự 床","x":"Bộ thành phần: 广 Quảng + 木 Mộc.\nMẹo nhớ: Cái giường làm bằng gỗ rộng rãi.","s":"HSK2_21#8"},{"c":"tu_mo_rong","t":"起床 thức dậy","x":"起床 (qǐchuáng): thức dậy (động từ)","s":"HSK2_21#8"}],"w_21_4":[{"c":"cach_dung","t":"后: thời gian/động từ + 后","x":"后 (hòu – danh từ): Hậu (sau). 后年: năm sau nữa.\nThời gian + 后: sau – 三年后我毕业。— 3 năm sau tôi tốt nghiệp.\nĐộng từ + 后: sau khi – 下课后，我回家。— Sau khi tan học, tôi về nhà.","s":"HSK2_21#10"},{"c":"cach_dung","t":"Hai nghĩa của 以后","x":"1. Thời gian/hành động + 以后: sau, sau khi – 吃早饭以后，我要去银行。— Sau khi ăn sáng, tôi phải đi ngân hàng.\n2. Sau này (đứng độc lập) – 以后我想当医生。— Sau này tôi muốn làm bác sĩ.","s":"HSK2_21#11"},{"c":"cach_dung","t":"Phân biệt 后 và 以后","x":"Giống: thời gian/động từ + （以）后: sau, sau khi – 三年（以）后我毕业; 吃早饭以后，我要去银行.\nKhác: chỉ 以后 có nghĩa \"sau này\" khi đứng độc lập – 以后我想当医生。","s":"HSK2_21#12"}],"w_21_5":[{"c":"cau_vi_du","t":"… giờ … phút","x":"Số + 点（钟）+ số + 分（钟）: … giờ … phút.\n两点二十分 — 2 giờ 20 phút\n现在是晚上六点十五分（钟）。— Bây giờ là 6 giờ 15 phút tối.","s":"HSK2_21#13"}],"w_21_6":[{"c":"chiet_tu","t":"Chiết tự 差","x":"Bộ thành phần: 羊 Dương (dê) + 工 Công.","s":"HSK2_21#14"},{"c":"cach_dung","t":"差 + số phút + giờ (giờ kém)","x":"Diễn đạt giờ kém: 差 + [số phút] + [giờ].\n差五分三点 — 3 giờ kém 5\n差十五分七点 — 7 giờ kém 15\n差十分十二点 — 12 giờ kém 10\n差二十分六点 — 6 giờ kém 20","s":"HSK2_21#15"}],"w_21_9":[{"c":"cach_dung","t":"门 + 课 và 节 + 课","x":"门 + 课: môn học\n节 + 课: tiết học","s":"HSK2_21#17"}],"w_21_10":[{"c":"chiet_tu","t":"Chiết tự 锻 và 炼","x":"锻 (duàn) – Hán Việt: Đoạn (rèn, rèn luyện).\nBộ thành phần: 钅 Kim + 段 Đoạn.\n炼 (liàn) – Hán Việt: Luyện.\nBộ thành phần: 火 Hỏa + 东 Đông + 一 Nhất.","s":"HSK2_21#21"},{"c":"cach_dung","t":"Phân biệt 练 và 炼","x":"练 (bộ mịch 纟): luyện tập, thực hành kỹ năng – 练习: luyện tập; 练字: luyện chữ\n炼 (bộ hỏa 火): rèn luyện (nhiệt độ cao, nội tâm, ý chí) – 锻炼身体: rèn luyện sức khỏe; 炼钢: luyện thép","s":"HSK2_21#23"}],"w_21_11":[{"c":"cach_dung","t":"Cách dùng 然后","x":"Nối các hành động xảy ra liên tiếp theo thứ tự thời gian; nhấn mạnh trình tự: việc A → rồi đến việc B.","s":"HSK2_21#25"},{"c":"cach_dung","t":"Phân biệt 以后 và 然后","x":"以后: sau khi – nhấn mạnh mốc thời gian (下课以后，我回家); còn có nghĩa \"sau này\" (我以后想当老师).\n然后: sau đó – nhấn mạnh trình tự hành động (我下课，然后回家).\n下课以后，我先回家，然后洗澡。— Sau khi tan học, tôi về nhà trước, rồi tắm rửa.","s":"HSK2_21#26"}],"w_21_12":[{"c":"chiet_tu","t":"Chiết tự 爬","x":"Bộ thành phần: 爪 Trảo (móng vuốt) + 巴 Ba.","s":"HSK2_21#29"},{"c":"tu_mo_rong","t":"爬山 leo núi","x":"爬山 (páshān – động từ ly hợp): leo núi","s":"HSK2_21#29"}],"w_21_13":[{"c":"cach_dung","t":"Đại từ số ít → số nhiều với 们","x":"我 → 我们 (chúng tôi)\n你 → 你们 (các bạn)\n他 → 他们 (họ)\n她 → 她们 (họ)\n老师 → 老师们 (các thầy cô giáo)","s":"HSK2_21#30"},{"c":"ngu_phap","t":"Quy tắc dùng 们","x":"们 dùng sau đại từ hoặc danh từ chỉ người, biểu thị số nhiều: 我们 你们 他们 咱们 老师们 同学们 朋友们.\nPhía trước có từ chỉ số lượng thì phía sau KHÔNG thêm 们. Không nói: 三个留学生们。我有很多朋友们。","s":"HSK2_21#44"}],"w_21_15":[{"c":"cach_dung","t":"准时 + động từ","x":"准时 + động từ: làm gì đúng giờ, đúng thời gian quy định.\n我们准时出发吧！— Chúng ta xuất phát đúng giờ nhé!","s":"HSK2_21#33"}],"w_21_16":[{"c":"cach_dung","t":"前: thời gian/địa điểm/động từ + 前","x":"前 (qián): Tiền (trước). 前年: năm trước.\nThời gian/địa điểm + 前: trước – 三年前: 3 năm trước; 教室前: trước phòng học.\nĐộng từ + 前: trước khi – 睡觉前，我洗澡。— Trước khi đi ngủ, tôi tắm rửa.","s":"HSK2_21#34"},{"c":"cach_dung","t":"Hai nghĩa của 以前","x":"1. Thời gian/hành động + 以前: trước, trước khi – 吃早饭以前，我要去银行。— Trước khi ăn sáng, tôi phải đi ngân hàng.\n2. Trước đây (đứng độc lập) – 以前我当医生。— Trước đây tôi là bác sĩ.","s":"HSK2_21#35"},{"c":"cach_dung","t":"Phân biệt 前 và 以前","x":"Giống: thời gian/động từ + （以）前: trước, trước khi – 三年（以）前我毕业; 吃早饭以前，我要去银行.\nĐịa điểm + 前: trước (chỉ dùng 前) – 教室前.\nKhác: chỉ 以前 có nghĩa \"trước đây\" khi đứng độc lập – 以前我当医生。","s":"HSK2_21#36"}],"w_21_17":[{"c":"chiet_tu","t":"Chiết tự 集","x":"集 (jí – động từ): Tập (tập hợp).\nBộ thành phần: 隹 Chuy (chim đuôi ngắn) + 木 Mộc.","s":"HSK2_21#37"},{"c":"cau_vi_du","t":"Ví dụ 集合","x":"明天上午八点半在教室前集合吧。— Ngày mai 8:30 sáng tập hợp ở trước phòng học nhé.","s":"HSK2_21#37"}],"w_21_18":[{"c":"chiet_tu","t":"Chiết tự 刻","x":"Bộ thành phần: 亥 Hợi + 刂 Đao đứng.","s":"HSK2_21#38"},{"c":"cach_dung","t":"一刻 = 十五分钟","x":"一刻 = 十五分钟 (1 khắc = 15 phút)\n7:15: 七点十五分 = 七点一刻","s":"HSK2_21#38"}],"w_21_21":[{"c":"cau_vi_du","t":"Ví dụ 带","x":"请带伞！— Hãy mang theo ô!","s":"HSK2_21#40"}],"w_22_1":[{"c":"cach_dung","t":"Hai nghĩa của 叫","x":"1. Tên là: 你叫什么名字？——我叫……。\n2. Gọi, bảo: 老师叫我回答（huídá: trả lời）那个问题。— Giáo viên gọi tôi trả lời câu hỏi kia.\n我妈妈每天都叫我起床。— Ngày nào mẹ tôi cũng gọi tôi dậy.","s":"HSK2_22#5"}],"w_22_2":[{"c":"chiet_tu","t":"Chiết tự 让","x":"Bộ thành phần: 讠 Ngôn + 上 Thượng.\nMẹo nhớ: Nhường cho nói trước.","s":"HSK2_22#6"},{"c":"cach_dung","t":"Hai nghĩa của 让; phủ định 不让","x":"1. Nhường: 你是哥哥，你要让妹妹吧！— Con là anh trai, con phải nhường em gái chứ.\n2. Cho phép, khiến, bảo: 让 + người + động từ. Phủ định: 不让 + người + động từ.\n老师，让我先说吧！— Thưa thầy, cho em nói trước.\n妈妈让我去买一斤苹果。— Mẹ bảo tôi đi mua 1 cân táo.","s":"HSK2_22#7"}],"w_22_4":[{"c":"cau_vi_du","t":"大家好！","x":"大家好！— Xin chào mọi người!","s":"HSK2_22#8"}],"w_22_5":[{"c":"chiet_tu","t":"Chiết tự 谈","x":"Bộ thành phần: 讠 Ngôn + 炎 Viêm (2 bộ 火 Hỏa).\nMẹo nhớ: Đàm thoại những câu chuyện nóng hổi.","s":"HSK2_22#9"},{"c":"cach_dung","t":"Sắc thái của 谈","x":"谈: nhiều người cùng nói, hoặc 1 người nói cho nhiều người nghe.\n谈工作: bàn công việc, nói chuyện công việc.\n老师叫我跟全班同学谈一谈家庭。— Giáo viên gọi tôi nói với cả lớp về gia đình.\n谈话 ~ 说话 ~ 聊天 (谈话 trang trọng hơn một chút).","s":"HSK2_22#10"}],"w_22_7":[{"c":"cach_dung","t":"Cách dùng 自己","x":"Đại từ nhân xưng + 自己: nhấn mạnh chính bản thân ai – 我自己: chính bản thân tôi.\n自己 + động từ: tự mình làm gì – 我自己去就行！— Tôi tự đi là được.\n要自己做自己的事。— Phải tự mình làm việc của mình.","s":"HSK2_22#11"}],"w_22_8":[{"c":"chiet_tu","t":"Chiết tự 爱 (phồn thể 愛)","x":"Bộ thành phần: 爫 Trảo (móng vuốt) + 冖 Mịch + 友 Hữu (bạn bè).\nPhồn thể: 愛.","s":"HSK2_22#12"}],"w_22_9":[{"c":"tu_mo_rong","t":"好 đọc hào: 好学; ví dụ 爱好","x":"好学 (hàoxué – tính từ): hiếu học, ham học hỏi\nA: 你有什么爱好？ B: 我的爱好是看中文电视剧。— Sở thích của tôi là xem phim truyền hình Trung Quốc.\n请你谈一谈你自己的爱好。— Mời bạn nói về sở thích của bản thân.","s":"HSK2_22#13"}],"w_22_11":[{"c":"chiet_tu","t":"Chiết tự 喜","x":"喜 (xǐ) – tính từ: Hỷ (vui mừng, hoan hỷ).\nBộ thành phần: 吉 Cát (cát tường; 士 Sĩ + 口 Khẩu) + 口 Khẩu.","s":"HSK2_22#16"},{"c":"cau_vi_du","t":"喜事 hỷ sự","x":"家里有喜事。— Trong nhà có hỷ sự (việc cưới xin).","s":"HSK2_22#16"},{"c":"cau_vi_du","t":"Hội thoại về sở thích","x":"A: 你有什么爱好？ B: 我喜欢看书。— Bạn có sở thích gì? – Tôi thích đọc sách.","s":"HSK2_22#17"}],"w_22_12":[{"c":"cach_dung","t":"Các phó từ chỉ mức độ đã học","x":"Phó từ chỉ mức độ đã học: 很、比较、太、非常.","s":"HSK2_22#18"}],"w_22_13":[{"c":"chiet_tu","t":"Chiết tự 唱","x":"Bộ thành phần: 口 Khẩu + 日 Nhật.","s":"HSK2_22#19"}],"w_22_14":[{"c":"chiet_tu","t":"Chiết tự 玩","x":"Bộ thành phần: 玉 Ngọc + 元 Nguyên.","s":"HSK2_22#20"},{"c":"tu_mo_rong","t":"好玩 thú vị","x":"好玩 (hǎowán – tính từ): thú vị (địa điểm, trò chơi…)","s":"HSK2_22#20"}],"w_22_16":[{"c":"chiet_tu","t":"Chiết tự 感","x":"感 (gǎn) – Hán Việt: Cảm (cảm thấy, cảm giác).\nBộ thành phần: 咸 Hàm (mặn) + 心 Tâm.","s":"HSK2_22#22"},{"c":"chiet_tu","t":"Chiết tự 到","x":"到 (dào) – Hán Việt: Đáo (đến).\nBộ thành phần: 至 Chí (đến) + 刂 Đao đứng.","s":"HSK2_22#23"},{"c":"cach_dung","t":"Phân biệt 觉得, 感到, 感觉","x":"Động từ \"cảm thấy\" (miêu tả cảm xúc): cả ba đều dùng được – 我觉得（感到/感觉）很难过。\n\"Cảm thấy, cho rằng\" (nêu quan điểm): dùng 觉得 – 我觉得中文很难。\nDanh từ \"cảm giác\": chỉ dùng 感觉 – 你现在有难过的感觉？(không nói 难过的觉得, 难过的感到)","s":"HSK2_22#25"},{"c":"cau_vi_du","t":"Ví dụ 感到; từ 难过","x":"今天我感到很难过（nánguò: buồn）。— Hôm nay tôi cảm thấy rất buồn.","s":"HSK2_22#24"},{"c":"tu_mo_rong","t":"感觉 cảm giác","x":"感觉 (gǎnjué – danh từ/động từ): cảm giác","s":"HSK2_22#22"}],"w_22_17":[{"c":"chiet_tu","t":"Chiết tự 情","x":"情 (qíng) – Hán Việt: Tình (tình cảm).\nBộ thành phần: 忄 Tâm đứng + 青 Thanh.","s":"HSK2_22#26"},{"c":"cau_vi_du","t":"Ví dụ 心情","x":"我的心情最近不太好。— Tâm trạng của tôi gần đây không tốt lắm.\n今天你的心情怎么样？— Hôm nay tâm trạng của bạn thế nào?","s":"HSK2_22#27"},{"c":"tu_mo_rong","t":"爱情 / 情人节","x":"爱情 (àiqíng – danh từ): ái tình, tình yêu\n情人节 (qíngrén jié – danh từ): lễ Tình nhân (Valentine)","s":"HSK2_22#26"}],"w_22_19":[{"c":"cach_dung","t":"业余时间; 业余 + danh từ","x":"业余时间: thời gian rảnh rỗi\n业余 + danh từ: người làm việc gì đó không chuyên – 他是个业余歌手（gēshǒu: ca sĩ）。— Anh ấy là một ca sĩ nghiệp dư.","s":"HSK2_22#29"}],"w_22_20":[{"c":"chiet_tu","t":"Chiết tự 兴 và 趣","x":"兴 (xìng) – Hán Việt: Hưng (hưng thịnh, hứng thú).\n趣 (qù) – Hán Việt: Thú (thú vị, hứng thú).\nBộ thành phần (趣): 走 Tẩu + 取 Thủ.","s":"HSK2_22#30"},{"c":"cach_dung","t":"对 + đối tượng + 感/有兴趣","x":"Có/cảm thấy hứng thú: 感兴趣 hoặc 有兴趣.\nCó hứng thú với…: 对 + đối tượng + 感（有）兴趣.\n对 + đối tượng + tính từ.","s":"HSK2_22#31"},{"c":"tu_mo_rong","t":"有趣 thú vị","x":"有趣 (yǒuqù – tính từ): thú vị\n他这个人也太有趣了吧。— Anh ta thú vị quá đi mất.","s":"HSK2_22#30"},{"c":"ngu_phap","t":"对 + đối tượng + 感兴趣","x":"我来中国以前就对书法感兴趣。\n我对书法感兴趣。(không nói: 我感兴趣书法。)\n他对这件事不感兴趣。\n他对中国文化很感兴趣。","s":"HSK2_22#42"}],"w_22_23":[{"c":"chiet_tu","t":"Chiết tự 特","x":"特 (tè) – Hán Việt: Đặc (đặc biệt, đặc sắc).\nBộ thành phần: 牛 Ngưu + 寺 Tự.","s":"HSK2_22#34"},{"c":"cach_dung","t":"特别: tính từ và phó từ","x":"1. Tính từ: 对我来说，他是一个非常特别的人。— Đối với tôi, anh ấy là một người rất đặc biệt.\n2. Phó từ (+ tính từ/động từ): 我很喜欢中国文化，特别是书法。我觉得特别愉快。","s":"HSK2_22#34"}],"w_22_24":[{"c":"cau_vi_du","t":"Ví dụ 派; 出差","x":"公司派我去中国出差（chūchāi: đi công tác）。— Công ty cử tôi đi Trung Quốc công tác.","s":"HSK2_22#35"}],"w_22_26":[{"c":"cach_dung","t":"画画儿 là động từ ly hợp","x":"画画儿 (động từ ly hợp): vẽ tranh","s":"HSK2_22#36"}],"w_22_27":[{"c":"khac","t":"Tên riêng 田中","x":"田中 (Tiánzhōng): Tanaka (tên người Nhật)","s":"HSK2_22#37"}],"w_23_1":[{"c":"chiet_tu","t":"Chiết tự 边","x":"Bộ thành phần: 辶 Quai xước + 力 Lực.","s":"HSK2_23#4"}],"w_23_14":[{"c":"chiet_tu","t":"Chiết tự 离","x":"Bộ thành phần: 亠 Đầu + 凶 Hung + 冂 Quynh + 厶 Tư.","s":"HSK2_23#10"},{"c":"cach_dung","t":"A 离 B + 远/近","x":"A 离 B …: A cách B …\n我家离学校很近。— Nhà tôi cách trường rất gần.\n我这儿离你那儿太远了！— Chỗ tôi cách chỗ bạn xa quá!","s":"HSK2_23#11"}],"w_23_17":[{"c":"cach_dung","t":"Hai nghĩa của 地方","x":"1. Nơi chốn, địa điểm: 这个地方很好看，但是也很远。— Chỗ này rất đẹp, nhưng cũng rất xa.\n什么地方？(shénme dìfang): nơi nào, chỗ nào?\n2. Địa phương (đối lập với trung ương): 地方政府 (dìfāng zhèngfǔ): chính quyền địa phương","s":"HSK2_23#12"}],"w_23_18":[{"c":"chiet_tu","t":"Chiết tự 球","x":"球 (qiú) – danh từ: quả cầu, quả bóng.\nBộ thành phần: 王 Ngọc (Vương) + 求 Cầu.","s":"HSK2_23#13"},{"c":"tu_mo_rong","t":"打 + các môn bóng","x":"打球 (dǎ qiú – động từ ly hợp): chơi bóng, đánh cầu (bằng tay)\n打篮球 (dǎ lánqiú): chơi bóng rổ\n打羽毛球 (dǎ yǔmáoqiú): đánh cầu lông\n打网球 (dǎ wǎngqiú): đánh tennis\n打乒乓球 (dǎ pīngpāngqiú): đánh bóng bàn\n打高尔夫球 (dǎ gāo'ěrfū qiú): đánh golf","s":"HSK2_23#13"},{"c":"tu_mo_rong","t":"踢足球 / 足球场","x":"足 (zú): Túc (chân) – bộ túc\n踢足球 (tī zúqiú – động từ): đá bóng\n足球场 (zúqiúchǎng – danh từ): sân bóng đá","s":"HSK2_23#14"}],"w_23_19":[{"c":"cach_dung","t":"劳驾 ít dùng – thay bằng 麻烦","x":"劳驾，请让一让。— Làm phiền, xin nhường đường một chút.\nHiện nay 劳驾 ít dùng, có thể thay bằng 麻烦 (máfan): 麻烦你给我买一斤苹果。— Làm phiền bạn mua cho tôi 1 cân táo.","s":"HSK2_23#15"}],"w_23_21":[{"c":"chiet_tu","t":"Chiết tự 博 và 物","x":"博 (bó) – tính từ: Bác (nhiều, phong phú, uyên bác).\nBộ thành phần: 十 Thập + 尃 Phu.\n物 (wù) – danh từ: Vật, đồ vật.\nBộ thành phần: 牛 Ngưu + 勿 Vật.","s":"HSK2_23#17"},{"c":"cau_vi_du","t":"Ví dụ 博物馆","x":"我们班打算这个星期六去博物馆参观。— Lớp chúng tôi dự định thứ 7 tuần này đi tham quan bảo tàng.","s":"HSK2_23#18"},{"c":"tu_mo_rong","t":"Các từ với 物","x":"礼物 (lǐwù): quà tặng (lễ vật)\n动物 (dòngwù): động vật\n植物 (zhíwù): thực vật","s":"HSK2_23#17"}],"w_23_24":[{"c":"cach_dung","t":"在 A 和 B 中间","x":"在 A 和 B 中间: ở giữa A và B.\n我坐在爸爸和妈妈中间。— Tôi ngồi giữa bố và mẹ.","s":"HSK2_23#21"}],"w_23_25":[{"c":"cach_dung","t":"从 A 到 B; các nghĩa của 到","x":"从 A 到 B: từ A đến B – 从我这儿到你那儿: từ chỗ tôi đến chỗ bạn.\n到 + địa điểm: đến đâu.\n到: có mặt (khi điểm danh).","s":"HSK2_23#22"}],"w_23_27":[{"c":"cau_vi_du","t":"Nói chiều cao với 米; 公里","x":"我一米七，我爸爸一米八。— Tôi cao 1m7, bố tôi 1m8.\n公里 (gōnglǐ – lượng từ): km","s":"HSK2_23#23"}],"w_23_29":[{"c":"cach_dung","t":"往 + hướng + động từ","x":"往 + hướng + động từ: làm gì về phía nào.\n往前走: đi về phía trước\n往上爬: leo lên trên\n你一直往前走就到。— Bạn cứ đi thẳng về phía trước là đến.","s":"HSK2_23#25"}],"w_23_30":[{"c":"chiet_tu","t":"Chiết tự 红 và 绿","x":"红 (hóng) – tính từ: Hồng (đỏ, màu đỏ).\nBộ thành phần: 纟 Mịch + 工 Công.\n绿 (lǜ) – tính từ: Lục (xanh lá).\nBộ thành phần: 纟 Mịch + 录 Lục.","s":"HSK2_23#26"},{"c":"chiet_tu","t":"Chiết tự 灯","x":"灯 (dēng) – danh từ: Đăng (đèn).\nBộ thành phần: 火 Hỏa + 丁 Đinh.","s":"HSK2_23#27"}],"w_23_31":[{"c":"chiet_tu","t":"Chiết tự 拐","x":"Bộ thành phần: 扌 Thủ (tay) + 口 Khẩu + 力 Lực.","s":"HSK2_23#28"},{"c":"cach_dung","t":"往左拐 / 往右拐","x":"往 + hướng + động từ:\n往左拐: rẽ trái\n往右拐: rẽ phải","s":"HSK2_23#28"}],"w_23_32":[{"c":"chiet_tu","t":"Chiết tự 路","x":"Bộ thành phần: 足 Túc + 各 Các.","s":"HSK2_23#29"},{"c":"tu_mo_rong","t":"Các từ với 路","x":"走路: đi bộ\n路上: trên đường – 路上有很多人。— Trên đường có rất nhiều người.\n马路 (danh từ): đường lớn, đường cái\n过马路: qua đường, băng qua đường\n路人 (danh từ): người qua đường","s":"HSK2_23#29"}],"w_23_33":[{"c":"cach_dung","t":"Phân biệt 坐 và 座","x":"坐 – động từ: ngồi (请坐), đi xe (坐车). Hình ảnh ghi nhớ: 2 người ngồi trên đất.\n座 – danh từ/lượng từ: chỗ ngồi (座位); dùng cho vật to lớn, vững chãi như tòa nhà, ngọn núi: 一座山，一座大楼. Hình ảnh ghi nhớ: chỗ ngồi có mái che.","s":"HSK2_23#30"}],"w_24_1":[{"c":"cach_dung","t":"会: hai nghĩa \"Biết\" và \"Sẽ\"","x":"会 (Động từ/Động từ năng nguyện):\n(1) Biết làm gì, tinh thông việc gì (thông qua học tập, rèn luyện):\n你会说汉语吗？——我会一点点。 — Bạn biết nói tiếng Trung không? – Tôi biết một chút.\n我不会做饭，因为 (yīnwèi – bởi vì) 在我家都是我妈妈做饭，我爸爸也不会。 — Tôi không biết nấu ăn, bởi vì ở nhà đều là mẹ tôi nấu, bố tôi cũng không biết.\n(2) Sẽ làm gì (hành động xảy ra trong tương lai):\n明天我一定会参加你的生日晚会。 — Ngày mai tôi nhất định sẽ tham gia bữa tiệc sinh nhật của bạn.","s":"HSK2_24#4"}],"w_24_2":[{"c":"tu_mo_rong","t":"Các từ ghép với 打","x":"打听 (dǎtīng – động từ): thăm dò, dò la — 你可以帮我打听一件事吗？(Bạn có thể giúp tôi thăm dò một chuyện được không?)\n打电话 (dǎ diànhuà – cụm động từ): gọi điện; 给 + đối tượng + 打电话: gọi điện cho ai — 我常常给爸爸妈妈打电话。(Tôi thường xuyên gọi điện cho bố mẹ.)\n打车 (dǎchē) = 打的 (dǎ dī): gọi xe, bắt xe — 咱们打车（打的）回学校吧！(Chúng ta gọi xe về trường đi!)\n打球 (dǎqiú): đánh cầu, chơi bóng nói chung — 我很喜欢打球。","s":"HSK2_24#5"}],"w_24_5":[{"c":"cach_dung","t":"上/下 + lượng từ hoặc danh từ thời gian","x":"上/下 + lượng từ hoặc danh từ thời gian:\n上个星期 — Tuần trước\n下个星期 — Tuần sau\n上个月 — Tháng trước\n下个月 — Tháng sau","s":"HSK2_24#8"}],"w_24_6":[{"c":"cau_vi_du","t":"Ví dụ đầy đủ cho 报名 (+ từ 活动)","x":"听说学校下个星期会举办一个活动 (huódòng – danh từ: hoạt động)，你想参加吗？我们一起报名吧！ — Nghe nói tuần sau trường sẽ tổ chức một hoạt động, bạn muốn tham gia không? Chúng ta cùng đăng ký đi!","s":"HSK2_24#9"}],"w_24_7":[{"c":"chiet_tu","t":"Chiết tự 开始","x":"开 Kāi – Khai (mở, tổ chức, lái xe): 开车 lái xe; 开学 khai giảng; 开会 tổ chức cuộc họp.\n始 Shǐ – Thủy (ban sơ, ban đầu). Bộ thành phần: 女 Nữ + 台 Đài (厶 Khư + 口 Khẩu).\n=> 开始 (kāishǐ – động từ): Bắt đầu.","s":"HSK2_24#10"},{"c":"cau_vi_du","t":"Thêm ví dụ với 开始","x":"你从什么时候开始学中文？ — Bạn bắt đầu học tiếng Trung từ khi nào?\n从哪儿（哪里）开始？ — Bắt đầu từ đâu?","s":"HSK2_24#11"}],"w_24_8":[{"c":"cach_dung","t":"再来: làm lại; 来 thay cho động từ","x":"再来: Làm lại.\n来 có thể thay thế cho một hành động cụ thể (tùy ngữ cảnh). Thường dùng trong khẩu ngữ.","s":"HSK2_24#12"}],"w_24_9":[{"c":"chiet_tu","t":"Chiết tự 遍 + 再来一遍","x":"Bộ thành phần: 辶 Quai sước + 扁 Biển (dẹt).\n再来一遍: Làm lại một lần nữa.\n麻烦老师再读一遍可以吗？ — Làm phiền thầy đọc lại một lần nữa được không?","s":"HSK2_24#13"},{"c":"cach_dung","t":"Phân biệt 遍 và 次","x":"遍: Nhấn mạnh số lần thực hiện động tác từ đầu đến cuối, thường dùng cho động tác ngắn, dễ kiểm soát như 听、说、读、写. VD: 读一遍, 再写一遍, 再说一遍.\n次: Không quan trọng có làm hết từ đầu đến cuối hay không, thường dùng cho hành động dài, phức tạp. VD: 去北京两次, 去河内三次, 第一次来这儿.","s":"HSK2_24#20"}],"w_24_10":[{"c":"chiet_tu","t":"Chiết tự 懂 + ví dụ","x":"Bộ thành phần: 忄 Tâm đứng + 董 Đổng (艹 Thảo + 重 Trọng).\n同学们，今天学的课文你们都懂了吗？——都懂了。 — Các em, bài khóa hôm nay các em đều hiểu chưa? – Đều hiểu hết rồi.\n什么都不懂: Cái gì cũng không hiểu.","s":"HSK2_24#14"}],"w_24_11":[{"c":"chiet_tu","t":"Chiết tự 舒 + mẩu đối thoại vui","x":"舒 Shū – Thư (thư giãn). Bộ thành phần: 舍 Xá (人 Nhân + 舌 Thiệt) + 予 Dữ (cho).\n我：我今天身体不太舒服，不想上班。 — Tôi: Hôm nay tôi thấy không khỏe lắm, không muốn đi làm.\n老板：哪里不舒服？ — Sếp: Chỗ nào không khỏe?\n我：看到你就感到不舒服。 — Tôi: Nhìn thấy sếp là thấy không khỏe.","s":"HSK2_24#15"}],"w_24_12":[{"c":"chiet_tu","t":"Chiết tự 意 và 思","x":"意 Yì – Ý (ý nghĩa). Bộ thành phần: 音 Âm (立 Lập + 日 Nhật) + 心 Tâm.\n思 Sī – Tư (tư tưởng). Bộ thành phần: 田 Điền + 心 Tâm.","s":"HSK2_24#16"},{"c":"cach_dung","t":"Các cụm với 意思","x":"老师，这个字是什么意思？ — Thầy/cô ơi, chữ này nghĩa là gì?\n有意思: Thú vị — 我觉得这个电影很有意思。\n没意思: Vô vị, chán.\n不好意思: Xin lỗi / Ngại quá (dùng cho lỗi nhỏ hoặc khi ngại ngùng).","s":"HSK2_24#17"}],"w_24_14":[{"c":"chiet_tu","t":"Chiết tự 次 + 第…次","x":"Bộ thành phần: 冫 Băng + 欠 Khiếm.\n你来越南几次了？ — Bạn đến Việt Nam mấy lần rồi?\n第 (dì) + số + 次: Lần thứ…\n这次是第二次。 — Lần này là lần thứ hai.","s":"HSK2_24#19"}],"w_24_15":[{"c":"cach_dung","t":"Nửa tiếng, tiếng rưỡi…","x":"半个小时: Nửa tiếng đồng hồ\n一个半小时: Một tiếng rưỡi đồng hồ\n两个半小时: Hai tiếng rưỡi đồng hồ","s":"HSK2_24#21"}],"w_24_17":[{"c":"chiet_tu","t":"Chiết tự 疼 + từ 心疼","x":"疼 Téng (tính từ): Đau. Bộ thành phần: 疒 Nạch + 冬 Đông.\n哪里不舒服？——头疼。 — Chỗ nào không khỏe? – Đau đầu.\n=> 心疼 (xīnténg – động từ): Thương, xót.","s":"HSK2_24#23"}],"w_24_18":[{"c":"chiet_tu","t":"Chiết tự 烧 (发烧)","x":"烧 Shāo – Thiêu (thiêu đốt, cơn sốt). Bộ thành phần: 火 Hỏa + 尧 Nghiêu.","s":"HSK2_24#24"}],"w_24_19":[{"c":"cau_vi_du","t":"Thêm ví dụ với 能","x":"能 + động từ: Có khả năng / có thể làm được việc gì (dựa vào năng lực tự nhiên hoặc điều kiện cho phép).\n你今天能来参加吗？ — Hôm nay bạn có thể đến tham gia không?","s":"HSK2_24#25"}],"w_24_20":[{"c":"cach_dung","t":"可能 + V: phỏng đoán; 不可能, 怎么可能","x":"可能 + động từ: Đưa ra phỏng đoán, dự đoán về việc có thể xảy ra trong tương lai.\n不可能！ — Không thể nào!\n怎么可能？ — Sao có thể thế được! / Làm gì có chuyện đó!","s":"HSK2_24#26"},{"c":"cach_dung","t":"Phân biệt 可以 và 可能","x":"可以: Cho phép / xin phép — 我可以试试吗？; 不可以: Không được phép.\n可能: Đưa ra phỏng đoán, dự đoán — 他可能不会来。; 不可能: Không thể nào.","s":"HSK2_24#27"}],"w_24_22":[{"c":"cau_vi_du","t":"Ví dụ cho 感冒","x":"我觉得身体有点不舒服，一直咳嗽，还发烧，可能感冒了。 — Tôi cảm thấy hơi không khỏe, cứ ho mãi, còn sốt nữa, chắc là bị cảm rồi.","s":"HSK2_24#29"}],"w_25_1":[{"c":"chiet_tu","t":"Chiết tự 台 + 上台, 电视台","x":"Bộ thành phần: 厶 Khư + 口 Khẩu.\n=> 上台 (shàngtái – động từ ly hợp): Lên bục giảng, lên sân khấu.\n电视台 (diànshìtái – danh từ, điện thị đài): Đài truyền hình.\n我听说他在电视台工作。 — Tôi nghe nói anh ấy làm việc ở đài truyền hình.","s":"HSK2_25#4"}],"w_25_2":[{"c":"cau_vi_du","t":"Ví dụ cho 表演","x":"老师让我上台表演。 — Giáo viên bảo tôi lên sân khấu biểu diễn.","s":"HSK2_25#5"}],"w_25_4":[{"c":"chiet_tu","t":"Chiết tự 愿意 + cách dùng","x":"愿 – Bộ thành phần: 原 Nguyên + 心 Tâm.\n意 – Bộ thành phần: 立 Lập + 日 Nhật + 心 Tâm.\n愿意 + động từ: Bằng lòng / nguyện ý làm gì.\nA：你愿意？B：我愿意。","s":"HSK2_25#7"}],"w_25_5":[{"c":"cau_vi_du","t":"Ví dụ cho 为什么","x":"他问我你为什么喜欢学习汉语。 — Anh ấy hỏi tôi vì sao lại thích học tiếng Trung.","s":"HSK2_25#8"}],"w_25_6":[{"c":"chiet_tu","t":"Chiết tự 得","x":"Bộ thành phần: 彳 Nhân kép + 日 Nhật + 一 Nhất + 寸 Thốn.","s":"HSK2_25#9"}],"w_25_7":[{"c":"chiet_tu","t":"Chiết tự 错 + 错了 / 不错 / 没错","x":"Bộ thành phần: 钅 Kim + 昔 Tích (艹 Thảo + 一 Nhất + 日 Nhật).\n这个对不对？——错了！ — Cái này đúng không? – Sai rồi!\n不错: Không tồi, rất tốt (~很好).\n没错: Không sai.","s":"HSK2_25#10"}],"w_25_9":[{"c":"tu_mo_rong","t":"HSK = 汉语水平考试; ví dụ 水平很高","x":"汉语水平考试 (Hànyǔ shuǐpíng kǎoshì): Kỳ thi trình độ Hán ngữ (HSK).\n他的中文水平很高。 — Trình độ tiếng Trung của anh ấy rất cao.","s":"HSK2_25#12"}],"w_25_10":[{"c":"chiet_tu","t":"Chiết tự 提高 + ví dụ","x":"提 Đề (cầm, nhấc lên) – Bộ thành phần: 扌 Thủ (tay) + 是 Thị.\n高 Cao – Bộ thành phần: 亠 Đầu + 口 Khẩu + 冂 Quynh.\n我觉得我的中文不太好，还要再学习提高自己的水平。 — Tôi thấy tiếng Trung của mình chưa tốt lắm, vẫn cần học thêm để nâng cao trình độ của mình.","s":"HSK2_25#13"}],"w_25_11":[{"c":"tu_mo_rong","t":"慢 (chậm) – trái nghĩa với 快","x":"=> 慢 (màn – tính từ): Chậm. Bộ thành phần: 忄 Tâm đứng + 曼 Mạn.\n太快了！你们慢一点吧，我跟不上。 — Nhanh quá! Các bạn chậm một chút đi, tôi theo không kịp.","s":"HSK2_25#14"}],"w_25_12":[{"c":"cach_dung","t":"这里 = 这儿, 那里 = 那儿, 哪里 = 哪儿","x":"这里 = 这儿\n那里 = 那儿\n哪里 = 哪儿","s":"HSK2_25#15"},{"c":"cach_dung","t":"Đáp lời khen: 哪里，哪里","x":"哪里 dùng khi đáp lại lời khen của người khác; có thể nói: 哪里，哪里。\nA：你怎么这么好看呢？B：哪里，哪里。\nA：你的中文太好了！B：哪里，哪里。","s":"HSK2_25#32"}],"w_25_14":[{"c":"chiet_tu","t":"Chiết tự 流利","x":"流 Lưu (đổ, chảy) – Bộ thành phần: 氵 Thủy + 亠 Đầu + 厶 Khư + 川 Xuyên (sông).\n利 Lợi (thuận lợi) – Bộ thành phần: 禾 Hòa + 刂 Đao đứng.","s":"HSK2_25#17"}],"w_25_15":[{"c":"chiet_tu","t":"Chiết tự 努力 + cấu trúc","x":"Bộ thành phần: 奴 Nô (女 Nữ + 又 Hựu) + 力 Lực.\n努力 + động từ: Cố gắng làm gì.","s":"HSK2_25#18"}],"w_25_16":[{"c":"chiet_tu","t":"Chiết tự 认真","x":"认 Nhận (nhận thức) – Bộ thành phần: 讠 Ngôn + 人 Nhân.\n真 Chân (thật, chân thực) – Bộ thành phần: 直 Trực + 八 Bát.\n真的吗？ — Thật à?","s":"HSK2_25#19"}],"w_25_18":[{"c":"chiet_tu","t":"Chiết tự 看 + 看书 / 读书 / 好看","x":"Bộ thành phần: 手 Thủ (tay) + 目 Mục (mắt).\n我很喜欢看书。 — Tôi rất thích đọc sách.\n读书: Học tập (~学习) — 我在中国读书。(Tôi học ở Trung Quốc.)\n=> 好看: Đẹp.","s":"HSK2_25#21"}],"w_25_19":[{"c":"cach_dung","t":"这么 / 那么 + tính từ","x":"Cấu trúc: 这么 / 那么 + tính từ: … như thế này / … như thế kia.","s":"HSK2_25#22"}],"w_25_23":[{"c":"chiet_tu","t":"Chiết tự 运动","x":"运 Vận (vận chuyển, vận mệnh) – Bộ thành phần: 辶 Quai sước + 云 Vân (mây).\n动 Động – Bộ thành phần: 云 Vân (mây) + 力 Lực.","s":"HSK2_25#24"}],"w_25_24":[{"c":"tu_mo_rong","t":"跑步 + chiết tự 跑","x":"跑步 (pǎobù – động từ ly hợp, bão bộ): Chạy bộ.\n跑 – Bộ thành phần: ⻊ Túc + 包 Bao.\n步 Bù (danh từ): Bộ, bước.","s":"HSK2_25#25"}],"w_25_25":[{"c":"tu_mo_rong","t":"足球 và 踢足球","x":"足球: Bóng đá (danh từ)\n踢足球: Đá bóng (động từ)","s":"HSK2_25#26"}],"w_25_26":[{"c":"cach_dung","t":"打篮球 + chiết tự 篮","x":"打篮球: Chơi bóng rổ.\n我的爱好是打篮球，业余时间常常跟朋友打篮球。 — Sở thích của tôi là chơi bóng rổ, thời gian rảnh thường chơi bóng rổ cùng bạn bè.\n篮 Lán (danh từ): Cái làn, rổ – Bộ thành phần: ⺮ Trúc + 监 Giám (giám sát).","s":"HSK2_25#27"}],"w_25_27":[{"c":"cach_dung","t":"Phân biệt 刚 và 刚才","x":"刚: Phó từ, đứng trước động từ — 我刚看到他。\n刚才: Danh từ chỉ thời gian, đứng trước hoặc sau chủ ngữ, làm trạng ngữ — 刚才我看到她。/ 我刚才看到她。","s":"HSK2_25#28"}],"w_25_28":[{"c":"chiet_tu","t":"Chiết tự 坚持 + ví dụ","x":"坚 Kiên (kiên định) – Bộ thành phần: 二 Nhị + 又 Hựu + 土 Thổ.\n持 Trì (duy trì) – Bộ thành phần: 扌 Thủ + 寺 Tự (土 Thổ + 一 Nhất + 寸 Thốn).\n加油，再坚持一点吧。 — Cố lên, kiên trì thêm một chút nữa nhé.","s":"HSK2_25#29"}],"w_25_29":[{"c":"ngu_phap","t":"因为……所以……: Bởi vì…, cho nên…","x":"因为 + nguyên nhân，所以 (suǒyǐ) + kết quả: Bởi vì…, cho nên…\n因为她一直很努力和认真，所以老师很喜欢她。 — Bởi vì cô ấy luôn cố gắng và nghiêm túc, cho nên giáo viên rất thích cô ấy.\nA：你为什么学习中文呢？B：因为我对中国文化和历史很感兴趣。","s":"HSK2_25#30"}],"w_26_3":[{"c":"chiet_tu","t":"Chiết tự 响 + ví dụ","x":"Bộ thành phần: 口 Khẩu + 向 Hướng.\n谁的电话（手机）在响呢？ — Điện thoại ai đang reo vậy?\n你的手机响了，快接吧！ — Điện thoại của bạn reo rồi kìa, mau nghe máy đi!","s":"HSK2_26#14"}],"w_26_5":[{"c":"chiet_tu","t":"Chiết tự 阿姨","x":"阿 – Bộ thành phần: 阝 Ấp/Phụ + 可 Khả.\n姨 – Bộ thành phần: 女 Nữ + 夷 Di (一 Nhất + 弓 Cung + 大 Đại).","s":"HSK2_26#5"}],"w_26_6":[{"c":"cach_dung","t":"中学 gồm 初中 và 高中; lượng từ 所","x":"中学 bao gồm cả 初中 (chūzhōng): THCS và 高中 (gāozhōng): THPT.\nLượng từ đi kèm: 所 (suǒ).","s":"HSK2_26#6"}],"w_26_7":[{"c":"cau_vi_du","t":"Câu trả lời mẫu với 出国","x":"你打算什么时候出国留学？——我打算明年会出国留学。 — Bạn dự định bao giờ ra nước ngoài du học? – Tôi dự định năm sau sẽ ra nước ngoài du học.","s":"HSK2_26#7"}],"w_26_10":[{"c":"cau_vi_du","t":"Ví dụ cho 关机 (+ từ 自动)","x":"我的手机没电了，自动 (zìdòng) 关机了。 — Điện thoại của tôi hết pin rồi, tự động tắt máy luôn.","s":"HSK2_26#9"}],"w_26_12":[{"c":"tu_mo_rong","t":"Ví dụ 开机 + từ 开关","x":"我开机以后给你打电话。 — Sau khi mở máy tôi sẽ gọi điện cho bạn.\n开关 (kāiguān – danh từ): Công tắc.","s":"HSK2_26#10"}],"w_26_13":[{"c":"cach_dung","t":"对了: dùng khi chợt nhớ ra","x":"对了 thường dùng khi chợt nhớ ra điều gì đó.\n对了！明天是他的生日。","s":"HSK2_26#11"}],"w_26_14":[{"c":"chiet_tu","t":"Chiết tự 忘 + ví dụ","x":"Bộ thành phần: 亡 Vong + 心 Tâm.\n下雨了！我忘带伞。 — Trời mưa rồi! Tôi quên mang theo ô.","s":"HSK2_26#12"}],"w_26_15":[{"c":"cach_dung","t":"Phân biệt 又 và 再","x":"Đều đứng trước động từ làm trạng ngữ, biểu thị sự lặp lại.\n又: Hành động đã xảy ra — 他昨天来看我了，今天又来了。他昨天没来上课，今天又没来。\n再: Hành động chưa xảy ra — 今天我去看她了，我想明天再去。再见。你再说一遍，可以吗？","s":"HSK2_26#13"}],"w_26_17":[{"c":"chiet_tu","t":"Chiết tự 接 + 接电话","x":"Bộ thành phần: 扌 Thủ + 妾 Thiếp (立 Lập + 女 Nữ).\n接电话: Nghe điện thoại.\n我给你打电话，你怎么没接呢？ — Tôi gọi điện cho bạn, sao bạn không nghe máy vậy?","s":"HSK2_26#15"}],"w_26_18":[{"c":"chiet_tu","t":"Chiết tự 踢 + ví dụ","x":"Bộ thành phần: ⻊ Túc + 易 Dịch.\n我的爱好是踢足球。我每天都去学校的足球场跟我朋友踢足球。 — Sở thích của tôi là đá bóng. Mỗi ngày tôi đều ra sân bóng của trường đá bóng cùng bạn bè.","s":"HSK2_26#16"}],"w_26_19":[{"c":"chiet_tu","t":"Chiết tự 输","x":"Bộ thành phần: 车 Xa + 俞 Du (人 Nhân + 一 Nhất + 月 Nguyệt + 刂 Đao đứng).","s":"HSK2_26#17"}],"w_26_20":[{"c":"chiet_tu","t":"Chiết tự 赢 + ví dụ","x":"Bộ thành phần: 亡 Vong + 口 Khẩu + 月 Nguyệt + 贝 Bối + 凡 Phàm.\n你们俩谁输谁赢呢？ — Hai bạn ai thắng ai thua vậy?","s":"HSK2_26#18"}],"w_26_21":[{"c":"cau_vi_du","t":"Ví dụ 比赛 + cấu trúc A 跟 B 比赛","x":"你有打算报名参加学校举行的足球比赛吗？ — Bạn có dự định đăng ký tham gia giải bóng đá do trường tổ chức không?\nA 跟 B 比赛: A thi đấu với B.","s":"HSK2_26#19"}],"w_26_23":[{"c":"cach_dung","t":"Số + 比 + số: chỉ tỉ số","x":"Số + 比 + số: Dùng để chỉ tỉ số.\n几比几了？——二比一了。","s":"HSK2_26#21"}],"w_26_24":[{"c":"cach_dung","t":"祝贺 trang trọng hơn 祝","x":"祝贺 trang trọng hơn 祝, thường dùng khi chúc mừng một sự kiện quan trọng, thành tựu lớn hoặc mốc son trong cuộc sống.","s":"HSK2_26#22"}],"w_26_25":[{"c":"cau_vi_du","t":"Nghĩa câu 哎，真是的！","x":"哎，真是的！ — Ôi, thật là!","s":"HSK2_26#23"}],"w_26_27":[{"c":"tu_mo_rong","t":"Lớp TOEFL; TOEIC, IELTS","x":"托福班: Lớp học TOEFL\n上托福班: Học / tham gia lớp TOEFL\n托业 (tuōyè): TOEIC\n雅思 (yǎsī): IELTS","s":"HSK2_26#24"}],"w_26_28":[{"c":"cach_dung","t":"已经 + V/Adj + 了","x":"已经 + động từ / tính từ + 了: Chỉ một hành động đã hoàn thành hoặc một trạng thái đã thay đổi.\n现在已经十一点了，快去睡觉吧。 — Bây giờ đã 11 giờ rồi, mau đi ngủ đi.","s":"HSK2_26#25"}],"w_26_29":[{"c":"cach_dung","t":"考 + môn học/kỳ thi; 高考","x":"考 + môn học / kỳ thi.\n明天我要考HSK。 — Ngày mai tôi phải thi HSK.\n考托福 / 托业 / 雅思: Thi TOEFL / TOEIC / IELTS.\n高考: Kỳ thi đại học — 中国学生都要参加高考。","s":"HSK2_26#26"}],"w_26_30":[{"c":"chiet_tu","t":"Chiết tự 陪 + cấu trúc A 陪 B","x":"Bộ thành phần: 阝 Phụ + 立 Lập + 口 Khẩu.\nA + 陪 + B + (一起) + V: A cùng B (cùng nhau) làm gì.\n明天你陪我一起去吧。 — Ngày mai bạn đi cùng tôi nhé.","s":"HSK2_26#27"}],"w_27_1":[{"c":"chiet_tu","t":"Chiết tự 病 + từ mở rộng","x":"Bìng (danh từ): Bệnh. Bộ thành phần: 疒 Nạch (bệnh tật) + 丙 Bính.\n病人 (bìngrén – danh từ): Bệnh nhân, người bệnh.\n生病 (shēngbìng – động từ ly hợp): Bị bệnh, bị ốm.\n看病 (kànbìng – động từ ly hợp): Khám bệnh.\n你是不是生病了？去医院看病吧！ — Bạn bị ốm à? Đi bệnh viện khám đi.\n有病？: Có vấn đề à, bị khùng à (đùa).","s":"HSK2_27#4"}],"w_27_2":[{"c":"chiet_tu","t":"Chiết tự 肚","x":"Bộ thành phần: 肉 Nhục + 土 Thổ.","s":"HSK2_27#5"}],"w_27_3":[{"c":"chiet_tu","t":"Chiết tự 拉 + ví dụ 拉肚子","x":"拉 Lā (động từ): Kéo. Bộ thành phần: 扌 Thủ (tay) + 立 Lập.\n昨天我吃了没洗的水果，今天拉肚子了。 — Hôm qua tôi ăn trái cây chưa rửa, hôm nay bị đau bụng đi ngoài rồi.","s":"HSK2_27#6"}],"w_27_4":[{"c":"chiet_tu","t":"Chiết tự 嗓 + ví dụ","x":"Bộ thành phần: 口 Khẩu + 又 Hựu + 木 Mộc.\n昨天我喝了太多冷水 (lěngshuǐ – nước lạnh)，今天嗓子很疼，有可能感冒了。 — Hôm qua tôi uống nhiều nước lạnh quá, hôm nay đau họng, có khi bị cảm rồi.","s":"HSK2_27#7"}],"w_27_5":[{"c":"chiet_tu","t":"Chiết tự 汗","x":"汗 Hàn (danh từ): Mồ hôi. Bộ thành phần: 氵 Thủy (3 chấm thủy) + 干 Can (khô).","s":"HSK2_27#8"}],"w_27_6":[{"c":"cau_vi_du","t":"Thêm ví dụ 厉害 (2 nghĩa)","x":"她学中文学得很厉害。 — Cô ấy học tiếng Trung cực giỏi.\n我肚子拉得很厉害。","s":"HSK2_27#9"}],"w_27_7":[{"c":"cach_dung","t":"片: lượng từ cho vật mỏng","x":"Dùng làm lượng từ cho các vật mỏng (bánh mì, thuốc, lá cây).\n医生说这种药每天吃两片。 — Bác sĩ nói loại thuốc này mỗi ngày uống hai viên.","s":"HSK2_27#10"}],"w_27_8":[{"c":"cau_vi_du","t":"Thêm ví dụ với 鱼","x":"今天的鱼做得非常好吃。 — Cá hôm nay nấu cực kỳ ngon.","s":"HSK2_27#11"}],"w_27_9":[{"c":"tu_mo_rong","t":"猪 – lợn; 猪肉 – thịt lợn","x":"猪 (zhū – danh từ): Lợn\n猪肉: Thịt lợn\n你想吃鱼还是牛肉？ — Bạn muốn ăn cá hay thịt bò?","s":"HSK2_27#12"}],"w_27_12":[{"c":"tu_mo_rong","t":"上厕所: từ thay thế cho 大便/小便","x":"上厕所 (shàng cèsuǒ): Đi vệ sinh – từ dùng thay thế cho 大便 / 小便.","s":"HSK2_27#14"}],"w_27_14":[{"c":"cau_vi_du","t":"Thêm ví dụ với 检查","x":"请再检查一遍。 — Vui lòng kiểm tra lại một lần nữa.","s":"HSK2_27#15"}],"w_27_15":[{"c":"chiet_tu","t":"Chiết tự 结 + ví dụ","x":"结 – Bộ thành phần: 纟 Mịch + 吉 Cát (士 Sĩ + 口 Khẩu).\n检查的结果已经出来了。 — Kết quả kiểm tra đã có rồi.","s":"HSK2_27#16"}],"w_27_16":[{"c":"cach_dung","t":"得病 ~ 生病","x":"得病 ~ 生病: Mắc bệnh, bị bệnh.\n得了这种病，要多休息。 — Mắc phải căn bệnh này thì cần nghỉ ngơi nhiều.","s":"HSK2_27#17"}],"w_27_18":[{"c":"cau_vi_du","t":"Ví dụ cho 开(药)","x":"医生给我开了一些药。 — Bác sĩ đã kê cho tôi một ít thuốc.\n因为我得了肠炎，医生开了很多药。 — Vì tôi bị viêm ruột, bác sĩ đã kê rất nhiều thuốc.","s":"HSK2_27#19"}],"w_27_19":[{"c":"chiet_tu","t":"Chiết tự 针 (打针)","x":"Bộ thành phần: 钅 Kim + 十 Thập.","s":"HSK2_27#20"}],"w_27_20":[{"c":"cach_dung","t":"消化 nghĩa bóng","x":"这个问题太难了，我要时间来消化。 — Câu hỏi này khó quá, tôi cần thời gian để 'tiêu hóa'.","s":"HSK2_27#21"}],"w_27_21":[{"c":"chiet_tu","t":"Chiết tự 哭 + mẹo nhớ","x":"Bộ thành phần: 口 Khẩu + 犬 Khuyển. Mẹo nhớ: Chó cắn 2 miếng là khóc ngay.\n你怎么哭了？谁不让你高兴了？ — Sao bạn lại khóc thế? Ai làm bạn không vui à?","s":"HSK2_27#22"}],"w_27_22":[{"c":"chiet_tu","t":"Chiết tự 寂寞 + ví dụ","x":"寂 – Bộ thành phần: 宀 Miên + 叔 Thúc.\n寞 – Bộ thành phần: 宀 Miên + 莫 Mạc (艹 Thảo đầu + 日 Nhật + 大 Đại).\n一个人在房间里，我觉得很寂寞。 — Một mình ở trong phòng, tôi cảm thấy rất cô đơn.","s":"HSK2_27#23"}],"w_27_23":[{"c":"cau_vi_du","t":"Ví dụ cho 所以","x":"因为今天我不太舒服，所以去医院看病。 — Vì hôm nay tôi không khỏe lắm, nên tôi đi bệnh viện khám.","s":"HSK2_27#24"},{"c":"ngu_phap","t":"因为 và 所以 có thể dùng riêng lẻ","x":"因为……所以……: Biểu thị quan hệ nguyên nhân – kết quả.\n他因为病了，所以没有来上课。\n他因为要去中国工作，所以学习汉语。\n因为她学习很努力，所以学得很好。\n因为 và 所以 đều có thể dùng riêng lẻ (因为 nêu nguyên nhân, 所以 nêu kết quả):\n因为下雨，下午我们不去公园了。\n我觉得很寂寞，所以常常想家。","s":"HSK2_27#41"}],"w_27_24":[{"c":"cach_dung","t":"别 = 不要; 别……了","x":"别 + động từ / tính từ = 不要 + động từ / tính từ.\n别……了！\n别说了！ — Đừng nói nữa!\n别哭了，事情已经过去了。 — Đừng khóc nữa, mọi chuyện đã qua rồi.","s":"HSK2_27#25"}],"w_27_27":[{"c":"chiet_tu","t":"Chiết tự 礼 + ví dụ 礼堂","x":"礼 – Bộ thành phần: 礻 Thị (hiển thị).\n学校的舞会就在礼堂里举行。 — Buổi vũ hội của trường được tổ chức ngay trong hội trường.","s":"HSK2_27#28"}],"w_27_28":[{"c":"chiet_tu","t":"Chiết tự 跳 + ví dụ","x":"跳 Tiào (động từ): Nhảy. Bộ thành phần: ⻊ Túc + 兆 Triệu.\n她跳舞跳得非常好。 — Cô ấy nhảy rất giỏi.","s":"HSK2_27#29"}],"w_28_1":[{"c":"chiet_tu","t":"Chiết tự 租 + mẹo nhớ","x":"Bộ thành phần: 禾 Hòa (lúa) + 且 Thả. Mẹo nhớ: Thuê thì thư thả mà trả bằng lúa.\n租车: Thuê xe.\n=> 出租: Cho thuê.","s":"HSK2_28#4"}],"w_28_2":[{"c":"cach_dung","t":"房间 và 房子; 房租","x":"房间: Căn phòng\n房子: Căn nhà\n有房有车: Có nhà có xe\n房租 (fángzū – danh từ): Tiền thuê nhà — 这个月的房租是多少？(Tiền thuê nhà tháng này bao nhiêu?)","s":"HSK2_28#5"}],"w_28_3":[{"c":"chiet_tu","t":"Chiết tự 套 + mẹo nhớ","x":"Bộ thành phần: 大 Đại + 镸 Trường (三 + 厶). Mẹo nhớ: Căn nhà có 3 phòng riêng tư.","s":"HSK2_28#6"}],"w_28_4":[{"c":"chiet_tu","t":"Chiết tự 满 và 意 + mẹo nhớ","x":"满 Mǎn (tính từ): Mãn (viên mãn, đầy). Bộ thành phần: 氵 Thủy (3 chấm thủy) + 艹 Thảo đầu + 两 Lưỡng. Mẹo nhớ: Cây cỏ được tưới nước 2 lần thì sẽ viên mãn, tràn đầy.\n意 Yì (danh từ): Ý (ý nghĩ, nguyện vọng). Bộ thành phần: 音 Âm + 心 Tâm.","s":"HSK2_28#7"},{"c":"cach_dung","t":"对 + đối tượng + tính từ; ví dụ 满意","x":"咱们今天上午看的三套房子我都不太满意。 — Ba căn nhà sáng nay chúng ta xem tôi đều không vừa ý lắm.\n对 + đối tượng + tính từ: Như thế nào với ai/cái gì.\n我对这套房子很满意。 — Tôi rất vừa ý với căn nhà này.\n他对我很好。 — Anh ấy rất tốt với tôi.","s":"HSK2_28#8"}],"w_28_5":[{"c":"cau_vi_du","t":"Thêm ví dụ 有的 (chỉ người)","x":"我们班有三十个学生，有的是美国人，有的是越南人。 — Lớp chúng tôi có 30 học sinh, có người là người Mỹ, có người là người Việt Nam.","s":"HSK2_28#9"}],"w_28_6":[{"c":"chiet_tu","t":"Chiết tự 周 + 周 = tuần lễ","x":"周 zhōu (danh từ): Châu/Chu (vòng, quanh, tuần lễ). Bộ thành phần: 冂 Quynh + 土 Thổ + 口 Khẩu. Mẹo nhớ: Chu vi xung quanh mảnh đất này đủ lớn để nuôi nhiều miệng ăn.\n周: Tuần lễ (~星期) => 周一（二、三、四、五、六、日/天）","s":"HSK2_28#10"},{"c":"chiet_tu","t":"Chiết tự 围 + 包围","x":"围 wéi (động từ): Vi (vây quanh, bao vây). Bộ thành phần: 口 Vây + 韦 Vi (da thuộc).\n包围 (bāowéi – động từ): Bao vây.","s":"HSK2_28#11"}],"w_28_7":[{"c":"chiet_tu","t":"Chiết tự 环 và 境 + 出境","x":"环 Huán (danh từ): Hoàn (hoàn cảnh, vòng, ngọc). Bộ thành phần: 王 Vương (玉 Ngọc) + 不 Bất.\n境 Jìng (danh từ): Cảnh (hoàn cảnh, biên giới). Bộ thành phần: 土 Thổ + 竟 Cánh (音 Âm + 儿 Nhi).\n=> 出境 (chūjìng – động từ): Xuất cảnh.","s":"HSK2_28#12"}],"w_28_8":[{"c":"chiet_tu","t":"Chiết tự 乱 + mẹo nhớ","x":"Bộ thành phần: 舌 Thiệt (lưỡi) + 乚 Ất (móc câu). Mẹo nhớ: Nói loạn đến mức lưỡi biến thành móc câu.","s":"HSK2_28#14"}],"w_28_9":[{"c":"chiet_tu","t":"Chiết tự 厨 + 厨师, 厨房","x":"厨 Chú: Trù (bếp, ngự trù). Bộ thành phần: 厂 Xưởng + 豆 Đậu + 寸 Thốn. Mẹo nhớ: Trong nhà bếp của xưởng có một cây đậu cao một tấc.\n厨师 (chúshī – danh từ): Đầu bếp.\n厨房 (chúfáng – danh từ): Phòng bếp, nhà bếp.","s":"HSK2_28#15"}],"w_28_10":[{"c":"chiet_tu","t":"Chiết tự 卧","x":"卧 Wò: Ngọa (nằm). Bộ thành phần: 臣 Thần + 卜 Bốc.","s":"HSK2_28#16"}],"w_28_11":[{"c":"chiet_tu","t":"Chiết tự 积 (面积)","x":"积 Jī: Tích. Bộ thành phần: 禾 Hòa + 只 Chỉ.","s":"HSK2_28#18"}],"w_28_12":[{"c":"chiet_tu","t":"Chiết tự 层 + ví dụ","x":"Bộ thành phần: 尸 Thi + 云 Vân.\n这座楼一共有三层。 — Tòa nhà này tổng cộng có 3 tầng.","s":"HSK2_28#19"}],"w_28_13":[{"c":"cau_vi_du","t":"Ví dụ cho 平(方)米","x":"这间客厅有三十平方米左右。 — Phòng khách này rộng khoảng 30 mét vuông.","s":"HSK2_28#20"}],"w_28_15":[{"c":"cach_dung","t":"阳光 >< 阴 + ví dụ","x":"阳光 >< 阴 (yīn – âm).\n这套房子没有阳光。 — Căn nhà này không có ánh nắng mặt trời.","s":"HSK2_28#22"}],"w_28_16":[{"c":"tu_mo_rong","t":"Vợ – chồng","x":"妻子 (qīzi): vợ — 丈夫 (zhàngfu): chồng\n老婆 (lǎopó): vợ — 老公 (lǎogōng): chồng","s":"HSK2_28#23"}],"w_28_19":[{"c":"chiet_tu","t":"Chiết tự 堵","x":"堵 Dǔ (động từ/tính từ): Tắc, tắc nghẽn. Bộ thành phần: 土 Thổ + 者 Giả.","s":"HSK2_28#26"}],"w_28_20":[{"c":"chiet_tu","t":"Chiết tự 赶 + 赶时间","x":"Bộ thành phần: 走 Tẩu + 干 Can.\n对不起，我现在正赶时间，以后再聊吧。 — Xin lỗi, bây giờ tôi đang vội, để sau nói chuyện nhé.","s":"HSK2_28#27"}],"w_28_25":[{"c":"cach_dung","t":"真: tính từ và phó từ","x":"Tính từ: Thật, thật sự, đúng với sự thật — 他说的事情是真的。\nPhó từ: Quá, thật, thực sự — 今天的天气真好啊！(Thời tiết hôm nay đẹp thật!)\n真的吗？——真的。 — Thật không? – Thật.","s":"HSK2_28#30"}],"w_28_26":[{"c":"cach_dung","t":"条: lượng từ cho vật thon dài, uốn lượn","x":"条 dùng cho những vật có hình dáng thon, dài, uốn lượn (con sông, con đường, con cá, cái quần, chiếc váy…).\nTrang phục: 一条裤子 (yì tiáo kùzi): Một chiếc quần.\nĐộng vật: 一条鱼 (yì tiáo yú): Một con cá.\nĐịa lý, đường sá: 一条路 (yì tiáo lù): Một con đường; 一条河 (yì tiáo hé): Một con sông.","s":"HSK2_28#31"}],"w_28_27":[{"c":"chiet_tu","t":"Chiết tự 河 + 河内","x":"Bộ thành phần: 氵 Thủy + 可 Khả.\n河内 (Hénèi): Hà Nội.","s":"HSK2_28#32"}],"w_28_28":[{"c":"cau_vi_du","t":"方便 khi gọi điện thoại","x":"您现在说话方便吗？ — Bây giờ anh/chị có tiện nói chuyện không ạ? (Dùng khi gọi điện thoại.)","s":"HSK2_28#33"}],"w_28_29":[{"c":"tu_mo_rong","t":"公共汽车 ~ 公交车","x":"公共汽车 (gōnggòng qìchē) ~ 公交车 (gōngjiāochē): Xe buýt.","s":"HSK2_28#34"}],"w_28_30":[{"c":"tu_mo_rong","t":"Chiết tự 站 + 车站","x":"Bộ thành phần: 立 Lập + 占 Chiếm.\n=> 车站: Bến xe.","s":"HSK2_28#34"}],"w_28_31":[{"c":"cau_vi_du","t":"Thêm ví dụ với 旁边","x":"坐在你旁边的那个人是谁？ — Người ngồi bên cạnh bạn là ai thế?","s":"HSK2_28#35"}],"w_28_32":[{"c":"chiet_tu","t":"Chiết tự 地, 铁 + từ mở rộng","x":"地 Dì: Địa, đất. Bộ thành phần: 土 Thổ + 也 Dã.\n地球 (dìqiú): Địa cầu, trái đất.\n铁 Tiě: Sắt. Bộ thành phần: 钅 Kim + 失 Thất.\n高铁 (gāotiě – danh từ): Tàu cao tốc.","s":"HSK2_28#36"}],"w_28_33":[{"c":"chiet_tu","t":"Chiết tự 附 (附近)","x":"Bộ thành phần: 阝 Phụ + 付 Phó.","s":"HSK2_28#37"}],"w_28_23":[{"c":"ngu_phap","t":"还是: như thế thì tốt hơn","x":"还是 biểu thị mong muốn, mang nghĩa 'như thế thì tốt hơn / làm thế thì tốt hơn'.\n我还是想要上下午都有阳光的。\n我还是想一个人住一个房间，不愿意跟别人合住。\n天冷了，还是买一件羽绒服吧。","s":"HSK2_28#41"}],"w_28_18":[{"c":"ngu_phap","t":"Phân biệt 就 và 才","x":"就 và 才 đều có thể đứng trước động từ làm trạng ngữ.\n就 – sự việc không lâu nữa sẽ xảy ra: 你等一下，她就来。现在六点，我们六点半就出发。\n就 – sự việc xảy ra sớm, nhanh, dễ hoặc thuận lợi: 她来中国以前就学汉语了。不要两个小时，一个小时就到了。她吃了两片药就好了。我早就下班了。\n才 – sự việc vừa mới xảy ra trước đó không lâu: 我才到家。她才来半年就已经说得不错了。\n才 – sự việc xảy ra muộn, chậm, không dễ dàng hoặc không thuận lợi: 他十点钟才起床。八点上课，她八点半才来。你怎么现在才来？我才会用筷子吃饭。","s":"HSK2_28#43"}],"w_28_22":[{"c":"ngu_phap","t":"要是……(的话)，就……: giả thiết – kết quả","x":"要是……(的话)，就…… nối câu phức, biểu thị quan hệ giả thiết – kết quả.\n要是你来，就给我打个电话，我去车站接你。\n要是想家，就给妈妈打个电话。\n要是你去，我就去。","s":"HSK2_28#44"}],"w_28_24":[{"c":"ngu_phap","t":"虽然……但是……: Mặc dù… nhưng…","x":"虽然……但是…… nối hai vế, biểu thị quan hệ chuyển hướng. 但是 có thể dùng riêng lẻ.\n他虽然学的时间不长，但是说得很不错。\n外边虽然很冷，但是屋子里很暖和。\n我也想家，但是我不感到寂寞。","s":"HSK2_28#45"}],"w_29_1":[{"c":"cau_vi_du","t":"Ví dụ cho 考试","x":"因为昨天的考试结果很好，所以他很开心。 — Vì kết quả bài thi hôm qua rất tốt nên anh ấy rất vui.","s":"HSK2_29#4"}],"w_29_4":[{"c":"tu_mo_rong","t":"完成: hoàn thành","x":"完成 (wánchéng – động từ): Hoàn thành.\n你已经完成今天的作业了吗？ — Bạn đã hoàn thành bài tập hôm nay chưa?","s":"HSK2_29#7"}],"w_29_6":[{"c":"chiet_tu","t":"Chiết tự 绩 + ví dụ","x":"绩 – Bộ thành phần: 纟 Mịch + 责 Trách (trách nhiệm).\n这次HSK考试，他的成绩很好。 — Kỳ thi HSK lần này điểm của anh ấy rất tốt.\n考试成绩什么时候出来？ — Khi nào thì có điểm thi?","s":"HSK2_29#8"}],"w_29_8":[{"c":"ngu_am","t":"干 gàn (làm) và gān (khô)","x":"你正在干什么呢？ — Bạn đang làm gì thế? (= 你在做什么？)\nĐọc thanh 1 – gān: Khô, cạn (tính từ/phó từ) — 衣服已经干了。(Quần áo đã khô rồi.)","s":"HSK2_29#10"}],"w_29_14":[{"c":"cau_vi_du","t":"Thêm ví dụ với 有意思","x":"他的故事都很有意思。 — Những câu chuyện của anh ấy đều rất thú vị.","s":"HSK2_29#15"}],"w_29_16":[{"c":"chiet_tu","t":"Chiết tự 笑 + ví dụ","x":"Bộ thành phần: ⺮ Trúc + 夭 Yểu.\n她笑得很开心。 — Cô ấy cười rất vui.","s":"HSK2_29#17"}],"w_29_17":[{"c":"cach_dung","t":"Phân biệt 于是 và 所以","x":"于是 (yúshì): Nối hai vế câu hoặc hai câu, vế sau là kết quả tự nhiên hoặc hành động nối tiếp ngay sau sự việc ở vế trước. Ngoài quan hệ nhân quả, 于是 nhấn mạnh tính nối tiếp về thời gian. 于是 không đi với 因为.\n所以 (suǒyǐ): Nhấn mạnh thuần túy quan hệ nhân quả logic, thường đi thành cặp 因为……所以…….","s":"HSK2_29#18"}],"w_29_19":[{"c":"cau_vi_du","t":"Ví dụ 会话 với 于是","x":"我想练口语，于是天天听汉语会话。 — Tôi muốn luyện nói, thế là ngày nào cũng nghe hội thoại tiếng Trung.","s":"HSK2_29#20"}],"w_29_20":[{"c":"tu_mo_rong","t":"回答 và 答题","x":"回答 (huídá – động từ/danh từ): Trả lời, hồi đáp — 请同学们回答这个问题。\n答题 (dá tí – động từ ly hợp): Trả lời câu hỏi, làm bài thi.","s":"HSK2_29#21"}],"w_29_21":[{"c":"cach_dung","t":"最好: 2 cách dùng","x":"Đưa ra lời khuyên (Tốt nhất là… / Nên…): 生病了，你最好去医院看看。\nChỉ cái tốt nhất / hay nhất: 谁是你最好的朋友？(Ai là người bạn tốt nhất của bạn?)","s":"HSK2_29#22"}],"w_29_22":[{"c":"cau_vi_du","t":"有办法 / 没办法","x":"别哭，我有办法。 — Đừng khóc, tớ có cách rồi.\n他不想去医院，我也没办法。 — Anh ấy không muốn đi bệnh viện, tôi cũng đành chịu.","s":"HSK2_29#23"}],"w_29_23":[{"c":"cach_dung","t":"Giải thích 合 + 上","x":"合 (hé – động từ): Khép lại, gập lại.\n上 (shang – bổ ngữ kết quả): Biểu thị hai bề mặt tiếp xúc, đóng chặt lại với nhau.","s":"HSK2_29#24"}],"w_29_24":[{"c":"cach_dung","t":"打开 và các cặp trái nghĩa","x":"打开: Mở sách, mở cửa, mở quà, hoặc bật thiết bị điện tử (điện thoại, máy tính, tivi, đèn…).\n请同学们打开书。 — Mời các em mở sách ra.\n打开书 (mở sách) >< 合上书 (gập sách)\n打开门 (mở cửa) >< 关上门 (đóng cửa)\n打开电视 (bật tivi) >< 关掉电视 (tắt tivi)","s":"HSK2_29#25"}],"w_29_26":[{"c":"chiet_tu","t":"Chiết tự 熟 + 2 nghĩa","x":"Bộ thành phần: 孰 Thục + 灬 Hỏa.\n1. Chín (đồ ăn đã nấu chín, trái cây đã chín): 米饭已经熟了。\n2. Quen thuộc, biết rõ (người, con đường, từ vựng…): 我和他是好朋友，我们很熟。","s":"HSK2_29#27"}],"w_29_5":[{"c":"ngu_phap","t":"Bổ ngữ kết quả 成","x":"Biểu thị động tác khiến sự vật này trở thành sự vật khác; kết quả có thể tốt hoặc không tốt.\n这篇课文，老师要我们改成叙述体。\n“是不是”，他总说成“四不四”。\n这是个“我”字，你写成“找”字了。","s":"HSK2_29#32"}],"w_30_1":[{"c":"cau_vi_du","t":"生活 làm động từ","x":"我在中国生活了两年。 — Tôi đã sống ở Trung Quốc được hai năm rồi.","s":"HSK2_30#5"}],"w_30_2":[{"c":"cach_dung","t":"差不多: 2 cách dùng","x":"差不多 + thời gian / số lượng (xấp xỉ, khoảng): 我在中国生活了差不多两年。(Tôi đã sống ở Trung Quốc khoảng hai năm rồi.)\n差不多 + động từ (gần như): 今天的汉语作业，我差不多做完了。(Bài tập tiếng Trung hôm nay tớ gần như làm xong rồi.)","s":"HSK2_30#6"}],"w_30_3":[{"c":"cach_dung","t":"习惯: danh từ và động từ","x":"Danh từ (thói quen): 每天早起是一个好习惯。\nĐộng từ (quen với, thích nghi với): 我已经习惯这里的生活了。(Tôi đã quen với cuộc sống ở đây rồi.)","s":"HSK2_30#7"}],"w_30_4":[{"c":"cau_vi_du","t":"Ví dụ cho 气候","x":"我不太喜欢这里的气候。 — Tôi không thích khí hậu ở đây lắm.","s":"HSK2_30#8"}],"w_30_7":[{"c":"cach_dung","t":"Lượng từ của 菜 là 道","x":"Lượng từ đi kèm: 道 (dào).\n今天妈妈做了三道菜。 — Hôm nay mẹ đã nấu ba món ăn.","s":"HSK2_30#11"}],"w_30_8":[{"c":"tu_mo_rong","t":"油, 加油 và 腻","x":"油 Yóu (danh từ/tính từ): Dầu, dầu mỡ => 加油: Đổ xăng / Cố lên.\n腻 Nì (tính từ): Ngấy — 这道菜太腻了。(Món này ngấy quá.)","s":"HSK2_30#12"}],"w_30_9":[{"c":"tu_mo_rong","t":"奶茶: trà sữa","x":"奶茶: Trà sữa","s":"HSK2_30#13"}],"w_30_10":[{"c":"cach_dung","t":"不过 ~ 但是 nhưng nhẹ nhàng hơn","x":"不过 (liên từ): Nhưng, tuy nhiên, có điều… ~ 但是 (dànshì) nhưng sắc thái nhẹ nhàng, uyển chuyển hơn.","s":"HSK2_30#14"}],"w_30_11":[{"c":"cau_vi_du","t":"Ví dụ cho 课间","x":"课间只有十分钟。 — Giờ ra chơi chỉ có 10 phút thôi.","s":"HSK2_30#15"}],"w_30_14":[{"c":"cach_dung","t":"从来 phải đi với 不 / 没","x":"从来 bắt buộc đi kèm 不 (bù) hoặc 没 (méi) phía sau.\n从来 + 不 + động từ: 我从来不吃肉，只喜欢吃菜。\n从来 + 没 + động từ: 我从来没听到这个故事。(Từ trước đến nay tôi chưa từng nghe câu chuyện này.)","s":"HSK2_30#17"}],"w_30_18":[{"c":"cach_dung","t":"做 / 复习 + 功课","x":"做 (zuò – làm) hoặc 复习 (fùxí – ôn tập) + 功课.","s":"HSK2_30#21"}],"w_30_21":[{"c":"cach_dung","t":"一般: phó từ và tính từ","x":"Phó từ (thường, thông thường, theo thói quen): 晚饭我一般只吃菜，不吃肉。\nTính từ (bình thường, tàm tạm): 我的汉语水平很一般，还有很多新词没有记住。(Trình độ tiếng Trung của tôi rất bình thường, vẫn còn nhiều từ mới chưa nhớ.)","s":"HSK2_30#23"}],"w_30_24":[{"c":"cau_vi_du","t":"Thêm ví dụ với 机会","x":"请再给我一个机会。 — Xin hãy cho tôi thêm một cơ hội nữa.","s":"HSK2_30#25"}],"w_30_25":[{"c":"cach_dung","t":"原来: 2 nghĩa","x":"Phó từ (hóa ra, té ra): 房间这么干净，原来是妈妈打扫过了。\nTính từ/danh từ (ban đầu, trước đây): 原来我不喜欢游泳，现在很喜欢。(Trước đây tôi không thích bơi, bây giờ lại rất thích.)","s":"HSK2_30#26"}],"w_30_29":[{"c":"cau_vi_du","t":"Ví dụ cho 不一定","x":"A：贵的东西就很好吗？——B：不一定。 — Đồ đắt tiền thì đều tốt sao? – Chưa chắc / Không hẳn đâu.","s":"HSK2_30#29"}],"w_30_30":[{"c":"cach_dung","t":"钟头 ~ 小时 (khẩu ngữ)","x":"Số từ + 个 + 钟头 ~ 小时 (xiǎoshí). Tuy nhiên, 钟头 mang sắc thái khẩu ngữ.","s":"HSK2_30#30"}],"w_30_32":[{"c":"cach_dung","t":"挺……的 ~ 很 / 非常","x":"挺 + …… + 的 ~ 很 / 非常.\n这道菜挺好吃的，有一点儿腻，不过我很喜欢。","s":"HSK2_30#32"}],"w_30_33":[{"c":"cach_dung","t":"必须: mức độ bắt buộc cao hơn 要","x":"必须 có mức độ bắt buộc cao hơn 要.\n明天有大考试，你今天晚上必须复习功课。","s":"HSK2_30#33"}],"w_30_34":[{"c":"tu_mo_rong","t":"处 (nơi chốn); 对身体有好处","x":"处 (chù – danh từ): Nơi, chỗ, địa điểm.\n每天早睡早起对身体有很多好处。 — Ngủ sớm dậy sớm mỗi ngày có rất nhiều lợi ích cho sức khỏe.","s":"HSK2_30#34"}],"w_30_36":[{"c":"cau_vi_du","t":"Ví dụ cho 打鱼","x":"他这次打了一条很大的鱼。 — Lần này anh ấy đã bắt được một con cá rất lớn.","s":"HSK2_30#35"}],"w_31_1":[{"c":"chiet_tu","t":"Chiết tự 变","x":"Bộ thành phần: 亠 Chấm đầu + 八 Bát + 二 Nhị + 又 Hựu.","s":"HSK3_01#5"}],"w_31_3":[{"c":"chiet_tu","t":"Chiết tự 暑 và 假 (暑假)","x":"暑 (shǔ – danh từ/tính từ) – Hán Việt: Thử (nắng nóng/mùa hè).\nBộ thành phần: 日 Nhật + 者 Giả (耂 Lão + 日 Nhật).\n假 (jià – danh từ): kỳ nghỉ.\nBộ thành phần: 亻 Nhân đứng + 尸 Thi (thi thể) + 二 Nhị + 又 Hựu.","s":"HSK3_01#6"},{"c":"cau_vi_du","t":"Ví dụ 请假 / 暑假","x":"你想请几天假？— Bạn muốn xin nghỉ mấy ngày phép?\n我今天有点不舒服，想请病假。— Hôm nay tôi hơi mệt, muốn xin nghỉ.\n今年的暑假你打算去哪里（去哪儿）旅行？— Kỳ nghỉ hè năm nay bạn dự định đi đâu du lịch?","s":"HSK3_01#6"},{"c":"tu_mo_rong","t":"Từ mở rộng với 假","x":"请假 (động từ ly hợp): xin nghỉ\n放暑假 (fàng shǔjià – động từ ly hợp): nghỉ hè","s":"HSK3_01#7"}],"w_31_6":[{"c":"cach_dung","t":"最 + tính từ","x":"最高、最好、最难、……\n最近？","s":"HSK3_01#10"}],"w_31_7":[{"c":"chiet_tu","t":"Chiết tự 城","x":"Bộ thành phần: 土 Thổ + 成 Thành.","s":"HSK3_01#11"},{"c":"tu_mo_rong","t":"胡志明市","x":"胡志明 (Hú Zhìmíng): Hồ Chí Minh","s":"HSK3_01#11"}],"w_31_9":[{"c":"chiet_tu","t":"Chiết tự 建 và 筑 (建筑)","x":"建 (jiàn) – Kiến (xây dựng).\nBộ thành phần: 廴 Dẫn + 聿 Duật (bút).\n筑 (zhù) – Trúc (xây dựng).\nBộ thành phần: ⺮ Trúc + 工 Công + 凡 Phàm (tầm thường/bình thường).","s":"HSK3_01#13"},{"c":"tu_mo_rong","t":"Từ mở rộng","x":"建筑师: kiến trúc sư","s":"HSK3_01#14"}],"w_31_11":[{"c":"cach_dung","t":"Cấu trúc 更 + tính từ","x":"更 + tính từ: hơn, càng …","s":"HSK3_01#16"}],"w_31_13":[{"c":"tu_mo_rong","t":"Bốn mùa","x":"一年有四季 (jì – mùa): 1 năm có 4 mùa\n春夏秋冬 (chūn xià qiū dōng): xuân hạ thu đông","s":"HSK3_01#18"}],"w_31_15":[{"c":"cach_dung","t":"可是 = 但是; 虽然……可是……","x":"可是 = 但是.\n虽然 (suīrán)……，但是/可是……: Mặc dù …, nhưng …\n他虽然很好，可是（但是）我不喜欢他。","s":"HSK3_01#20"}],"w_31_18":[{"c":"tu_mo_rong","t":"天气预报","x":"天气预报: dự báo thời tiết","s":"HSK3_01#23"}],"w_31_19":[{"c":"tu_mo_rong","t":"Từ mở rộng","x":"低 (dī): thấp","s":"HSK3_01#24"}],"w_31_22":[{"c":"cach_dung","t":"屋子 ≈ 房间","x":"屋子 ≈ 房间 (phòng)","s":"HSK3_01#27"}],"w_31_23":[{"c":"cau_vi_du","t":"Ví dụ 感觉 (danh từ)","x":"跟我说你的感觉吧！— Nói cho tôi biết cảm giác của bạn đi!","s":"HSK3_01#28"}],"w_31_24":[{"c":"chiet_tu","t":"Chiết tự 庭","x":"Bộ thành phần: 广 Quảng + 廷 Đình.","s":"HSK3_01#29"}],"w_31_25":[{"c":"cach_dung","t":"Lượng từ và từ gần nghĩa của 旅馆","x":"Lượng từ đi kèm: 家.\n~酒店 (jiǔdiàn): khách sạn (thường sẽ lớn và sang trọng hơn 旅馆).","s":"HSK3_01#30"}],"w_31_26":[{"c":"cach_dung","t":"Lượng từ và từ gần nghĩa của 饭店","x":"Lượng từ đi kèm: 家.\n~饭馆","s":"HSK3_01#31"}],"w_31_27":[{"c":"cach_dung","t":"Hai nghĩa của 迷","x":"Danh từ: người đam mê, hâm mộ (… + 迷), ví dụ 足球迷.\nĐộng từ: lạc (đường): 我常迷路。— Tôi thường xuyên lạc đường.","s":"HSK3_01#32"}],"w_31_28":[{"c":"cach_dung","t":"Cách dùng 光","x":"光 + động từ: chỉ làm việc gì đó mà không làm việc khác – 光说不做: chỉ nói không làm.\n光 + danh từ: chỉ riêng đối tượng nào đó.","s":"HSK3_01#33"}],"w_31_29":[{"c":"cach_dung","t":"Sắc thái của 也许","x":"Có lẽ, có thể: thể hiện sự suy đoán, phỏng đoán sự việc không chắc chắn, có thể sẽ xảy ra trong tương lai.\n≈ 可能（有可能）","s":"HSK3_01#34"}],"w_31_32":[{"c":"tu_mo_rong","t":"Từ mở rộng với 世界","x":"世界杯 (shìjièbēi): World Cup\n全世界: toàn thế giới/cả thế giới","s":"HSK3_01#36"}],"w_31_34":[{"c":"tu_mo_rong","t":"Từ mở rộng với 歌","x":"歌 (gē – danh từ): ca (bài hát)\n唱歌 (chàng gē – động từ ly hợp): hát (bài hát)","s":"HSK3_01#38"}],"w_31_35":[{"c":"cach_dung","t":"歌 = 歌曲","x":"歌 = 歌曲.\nLượng từ đi kèm: 首 (shǒu).","s":"HSK3_01#39"}],"w_31_38":[{"c":"tu_mo_rong","t":"Từ trái nghĩa","x":"老年人: người già (>< 年轻人)","s":"HSK3_01#41"}],"w_32_1":[{"c":"cau_vi_du","t":"Ví dụ 国家","x":"越南是一个发展很快的国家。— Việt Nam là một quốc gia phát triển rất nhanh.","s":"HSK3_02#4"},{"c":"tu_mo_rong","t":"Từ mở rộng","x":"发展 (fāzhǎn – danh từ/động từ): phát triển","s":"HSK3_02#4"}],"w_32_5":[{"c":"cau_vi_du","t":"Ví dụ 半夜","x":"都半夜了，你怎么还没睡觉？— Đã nửa đêm rồi, bạn sao mà vẫn chưa ngủ?","s":"HSK3_02#6"},{"c":"tu_mo_rong","t":"Từ mở rộng với 夜","x":"夜里 = 夜晚: buổi đêm\n半夜: nửa đêm","s":"HSK3_02#6"}],"w_32_7":[{"c":"cau_vi_du","t":"Ví dụ 春节","x":"今年的春节你打算怎么过？回家还是跟朋友去旅行？— Tết năm nay bạn định đón như thế nào? Về nhà hay là đi du lịch với bạn bè?","s":"HSK3_02#8"},{"c":"tu_mo_rong","t":"春节","x":"春节: Tết ta, Tết âm lịch, Tết Nguyên Đán","s":"HSK3_02#8"}],"w_32_12":[{"c":"tu_mo_rong","t":"Từ mở rộng","x":"刮 (guā – động từ): cạo, gọt","s":"HSK3_02#11"}],"w_32_14":[{"c":"cau_vi_du","t":"Ví dụ 下雨 / 下雪","x":"下雨了！你带雨伞吗？— Trời mưa rồi! Bạn đem theo ô không?\n外面（下）雪下得很大。— Bên ngoài tuyết rơi rất lớn.","s":"HSK3_02#12"},{"c":"tu_mo_rong","t":"下雪","x":"下雪 (động từ ly hợp): tuyết rơi","s":"HSK3_02#12"}],"w_32_16":[{"c":"cach_dung","t":"得病 = 生病","x":"得病 = 生病 (mắc bệnh)\n医生，您帮我看一下我是不是得了什么病了？最近觉得不舒服。— Bác sĩ khám giúp tôi xem có phải tôi mắc bệnh gì rồi không? Gần đây cảm thấy không khỏe.","s":"HSK3_02#14"}],"w_32_19":[{"c":"cach_dung","t":"周 = 星期","x":"周 = 星期\n周一（星期一）；周二（星期二）；……；周日/周天（星期天/日）","s":"HSK3_02#15"}],"w_32_22":[{"c":"cach_dung","t":"对……产生兴趣","x":"对……产生兴趣: nảy sinh hứng thú với …","s":"HSK3_02#16"}],"w_32_23":[{"c":"chiet_tu","t":"Chữ 册","x":"册: chữ tượng hình mô tả các thẻ tre được xâu lại với nhau làm sổ viết ngày xưa.","s":"HSK3_02#17"}],"w_32_24":[{"c":"chiet_tu","t":"Chiết tự 研 và 究 (研究)","x":"研 – Bộ thành phần: 石 Thạch (đá) + 开 Khai.\n究 – Bộ thành phần: 宀 Miên + 八 Bát + 九 Cửu.","s":"HSK3_02#18"},{"c":"tu_mo_rong","t":"Từ mở rộng","x":"研究生: nghiên cứu sinh","s":"HSK3_02#18"}],"w_32_27":[{"c":"tu_mo_rong","t":"改革开放","x":"改革开放 (gǎigé kāifàng): cải cách mở cửa","s":"HSK3_02#19"}],"w_33_1":[{"c":"cach_dung","t":"爱 + động từ","x":"爱 + động từ: thích làm gì.","s":"HSK3_03#5"},{"c":"tu_mo_rong","t":"Từ mở rộng","x":"爱情 (danh từ): tình yêu","s":"HSK3_03#5"}],"w_33_3":[{"c":"chiet_tu","t":"Chiết tự 滑","x":"Bộ thành phần: 氵 3 chấm thủy + 骨 Cốt (xương cốt).","s":"HSK3_03#6"},{"c":"cach_dung","t":"Từ loại của 滑","x":"Tính từ: trơn trượt; động từ: lướt/trượt.","s":"HSK3_03#6"}],"w_33_5":[{"c":"cau_vi_du","t":"Ví dụ 滑雪","x":"我弟弟滑雪滑得比我快。— Em trai tôi trượt tuyết nhanh hơn tôi.","s":"HSK3_03#7"}],"w_33_6":[{"c":"tu_mo_rong","t":"Từ gần nghĩa","x":"≈ 老家 (danh từ): quê nhà","s":"HSK3_03#8"}],"w_33_7":[{"c":"cach_dung","t":"有名 ≈ 很火","x":"有名 ≈ 很火","s":"HSK3_03#9"}],"w_33_9":[{"c":"tu_mo_rong","t":"Từ mở rộng với 区","x":"风景区（景区）: khu danh lam thắng cảnh, khu du lịch\n旅游区: khu du lịch","s":"HSK3_03#10"}],"w_33_10":[{"c":"cach_dung","t":"旅游 ≈ 旅行","x":"旅游 ≈ 旅行\n这个景区的风景很迷人。— Phong cảnh của khu du lịch này rất mê người.","s":"HSK3_03#11"}],"w_33_11":[{"c":"cach_dung","t":"尤其是 ≈ 特别是","x":"尤其是 ≈ 特别是\n我觉得中文很难，尤其是（特别是）汉字。— Tôi cảm thấy tiếng Trung rất khó, đặc biệt là Hán tự.","s":"HSK3_03#12"}],"w_33_13":[{"c":"chiet_tu","t":"Chiết tự 避","x":"避 (bì – động từ): né, tránh.\nBộ thành phần: 辶 Quai xước + 尸 Thi (thi thể) + 口 Khẩu + 立 Lập + 十 Thập.","s":"HSK3_03#14"},{"c":"cau_vi_du","t":"Ví dụ 避","x":"下雨了，忘带了伞。咱们快找一个地方避一下雨吧！— Trời mưa rồi, quên mang theo ô. Chúng ta nhanh tìm chỗ để tránh mưa đi.","s":"HSK3_03#14"}],"w_33_15":[{"c":"chiet_tu","t":"Chiết tự 靠","x":"Bộ thành phần: 告 Cáo (nói) + 非 Phi.","s":"HSK3_03#16"},{"c":"cau_vi_du","t":"Ví dụ 靠山","x":"一个人最大的靠山就是自己。— Chỗ dựa lớn nhất của 1 người chính là bản thân.","s":"HSK3_03#16"}],"w_33_16":[{"c":"cau_vi_du","t":"Ví dụ 经营","x":"这家公司经营得很好。— Công ty này kinh doanh rất tốt.","s":"HSK3_03#17"}],"w_33_17":[{"c":"cau_vi_du","t":"Ví dụ 发财","x":"很多人家靠经营旅馆发大财。— Rất nhiều gia đình nhờ kinh doanh nhà nghỉ/khách sạn mà phát tài lớn.","s":"HSK3_03#18"}],"w_33_24":[{"c":"cau_vi_du","t":"Ví dụ 急","x":"有一件急事，快来帮帮我。— Có 1 việc gấp, nhanh đến giúp tôi.","s":"HSK3_03#22"},{"c":"tu_mo_rong","t":"Từ mở rộng","x":"急 (jí – tính từ): cấp (cấp bách)","s":"HSK3_03#22"}],"w_33_26":[{"c":"tu_mo_rong","t":"Từ mở rộng với 表","x":"手表: đồng hồ đeo tay\n课表: thời khóa biểu","s":"HSK3_03#24"}],"w_33_27":[{"c":"cau_vi_du","t":"Ví dụ 坏 (xấu)","x":"我觉得他不是坏人。— Tôi cảm thấy anh ấy không phải là người xấu.","s":"HSK3_03#25"}],"w_33_32":[{"c":"tu_mo_rong","t":"Từ mở rộng","x":"水池: hồ nước","s":"HSK3_03#28"}],"w_33_33":[{"c":"cach_dung","t":"Phân biệt 迟/晚, 迟到/来晚","x":"迟 (chí – tính từ): trễ, muộn: 你怎么来得这么迟？— Sao bạn lại tới muộn như vậy?\n迟: muộn – quá mốc thời gian quy định (đi học, đi làm, họp hành,… bối cảnh trang trọng).\n晚: muộn – ý kiến chủ quan (ví dụ như ăn tối lúc 8h là muộn, mà 9h cũng là muộn).\n迟到: đến muộn – so với quy định, bối cảnh trang trọng.\n来晚: đến muộn – so với kỳ vọng, sắc thái nhẹ hơn: 不好意思，我来晚了，让大家久等了。","s":"HSK3_03#29"}],"w_33_34":[{"c":"cach_dung","t":"Cách dùng 啦","x":"Là sự kết hợp của 了 (le) và 啊 (a). Biểu thị sự khẳng định hoặc cảm thán.","s":"HSK3_03#30"}],"w_33_35":[{"c":"cach_dung","t":"母亲 / 父亲","x":"Đây là cách gọi trang trọng hơn so với 爸爸 và 妈妈. Thường dùng trong văn viết hoặc khi giới thiệu chính thức.","s":"HSK3_03#31"}],"w_33_38":[{"c":"cach_dung","t":"跟/和 + ai + 结婚（离婚）","x":"跟/和 + ai + 结婚（离婚）\n我和女朋友打算明年结婚。— Tôi và bạn gái dự định năm sau kết hôn.","s":"HSK3_03#33"}],"w_33_42":[{"c":"cach_dung","t":"将来 ≈ 未来","x":"将来 ≈ 未来\n我将来（未来）想当医生。— Tương lai tôi sẽ làm bác sĩ.","s":"HSK3_03#35"}],"w_33_43":[{"c":"cau_vi_du","t":"Ví dụ 这样","x":"你不要这样吧！— Bạn đừng như vậy chứ!","s":"HSK3_03#36"}],"w_34_1":[{"c":"cach_dung","t":"送（给）+ người + vật","x":"送（给）+ người + vật: tặng ai cái gì.","s":"HSK3_04#5"},{"c":"cau_vi_du","t":"Ví dụ 送 (tiễn)","x":"明天我会送你到机场。— Ngày mai tôi sẽ tiễn bạn đến sân bay.","s":"HSK3_04#5"}],"w_34_2":[{"c":"tu_mo_rong","t":"Cụm từ kết hợp với 开","x":"开车\n开学\n开药","s":"HSK3_04#6"}],"w_34_4":[{"c":"cach_dung","t":"研讨 = 研究 + 讨论","x":"研讨 = 研究 (yánjiū: nghiên cứu) và 讨论 (tǎolùn: thảo luận/trao đổi)","s":"HSK3_04#7"}],"w_34_6":[{"c":"cau_vi_du","t":"Ví dụ 经过 (trải qua)","x":"经过半个小时，我们到了公园。— Qua nửa tiếng, chúng tôi đã đến công viên.","s":"HSK3_04#8"}],"w_34_7":[{"c":"cach_dung","t":"Hai cách dùng của 向","x":"向 + phương hướng + động từ: làm gì về hướng nào; 向 ≈ 往.\n向 + người (đối tượng) + động từ: người là đối tượng của động từ phía sau.\n向他学习: học hỏi anh ấy\n向老师请假: xin thầy nghỉ","s":"HSK3_04#9"}],"w_34_12":[{"c":"cach_dung","t":"Phân biệt 门 và 门口","x":"门: cái cửa (vật thể); động từ đi kèm: đóng, mở, sửa, khóa – 你关门了吗？— Bạn đóng cửa chưa?\n门口: cửa, cổng, lối vào (không gian); động từ đi kèm: đứng, đợi, đỗ xe, gặp nhau.","s":"HSK3_04#13"}],"w_34_13":[{"c":"cach_dung","t":"辛苦你了！","x":"辛苦你了！– thường dùng để cảm ơn hoặc an ủi người khác đã giúp đỡ mình.","s":"HSK3_04#14"}],"w_34_14":[{"c":"cach_dung","t":"Phân biệt 麻烦 và 烦","x":"麻烦 (tính từ): rắc rối, phiền phức (tính chất của sự việc): 我觉得这件事比较麻烦，要慢慢做。— Tôi cảm thấy việc này khá rắc rối, cần làm từ từ.\n麻烦 (động từ): làm phiền (nhờ vả): 麻烦你帮我办一件事，可以吗？— Làm phiền bạn làm giúp tôi 1 việc, được không?\n烦 (tính từ): phiền muộn, khó chịu (tâm trạng của người): 最近因为工作不顺，所以心里有点烦。— Gần đây vì công việc không thuận lợi, nên trong lòng hơi phiền muộn.\n烦 (động từ): làm phiền (quấy rầy): 别烦我，我现在很累。— Đừng làm phiền tôi, tôi đang rất mệt.","s":"HSK3_04#16"}],"w_34_15":[{"c":"cach_dung","t":"跑一趟","x":"跑一趟: đi một chuyến hoặc cất công đi một lần.","s":"HSK3_04#17"}],"w_34_16":[{"c":"cach_dung","t":"Lưu ý về 爱人","x":"Trong tiếng Trung hiện đại, từ này dùng để chỉ người đã kết hôn (vợ/chồng), không phải “người yêu”.","s":"HSK3_04#18"}],"w_34_18":[{"c":"chiet_tu","t":"Mẹo nhớ 马上","x":"Đang ở trên (上) lưng ngựa (马) nên phải đi rất nhanh, ngay lập tức.","s":"HSK3_04#20"},{"c":"cach_dung","t":"Cách dùng 马上","x":"Có thể dùng độc lập thành 1 câu (thường là trong hội thoại): A：快点！车来了 B：马上！\n马上（+就/就要）+ động từ.","s":"HSK3_04#20"}],"w_34_19":[{"c":"cach_dung","t":"慢走","x":"慢走: lời nói khách khí khi tiễn khách.","s":"HSK3_04#38"}],"w_34_21":[{"c":"cau_vi_du","t":"Ví dụ 展览 (danh từ)","x":"我们打算举行一个艺术展览。— Chúng tôi dự định tổ chức 1 buổi triển lãm nghệ thuật.","s":"HSK3_04#22"}],"w_34_30":[{"c":"cach_dung","t":"大约 ≈ 大概","x":"大约 ≈ 大概","s":"HSK3_04#29"}],"w_34_31":[{"c":"cau_vi_du","t":"Ví dụ 要求 (động từ)","x":"妈妈要求我半个小时后回到家。— Mẹ yêu cầu tôi nửa tiếng sau về đến nhà.","s":"HSK3_04#30"}],"w_34_32":[{"c":"cau_vi_du","t":"Ví dụ 声","x":"你走的时候就跟我说一声吧。— Lúc bạn đi thì nói với tôi 1 tiếng nhé.","s":"HSK3_04#31"}],"w_34_34":[{"c":"cach_dung","t":"Cách dùng 师傅 trong khẩu ngữ","x":"Bác tài / Thợ / Sư phụ: trong khẩu ngữ hiện đại, thường dùng để gọi tài xế, thợ sửa chữa hoặc những người lao động có tay nghề một cách lịch sự.","s":"HSK3_04#33"}],"w_35_2":[{"c":"cach_dung","t":"过 làm động từ: qua, đi qua","x":"(Động từ) Qua/đi qua (hữu hình và vô hình):\n过马路: qua đường\n过节: đón lễ\n过年: đón Tết\n过 + bổ ngữ xu hướng: 过来；过去\n(Trợ từ động thái) Động từ + 过: đã từng làm gì (nhấn mạnh trải nghiệm).","s":"HSK3_05#6"}],"w_35_3":[{"c":"tu_mo_rong","t":"医院 / 出院","x":"医院 (yīyuàn – danh từ): y viện, bệnh viện\n出院 (chūyuàn – động từ ly hợp): xuất viện","s":"HSK3_05#7"}],"w_35_4":[{"c":"tu_mo_rong","t":"西医 / 中药 vs 西药","x":"西医: Tây y (y học phương Tây)\nSo sánh: 中药 (thuốc Đông y) vs 西药 (thuốc Tây)","s":"HSK3_05#8"}],"w_35_5":[{"c":"van_hoa","t":"良药苦口","x":"良药苦口 (liángyào kǔkǒu): Thuốc đắng dã tật.\nTừ liên quan cần nhớ: 辛苦?","s":"HSK3_05#9"}],"w_35_8":[{"c":"tu_mo_rong","t":"开药方","x":"开药方 (động từ ly hợp): kê đơn thuốc.","s":"HSK3_05#10"}],"w_35_12":[{"c":"chiet_tu","t":"Chiết tự 针 (zhēn)","x":"针 Zhēn (danh từ): kim, cây kim.\nBộ thành phần: Kim 钅 + Thập 十.","s":"HSK3_05#13"},{"c":"tu_mo_rong","t":"打针 – tiêm, chích","x":"打针 (dǎzhēn – động từ ly hợp): tiêm, chích\n我怕疼，所以不敢打针。 — Tôi sợ đau, nên tôi không dám tiêm.","s":"HSK3_05#13"}],"w_35_14":[{"c":"tu_mo_rong","t":"治病 / 生病 vs 有病","x":"治病 (động từ ly hợp): điều trị bệnh, chữa trị bệnh.\nPhân biệt: 生病 VS 有病.","s":"HSK3_05#15"}],"w_35_15":[{"c":"cach_dung","t":"扎针 khác 打针","x":"扎针: châm kim (phương pháp của châm cứu), khác với 打针 (tiêm).","s":"HSK3_05#16"}],"w_35_17":[{"c":"cach_dung","t":"曾经 + Động từ + (过); 已经 vs 曾经","x":"Cấu trúc: 曾经 + Động từ + (过).\n已经: nhấn mạnh hành động đã hoàn thành.\n曾经: nhấn mạnh trải nghiệm trong quá khứ.","s":"HSK3_05#18"}],"w_35_18":[{"c":"cach_dung","t":"Lượng từ của 烤鸭","x":"Lượng từ đi kèm: 只 (zhī): con (dùng cho động vật).","s":"HSK3_05#19"}],"w_35_19":[{"c":"chiet_tu","t":"Chiết tự 烤","x":"Bộ thành phần: Hỏa 火 + Khảo 考.","s":"HSK3_05#19"}],"w_35_20":[{"c":"cach_dung","t":"第 + Số từ + Lượng từ + Danh từ","x":"Thêm 第 vào trước số để biến số đếm thành số thứ tự: 第一次, 第五天, 第一个星期, 第四十一课.\nCấu trúc: 第 + Số từ + Lượng từ + Danh từ.\nĐôi khi số từ vốn đã chỉ thứ tự thì không cần thêm 第: 一月, 三楼, 四门.","s":"HSK3_05#20"}],"w_35_21":[{"c":"tu_mo_rong","t":"Các từ liên quan đến 餐","x":"中餐 (zhōngcān): món ăn Trung Hoa\n西餐 (xīcān): món ăn phương Tây\n早餐 = 早饭 (zǎocān = zǎofàn): bữa sáng\n午餐 = 午饭 (wǔcān = wǔfàn): bữa trưa\n晚餐 = 晚饭 (wǎncān = wǎnfàn): bữa tối\n快餐 (kuàicān): đồ ăn nhanh (fast food)\n餐厅 (cāntīng): nhà hàng, phòng ăn","s":"HSK3_05#21"}],"w_35_22":[{"c":"tu_mo_rong","t":"烤白薯 và các cách gọi khác của khoai lang","x":"烤白薯: khoai lang nướng.\nCác cách gọi khác của khoai lang: 红薯 (hóngshǔ); 地瓜 (dìguā).","s":"HSK3_05#22"}],"w_35_23":[{"c":"chiet_tu","t":"Chiết tự 糖","x":"Bộ thành phần: Mễ 米 + Đường 唐.","s":"HSK3_05#23"},{"c":"tu_mo_rong","t":"糖果","x":"糖果: kẹo.","s":"HSK3_05#23"}],"w_35_24":[{"c":"cau_vi_du","t":"Câu đáp với 糖葫芦","x":"都很甜，我不太喜欢吃。 — Đều rất ngọt, tôi không thích ăn lắm.","s":"HSK3_05#24"}],"w_35_25":[{"c":"cach_dung","t":"Cách dùng 什么的","x":"Đứng cuối một danh sách liệt kê để thay thế cho các sự vật cùng loại còn lại; tương tự 等等 (děngděng).","s":"HSK3_05#25"}],"w_35_26":[{"c":"cach_dung","t":"亲 + bộ phận cơ thể","x":"亲 (thân / tự mình) + cơ quan cơ thể: 亲眼看到 (tận mắt nhìn thấy), 亲手做 (tự tay làm).","s":"HSK3_05#26"}],"w_35_27":[{"c":"cau_vi_du","t":"Câu ví dụ với 弹钢琴","x":"他弹钢琴弹得很好听。 — Anh ấy chơi piano rất hay.","s":"HSK3_05#27"},{"c":"tu_mo_rong","t":"弹 / 弹琴 – đánh đàn","x":"弹 (tán – động từ): đánh/gảy đàn. Bộ thành phần: Cung 弓 + Đơn 单.\n弹琴 (tán qín – động từ ly hợp): đánh/gảy đàn.","s":"HSK3_05#27"}],"w_35_29":[{"c":"cach_dung","t":"演奏 + nhạc cụ/bản nhạc","x":"演奏 + nhạc cụ/bản nhạc.\n我不会演奏钢琴。 — Tôi không biết chơi piano.","s":"HSK3_05#28"}],"w_35_30":[{"c":"tu_mo_rong","t":"…家 chỉ chuyên gia","x":"…家 (hậu tố của danh từ): nhà… (chỉ chuyên gia, người am hiểu sâu).\n钢琴家 (gāngqínjiā): nghệ sĩ piano\n画家 (huàjiā): họa sĩ","s":"HSK3_05#29"}],"w_35_31":[{"c":"cau_vi_du","t":"Câu ví dụ với 极了","x":"这件事让我着急极了。 — Chuyện này làm tôi gấp gáp vô cùng.","s":"HSK3_05#30"}],"w_35_32":[{"c":"khac","t":"Phân tích 协奏曲","x":"协 (Hiệp – phối hợp), 奏 (Tấu – biểu diễn), 曲 (Khúc – bản nhạc).","s":"HSK3_05#31"}],"w_35_36":[{"c":"cach_dung","t":"Cách dùng 嘛","x":"Đứng cuối câu để biểu thị một sự việc là hiển nhiên, hoặc mang sắc thái làm nũng, thuyết phục.","s":"HSK3_05#33"}],"w_35_35":[{"c":"van_hoa","t":"好借好还，再借不难","x":"好借好还，再借不难: Mượn đúng lúc, trả đúng hạn, lần sau mượn lại chẳng khó khăn gì.","s":"HSK3_05#37"}],"w_35_37":[{"c":"van_hoa","t":"Cáp Nhĩ Tân","x":"Thành phố ở cực Bắc Trung Quốc, nổi tiếng với mùa đông rất lạnh.","s":"HSK3_05#34"}],"w_35_38":[{"c":"van_hoa","t":"Đảo Hải Nam","x":"Tỉnh đảo cực Nam, khí hậu nhiệt đới giống Việt Nam.","s":"HSK3_05#34"}],"w_35_39":[{"c":"van_hoa","t":"Thái Sơn","x":"Là ngọn núi đứng đầu trong “Ngũ Nhạc” của Trung Quốc. Trong tiếng Việt cũng có câu “Công cha như núi Thái Sơn”.","s":"HSK3_05#34"}],"w_35_40":[{"c":"van_hoa","t":"Tây An","x":"Cố đô nổi tiếng, nơi có đội quân đất nung (Binh mã dũng).","s":"HSK3_05#34"}],"w_35_41":[{"c":"van_hoa","t":"Đôn Hoàng","x":"Nổi tiếng với hang đá Mạc Cao và con đường tơ lụa.","s":"HSK3_05#34"}],"w_35_42":[{"c":"van_hoa","t":"Di Hòa Viên","x":"Là khu vườn hoàng gia lớn nhất và được bảo tồn tốt nhất ở Bắc Kinh.","s":"HSK3_05#35"}],"w_35_45":[{"c":"van_hoa","t":"Hoàng Hà – sông và bản hòa tấu","x":"Sông Hoàng Hà: con sông dài thứ 2 Trung Quốc, được coi là “dòng sông mẹ” của dân tộc Trung Hoa.\nBản hòa tấu piano 《黄河》 được coi là một kiệt tác kinh điển của nền âm nhạc Trung Quốc.","s":"HSK3_05#35"}],"w_35_46":[{"c":"van_hoa","t":"Lương Chúc","x":"Tên đầy đủ của tác phẩm là 《梁山伯与祝英台》 (Lương Sơn Bá và Chúc Anh Đài).","s":"HSK3_05#35"}],"w_36_3":[{"c":"chiet_tu","t":"Chiết tự 导 (dǎo)","x":"导 Dǎo: Đạo (chỉ đạo, hướng dẫn).\nBộ thành phần: Tị 巳 + Thốn 寸.","s":"HSK3_06#5"},{"c":"tu_mo_rong","t":"Từ ghép với 导 và lượng từ 名","x":"导师 (dǎoshī – danh từ): giáo viên hướng dẫn\n领导 (lǐngdǎo – danh từ/động từ): lãnh đạo, người lãnh đạo\nLượng từ đi kèm: 名 (dùng cho người, mang sắc thái trang trọng và khách quan).","s":"HSK3_06#5"}],"w_36_4":[{"c":"tu_mo_rong","t":"硕士研究生 / 博士研究生","x":"硕士研究生 (shuòshì yánjiūshēng): nghiên cứu sinh thạc sĩ\n博士研究生 (bóshì yánjiūshēng): nghiên cứu sinh tiến sĩ","s":"HSK3_06#6"}],"w_36_5":[{"c":"khac","t":"打工人 ~ 牛马","x":"打工人 ~ 牛马: cách nói vui chỉ người đi làm thuê.","s":"HSK3_06#7"}],"w_36_7":[{"c":"tu_mo_rong","t":"Những cụm từ liên quan đến 假","x":"请假, 放假, 暑假, 寒假","s":"HSK3_06#9"}],"w_36_9":[{"c":"cach_dung","t":"Từ gần nghĩa với 组织","x":"组织 ~ 举行、举办","s":"HSK3_06#11"}],"w_36_11":[{"c":"cau_vi_du","t":"需要 làm danh từ","x":"你有学习中文的需要吗？ — Bạn có nhu cầu học tiếng Trung không?","s":"HSK3_06#13"}],"w_36_12":[{"c":"cach_dung","t":"经常 ~ 常常","x":"经常 ~ 常常 (thường xuyên).","s":"HSK3_06#14"}],"w_36_15":[{"c":"cau_vi_du","t":"安排 làm danh từ","x":"我们都听你的安排。 — Chúng tôi đều nghe theo sự sắp xếp của bạn.","s":"HSK3_06#17"}],"w_36_16":[{"c":"cach_dung","t":"Phân biệt 帮 / 帮助 / 帮忙","x":"帮助 (danh từ): 我需要你的帮助。\n帮 / 帮助 (động từ): 你可以帮我去买一些东西吗？ 你经常帮助别人吗？\n帮忙 (động từ ly hợp): không trực tiếp mang tân ngữ phía sau, dùng 帮 + … + 忙: 你可以帮我一个忙吗？","s":"HSK3_06#19"}],"w_36_17":[{"c":"cau_vi_du","t":"希望 làm danh từ","x":"她已经成为我的希望。 — Cô ấy đã trở thành sự hy vọng của tôi.","s":"HSK3_06#20"},{"c":"tu_mo_rong","t":"失望","x":"失望 (shīwàng – danh từ/động từ): thất vọng.","s":"HSK3_06#20"}],"w_36_19":[{"c":"cach_dung","t":"Từ gần nghĩa","x":"风光 ~ 风景","s":"HSK3_06#21"}],"w_36_21":[{"c":"cach_dung","t":"Từ gần nghĩa","x":"故乡 ~ 老家、家乡","s":"HSK3_06#23"}],"w_36_24":[{"c":"cach_dung","t":"互相 + động từ","x":"互相 + động từ (thường là động từ 2 âm tiết): 互相帮助, 互相学习.","s":"HSK3_06#26"}],"w_36_25":[{"c":"van_hoa","t":"Cách gọi 老外","x":"老外 ~ 外国人. Người Trung Quốc thường gọi người nước ngoài là 老外.","s":"HSK3_06#35"}],"w_36_28":[{"c":"tu_mo_rong","t":"长发 >< 短发; 剪","x":"长发（长头发）>< 短发（短头发）\n剪 (jiǎn – động từ): cắt; 剪发: cắt tóc.","s":"HSK3_06#28"}],"w_36_29":[{"c":"ngu_am","t":"睛 đọc thanh nhẹ; phân biệt 眼镜","x":"Chữ 睛 trong 眼睛 đọc thanh nhẹ (jing).\nĐừng nhầm với 眼镜 (yǎnjìng – kính mắt).","s":"HSK3_06#29"}],"w_37_1":[{"c":"chiet_tu","t":"Chiết tự 放","x":"Bộ thành phần: Phương 方 + Phộc (roi) 攵.","s":"HSK3_07#5"},{"c":"tu_mo_rong","t":"放假","x":"放假 (động từ ly hợp): nghỉ lễ.","s":"HSK3_07#5"}],"w_37_2":[{"c":"tu_mo_rong","t":"半 – một nửa","x":"半: Bán (một nửa). 半年: nửa năm.\n我已经吃了半个苹果。 — Tôi đã ăn một nửa quả táo rồi.\n半天: diễn tả một khoảng thời gian rất lâu (đợi lâu, tìm lâu).","s":"HSK3_07#6"}],"w_37_4":[{"c":"chiet_tu","t":"Chiết tự 签证","x":"签 Qiān (động từ): ký. Bộ thành phần: Trúc ⺮ + Thiêm 佥.\n证: Chứng (chứng minh). Bộ thành phần: Ngôn 讠 + Chính 正.","s":"HSK3_07#8"},{"c":"tu_mo_rong","t":"签名 / 证明 / 办签证","x":"签名 (qiānmíng – động từ ly hợp): ký tên\n证明 (zhèngmíng – động từ): chứng minh\n办签证: làm/xin visa\nTừ liên quan cần nhớ: 过期?","s":"HSK3_07#8"}],"w_37_5":[{"c":"khac","t":"Phân tích 手提包","x":"手 (tay) + 提 (xách/nhấc) + 包 (túi/bao)","s":"HSK3_07#9"}],"w_37_6":[{"c":"tu_mo_rong","t":"交作业 / 交朋友","x":"交作业: nộp bài tập\n交朋友: kết bạn — 我们可以交朋友吗？ — Chúng ta có thể kết bạn được không?","s":"HSK3_07#10"}],"w_37_7":[{"c":"cach_dung","t":"好好儿 + Động từ","x":"好好儿 + Động từ: khuyên nhủ hoặc thể hiện quyết tâm làm việc gì đó một cách chu đáo.\n你再好好儿找找。 — Bạn tìm lại cẩn thận đi.","s":"HSK3_07#11"}],"w_37_9":[{"c":"chiet_tu","t":"Chiết tự 袋","x":"Bộ thành phần: Đại (đại diện/đại từ) 代 + Y 衣.","s":"HSK3_07#13"}],"w_37_10":[{"c":"cau_vi_du","t":"Câu ví dụ với 丢三落四","x":"他这个人总是丢三落四的，刚拿的钱包又找不到了。 — Cái anh này toàn quên trước quên sau, ví tiền vừa cầm đã không thấy đâu rồi.","s":"HSK3_07#14"}],"w_37_13":[{"c":"cau_vi_du","t":"Câu ví dụ với 发现","x":"我发现他今天不高兴。 — Tôi nhận ra hôm nay anh ấy không vui.","s":"HSK3_07#15"}],"w_37_14":[{"c":"tu_mo_rong","t":"… + 迷","x":"… + 迷: người đam mê/hâm mộ cái gì.\nTừ liên quan cần nhớ: 迷路?","s":"HSK3_07#16"}],"w_37_15":[{"c":"cach_dung","t":"可 + Động từ/Tính từ","x":"可 + Động từ/Tính từ: quả là, thật là / nhất định (dùng để nhấn mạnh).\n你可别忘了带护照。 — Bạn nhất định đừng quên mang theo hộ chiếu nhé.\n今天的天气可好了！ — Thời tiết hôm nay thật là đẹp!\n这件事你可不能告诉别人。 — Chuyện này bạn tuyệt đối không được nói cho người khác.","s":"HSK3_07#17"}],"w_37_16":[{"c":"cach_dung","t":"Phân biệt 程度 và 水平","x":"程度: mức độ (tính trạng/trạng thái) — 难度 (mức độ khó).\n水平: trình độ (có thang đo) — 汉语水平, 生活水平.","s":"HSK3_07#18"}],"w_37_17":[{"c":"cach_dung","t":"Cấu trúc với 为了; phân biệt 为了 và 因为","x":"为了 + Mục đích, (Chủ ngữ) + Hành động.\n(Chủ ngữ) + Hành động + 是为了 + Mục đích: 他来学校是为了找老师。 — Anh ấy đến trường là để tìm thầy giáo.\n为了: để, vì — 为了 + mục đích.\n因为: vì, bởi vì — 因为 + nguyên nhân.","s":"HSK3_07#19"}],"w_37_18":[{"c":"cau_vi_du","t":"Câu ví dụ với 正常","x":"医生说他的身体很正常，不用担心。 — Bác sĩ nói sức khỏe của anh ấy rất bình thường, không cần lo lắng.","s":"HSK3_07#20"}],"w_37_19":[{"c":"cau_vi_du","t":"Câu ví dụ với 承认","x":"承认: thừa nhận (sự thật hoặc lỗi lầm).\n虽然大家都看到了，但他还是不承认。 — Mặc dù mọi người đều nhìn thấy rồi, nhưng anh ấy vẫn không thừa nhận.","s":"HSK3_07#21"}],"w_37_20":[{"c":"chiet_tu","t":"Chiết tự 狂","x":"狂 (tính từ): điên, điên cuồng. Bộ thành phần: Khuyển 犭 + Vương 王.","s":"HSK3_07#22"},{"c":"cau_vi_du","t":"Câu ví dụ với 发狂","x":"有时候，他都迷到了发狂的程度。 — Có lúc, anh ấy đã mê đến mức phát cuồng.","s":"HSK3_07#22"}],"w_37_21":[{"c":"cach_dung","t":"Từ gần nghĩa","x":"锦标赛 ~ 比赛","s":"HSK3_07#23"}],"w_37_22":[{"c":"cau_vi_du","t":"Câu ví dụ với 期间","x":"他在北京期间，认识了很多朋友。 — Trong thời gian ở Bắc Kinh, anh ấy đã quen biết rất nhiều bạn bè.\n在这期间，他学到了很多东西。 — Trong giai đoạn này, anh ấy đã học được rất nhiều thứ.","s":"HSK3_07#24"}],"w_37_23":[{"c":"cach_dung","t":"A + 像 + B + 一样","x":"A + 像 + B + 一样 (+ Động từ/Tính từ).\n妹妹像妈妈爱唱歌。 — Em gái giống mẹ thích ca hát.\n今天像夏天一样热。 — Hôm nay nóng giống như mùa hè vậy.","s":"HSK3_07#25"}],"w_37_24":[{"c":"cau_vi_du","t":"Câu ví dụ với 生病","x":"我昨天生了病，所以不能上课。\nPhân biệt với: 有病?","s":"HSK3_07#26"}],"w_37_25":[{"c":"cach_dung","t":"Từ trái nghĩa","x":"白天 >< 晚上","s":"HSK3_07#27"}],"w_37_26":[{"c":"cau_vi_du","t":"Câu ví dụ với 精神","x":"睡了一觉以后，我感觉特别有精神。 — Sau khi ngủ một giấc, tôi cảm thấy tỉnh táo/có tinh thần hơn rồi.","s":"HSK3_07#28"}],"w_37_27":[{"c":"chiet_tu","t":"Chiết tự 贴","x":"Bộ thành phần: Bối 贝 + Chiếm 占.","s":"HSK3_07#29"}],"w_37_30":[{"c":"cau_vi_du","t":"Câu ví dụ với 营业","x":"本店因春节暂停营业。 — Cửa hàng tạm dừng kinh doanh vì dịp Tết.","s":"HSK3_07#31"}],"w_37_31":[{"c":"cau_vi_du","t":"Câu ví dụ với 够","x":"钱不够，我还差十块钱。 — Tiền không đủ, tôi còn thiếu 10 tệ nữa.\n够了！别说了。 — Đủ rồi! Đừng nói nữa.","s":"HSK3_07#32"}],"w_37_32":[{"c":"cau_vi_du","t":"Câu ví dụ với 算","x":"今天的考试不算难。 — Kỳ thi hôm nay không coi là khó (không đến nỗi khó).","s":"HSK3_07#33"}],"w_37_33":[{"c":"cau_vi_du","t":"Câu ví dụ với 多的是","x":"像他这样努力的人，多的是。 — Những người nỗ lực như anh ấy có rất nhiều.\n别担心，机会多的是。 — Đừng lo lắng, cơ hội không thiếu gì đâu.","s":"HSK3_07#34"}],"w_37_36":[{"c":"cach_dung","t":"准: tính từ và động từ","x":"Tính từ: chuẩn, chính xác — 他的发音很准。\nĐộng từ: cho phép — 这里不准抽烟 (chōuyān)。 — Ở đây không được phép hút thuốc.\n老师不准我们在教室里吃东西。 — Thầy giáo không cho phép chúng tôi ăn đồ ăn trong lớp.","s":"HSK3_07#37"}],"w_37_37":[{"c":"cau_vi_du","t":"Câu ví dụ với 辞职","x":"因为身体不好，他打算向公司辞职。 — Vì sức khỏe không tốt, anh ấy định xin nghỉ việc ở công ty.","s":"HSK3_07#38"}],"w_37_38":[{"c":"cau_vi_du","t":"Câu ví dụ với 最后","x":"经过半天的商量，我们最后决定去深圳。 — Sau nửa ngày bàn bạc, cuối cùng chúng tôi quyết định đi Thâm Quyến.","s":"HSK3_07#39"}],"w_37_39":[{"c":"tu_mo_rong","t":"成为","x":"成为 (chéngwéi): trở thành.","s":"HSK3_07#40"}],"w_37_41":[{"c":"cau_vi_du","t":"Câu ví dụ với 棒","x":"这次足球比赛他们踢得非常棒。 — Trận bóng đá lần này họ đá cực kỳ giỏi.","s":"HSK3_07#42"}],"w_38_2":[{"c":"chiet_tu","t":"Chiết tự 洗","x":"Bộ thành phần: Thủy 氵 + Tiên 先.","s":"HSK3_08#5"}],"w_38_3":[{"c":"chiet_tu","t":"Chiết tự 闭","x":"Bộ thành phần: Môn 门 + Tài 才.","s":"HSK3_08#6"}],"w_38_4":[{"c":"cach_dung","t":"Lượng từ của 油画","x":"Lượng từ đi kèm: 幅 (fú) hoặc 张 (zhāng).","s":"HSK3_08#7"}],"w_38_7":[{"c":"tu_mo_rong","t":"厘米 (límǐ)","x":"~ 厘米 (límǐ): cm, cách nói sử dụng phổ biến hơn 公分.","s":"HSK3_08#10"}],"w_38_9":[{"c":"chiet_tu","t":"Chiết tự 碰","x":"Bộ thành phần: Thạch 石 (hòn đá).","s":"HSK3_08#12"},{"c":"tu_mo_rong","t":"碰见","x":"碰见: tình cờ gặp. Ví dụ: 今天我在超市碰见了以前的同学。 — Hôm nay tôi tình cờ gặp bạn học cũ ở siêu thị.","s":"HSK3_08#12"}],"w_38_10":[{"c":"cach_dung","t":"Lượng từ 起","x":"Lượng từ của vụ án, tai nạn, sự cố (ví dụ trong bài: 一起交通事故).","s":"HSK3_08#13"}],"w_38_11":[{"c":"tu_mo_rong","t":"交通事故","x":"交通事故: tai nạn giao thông.","s":"HSK3_08#14"},{"c":"khac","t":"事故 và 故事","x":"Chú ý phân biệt 事故 với 故事 (hai chữ đảo vị trí).","s":"HSK3_08#14"}],"w_38_12":[{"c":"chiet_tu","t":"Chiết tự 整","x":"Bộ thành phần: Sắc 敕 + Chính 正.","s":"HSK3_08#15"},{"c":"cach_dung","t":"Cách dùng 整","x":"Đứng trước danh từ chỉ thời gian để nhấn mạnh khoảng thời gian đó diễn ra liên tục, không bị ngắt quãng.","s":"HSK3_08#15"},{"c":"tu_mo_rong","t":"整天 / 整夜 / 整整一年","x":"整天 (zhěngtiān): cả ngày; 整夜 (zhěngyè): cả đêm; 整整一年 (zhěngzhěng yī nián): trọn vẹn một năm.","s":"HSK3_08#15"}],"w_38_13":[{"c":"chiet_tu","t":"Chiết tự 镜","x":"Bộ thành phần: Kim 钅 + Cánh 竟.","s":"HSK3_08#16"},{"c":"tu_mo_rong","t":"照镜子 / 戴眼镜","x":"照镜子: soi gương; 戴眼镜 (dài yǎnjìng): đeo kính.","s":"HSK3_08#16"}],"w_38_14":[{"c":"cach_dung","t":"Cách dùng 别提了","x":"Câu cửa miệng dùng ở đầu câu khi người nói không muốn nhắc lại một trải nghiệm tồi tệ, xui xẻo hoặc phiền phức vì càng nghĩ càng bực mình. Biểu thị người hoặc sự vật làm người ta không hài lòng, không vui; có ngữ khí cảm thán. Ví dụ: A：你怎么了？B：嗨，别提了，昨天又拉肚子了。","s":"HSK3_08#17"}],"w_38_15":[{"c":"chiet_tu","t":"Chiết tự 倒霉","x":"倒 – Bộ thành phần: Nhân 亻 + Đáo 到; 霉 – Bộ thành phần: Vũ 雨 + Mỗi 每.","s":"HSK3_08#18"},{"c":"cau_vi_du","t":"Ví dụ 倒霉","x":"别生气了，谁都有倒霉的时候。 — Đừng tức giận, ai mà chẳng có lúc xui xẻo.","s":"HSK3_08#18"}],"w_38_16":[{"c":"chiet_tu","t":"Chiết tự 跤","x":"Bộ thành phần: Túc 足 + Giao 交.","s":"HSK3_08#19"}],"w_38_17":[{"c":"chiet_tu","t":"Chiết tự 摔","x":"Bộ thành phần: Thủ 扌 + Luật 率.","s":"HSK3_08#19"},{"c":"cach_dung","t":"摔 nghĩa là ngã","x":"摔 (Động từ) còn có nghĩa: ngã.","s":"HSK3_08#19"},{"c":"tu_mo_rong","t":"摔倒","x":"摔倒 (shuāidǎo – Động từ + Bổ ngữ kết quả): ngã lộn nhào, té ngã.","s":"HSK3_08#19"}],"w_38_18":[{"c":"tu_mo_rong","t":"掉眼泪 / 掉头发","x":"掉眼泪 (diào yǎnlèi): rơi nước mắt; 掉头发 (diào tóufa): rụng tóc.","s":"HSK3_08#20"}],"w_38_22":[{"c":"cau_vi_du","t":"Ví dụ 保证","x":"多喝水能保证身体健康。 — Uống nhiều nước có thể bảo đảm cho sức khỏe cơ thể.","s":"HSK3_08#23"}],"w_38_23":[{"c":"chiet_tu","t":"Chiết tự 遵守","x":"遵 – Bộ thành phần: Quai xước 辶 + Tôn 尊; 守 – Bộ thành phần: Miên 宀 + Thốn 寸.","s":"HSK3_08#24"},{"c":"tu_mo_rong","t":"Cụm từ với 遵守","x":"遵守交通规则 (zūnshǒu jiāotōng guīzé): tuân thủ luật giao thông; 遵守时间 (zūnshǒu shíjiān): tuân thủ giờ giấc (đúng giờ); 遵守法律 (zūnshǒu fǎlǜ): tuân thủ pháp luật.","s":"HSK3_08#24"}],"w_38_24":[{"c":"chiet_tu","t":"Chiết tự 规则","x":"规 (Quy) – Bộ thành phần: Phu 夫 + Kiến 见; 则 (Tắc) – Bộ thành phần: Bối 贝 + Đao đứng 刂.","s":"HSK3_08#25"}],"w_38_26":[{"c":"tu_mo_rong","t":"交通拥挤","x":"交通拥挤 (jiāotōng yōngjǐ): giao thông tắc nghẽn / đông đúc.","s":"HSK3_08#27"}],"w_38_27":[{"c":"tu_mo_rong","t":"Từ gần nghĩa / trái nghĩa của 主要","x":"~ 重要 (zhòngyào – quan trọng), 首要 (shǒuyào – hàng đầu); >< 次要 (cìyào – thứ yếu/phụ).","s":"HSK3_08#28"}],"w_38_28":[{"c":"cau_vi_du","t":"Ví dụ 原因","x":"因为天气的原因，比赛暂停了。 — Vì nguyên nhân thời tiết nên trận đấu đã tạm dừng.","s":"HSK3_08#29"},{"c":"tu_mo_rong","t":"理由","x":"~ 理由 (lǐyóu – lý do).","s":"HSK3_08#29"}],"w_38_29":[{"c":"cach_dung","t":"Cấu trúc 之一","x":"Danh từ số nhiều / Cụm từ + 之一: một trong những…","s":"HSK3_08#30"},{"c":"cau_vi_du","t":"Ví dụ 之一 (1)","x":"他是我最好的朋友之一。 — Anh ấy là một trong những người bạn thân nhất của tôi.","s":"HSK3_08#30"},{"c":"cau_vi_du","t":"Ví dụ 之一 (2)","x":"这也是我想辞职的原因之一。 — Đây cũng là một trong những nguyên nhân khiến tôi muốn nghỉ việc.","s":"HSK3_08#30"}],"w_38_30":[{"c":"cau_vi_du","t":"Ví dụ 引起","x":"这本书引起我的兴趣。 — Cuốn sách này khơi dậy sự hứng thú của tôi.","s":"HSK3_08#31"}],"w_38_31":[{"c":"cau_vi_du","t":"Ví dụ 赶快","x":"你生病了，一定要赶快去医院看医生。 — Bạn ốm rồi, nhất định phải mau chóng đến bệnh viện khám bác sĩ.","s":"HSK3_08#32"}],"w_39_2":[{"c":"cach_dung","t":"Cách dùng 图书","x":"图书: sách và tài liệu nói chung; thường được dùng để chỉ các loại sách bao gồm sách học thuật, tài liệu nghiên cứu và sách trong thư viện.","s":"HSK3_09#5"}],"w_39_1":[{"c":"chiet_tu","t":"Chiết tự 城","x":"城: Thành (thành phố). Bộ thành phần: Thổ 土 + Thành 成.","s":"HSK3_09#5"},{"c":"tu_mo_rong","t":"城市","x":"城市 (chéngshì – Danh từ): thành phố, đô thị.","s":"HSK3_09#5"},{"c":"khac","t":"图书城 VS 图书馆","x":"Chú ý phân biệt 图书城 (siêu thị sách) với 图书馆.","s":"HSK3_09#5"}],"w_39_4":[{"c":"cach_dung","t":"Cấu trúc với 各","x":"各 + Lượng từ + Danh từ.","s":"HSK3_09#7"},{"c":"cau_vi_du","t":"Ví dụ 各","x":"各国有不同的文化。 — Mỗi quốc gia đều có những văn hóa khác nhau.","s":"HSK3_09#7"}],"w_39_6":[{"c":"cau_vi_du","t":"Ví dụ 兴奋","x":"她兴奋地跟妈妈说今天她得了90分。 — Cô ấy hào hứng nói với mẹ rằng hôm nay cô ấy đạt được 90 điểm.","s":"HSK3_09#9"}],"w_39_7":[{"c":"tu_mo_rong","t":"衣架","x":"衣架 (yījià): móc treo quần áo, giá treo đồ.","s":"HSK3_09#10"}],"w_39_10":[{"c":"tu_mo_rong","t":"抽烟","x":"抽烟 (chōuyān): hút thuốc. Ví dụ: 这里不可以抽烟。 — Ở đây không cho phép hút thuốc.","s":"HSK3_09#12"},{"c":"tu_mo_rong","t":"抽时间","x":"抽时间 (chōu shíjiān): dành thời gian, tranh thủ thời gian. Ví dụ: 工作再忙，我们也要抽时间运动。 — Công việc có bận đến thế nào đi nữa, chúng ta cũng phải dành thời gian để vận động.","s":"HSK3_09#12"}],"w_39_11":[{"c":"chiet_tu","t":"Chiết tự 挑","x":"Bộ thành phần: Thủ 扌 + Triệu 兆.","s":"HSK3_09#13"},{"c":"tu_mo_rong","t":"商品","x":"商品 (shāngpǐn – Danh từ): hàng hóa.","s":"HSK3_09#13"}],"w_39_12":[{"c":"cach_dung","t":"Phân biệt 挑 và 选","x":"选: lựa chọn (mức độ thấp hơn); 挑: kén, chọn kỹ.","s":"HSK3_09#14"},{"c":"tu_mo_rong","t":"挑选","x":"挑选 (tiāoxuǎn – Động từ): chọn, lựa chọn, chọn lựa, chọn lọc. Ví dụ: 我花了一小时挑选了一件衣服。 — Tôi đã dành một tiếng đồng hồ để chọn một bộ quần áo.","s":"HSK3_09#14"}],"w_39_13":[{"c":"tu_mo_rong","t":"小说迷","x":"小说迷: người mê tiểu thuyết.","s":"HSK3_09#15"}],"w_39_14":[{"c":"cach_dung","t":"Hai cách dùng 除了…（以外）","x":"1. Bao hàm / thêm vào: vế sau thường đi với 还 hoặc 也 (除了英语以外，我还会说汉语。). 2. Loại trừ hoàn toàn: vế sau thường đi với 都.","s":"HSK3_09#16"},{"c":"cau_vi_du","t":"Ví dụ 除了 (loại trừ)","x":"除了我，他们都去了。 — Ngoài tôi ra thì bọn họ đều đã đi.","s":"HSK3_09#16"}],"w_39_15":[{"c":"cach_dung","t":"Cách dùng 于是","x":"Dùng để nối hai vế câu hoặc hai câu, diễn tả vế sau là kết quả tự nhiên hoặc một hành động nối tiếp ngay sau sự việc ở vế trước.","s":"HSK3_09#17"},{"c":"cach_dung","t":"Phân biệt 所以 và 于是","x":"所以 (suǒyǐ): nhấn mạnh thuần túy vào quan hệ nhân quả, thường đi thành cặp 因为……所以……. 于是 (yúshì): ngoài quan hệ nhân quả còn nhấn mạnh tính nối tiếp theo thời gian; 于是 không đi với 因为.","s":"HSK3_09#17"}],"w_39_16":[{"c":"cach_dung","t":"Nghĩa của 音像","x":"音 = âm thanh + 像 = hình ảnh; 音像 thường chỉ các sản phẩm, tư liệu hoặc nội dung kết hợp âm thanh và hình ảnh.","s":"HSK3_09#18"},{"c":"tu_mo_rong","t":"音像资料","x":"音像资料: tư liệu nghe nhìn.","s":"HSK3_09#18"}],"w_39_17":[{"c":"cach_dung","t":"这里 = 这儿","x":"这里 = 这儿; 那里 = 那儿.","s":"HSK3_09#19"}],"w_39_19":[{"c":"cau_vi_du","t":"Ví dụ 根据 (danh từ)","x":"你这么说有什么根据吗？ — Bạn nói như vậy có căn cứ gì không?","s":"HSK3_09#20"}],"w_39_20":[{"c":"tu_mo_rong","t":"拍照片 / 拍电影","x":"拍照片: chụp ảnh; 拍电影: quay phim.","s":"HSK3_09#21"}],"w_39_21":[{"c":"chiet_tu","t":"Chiết tự 盒","x":"Bộ thành phần: Hợp 合 + Mãnh 皿 (bát đĩa/đồ chứa).","s":"HSK3_09#22"}],"w_39_22":[{"c":"cach_dung","t":"上 và 下 chỉ thời gian","x":"上 chỉ thời gian vừa qua (quá khứ), 下 chỉ thời gian sắp tới (tương lai): 上（个）学期 / 下（个）学期; 上个月 / 下个月; 上个星期（上周）/ 下个星期（下周）.","s":"HSK3_09#23"}],"w_39_24":[{"c":"cach_dung","t":"Lượng từ của 纸","x":"Lượng từ đi kèm: 张.","s":"HSK3_09#24"},{"c":"tu_mo_rong","t":"Từ ghép với 纸","x":"纸巾 (zhǐjīn): khăn giấy / giấy ăn; 卫生纸 (wèishēngzhǐ): giấy vệ sinh; 报纸 (bàozhǐ): báo, tờ báo; 白纸 (báizhǐ): giấy trắng.","s":"HSK3_09#24"}],"w_39_25":[{"c":"tu_mo_rong","t":"开饭馆 / 饭店 / 餐厅","x":"开饭馆: mở quán ăn; từ gần nghĩa: 饭店, 餐厅.","s":"HSK3_09#25"}],"w_39_29":[{"c":"tu_mo_rong","t":"梯 / 坐电梯","x":"梯: thang. Đi thang máy: 坐电梯.","s":"HSK3_09#28"}],"w_39_30":[{"c":"tu_mo_rong","t":"修路","x":"修路 (xiū lù): làm đường / sửa đường.","s":"HSK3_09#29"}],"w_39_31":[{"c":"chiet_tu","t":"Cấu tạo 维修","x":"Bộ thành phần: 维 (duy trì/gìn giữ) + 修 (sửa chữa/tu sửa).","s":"HSK3_09#29"}],"w_39_32":[{"c":"tu_mo_rong","t":"Cụm từ với 楼梯","x":"爬楼梯 (pá lóutī): leo thang bộ; 走楼梯 (zǒu lóutī): đi thang bộ; 楼梯口: lối lên cầu thang.","s":"HSK3_09#30"}],"w_39_33":[{"c":"cach_dung","t":"Cách dùng 只好","x":"Biểu thị do hoàn cảnh khách quan ép buộc, không còn sự lựa chọn nào tốt hơn, đành phải đưa ra quyết định này.","s":"HSK3_09#31"}],"w_39_35":[{"c":"tu_mo_rong","t":"Từ ghép với 步","x":"跑步 (pǎobù): chạy bộ (động từ ly hợp); 进步 (jìnbù): tiến bộ (vừa là động từ vừa là danh từ); 第一步 (dì-yī bù): bước đầu tiên; 下一步 (xià yí bù): bước tiếp theo.","s":"HSK3_09#33"}],"w_39_36":[{"c":"chiet_tu","t":"Chiết tự 钥匙","x":"Bộ thành phần: 钥 (bộ Kim 钅 – kim loại) + 匙 (bộ Chủy 匕 – cái thìa/muỗng). Mẹo nhớ: Chìa khóa ngày xưa làm bằng kim loại và có hình dáng hơi giống cái thìa nhỏ.","s":"HSK3_09#34"}],"w_39_37":[{"c":"cach_dung","t":"Cách dùng 却","x":"Biểu thị sự chuyển ngoặt: 却 + Động từ/Tính từ.","s":"HSK3_09#35"},{"c":"cau_vi_du","t":"Ví dụ 却","x":"虽然这（个）学期大家都特别累，他却很有精神。 — Tuy học kỳ này mọi người đều đặc biệt mệt, anh ấy lại trông rất có tinh thần.","s":"HSK3_09#35"}],"w_39_39":[{"c":"cach_dung","t":"Phân biệt 想起来 và 想出来","x":"想起来: nhớ lại một thứ đã có sẵn trong đầu nhưng bị quên (nhớ ra chìa khóa để đâu, nhớ ra tên người quen). 想出来: nghĩ ra một ý tưởng, một phương pháp mới tinh, chưa từng có (nghĩ ra cách giải bài toán, nghĩ ra ý tưởng kinh doanh).","s":"HSK3_09#37"}],"w_39_40":[{"c":"tu_mo_rong","t":"插钥匙 / 插花","x":"插钥匙: cắm chìa khóa; 插花: cắm hoa. Ví dụ: 把钥匙插进去后就可以开门。 — Cắm chìa khóa vào xong là có thể mở cửa.","s":"HSK3_09#38"}],"w_40_1":[{"c":"tu_mo_rong","t":"客厅 / 大厅","x":"客厅: phòng khách; 大厅: đại sảnh (sảnh khách sạn,…).","s":"HSK3_10#4"}],"w_40_2":[{"c":"khac","t":"会议厅 VS 会议室","x":"Chú ý phân biệt 会议厅 với 会议室.","s":"HSK3_10#4"}],"w_40_3":[{"c":"tu_mo_rong","t":"城市中心 / 购物中心","x":"城市中心: trung tâm thành phố; 购物中心 (gòuwù zhōngxīn): trung tâm mua sắm.","s":"HSK3_10#5"}],"w_40_4":[{"c":"tu_mo_rong","t":"服务","x":"服务 (fúwù – Động từ/Danh từ): dịch vụ, phục vụ. Ví dụ: 这个饭馆的服务态度非常好。 — Thái độ phục vụ của nhà hàng này cực kỳ tốt.","s":"HSK3_10#6"}],"w_40_5":[{"c":"cach_dung","t":"长得 + Tính từ","x":"Nói về ngoại hình: 长得 + Tính từ.","s":"HSK3_10#7"},{"c":"cach_dung","t":"长 đọc cháng","x":"长 (cháng – Tính từ): dài (trường). Ví dụ: 这条路很长。 — Con đường này rất dài.","s":"HSK3_10#7"},{"c":"cau_vi_du","t":"Ví dụ 长得","x":"他长得很像他爸。 — Anh ấy trông cực kỳ giống bố anh ấy.","s":"HSK3_10#7"}],"w_40_6":[{"c":"tu_mo_rong","t":"个子高 / 个子矮","x":"个子高: dáng cao; >< 个子矮 (gèzi ǎi): dáng thấp.","s":"HSK3_10#8"}],"w_40_7":[{"c":"cach_dung","t":"Vị trí của 左右","x":"Luôn đứng SAU số từ để chỉ số xấp xỉ.","s":"HSK3_10#9"}],"w_40_8":[{"c":"tu_mo_rong","t":"Cụm từ với 戴","x":"戴眼镜 (dài yǎnjìng): đeo kính; 戴帽子 (dài màozi): đội mũ; 戴手表 (dài shǒubiǎo): đeo đồng hồ.","s":"HSK3_10#10"}],"w_40_9":[{"c":"cach_dung","t":"Động từ + 着","x":"Động từ + 着: biểu thị trạng thái của hành động đang được duy trì (đang có sẵn trạng thái đó).","s":"HSK3_10#11"}],"w_40_10":[{"c":"cach_dung","t":"Hai cách dùng 副","x":"1. Lượng từ: dùng cho các đồ vật đi thành bộ, đôi hoặc trên khuôn mặt – 一副眼镜: một cặp kính; 一副手套: một đôi găng tay. 2. Tính từ: phó, chức vụ cấp phó (副校长: hiệu phó).","s":"HSK3_10#12"}],"w_40_11":[{"c":"cach_dung","t":"Phân biệt 穿 và 戴","x":"穿 dùng với: 衣服 (áo), 裤子 (quần), 鞋子 (giày), 袜子 (tất). 戴 dùng với: 眼镜 (kính), 帽子 (mũ), 手表 (đồng hồ), 戒指 (nhẫn).","s":"HSK3_10#13"},{"c":"tu_mo_rong","t":"Cụm từ với 穿","x":"穿衣服 (chuān yīfu): mặc quần áo; 穿鞋 (chuān xié): đi giày; 穿上 (động từ + bổ ngữ kết quả).","s":"HSK3_10#13"}],"w_40_12":[{"c":"cach_dung","t":"Lượng từ của 西服","x":"Lượng từ đi kèm: 套 (tào – một bộ) hoặc 件 (jiàn – một chiếc áo vest đơn lẻ).","s":"HSK3_10#14"}],"w_40_13":[{"c":"chiet_tu","t":"Chiết tự 裙","x":"Bộ thành phần: Y 衤 + Quân 君.","s":"HSK3_10#15"},{"c":"cach_dung","t":"Lượng từ của 裙子","x":"Lượng từ đi kèm: 条 (tiáo – dùng cho các vật dáng dài, thon).","s":"HSK3_10#15"}],"w_40_14":[{"c":"cach_dung","t":"干 gān và 干 gàn","x":"gān (Tính từ): khô ráo (như trong 干净 gānjìng – sạch sẽ). gàn (Động từ): làm (bằng nghĩa với 做, nhưng mang sắc thái khẩu ngữ mạnh mẽ, dứt khoát hơn).","s":"HSK3_10#16"}],"w_40_17":[{"c":"cach_dung","t":"Cách dùng 小伙子","x":"Dùng để gọi một cách thân mật, khen ngợi những người nam giới trẻ tuổi.","s":"HSK3_10#18"}],"w_40_21":[{"c":"cach_dung","t":"Cấu trúc với 讲话","x":"跟/对 + [ai đó] + 讲话: nói chuyện với ai.","s":"HSK3_10#20"}],"w_40_24":[{"c":"cach_dung","t":"Lượng từ và cụm từ với 婚礼","x":"Lượng từ đi kèm: 场 (chǎng) hoặc 个 (gè). 参加婚礼: tham gia đám cưới; 举办婚礼: tổ chức đám cưới.","s":"HSK3_10#23"}],"w_40_25":[{"c":"tu_mo_rong","t":"看热闹","x":"看热闹: hóng hớt, hóng chuyện, hiếu kỳ.","s":"HSK3_10#24"}],"w_40_31":[{"c":"chiet_tu","t":"Cấu tạo 棉袄","x":"Bộ thành phần: 棉 (bông vải) + 袄 (áo vạt dài – bộ Y 衤).","s":"HSK3_10#28"}],"w_40_32":[{"c":"tu_mo_rong","t":"Từ trái nghĩa của 帅","x":"丑 (chǒu): xấu xí.","s":"HSK3_10#29"}],"w_40_33":[{"c":"chiet_tu","t":"Cấu tạo 领带","x":"Bộ thành phần: 领 (lǐng – cái cổ áo, cổ) + 带 (dài – dây đai). Mẹo nhớ: chiếc dây thắt ở cổ áo.","s":"HSK3_10#30"},{"c":"cach_dung","t":"Lượng từ và động từ đi với 领带","x":"Lượng từ đi kèm: 条. Thắt/đeo cà vạt: 打 (dǎ) hoặc 系 (jì).","s":"HSK3_10#30"}],"w_40_35":[{"c":"cach_dung","t":"Lượng từ của 客人","x":"Lượng từ đi kèm: 位 (wèi – trang trọng), 个 (gè).","s":"HSK3_10#32"}],"w_40_36":[{"c":"ngu_am","t":"倒 dào và 倒 dǎo","x":"dào (thanh 4): rót, đổ, lộn ngược (nghiêng bình để chất lỏng chảy ra) – 倒茶 (rót trà), 倒水 (rót nước), 倒酒 (rót rượu). dǎo (thanh 3): ngã, đổ, sập (vật đang đứng thẳng bị đổ rạp xuống) – 摔倒 (shuāidǎo – ngã đổ).","s":"HSK3_10#33"}],"w_40_37":[{"c":"cach_dung","t":"不停地 + Động từ","x":"不停地 + Động từ: biểu thị hành động diễn ra liên tục không hề ngắt quãng.","s":"HSK3_10#34"}]},"lessons":{"0":[{"c":"ngu_phap","t":"12 loại từ trong tiếng Trung","x":"1. Danh từ: người/vật; thời gian; địa điểm; phương vị (trên, dưới, trước, sau).\n2. Động từ: động tác/hành vi; hoạt động tâm lý (yêu, ghét); thay đổi/tồn tại/biến mất; phán đoán (là); năng nguyện (có thể, nên, muốn, cần); xu hướng (lên, xuống, quay về); động từ li hợp; động từ trùng điệp.\n3. Tính từ (hình dung từ): trạng thái (to, đẹp, nhanh, bận); tính chất (tốt, đúng).\n4. Số từ: số đếm; số thứ tự.\n5. Lượng từ: danh lượng từ (1 con mèo); động lượng từ (nhìn một cái).\n6. Phó từ: mức độ (rất, hơi, nhất); phạm vi (chỉ, tổng); thời gian (đã, vừa mới); khẳng định; phủ định; trạng thái; tần suất… Thường đứng trước động từ/tính từ.\n7. Đại từ: nhân xưng (tôi, bạn); nghi vấn (cái gì); chỉ thị (đây, kia).\n8. Từ tượng thanh: haha.\n9. Thán từ: à, alo.\n10. Giới từ: thời gian (lúc, từ); vị trí/phương hướng (từ, hướng đến); đối tượng (cho, đối với); phương thức (dựa vào); nguyên nhân, mục đích; so sánh; khoảng cách; căn cứ; loại trừ; liên quan…\n11. Liên từ: đẳng lập (và); lựa chọn (hoặc); tăng tiến (không chỉ… mà còn); tương phản; điều kiện; so sánh…\n12. Trợ từ: trợ từ kết cấu, động thái, ngữ khí, so sánh.","s":"HSK1_01#17"},{"c":"ngu_am","t":"Âm hai môi & âm môi răng (so với tiếng Việt)","x":"Âm hai môi: b, p, m. “b” gần “p” tiếng Việt; “p” là âm bật hơi.\nÂm môi răng: f. “f” gần “f”/“ph” tiếng Việt.","s":"HSK1_00#10"},{"c":"ngu_am","t":"Âm đầu lưỡi giữa, cuống lưỡi, mặt lưỡi","x":"Âm đầu lưỡi giữa: d, t, n, l. “d” gần “t”; “t” gần “th”.\nÂm cuống lưỡi: g, k, h. “g” gần “c”; “k” bật hơi; “h” gần “kh”.\nÂm mặt lưỡi: j, q, x. “j” gần “ch”; “q” bật hơi; “x” gần “x”.","s":"HSK1_00#11"},{"c":"ngu_am","t":"Âm đầu lưỡi trước z, c, s","x":"Khi phát âm, đầu lưỡi đặt ở phía sau răng cửa hàm trên.\n“z” gần “z” trong tiếng Anh; “c” bật hơi; “s” gần “x” tiếng Việt.","s":"HSK1_00#12"},{"c":"ngu_am","t":"Âm uốn lưỡi zh, ch, sh, r và y, w","x":"Âm đầu lưỡi sau (âm uốn lưỡi): zh, ch, sh, r.\n“zh” gần “tr”; “ch” bật hơi; “sh” gần “s”; “r” gần “r”.\nThanh mẫu không chính thức: y, w.","s":"HSK1_00#15"},{"c":"ngu_am","t":"Cách đọc i sau j/q/x và z/c/s/zh/ch/sh/r","x":"j, q, x + i (ji, qi, xi) → đọc là [i].\nz, c, s, zh, ch, sh, r + i (zi, ci, si, zhi, chi, shi, ri) → đọc là [ư].","s":"HSK1_00#14"},{"c":"ngu_am","t":"Khẩu hình vận mẫu đơn","x":"a: khẩu hình mở to, đặt lưỡi thấp.\no (ua/ô): khẩu hình mở vừa, đặt lưỡi cao vừa, tròn môi.\ne (ưa/ơ)\ni, u, ü: khi phát âm không thay đổi khẩu hình.\nLuyện ghép: ma, ni, ba, po, he, ti, lü.","s":"HSK1_00#18"},{"c":"ngu_am","t":"Dạng đầy đủ của một số vận mẫu","x":"er = e + uốn lưỡi\niu = iou\nui = uei\nun = uen","s":"HSK1_00#19"},{"c":"ngu_am","t":"Quy tắc viết phiên âm: i, ü đầu âm tiết","x":"1. Khi i bắt đầu âm tiết thì viết thành y.\n2. Khi ü bắt đầu âm tiết thì viết thành yu.","s":"HSK1_00#22"},{"c":"ngu_am","t":"Quy tắc viết phiên âm: j/q/x + ü, n/l + ü, iou","x":"3. Khi j, q, x đi với ü (üe, üan, ün) thì bỏ 2 dấu chấm trên chữ u: j, q, x + ü → u.\n4. Khi n, l đi với ü (üe, üan, ün) thì vẫn giữ nguyên ü.\n5. Vận mẫu iou khi có thanh mẫu phía trước thì viết thành iu.","s":"HSK1_00#23"},{"c":"ngu_am","t":"Quy tắc viết phiên âm: u → w, dấu cách âm '","x":"6. Khi u bắt đầu âm tiết thì viết thành w.\n7. Khi a, o, e bắt đầu một âm tiết đứng ngay sau âm tiết khác thì thêm dấu ' để ngăn cách, tránh lẫn lộn.","s":"HSK1_00#24"},{"c":"ngu_am","t":"Cách đánh dấu thanh điệu","x":"1. Dấu thanh chủ yếu đánh trên nguyên âm.\n2. Khi đánh dấu thanh trên i thì bỏ dấu chấm của i. Ví dụ: nǐ, pí.\n3. Vận mẫu có từ 2 nguyên âm trở lên thì đánh dấu trên nguyên âm có độ mở khẩu hình lớn nhất, theo thứ tự: a, o, e, i, u, ü. Ví dụ: pǎo, mèi, lóu.","s":"HSK1_00#30"},{"c":"ngu_am","t":"Âm uốn lưỡi er và vần 儿化","x":"Khi phát âm /er/, lưỡi đặt ở vị trí như khi phát âm /e/, sau đó cong lưỡi lên dần.\nKhi /er/ đứng sau vận mẫu: phiên âm chỉ thêm “r” ngay sau vận mẫu gốc; chữ Hán thêm 儿 phía sau (có lúc được lược bỏ).","s":"HSK1_00#31"},{"c":"ngu_am","t":"Biến điệu khi 3 hoặc 4 thanh 3 liền nhau","x":"3 thanh 3 liền nhau (3-3-3): đọc 3-2-3 hoặc 2-2-3.\nVí dụ: 好想你 Hǎo xiǎng nǐ → Hǎo xiáng nǐ / Háo xiáng nǐ.\n4 thanh 3 liền nhau (3-3-3-3): đọc 2-3-2-3 hoặc 2-2-2-3.\nVí dụ: 我也很好 Wǒ yě hěn hǎo → Wó yě hén hǎo / Wó yé hén hǎo.","s":"HSK1_00#35"},{"c":"ngu_am","t":"Nửa thanh 3","x":"Thanh 3 + thanh 1/2/4 → nửa thanh 3 (2-1-4 → 2-1).\nChỉ đọc phần đầu của thanh 3, không đọc phần lên giọng phía sau, rồi chuyển nhanh sang âm tiết tiếp theo.","s":"HSK1_00#36"},{"c":"van_hoa","t":"Chữ giản thể và phồn thể","x":"Phồn thể: kiểu chữ truyền thống, nhiều nét, phức tạp; dùng nhiều ở Đài Loan, Hồng Kông và Ma Cao.\nGiản thể: giản lược từ phồn thể, ít nét, dễ nhớ; dùng ở Trung Quốc đại lục.","s":"HSK1_01#6"},{"c":"khac","t":"Các cấp HSKK (thi khẩu ngữ)","x":"HSKK – Kỳ thi năng lực khẩu ngữ tiếng Trung, tương ứng với các cấp HSK 2.0:\nHSK 1–2 (sơ cấp) ↔ HSKK sơ cấp\nHSK 3–4 (trung cấp) ↔ HSKK trung cấp\nHSK 5–6 (cao cấp) ↔ HSKK cao cấp","s":"HSK1_00#2"},{"c":"khac","t":"Các cách cấu tạo chữ Hán","x":"1. Chữ tượng hình: vẽ lại sự vật/sự việc (山、日).\n2. Chữ hội ý: dùng hai hay nhiều bộ thủ cùng thể hiện một ý nghĩa để tạo chữ mới (安、男).\n3. Chữ hình thanh: gồm hai bộ phận, một bộ phận biểu thị ý nghĩa, một bộ phận biểu thị âm đọc (请、把).\n4. Chữ chỉ sự: trừu tượng, dùng ký hiệu để thể hiện (上、下、本).","s":"HSK1_01#5"},{"c":"khac","t":"8 nét cơ bản trong chữ Hán","x":"Nét ngang: nét thẳng ngang, kéo từ trái sang phải.\nNét sổ: nét thẳng đứng, kéo từ trên xuống dưới.\nNét chấm: một dấu chấm từ trên xuống.\nNét hất: nét cong, đi lên từ trái sang phải.\nNét phẩy: nét cong, kéo xuống từ phải qua trái.\nNét mác: nét thẳng, kéo xuống từ trái qua phải.\nNét gập: có một chỗ gập giữa nét.\nNét móc: móc lên ở cuối các nét khác.","s":"HSK1_01#12"},{"c":"khac","t":"Quy tắc viết chữ Hán (thứ tự nét)","x":"1. Ngang trước sổ sau.\n2. Phẩy trước mác sau.\n3. Trên trước dưới sau.\n4. Trái trước phải sau.\n5. Ngoài trước trong sau.\n6. Vào trước đóng sau.\n7. Giữa trước hai bên sau.\n8. Nét bao quanh ở đáy viết sau cùng.","s":"HSK1_01#13"}],"2":[{"c":"chiet_tu","t":"Chiết tự 吗","x":"吗 (ma, trợ từ): không (dùng ở cuối câu hỏi).\nBộ thành phần: 口 Khẩu + 马 Mã.\n你好吗？ — Bạn khỏe không?\n你忙吗？ — Bạn bận không?","s":"HSK1_02#5"}],"3":[{"c":"chiet_tu","t":"Chiết tự 韩, 国","x":"韩 (Hán): Hàn. Bộ thành phần: 十 Thập + 早 Tảo + bộ Vi (da thuộc).\n国 (guó): Quốc gia, đất nước. Bộ thành phần: 囗 Vi (vây) + 玉 Ngọc.\nMẹo nhớ: Quốc gia có bức tường thành bao quanh, bên trong có ngọc tỷ.","s":"HSK1_03#5"},{"c":"tu_mo_rong","t":"韩国 – Hàn Quốc","x":"韩国 (Hánguó): Hàn Quốc","s":"HSK1_03#5"}],"4":[{"c":"cach_dung","t":"Mẹo đọc thứ; 星期天 và 星期日","x":"Mẹo: lấy thứ theo tiếng Việt trừ 1 (thứ 2 = 星期一 … thứ 7 = 星期六).\nChủ nhật: 星期天 (văn nói), 星期日 (văn viết).","s":"HSK1_04#8"},{"c":"cau_vi_du","t":"Câu ví dụ với 天安门 và 再","x":"今天星期六我去天安门。 — Hôm nay thứ 7 tôi đi Thiên An Môn.\n明天星期天（星期日）我再去天安门。 — Ngày mai chủ nhật tôi lại đi Thiên An Môn.","s":"HSK1_04#20"},{"c":"tu_mo_rong","t":"安, 门 (天安门)","x":"安 (ān): Bình yên, bình an – Hán Việt: An; bộ thành phần: 宀 Miên + 女 Nữ\n门 (mén): Cửa, cổng – Hán Việt: Môn\n天安门 (Tiān'ānmén): Thiên An Môn","s":"HSK1_04#19"},{"c":"ngu_phap","t":"Câu hỏi chính phản và câu hỏi 吗","x":"对不对？ — Đúng hay không?  /  对吗？ — Đúng không?\n去不去？ — Đi hay không?  /  去吗？ — Đi không?\n明天你忙不忙？ = 明天你忙吗？ — Ngày mai bạn bận không?\n汉语难不难？ = 汉语难吗？ — Tiếng Trung khó không?","s":"HSK1_04#22"}],"5":[{"c":"tu_mo_rong","t":"王 – Vương","x":"王 (Wáng): Vương, vua\n王老师: Thầy giáo Vương\n这是王老师。 — Đây là thầy giáo Vương.","s":"HSK1_05#24"}],"7":[{"c":"chiet_tu","t":"Chiết tự 饺","x":"Bộ thành phần: 饣 Thực + 交 Giao.\n这些饺子很好吃。 — Những cái sủi cảo này rất ngon.","s":"HSK1_07#20"},{"c":"ngu_phap","t":"Thứ tự thời gian: từ lớn đến bé","x":"Trong tiếng Trung, thời gian sắp xếp từ lớn đến bé.\n明天中午 — Trưa mai\n明天中午我去朋友那儿。 — Trưa mai tôi đi chỗ bạn tôi.","s":"HSK1_07#4"}],"8":[{"c":"khac","t":"Tỷ giá tham khảo NDT – VND","x":"越南盾 (yuènán dùn): Việt Nam đồng (VND)\n1 块 ≈ 3.900 越南盾 (tỷ giá tham khảo tại thời điểm soạn bài)","s":"HSK1_08#22"}],"9":[{"c":"chiet_tu","t":"Chiết tự 图 và từ lóng P图","x":"图 (tú) – Hán Việt: Đồ (hình vẽ, hình ảnh nói chung)\nBộ thành phần: 囗 Vi + 冬 Đông. Mẹo nhớ: Bức ảnh thì bên ngoài là khung, bên trong là khung cảnh mùa đông.\nP图: Photoshop (chỉnh ảnh)","s":"HSK1_09#8"},{"c":"chiet_tu","t":"Chiết tự 馆 (饭馆)","x":"馆 (guǎn) – Hán Việt: Quán\nBộ thành phần: 饣 Thực + 官 Quan\n饭馆: Nhà hàng, quán cơm","s":"HSK1_09#10"},{"c":"chiet_tu","t":"Chiết tự 香 (thơm)","x":"香 (xiāng – hình dung từ): Thơm – Hán Việt: Hương\nBộ thành phần: 禾 Hòa (cây lúa) + 日 Nhật. Mẹo nhớ: Bông lúa ở dưới ánh mặt trời sẽ tỏa hương rất thơm.","s":"HSK1_09#24"},{"c":"cau_vi_du","t":"图书馆 (thư viện) + ví dụ","x":"图书馆 (túshūguǎn – danh từ): Thư viện – Hán Việt: Đồ thư quán (书 – Thư)\n昨天上午（早上）我去学校图书馆。 — Sáng hôm qua tôi đi thư viện trường.","s":"HSK1_09#11"},{"c":"cau_vi_du","t":"小 (nhỏ) + ví dụ","x":"小 (xiǎo – hình dung từ): Nhỏ, bé – Hán Việt: Tiểu\n这个苹果太小了！我要吃大的（苹果）。 — Quả táo này nhỏ quá! Tôi muốn ăn quả lớn.","s":"HSK1_09#13"},{"c":"tu_mo_rong","t":"中午 – buổi trưa và thứ tự các buổi","x":"中午 (zhōngwǔ): Buổi trưa\nThứ tự các buổi: 早上 (sáng sớm) → 上午 (buổi sáng) → 中午 (buổi trưa) → 下午 (buổi chiều) → 晚上 (buổi tối)","s":"HSK1_09#7"},{"c":"ngu_phap","t":"3 quy tắc đọc số 0","x":"1. Số 0 đứng ở cuối: có thể đọc hoặc lược bỏ đơn vị cuối\n680: 六百八十（六百八）\n6800: 六千八百（六千八）\n610: 六百一十（六百一）\n2. Số 0 đứng giữa: chỉ cần đọc 零 một lần duy nhất\n608: 六百零八\n6008: 六千零八\n60008: 六万零八\n3. Vừa có số 0 ở giữa vừa có ở cuối: phải đọc cả đơn vị cuối\n6080: 六千零八十 (nếu đọc 六千零八 sẽ nhầm thành 6008)\n60080: 六万零八十 (nếu đọc 六万零八 sẽ nhầm thành 60008)","s":"HSK1_09#33"}],"10":[{"c":"tu_mo_rong","t":"Tên riêng 李昌浩 (Lý Xương Hạo)","x":"昌 (chāng): Hưng thịnh, họ Xương – Bộ thành phần: 日 Nhật (x2). Mẹo nhớ: Hai mặt trời ở cạnh nhau rất sáng, tượng trưng cho sự hưng thịnh.\n浩 (hào): Hạo – Bộ thành phần: 氵 Ba chấm thủy + 告 Cáo (báo cáo). Mẹo nhớ: Anh Hạo uống nước làm báo cáo.\n李昌浩: Lý Xương Hạo","s":"HSK1_10#28"},{"c":"ngu_phap","t":"6 thành phần câu tiếng Hán","x":"Câu tiếng Hán do 6 thành phần tạo thành: Chủ ngữ, Vị ngữ, Tân ngữ, Định ngữ, Trạng ngữ, Bổ ngữ.","s":"HSK1_10#30"},{"c":"ngu_phap","t":"Câu vị ngữ động từ","x":"Câu vị ngữ động từ: câu có động từ làm thành phần chính trong vị ngữ.\nCấu trúc: Chủ ngữ + Động từ + Tân ngữ","s":"HSK1_10#31"}],"11":[{"c":"tu_mo_rong","t":"和 (và): chiết tự và cách dùng","x":"和 (hé – liên từ): Và – Hán Việt: Hòa (hòa bình, hòa thuận)\nBộ thành phần: 禾 Hòa + 口 Khẩu. Mẹo nhớ: Có đủ lúa để ăn thì cuộc sống sẽ hòa bình.\nA 和 B: A và B\n她和她的朋友都是中国人。 — Cô ấy và bạn cô ấy đều là người Trung Quốc.","s":"HSK1_11#23"}],"12":[{"c":"cach_dung","t":"怎么样: chiết tự 样 và các cách dùng","x":"样 (yàng): Dạng (hình dáng)\nBộ thành phần: 木 Mộc + 羊 Dương (con dê). Mẹo nhớ: Hình dáng con dê đứng dưới gốc cây.\n怎么样 (zěnmeyàng): Như thế nào?\n1. Hỏi chất lượng, tình trạng: 这个怎么样？——这个很好。\n2. Hỏi thăm sức khỏe, tình hình: 你爸爸妈妈怎么样？——他们都很好。\n3. Đề xuất ý kiến: (Phương án này) như thế nào?\n不怎么样: Không ra gì","s":"HSK1_12#7"},{"c":"tu_mo_rong","t":"听说: nghe nói","x":"听说 (tīngshuō): Nghe nói, được nghe rằng\n我听说你明天去北京。 — Tôi nghe nói ngày mai bạn sẽ đi Bắc Kinh.","s":"HSK1_12#15"},{"c":"tu_mo_rong","t":"法律 (pháp luật)","x":"法律 (fǎlǜ): Pháp luật\n律: 彳 Xích + 聿 Duật (xem chiết tự 律 ở Bài 11)","s":"HSK1_12#30"},{"c":"ngu_phap","t":"Định ngữ và trợ từ kết cấu 的","x":"1. Danh từ hoặc đại từ làm định ngữ biểu thị quan hệ hạn chế hoặc sở hữu thì phải thêm 的: 我的书；他的词典；老师的本子；图书馆的书；我们的老师\n2. Cụm hình dung từ (tính từ) làm định ngữ thì phải thêm 的: 很好的老师；很贵的手机；不太贵的东西\n3. Có khi giữa định ngữ và trung tâm ngữ không cần thêm 的: 男同学；中文书；汉语老师","s":"HSK1_12#35"}],"13":[{"c":"tu_mo_rong","t":"这儿 (ở đây)","x":"这儿 (zhèr – đại từ chỉ nơi chốn): Đây, ở đây\nA：请问，这儿有没有银行？我要取钱和换钱。 — Cho hỏi, ở đây có ngân hàng không? Tôi cần rút tiền và đổi tiền.\nB：没有。 — Không có.","s":"HSK1_13#7"},{"c":"ngu_phap","t":"Câu vị ngữ hình dung từ","x":"Câu vị ngữ hình dung từ: câu có hình dung từ làm thành phần chính của vị ngữ.\n1. Không thêm 是 vào giữa chủ ngữ và vị ngữ. Không nói: ✗ 我是很忙。 ✗ 我们老师是很好。\n2. Trước hình dung từ thường có phó từ chỉ mức độ; nếu không có phó từ thì câu không còn mang ý nghĩa miêu tả mà mang ý nghĩa so sánh.","s":"HSK1_13#36"},{"c":"ngu_phap","t":"Câu nghi vấn chính phản","x":"Kết hợp hình thức khẳng định và phủ định của thành phần chủ yếu trong vị ngữ sẽ tạo thành câu nghi vấn chính phản.\n你去洗手间吗？ → 你去不去洗手间？\n他喝鸡蛋汤吗？ → 他喝不喝鸡蛋汤？\n你买光盘吗？ → 你买不买光盘？\n你有手机吗？ → 你有没有手机？\n你的手机新吗？ → 你的手机新不新？","s":"HSK1_13#37"},{"c":"ngu_phap","t":"Kết cấu chữ 的","x":"Kết cấu chữ 的: thêm 的 vào sau danh từ, đại từ, hình dung từ, động từ hoặc cụm từ. Kết cấu này có vai trò tương đương danh từ và có thể đảm nhiệm các thành phần câu mà danh từ đảm nhiệm.\nVí dụ: 红的, 黑的, 我爸爸妈妈的, 他的","s":"HSK1_13#38"}],"14":[{"c":"ngu_phap","t":"呢: hỏi địa điểm khi không có bối cảnh","x":"Khi không có bối cảnh trước đó, câu hỏi với 呢 dùng để hỏi địa điểm.\n我的书呢？（= 我的书在哪儿？）\nLuyện tập: 玛丽呢？ 你呢？ 张东呢？ 那些呢？ 你的呢？","s":"HSK1_14#28"}],"15":[{"c":"cau_vi_du","t":"Ví dụ 都不是 và 不都是","x":"他们都不是越南人。 — Họ đều không phải là người Việt Nam. (phủ định hoàn toàn)\n我们班的学生不都是越南人，玛丽是英国人，张东是中国人。 — Học sinh lớp chúng tôi không phải đều là người Việt Nam: Mary là người Anh, Trương Đông là người Trung Quốc. (phủ định một phần)","s":"HSK1_15#26"}],"16":[{"c":"chiet_tu","t":"Chiết tự 时 và 候 (时候)","x":"时 (shí) – Hán Việt: Thời, thì (thời gian).\nBộ thành phần: 日 Nhật + 寸 Thốn.\n候 – Hán Việt: Hậu (lúc, khi).\nBộ thành phần: 亻 Nhân đứng + 矢 Thỉ (mũi tên).","s":"HSK2_16#14"},{"c":"chiet_tu","t":"Chiết tự 资 và 料 (资料)","x":"资 (zī) – Hán Việt: Tư (tư liệu, đầu tư).\nBộ thành phần: 次 Lần + 贝 Bối.\nMẹo nhớ: Mỗi lần đầu tư là lại mất tiền.\n料 (liào) – Hán Việt: Liệu (tư liệu, nguyên liệu).\nBộ thành phần: 米 Mễ + 斗 Đấu.\nMẹo nhớ: Nguyên liệu là gạo và được đựng trong cái đấu.","s":"HSK2_16#18"},{"c":"chiet_tu","t":"Chiết tự 安 (安静)","x":"安 (ān) – Hán Việt: An (bình an, bình yên).\nBộ thành phần: 宀 Miên + 女 Nữ.\nMẹo nhớ: Có người phụ nữ ở trong nhà thì chắc chắn ngôi nhà sẽ bình yên.","s":"HSK2_16#21"},{"c":"chiet_tu","t":"Chiết tự 静 (安静)","x":"静 (jìng) – Hán Việt: Tĩnh (yên tĩnh, yên lặng).\nBộ thành phần: 青 Thanh + 争 Tranh (tranh giành).\nMẹo nhớ: Dù ngoài kia còn nhiều tranh giành nhưng vẫn giữ lòng thanh thản, đó là Tĩnh.","s":"HSK2_16#22"},{"c":"chiet_tu","t":"Chiết tự 休 và 息 (休息)","x":"休 (xiū) – Hán Việt: Hưu (nghỉ ngơi).\nBộ thành phần: 亻 Nhân + 木 Mộc.\nMẹo nhớ: Người dựa vào gốc cây để nghỉ ngơi.\n息 – Hán Việt: Tức.\nBộ thành phần: 自 Tự + 心 Tâm.","s":"HSK2_16#36"},{"c":"chiet_tu","t":"Chiết tự 超 và 市 (超市)","x":"超 (chāo) – Hán Việt: Siêu.\nBộ thành phần: 走 Tẩu + 召 Triệu.\n市 (shì) – Hán Việt: Thị.\nBộ thành phần: 亠 Đầu + 巾 Cân (khăn).\nMẹo nhớ: Triệu tập mọi người đi bộ đến siêu thị mua khăn đội đầu.","s":"HSK2_16#40"},{"c":"tu_mo_rong","t":"时候 / 有时候","x":"时候 (shíhou): danh từ – lúc, thời điểm\n有时候: có lúc, có khi\n有时候骑自行车，有时候骑摩托车，有时候开汽车。— Có khi thì đạp xe đạp, có khi thì đi xe máy, có lúc thì lái ô tô.","s":"HSK2_16#14"},{"c":"tu_mo_rong","t":"资料 tư liệu, tài liệu","x":"资料 (zīliào): tư liệu, tài liệu (danh từ)\n我常上网查资料。— Tôi thường xuyên lên mạng tra tài liệu.","s":"HSK2_16#18"},{"c":"tu_mo_rong","t":"安静 yên tĩnh","x":"安静 (ānjìng): yên tĩnh, yên lặng (tính từ)\n图书馆总是很安静。— Thư viện luôn rất yên tĩnh.","s":"HSK2_16#22"},{"c":"tu_mo_rong","t":"上课 / 下课","x":"上课 (shàng kè): đi học, lên lớp\n下课 (xià kè): tan học","s":"HSK2_16#24"},{"c":"tu_mo_rong","t":"休息 nghỉ ngơi","x":"休息 (xiūxi): nghỉ ngơi (động từ)","s":"HSK2_16#36"},{"c":"tu_mo_rong","t":"超市 siêu thị","x":"超市 (chāoshì): siêu thị (danh từ)","s":"HSK2_16#40"},{"c":"ngu_phap","t":"Câu hỏi …，好吗？","x":"Sau câu trần thuật thêm \"…，好吗？\" để nêu ý kiến và hỏi ý kiến của đối phương, mang ý thương lượng, thỉnh cầu.\n晚上咱们去看电影，好吗？\n你跟我一起去，好吗？","s":"HSK2_16#43"},{"c":"ngu_phap","t":"Trợ từ ngữ khí 吧","x":"吧 đặt ở cuối câu biểu thị ý thương lượng, đề nghị, thỉnh cầu, đồng ý.\nA: 咱们一起去吧。(đề xuất) — B: 好吧。(đồng ý)\nA: 咱们走吧。(đề xuất) — B: 走吧。(đồng ý)","s":"HSK2_16#44"},{"c":"ngu_phap","t":"很少 + động từ","x":"很少 + động từ: ít khi làm gì.\nCó thể nói: 很少吃馒头。很少看电影。很少看电视。\nKhông nói: 很多吃米饭。很多看电视。(很多 không dùng như vậy)","s":"HSK2_16#45"},{"c":"ngu_phap","t":"Từ chỉ thời gian làm trạng ngữ","x":"Từ chỉ thời gian thường đứng trước động từ hoặc trước chủ ngữ, biểu thị thời gian của hành động.\nA: 你晚上做什么？ B: 我晚上做练习。\nA: 下午你常去哪儿？ B: 我常去图书馆。","s":"HSK2_16#46"},{"c":"ngu_am","t":"Trọng âm câu","x":"1. Trạng ngữ trong câu thường được đọc nhấn mạnh: 他'常常去图书馆。我'很少看电视。你'晚上做什么？\n2. Phó từ phủ định làm trạng ngữ, nếu không nhấn mạnh phủ định thì không đọc nhấn mạnh: 他不常看电视。\n3. Với \"…，好吗\", 好 được đọc nhấn mạnh, cuối câu lên giọng: 你跟我一起去，'好吗？","s":"HSK2_16#48"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"wǎnshang – wǎngshàng\nxiūxi – xiūlǐ\nliànxí – liánxì\nzīliào – zhìliáo\nshēngcí – shēngzì\nyùxí – fùxí","s":"HSK2_16#55"},{"c":"khac","t":"Các loại \"…馆\" (luyện đọc)","x":"图书馆 túshūguǎn\n博物馆 bówùguǎn\n大使馆 dàshǐguǎn\n展览馆 zhǎnlǎnguǎn\n美术馆 měishùguǎn\n体育馆 tǐyùguǎn\n文化馆 wénhuàguǎn\n天文馆 tiānwénguǎn","s":"HSK2_16#56"},{"c":"khac","t":"Luyện đọc với 常 / 不常 / 很少","x":"常看电视　常复习课文　常预习生词\n不常吃馒头　不常喝啤酒　不常看电影　不常去公园\n很少看书　很少喝酒　很少去图书馆　很少吃面条","s":"HSK2_16#58"}],"17":[{"c":"chiet_tu","t":"Chiết tự 出","x":"出 (chū) – động từ: ra. Hán Việt: Xuất.\nBộ thành phần: 山 Sơn (núi).\nMẹo nhớ: Ra núi này đến núi khác.","s":"HSK2_17#8"},{"c":"chiet_tu","t":"Chiết tự 来","x":"来 (lái) – động từ: đến (hướng về người nói).\nBộ thành phần: 一 Nhất + 米 Mễ.\nMẹo nhớ: Đến thì mang 1 bao gạo theo.","s":"HSK2_17#9"},{"c":"chiet_tu","t":"Chiết tự 想","x":"想 (xiǎng) – động từ: suy nghĩ, muốn, nhớ. Hán Việt: Tưởng.\nBộ thành phần: 相 Tương (木 + 目) + 心 Tâm.\nMẹo nhớ: Tương tư ai đó bằng cả trái tim là đang nhớ người đó.","s":"HSK2_17#16"},{"c":"chiet_tu","t":"Chiết tự 挤","x":"挤 (jǐ) – động từ/tính từ: đông đúc, chen chúc. Hán Việt: Tễ.\nBộ thành phần: 扌 Thủ (tay) + 齐 Tề (ngang bằng).\nMẹo nhớ: Nơi có nhiều cánh tay ngang bằng nhau là nơi đông đúc.","s":"HSK2_17#22"},{"c":"chiet_tu","t":"Chiết tự 综 và 合 (综合)","x":"综 (zōng) – Hán Việt: Tổng (tổng hợp).\nBộ thành phần: 纟 Mịch + 宀 Miên + 二 Nhị + 小 Tiểu.\nMẹo nhớ: Gom tơ lụa tổng hợp vào trong nhà thành 2 nhóm nhỏ.\n合 (hé) – Hán Việt: Hợp.\nBộ thành phần: 人 Nhân + 一 Nhất + 口 Khẩu.\nMẹo nhớ: Người hợp nhau về 1 cái miệng.","s":"HSK2_17#24"},{"c":"cach_dung","t":"Phân biệt 来 và 去 (hướng di chuyển)","x":"来 (đến): hướng về phía người nói – 你来我家\n去 (đi): rời xa người nói – 我去你家\nỨng dụng: 进来, 出来, 进去, 出去.\n我出来的时候，我爸爸正在看电视呢。— Lúc tôi đi ra ngoài, bố tôi đang xem TV.","s":"HSK2_17#9"},{"c":"cach_dung","t":"Ba nghĩa của 想","x":"1. Muốn: 我想去买水果。— Tôi muốn đi mua hoa quả.\n2. Nghĩ, suy nghĩ: 你在想什么呀？— Bạn đang nghĩ gì vậy?\n3. Nhớ: 我想你。— Anh nhớ em.","s":"HSK2_17#17"},{"c":"cau_vi_du","t":"Ví dụ 挤 đông đúc","x":"今天星期六，坐车很挤，咱们骑车（骑自行车）吧！— Hôm nay thứ 7, đi xe đông lắm, chúng ta đạp xe đi.","s":"HSK2_17#22"},{"c":"tu_mo_rong","t":"汉英 Hán – Anh","x":"汉英 (Hàn – Yīng): Hán – Anh, tiếng Trung – tiếng Anh\n一本汉英词典 — Một quyển từ điển Trung – Anh.\n给我那本汉英资料。— Đưa tôi cuốn tài liệu song ngữ Trung – Anh kia.","s":"HSK2_17#18"},{"c":"tu_mo_rong","t":"行: được, OK","x":"行 (xíng) – Hán Việt: hành – được, OK (thể hiện sự đồng ý).\n我们明天上午八点去，好吗？— 行（好）。— Ngày mai 8 giờ sáng chúng ta đi được không? – Được!","s":"HSK2_17#21"},{"c":"tu_mo_rong","t":"综合 tổng hợp","x":"综合 (zōnghé): tổng hợp (động từ)\n综合课: môn tổng hợp","s":"HSK2_17#24"},{"c":"tu_mo_rong","t":"Từ bổ sung (phương tiện, gọi điện)","x":"打电话 (dǎ diànhuà): gọi điện thoại\n飞机 (fēijī): máy bay\n火车 (huǒchē): tàu hỏa\n走路 (zǒu lù): đi bộ\n打的 (dǎdī): đi taxi","s":"HSK2_17#31"},{"c":"ngu_phap","t":"Phủ định của 正/在/正在; động từ không dùng được","x":"Hình thức phủ định: dùng 没（有）.\nA：麦克，你是不是在听音乐呢？ B：我没有听音乐，我在听课文录音。\nLưu ý: các động từ KHÔNG đi cùng 在、正、正在:\n– Thể hiện sự tồn tại: 是 (là)、在 (ở)、有 (có)\n– Di chuyển: 来 (đến)、去 (đi)\n– 认识 (quen biết)","s":"HSK2_17#7"},{"c":"ngu_phap","t":"Trợ từ 呢 cuối câu nghi vấn","x":"呢 dùng ở cuối câu nghi vấn, giúp ngữ khí của câu ôn hòa hơn.\nA: 咱们怎么去呢？ B: 骑车去吧。\n他去不去呢？\n你上午去还是下午去呢？","s":"HSK2_17#33"},{"c":"ngu_phap","t":"Câu có hai tân ngữ","x":"Chủ ngữ + động từ + tân ngữ 1 (người) + tân ngữ 2 (vật).\nNhững động từ mang hai tân ngữ: 教 (dạy)，给 (đưa)，还 (trả lại)，问 (hỏi)，回答 (trả lời)，告诉 (kể).\n王老师教我们课文和语法。\n玛丽给我一本英文杂志。\n我问老师一个问题。","s":"HSK2_17#35"},{"c":"ngu_phap","t":"怎么 + động từ (hỏi cách thức)","x":"怎么 + động từ: hỏi cách thức thực hiện hành động, yêu cầu đối phương nói rõ làm việc đó như thế nào.\nA: 你怎么去公园？ B: 我坐车去。\nA: 咱们怎么去？ B: 骑车去吧。","s":"HSK2_17#36"},{"c":"ngu_am","t":"Trọng âm câu hai tân ngữ / câu có 吧","x":"Tân ngữ trực tiếp trong câu có 2 tân ngữ thường đọc nhấn mạnh: 林老师教我们'听力。姐姐给我一本'词典。\nCâu nghi vấn hoặc câu cầu khiến dùng 吧 thì cuối câu đọc xuống giọng: 我们走吧。你跟我一起去吧。","s":"HSK2_17#38"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"zěnme – zhème\nshíhòu – shítou\nyīnyuè – yīngyǔ\nshūdiàn – shuǐ diàn\nxiànzài – gāngcái\ntǐyù – dìlǐ","s":"HSK2_17#44"},{"c":"ngu_am","t":"Đọc liền nhiều âm tiết","x":"公共厕所 gōnggòng cèsuǒ\n公共交通 gōnggòng jiāotōng\n公用电话 gōngyòng diànhuà\n公关小姐 gōngguān xiǎojie","s":"HSK2_17#45"},{"c":"khac","t":"Luyện đọc 怎么 + V, 在/正/正在 … 呢","x":"怎么去　怎么走　怎么写　怎么读　怎么用　怎么坐车\n他在听音乐　我在看信　他在看电视\n正看电视呢　正听录音呢　正跟朋友聊天呢\n正在写信呢　正在打电话呢　正在买东西呢\n王老师教我们语法　我问你一个问题　姐姐给我一本词典","s":"HSK2_17#46"}],"18":[{"c":"tu_mo_rong","t":"Tên riêng: 上海, 珍妮","x":"上海 (Shànghǎi): Thượng Hải\n珍妮 (Zhēnní): Trân Ni – Janet","s":"HSK2_18#35"},{"c":"ngu_phap","t":"Nhắc lại 给 (động từ & giới từ)","x":"1. Động từ – đưa, đưa cho: 妈妈给我钱。— Mẹ đưa tiền cho tôi.\n2. Giới từ – A + 给 + B + động từ: A làm gì cho B.\n我给你介绍一下，这是王老师。— Tôi giới thiệu cho bạn một chút, đây là thầy giáo Vương.\n他给代表团当翻译。— Anh ấy làm phiên dịch cho đoàn đại biểu.","s":"HSK2_18#36"},{"c":"ngu_phap","t":"Câu liên động – 2 loại","x":"Câu có vị ngữ do hai động từ hoặc hai cụm động từ trở lên kết hợp tạo thành gọi là câu liên động.\n1. 去/来 + địa điểm + động từ: đi/đến đâu làm gì – 外贸代表团明天去上海参观。我来中国学汉语。\n2. Làm gì bằng cách nào – 我们坐飞机去上海。他骑车去寄包裹。我们用汉语聊天。","s":"HSK2_18#41"},{"c":"ngu_am","t":"Trọng âm logic","x":"Khi nói, để nhấn mạnh một hàm nghĩa đặc biệt, ta đọc nhấn mạnh một từ hoặc cụm từ – gọi là trọng âm logic. Trọng âm logic không có vị trí cố định, thay đổi theo ý của người nói.\nVí dụ: 珍妮明天坐飞机去上海参观。\nA: 谁明天坐飞机去上海参观？ → nhấn 珍妮\nA: 珍妮什么时候坐飞机去上海参观？ → nhấn 明天\nA: 珍妮明天怎么去上海？ → nhấn 坐飞机\nA: 珍妮明天坐飞机去哪儿参观？ → nhấn 上海\nA: 珍妮明天坐飞机去上海做什么？ → nhấn 参观","s":"HSK2_18#43"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"shùnbiàn – suíbiàn\njiāo huā – jiǎohuá\nlǚxíng – lǐxìng\nhuǒchē – huòchē\ncānguāntuán, dàibiǎotuán, lǚyóutuán, zhǔxítuán","s":"HSK2_18#45"},{"c":"khac","t":"Luyện đọc 当… / 替… / 给… / 寄…","x":"当老师　当大夫　当翻译　当律师\n替朋友借书　替我还书　给妈妈打电话　给代表团当翻译\n寄书　寄光盘　寄包裹　寄中药","s":"HSK2_18#46"}],"19":[{"c":"chiet_tu","t":"Chiết tự 宜 (便宜)","x":"宜 (yí) – Hán Việt: Nghi (phù hợp).\nBộ thành phần: 宀 Miên + 且 Thả.","s":"HSK2_19#7"},{"c":"cach_dung","t":"Hai cách đọc của 便","x":"Biàn: 顺便 (shùnbiàn) – thuận tiện.\nPián: 便宜 (piányi) – rẻ (Hán Việt: Tiện nghi).\n我觉得那件羽绒服不太便宜。— Tôi cảm thấy cái áo phao kia không rẻ lắm.","s":"HSK2_19#7"},{"c":"cach_dung","t":"Thêm 钱 khi chỉ có một đơn vị","x":"Nếu chỉ có một đơn vị là 块 (tệ), 毛 (hào) hoặc 分 (xu), trong khẩu ngữ thường thêm 钱 ở cuối.","s":"HSK2_19#27"},{"c":"cach_dung","t":"Cách đọc số tiền","x":"0.05 块: 五分\n0.26 元: 两毛六分\n3.08 元: 三块零八分\n105.90 元: 一百零五块九毛","s":"HSK2_19#28"},{"c":"tu_mo_rong","t":"Từ bổ sung","x":"面包 (miànbāo): bánh mì\n鞋 (xié): giày\n双 (shuāng): đôi\n毛衣 (máoyī): áo len","s":"HSK2_19#24"},{"c":"ngu_phap","t":"Cấu trúc 太 + tính từ + 了","x":"太 + tính từ + 了: biểu thị mức độ quá mức (diễn tả sự không hài lòng) hoặc mức độ cao (dùng để khen ngợi, cảm thán).","s":"HSK2_19#29"},{"c":"ngu_phap","t":"Lặp lại động từ – ý nghĩa ngữ khí","x":"Khi biểu thị thời gian ngắn, động tác xảy ra nhanh thì dùng hình thức lặp lại động từ; ngữ khí nhẹ nhàng, tự nhiên, thường dùng trong khẩu ngữ.\nA一A: 试一试　听一听　看一看\nAA: 试试　听听　看看\nABAB: 预习预习　复习复习　休息休息\n你看看这本词典怎么样？\n我试一试，可以吗？","s":"HSK2_19#31"},{"c":"ngu_phap","t":"Lặp động từ đã hoàn thành (A了A) và hạn chế","x":"Động tác đã xảy ra hoặc đã hoàn thành: A了A / AB了AB – 试了试　看了看　复习了复习　预习了预习.\nĐộng từ chỉ trạng thái/quan hệ như 在，有，是 KHÔNG lặp lại – không nói: 我在在听听录音呢。\nĐộng từ biểu thị động tác đang tiến hành cũng không lặp lại – không nói: 正在看看书呢。","s":"HSK2_19#32"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"dāngrán – tǎnrán\nshìshi – shíshí\nhéshì – héshí\npiányi – biànlì\ntài guì le, tài duì le, tài hǎo le, tài měi le, tài shòu le, tài féi le, tài yuǎn le, tài dà le","s":"HSK2_19#41"},{"c":"van_hoa","t":"Đơn vị Nhân dân tệ: văn viết và khẩu ngữ","x":"Đơn vị Nhân dân tệ: 元 (đồng/tệ), 角 (hào), 分 (xu).\nTrong khẩu ngữ gọi là: 块, 毛, 分.","s":"HSK2_19#26"},{"c":"khac","t":"Luyện đọc lặp động từ, 又…又…, 不A不B","x":"试试　看看　听听　读读\n试一试　看一看　听一听　读一读\n又饿又渴　又冷又累　又好又便宜　又贵又不好\n不大不小　不肥不瘦　不深不浅　不长不短","s":"HSK2_19#42"}],"20":[{"c":"cach_dung","t":"Cách đọc năm, tháng, ngày","x":"1. Năm: đọc từng chữ số – 2020: 二零二零年; 1989: 一九八九年; 1999: 一九九九年.\n2. Ngày: số + 号/日 (一号/日, 二号/日, 十一号/日); Tháng: số + 月 (一月, 二月, 五月, 九月).\n3. Thứ tự ngược với tiếng Việt, từ lớn đến nhỏ: năm – tháng – ngày – giờ: 今天是2020年8月29号（日）9点。","s":"HSK2_20#11"},{"c":"ngu_phap","t":"Câu vị ngữ danh từ","x":"Vị ngữ do danh từ, cụm danh từ, số lượng từ, từ chỉ thời gian đảm nhiệm. Cấu trúc: chủ ngữ + danh từ.\nTrước danh từ có thể BỎ 是. Phủ định: 不是 + danh từ.\n今天几号？— 今天十月八号。\n今天星期几？— 今天星期二。\n苹果一斤多少钱？— 一斤两块五。\n他二十岁。\n明天阴天（yīntiān: trời âm u）。\n我中国人，他美国人。\n现在几点？— 现在八点。","s":"HSK2_20#39"},{"c":"van_hoa","t":"Năm con giáp","x":"2026年是马年，去年是蛇年。— Năm 2026 là năm con ngựa, năm ngoái là năm con rắn.","s":"HSK2_20#16"},{"c":"khac","t":"Luyện đọc các mốc ngày","x":"1945年9月2日\n1949年10月1日\n1975年4月30日\n2021年8月9日\n2010年1月1日","s":"HSK2_20#12"}],"21":[{"c":"chiet_tu","t":"Chiết tự 操 và 场 (操场)","x":"操 (cāo – động từ): Thao (thao luyện, tập luyện).\nBộ thành phần: ⺘ Thủ + 喿 Táo (品 Phẩm + 木 Mộc).\n场 (chǎng – danh từ): Trường (sân).\nBộ thành phần: 土 Thổ + 𠃓.","s":"HSK2_21#20"},{"c":"chiet_tu","t":"Chiết tự 洗 và 澡 (洗澡)","x":"洗 (xǐ) – Hán Việt: Tẩy (tẩy rửa).\nBộ thành phần: 氵 Ba chấm thủy + 先 Tiên.\n澡 (zǎo) – Hán Việt: Táo (tắm rửa).\nBộ thành phần: 氵 Ba chấm thủy + 喿 Táo.","s":"HSK2_21#24"},{"c":"chiet_tu","t":"Chiết tự 睡 và 觉 (睡觉)","x":"睡 (shuì) – Hán Việt: Thụy (ngủ).\nBộ thành phần: 目 Mục + 垂 Thùy (rủ xuống).\n觉 (jiào) – Hán Việt: Giác (giấc ngủ).\nBộ thành phần: 𭕄 + 冖 Mịch + 见 Kiến.","s":"HSK2_21#27"},{"c":"chiet_tu","t":"Chiết tự 级 (年级)","x":"级 (jí – danh từ): Cấp (cấp, bậc).\nBộ thành phần: 纟 Mịch (sợi tơ) + 及 Cập.","s":"HSK2_21#31"},{"c":"tu_mo_rong","t":"饭 và các bữa ăn","x":"饭 (fàn): cơm, bữa cơm (danh từ)\n早饭: bữa sáng\n午饭: bữa trưa\n晚饭: bữa tối\n你吃早饭了吗？我打算去买包子和水果，你想一起去吗？— Bạn ăn sáng chưa? Tôi định đi mua bánh bao và hoa quả, bạn muốn đi cùng không?","s":"HSK2_21#9"},{"c":"tu_mo_rong","t":"教: 教授, 教师, 教师节","x":"教 (động từ): Giáo (giáo dục, giảng dạy). A 教 B + …: A dạy B cái gì.\n教授: giáo sư\n教师: giáo viên, nhà giáo = 老师\n11月20日是越南教师节。— Ngày 20/11 là ngày Nhà giáo Việt Nam.","s":"HSK2_21#18"},{"c":"tu_mo_rong","t":"室: 教室, 办公室","x":"室 (shì – danh từ): phòng\n办公室: văn phòng\n教室 (jiàoshì – danh từ): phòng học, giảng đường\n我们学校的教室又新又大。— Phòng học của trường chúng tôi vừa mới vừa to.","s":"HSK2_21#19"},{"c":"tu_mo_rong","t":"操场 / 机场","x":"操场 (cāochǎng): thao trường, sân tập\n机场: sân bay","s":"HSK2_21#20"},{"c":"tu_mo_rong","t":"Các từ với 洗; 洗澡","x":"洗衣服: giặt quần áo\n洗碗: rửa bát\n洗手: rửa tay\n洗手间: nhà vệ sinh\n洗澡 (xǐzǎo – động từ ly hợp): tắm rửa","s":"HSK2_21#24"},{"c":"tu_mo_rong","t":"睡觉 ngủ","x":"睡觉 (shuìjiào – động từ ly hợp): ngủ\n我每天都是晚上十一点半睡觉。— Ngày nào tôi cũng đi ngủ lúc 23:30.","s":"HSK2_21#27"},{"c":"tu_mo_rong","t":"年级 lớp, năm thứ","x":"年级 (niánjí – danh từ): Niên cấp (lớp, năm thứ). Số thứ tự + 年级: lớp…, năm thứ…\nA: 你今年几年级的？— Bạn năm nay là năm thứ mấy?\nB: 我是大学二年级（大二）的学生。— Tôi là sinh viên đại học năm 2.","s":"HSK2_21#31"},{"c":"ngu_phap","t":"Người + 这儿/那儿 thành từ chỉ địa điểm","x":"Sau 来 (đến)，去 (đi)，在 (ở)，从 (từ)，到 (tới) phải là tân ngữ chỉ địa điểm. Nếu là danh từ/đại từ chỉ người thì phải thêm 这儿 hoặc 那儿 phía sau.\n他明天来我这儿。\n我去王老师那儿。\n我去朋友那儿聊天儿。","s":"HSK2_21#43"},{"c":"ngu_phap","t":"Cách đọc giờ","x":"Hỏi giờ: 现在几点？\n8:00 八点\n8:05 八点（零）五（分）\n8:15 八点一刻 / 八点十五（分）\n8:30 八点半 / 八点三十（分）\n8:45 八点三刻 / 八点四十五（分）\n8:55 八点五十五（分）/ 差五分九点","s":"HSK2_21#46"},{"c":"ngu_phap","t":"Thứ tự thời gian: lớn → nhỏ","x":"Thời gian được biểu đạt từ đơn vị lớn đến nhỏ: 年，月，日，点（钟），分.\n1949年10月1日上午八点二十分\n2020年9月25日晚上十点半","s":"HSK2_21#47"},{"c":"ngu_phap","t":"Chức năng của từ chỉ thời gian trong câu","x":"Từ chỉ thời gian có thể làm chủ ngữ, vị ngữ, định ngữ, trạng ngữ.\n现在八点半。(vị ngữ)\n今天星期五。(vị ngữ)\n我看晚上七点一刻的电影。(định ngữ)\n我明天上午有课。(trạng ngữ)","s":"HSK2_21#48"},{"c":"ngu_phap","t":"Thời gian đứng trước địa điểm","x":"Khi câu có cả trạng ngữ chỉ thời gian và trạng ngữ chỉ địa điểm, thời gian thường đứng trước.\n我晚上在宿舍看书。/ 晚上我在宿舍看书。(không nói: 我在宿舍晚上看书)\n去年我在北京学习。/ 我去年在北京学习。(không nói: 我在北京去年学习)","s":"HSK2_21#49"},{"c":"ngu_am","t":"觉 hai cách đọc","x":"jiào – ngủ: 睡觉\njué – cảm nhận: 觉得","s":"HSK2_21#28"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu; biến điệu 一","x":"měi tiān – míngtiān\nqǐ chuáng – qìchuán\nchūfā – shūfǎ\njiàoshì – jiàoshī\nxǐ zǎo – qǐ zǎo\nshuì jiào – shuǐdào\nThành ngữ: 一片好心 yí piàn hǎoxīn; 一帆风顺 yì fān fēng shùn; 一五一十 yì wǔ yì shí; 一心一意 yì xīn yí yì; 一言为定 yì yán wéi dìng; 一切顺利 yíqiè shùnlì","s":"HSK2_21#55"},{"c":"khac","t":"Luyện đọc 每 / 半 / 上 / 带","x":"每天　每星期　每月　每年　每个同学　每个老师\n八点半　十点半　半天　半月　半年　半个\n上课　上车　上学\n带午饭　带词典　带钱","s":"HSK2_21#56"}],"22":[{"c":"cach_dung","t":"Phân biệt 去, 到, 来","x":"到 + địa điểm/thời gian: đến.\n去 (đi): nhấn mạnh sự di chuyển – 我去学校。\n到 (đến): nhấn mạnh điểm đích – 你到学校了吗？\n来 (đến): nhấn mạnh hướng lại gần người nói – 你来学校吧！我在学校等你！","s":"HSK2_22#23"},{"c":"tu_mo_rong","t":"所以 nên, vì vậy","x":"所以 (suǒyǐ): nên, vì vậy\n我觉得书法非常有趣，所以我对练习写书法感兴趣。— Tôi thấy thư pháp rất thú vị, nên tôi có hứng thú luyện viết thư pháp.","s":"HSK2_22#33"},{"c":"ngu_phap","t":"以前 / 以后 đứng độc lập hoặc làm trạng ngữ","x":"以前, 以后 có thể dùng độc lập: 以前我是公司职员，现在是留学生。现在他是学生，以后想当教师。\nPhía trước có thể thêm từ ngữ khác, làm trạng ngữ chỉ thời gian: 来中国以前我是公司职员。我一个星期以后回来。","s":"HSK2_22#41"},{"c":"ngu_phap","t":"Câu kiêm ngữ","x":"Dùng khi muốn diễn đạt \"yêu cầu ai đó làm việc gì\".\nVị ngữ gồm hai cụm động từ – tân ngữ; tân ngữ của động từ 1 đồng thời là chủ ngữ của động từ 2; động từ 1 thường mang nghĩa sai khiến như 请，叫，让.\nCấu trúc: chủ ngữ + động từ sai khiến (叫/请/让) + kiêm ngữ + động từ 2 + tân ngữ.","s":"HSK2_22#44"},{"c":"ngu_phap","t":"Phân tích câu kiêm ngữ","x":"Chủ ngữ | Động từ 1 | Kiêm ngữ | Động từ 2 | Tân ngữ\n（我）| 请 | 你们 | 谈谈 | 自己的爱好\n老师 | 叫 | 大家 | 回答 | 问题\n公司 | 派 | 他 | 来 | 中国\n我 | 想请 | 一个老师 | 教 | 我书法","s":"HSK2_22#45"},{"c":"ngu_am","t":"Biến âm của 啊 (是啊)","x":"是啊 biểu thị ngữ khí khẳng định.\n啊 biến âm theo âm cuối của âm tiết đứng trước:\n– a, e, i, o, ü → đọc \"ya\", có thể viết 呀\n– u, ao, ou → đọc \"wa\", có thể viết 哇\n– n → đọc \"na\", có thể viết 哪\n– ng → đọc \"nga\"\nKhi viết có thể đều dùng 啊.","s":"HSK2_22#40"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu; biến điệu 不","x":"zìjǐ – zhījǐ\njīngjù – jīngjì\nyèyú – yěxǔ\nfēicháng – péicháng\nxìngqù – xīngqī\nyǐqián – yì nián\nBiến điệu 不: bù dǒng wàiyǔ; bú bì kèqi; bú yào kuàng kè; bú pà kùnnan; bù nán xué huì; bú yào hòutuì","s":"HSK2_22#51"},{"c":"khac","t":"Luyện đọc 啊 / 喜欢 / 爱好 / 以前以后 / 感兴趣 / kiêm ngữ","x":"来啊　去啊　跑啊　走啊　好啊　是啊　看啊　想啊\n喜欢汉语　喜欢音乐　喜欢学习　喜欢看电视\n爱好京剧　爱好音乐　爱好体育　爱好运动\n上课以前　睡觉以前　下课以后　回家以后\n对玩电脑感兴趣　对京剧感兴趣　对这个不感兴趣\n请你说　请大家看　请你们读\n派我来中国　派他去上海　让我们谈爱好\n请老师教书法　请老师教英语　请老师教京剧","s":"HSK2_22#52"}],"23":[{"c":"cach_dung","t":"Số từ + lượng từ + 左右: khoảng","x":"Số từ + lượng từ + 左右: khoảng, xấp xỉ…\n二十岁左右 — khoảng 20 tuổi","s":"HSK2_23#8"},{"c":"tu_mo_rong","t":"Từ mới bổ sung","x":"迷路 (mí lù): lạc đường\n公共汽车 (gōnggòng qìchē): xe buýt\n出租车 (chūzūchē): taxi\n司机 (sījī): tài xế\n算了吧 (suàn le ba): thôi được rồi\n平方米 (píngfāng mǐ): mét vuông\n高 (gāo): cao","s":"HSK2_23#31"},{"c":"ngu_phap","t":"有 biểu thị ước lượng","x":"离这儿有多远？\n有 ở giữa câu biểu thị sự ước lượng, ước chừng.\n她有二十岁。\n从这儿到博物馆有两三公里。","s":"HSK2_23#33"},{"c":"ngu_phap","t":"Hai số liền nhau biểu thị số ước lượng","x":"Hai số liền nhau biểu thị số xấp xỉ: 有七八百米；五六百米；三四公里；十七八个；二十三四岁","s":"HSK2_23#34"},{"c":"ngu_phap","t":"多 + 远/高/大/重/长？","x":"Dùng để hỏi cự ly, độ cao, tuổi tác, diện tích, trọng lượng, độ dài…\n1. Cự ly: 从学校到博物馆（有）多远？—— 有五六公里。\n2. Độ cao: 你多高？—— 一米七八。\n3. Tuổi tác: 小王多大？—— 她二十岁。\n4. Trọng lượng: 这个箱子多重？—— 20公斤。\n5. Độ dài: 长江有多长？—— 6300多公里。","s":"HSK2_23#35"},{"c":"ngu_phap","t":"Chức năng ngữ pháp của phương vị từ","x":"Phương vị từ giống danh từ, có thể làm chủ ngữ, tân ngữ, định ngữ hoặc trung tâm ngữ.\n里边有两个人。\n邮局在西边。\n左边的椅子是我的。\n前边的学生是我们班的。\n图书馆里边有很多阅览室。","s":"HSK2_23#38"},{"c":"ngu_phap","t":"Phương vị từ làm định ngữ / trung tâm ngữ","x":"Phương vị từ làm định ngữ thì phải thêm 的: 外边的教室；里边的房间；中间的小朋友；前边的同学.\nPhương vị từ làm trung tâm ngữ thì phía trước không cần 的: 教室里边；邮局东边；学校外边.","s":"HSK2_23#39"},{"c":"ngu_phap","t":"Lược bỏ 边; không dùng 里 sau tên nước, địa danh","x":"Danh từ + 里边/上边 có thể lược bỏ 边: 屋子里有很多人。桌子上有很多书。\nSau tên quốc gia, địa danh không thêm 里. Không nói: 在中国里；在北京里. Mà nói: 在中国；在北京.","s":"HSK2_23#40"},{"c":"ngu_phap","t":"Ba cấu trúc biểu thị sự tồn tại: 在, 有, 是","x":"1. 在 – phương vị, nơi chốn của sự vật: danh từ (người/vật) + 在 + từ chỉ phương vị/nơi chốn: ai/cái gì ở đâu.\n2. 有 – tại một nơi tồn tại người hoặc vật: từ chỉ phương vị/nơi chốn + 有 + danh từ: ở đâu có cái gì.\n3. 是 – biết nơi đó có người/vật nhưng muốn xác định rõ là ai/cái gì: từ chỉ phương vị/nơi chốn + 是 + danh từ: ở đâu là cái gì.","s":"HSK2_23#41"},{"c":"ngu_phap","t":"Giới từ 离, 从, 往","x":"Các giới từ 离 (cách), 从 (từ), 往 (hướng về) kết hợp với từ chỉ nơi chốn, đặt trước động từ làm trạng ngữ.\n1. 离 – khoảng cách: 北京离上海1462公里。(không nói: 北京从上海1462公里。)\n2. 从 – điểm bắt đầu (nơi chốn hoặc thời gian): 太阳从东边升起。他从美国来中国。我们从八点开始上课。玛丽从学校去大使馆。\n3. 往 – phương hướng: 从这儿往东走。我要往那边去，你呢？往前一直走就是博物馆。","s":"HSK2_23#44"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"dìfang – dīfáng\nzúqiú – chūqiū\ngōnglǐ – kōngqì\nzhōngjiān – zhòngdiǎn\nyìzhí – yì zhī\ndà lóu – dǎ qiú\ndōngbian xībian nánbian běibian shàngbian xiàbian zuǒbian yòubian lǐbian wàibian qiánbian hòubian","s":"HSK2_23#50"},{"c":"khac","t":"Luyện đọc 往 / 在哪儿 / 到 / 离 / 有多…","x":"往前走　往后走　往左走　往右走　往东跑　往西开　往南看　往北去　往里坐　往外坐　往左拐　往右拐\n食堂在哪儿　图书馆在哪儿　医院在哪儿　邮局在哪儿　博物馆在哪儿　银行在哪儿\n到学校　到医院　到北京　到红绿灯那儿　去朋友那儿　在老师那儿\n离家不远　离学校很近　离这儿很远\n有多长　有多远　有多大","s":"HSK2_23#51"}],"24":[{"c":"tu_mo_rong","t":"Từ mới bổ sung: hoạt động (1-6)","x":"开车 (kāichē): lái xe\n游泳 (yóuyǒng): bơi lội\n钓鱼 (diàoyú): câu cá\n停车 (tíngchē): dừng xe, đỗ xe\n滑冰 (huábīng): trượt băng\n拍照 (pāizhào): chụp ảnh","s":"HSK2_24#31"},{"c":"tu_mo_rong","t":"Từ mới bổ sung: hoạt động, giấy tờ (7-12)","x":"抽烟 / 吸烟 (chōuyān / xīyān): hút thuốc\n唱歌 (chànggē): ca hát\n跳舞 (tiàowǔ): khiêu vũ, múa\n打篮球 (dǎ lánqiú): chơi bóng rổ\n护照 (hùzhào): hộ chiếu\n驾照 (jiàzhào): giấy phép lái xe","s":"HSK2_24#32"},{"c":"ngu_phap","t":"Chú thích: 再 + V và 从……到……","x":"再 + động từ: Thể hiện hành động lặp lại / tiếp tục. VD: 你能不能再说一遍？您再说一遍，好吗？明天我再来。\n从……到……: Từ… đến… VD: 从几点到几点上课？我们上午从八点到十二点上课。从七月十号到八月三十一号放假 (放假: nghỉ lễ)。","s":"HSK2_24#34"},{"c":"ngu_phap","t":"Đặc điểm động từ năng nguyện","x":"Động từ năng nguyện biểu thị năng lực, yêu cầu, mong muốn, khả năng. VD: 能、会、可以、要、想.\nCấu trúc: Động từ năng nguyện + động từ.\nPhủ định: 不 + động từ năng nguyện + động từ.\nNghi vấn: dùng 吗 hoặc dạng chính phản: 能…吗？= 能不能…？; 可以…吗？= 可不可以…？\nKhông thể lặp lại: không nói 能能、会会、要要.\nCuối câu không được thêm 了.","s":"HSK2_24#36"},{"c":"ngu_phap","t":"Phân biệt 能 – 可以 – 会: ví dụ và lỗi sai","x":"能: Nhấn mạnh năng lực tự nhiên hoặc điều kiện cho phép — 你一分钟能写多少汉字？\n可以: Được phép làm gì — 我可以进去吗？\n会: Biết làm gì (do học tập, rèn luyện) — 他会说英语和汉语。\nDạng chính phản đặt ở động từ năng nguyện: A：你会不会打太极拳？（不能说：你会打不打太极拳）B：我不会。","s":"HSK2_24#37"},{"c":"ngu_phap","t":"Phủ định: 不能 và 不会","x":"不能: Không thể / không có khả năng / do hoàn cảnh không cho phép.\n(1) A：这儿可以抽烟吗？B：对不起，这儿不能抽烟。(Hỏi bằng 可以, trả lời phủ định bằng 不能.)\n(2) A：下午你能不能跟我一起去？B：对不起，我有事，不能跟你一起。（不能说：对不起，我有事，不会跟你一起。）\n(3) 玛丽感冒了，不能来上课。\n不会 (phủ định của 会): A：你会不会打太极拳？B：我不会打太极拳。","s":"HSK2_24#38"},{"c":"ngu_phap","t":"Phân biệt 想 và 要 (động từ năng nguyện)","x":"Mức độ mong muốn: 想 – nhẹ nhàng, chủ quan, chưa chắc thực hiện; 要 – quyết tâm, chắc chắn, có thể mang tính đòi hỏi hoặc mệnh lệnh.\nPhủ định: 不想.\n很多外国学生想来中国留学。\n你想不想学太极拳？（不能说：你想学不学太极拳）\nA：今天下午你想不想去商店？B：我要学太极拳，不想去商店。（不能说：我要学太极拳，不要去商店）\n不要 + động từ: Đừng làm gì (= 别 + động từ) — 请大家不要说话。（请大家别说话）","s":"HSK2_24#40"},{"c":"ngu_phap","t":"想 và 要 làm động từ chính (+ tân ngữ)","x":"想 (+ tân ngữ):\n(1) Nhớ — 我有点想家。\n(2) Nghĩ — 你们想想这个问题怎么回答。\n要 (+ tân ngữ): Muốn có\n(1) A：你要什么？B：我要一斤苹果。\n(2) A：你要点儿什么？B：我要一杯咖啡。","s":"HSK2_24#41"},{"c":"ngu_phap","t":"怎么 + phủ định: hỏi nguyên nhân","x":"怎么 đứng trước dạng phủ định của động từ để hỏi nguyên nhân.\nA：玛丽怎么没来？B：老师，她今天有点不舒服，要去医院，不能来上课。\nA：昨天你怎么没去学太极拳？B：昨天我有事。\nA：你怎么不喝啤酒？B：我不喜欢喝啤酒。","s":"HSK2_24#42"}],"25":[{"c":"ngu_phap","t":"还 + tính từ: tạm chấp nhận được","x":"还 (phó từ chỉ mức độ) + tính từ: Vẫn, vẫn còn – mức độ tạm, miễn cưỡng chấp nhận được.\n他汉语说得还可以。\n这个房子还不错。\n爸爸妈妈身体还好。","s":"HSK2_25#33"},{"c":"ngu_phap","t":"Bổ ngữ trạng thái: chức năng + ví dụ","x":"Bổ ngữ trạng thái chủ yếu dùng để miêu tả, phán đoán hoặc đánh giá kết quả, trình độ, trạng thái…\nKhẳng định: Động từ + 得 + (很) + tính từ.\n(1) A：你每天起得早不早？B：我每天起得很早。\n(2) A：她太极拳打得怎么样？B：打得很不错。\n(3) A：她说汉语说得好吗？B：说得很好。\n(4) 他喝啤酒喝得很多。","s":"HSK2_25#35"},{"c":"ngu_phap","t":"Bổ ngữ trạng thái: câu hỏi chính phản và phủ định","x":"Nghi vấn chính phản: Động từ + 得 + tính từ + 不 + tính từ.\n你今天起得早不早？\n她汉语说得好不好？\nPhủ định (ví dụ):\nA：你星期天起得早吗？B：不早。\nA：他汉字写得好不好？B：不好。（他汉字写得不好。）","s":"HSK2_25#37"},{"c":"ngu_phap","t":"Lược bỏ động từ thứ nhất khi có tân ngữ","x":"Trong giao tiếp thực tế, động từ thứ nhất thường được lược bỏ:\n他打太极拳打得很好。=> 他太极拳打得很好。\n她说汉语说得很好。=> 她汉语说得很流利。","s":"HSK2_25#38"},{"c":"ngu_am","t":"Bổ ngữ trạng thái phải đọc nhấn mạnh","x":"Trong câu có bổ ngữ trạng thái, bổ ngữ trạng thái phải đọc nhấn mạnh (dấu ' đánh dấu chỗ nhấn):\n老师说得很'清楚。\n她教得很'好。\n麦克跑步跑得很'快。","s":"HSK2_25#40"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"liúlì – nǔlì\nbiǎoyǎn – biǎoyáng\njiémù – juéwù\njìnbù – xìngfú\nnǎli – nàli\npǎo bù – bàofù","s":"HSK2_25#47"},{"c":"van_hoa","t":"Câu nói và thơ cổ luyện đọc","x":"世上无难事，只怕有心人 (shì shàng wú nán shì, zhǐ pà yǒu xīn rén)\n欲穷千里目，更上一层楼 (yù qióng qiān lǐ mù, gèng shàng yì céng lóu)","s":"HSK2_25#47"},{"c":"khac","t":"Cụm từ luyện tập (练习)","x":"为学习汉语 / 为练习书法 / 为练习打太极拳\n坚持学习 / 坚持锻炼 / 坚持练习\n这么便宜 / 这么容易 / 这么难 / 这么努力\n怎么这么便宜 / 怎么这么难 / 怎么这么容易 / 怎么这么努力\n学得怎么样 / 说得怎么样 / 写得怎么样 / 唱得怎么样\n读得很快 / 打得很好 / 做得很对 / 表演得很好\n说得很流利 / 唱得很好 / 写得很快 / 学得很认真\n说得对不对 / 唱得好不好 / 起得早不早 / 睡得晚不晚\n说得不对 / 唱得不好 / 起得不早 / 睡得不晚","s":"HSK2_25#48"}],"26":[{"c":"ngu_phap","t":"吧 nghi vấn; 不是……吗？","x":"(1) 你给我打电话了吧？ – Trợ từ ngữ khí 吧 ở đây biểu thị ngữ khí nghi vấn.\n(2) 你不是要上托福班吗？ – 不是……吗？: 'Chẳng phải là… sao?' / 'Không phải là… à?' – dùng khi người nói cho rằng điều đó là đúng, chỉ muốn xác nhận lại hoặc bày tỏ sự ngạc nhiên.\n他不是很忙吗？ — Anh ấy chẳng phải là rất bận sao?","s":"HSK2_26#29"},{"c":"ngu_phap","t":"Câu hỏi chính phản 是不是","x":"是不是 có thể đứng trước vị ngữ, ở đầu câu hoặc cuối câu.\nA：你是不是想家了？B：是。我常常想家。\nA：你们输了，是不是？B：是。","s":"HSK2_26#30"},{"c":"ngu_phap","t":"Trợ từ ngữ khí 了 cuối câu","x":"Trợ từ ngữ khí 了 dùng ở cuối câu, biểu thị ngữ khí khẳng định: sự việc đã xảy ra, động tác đã hoàn thành hoặc trạng thái thay đổi.\n安娜跟外贸代表团去上海了。\n田芳的手机关了。\n他已经睡了。别叫他了。\n她今年20岁了。\n饭好了。我们吃饭吧。","s":"HSK2_26#32"},{"c":"ngu_phap","t":"So sánh trước và sau khi sự việc xảy ra","x":"Trước khi sự việc xảy ra (事情发生前): A：你去哪儿？B：我去商店。A：你买什么？B：我买衣服。\nSau khi sự việc xảy ra (事情发生后): A：你去哪儿了？B：我去商店了。A：你买什么了？B：我买衣服了。","s":"HSK2_26#33"},{"c":"ngu_phap","t":"Câu hỏi ……了没（有）？ và phủ định 还没……呢","x":"Câu hỏi: ……了 + 没（有）？ hoặc ……了吗？\nPhủ định: 还没（有）……（呢） – sự việc đến hiện tại vẫn chưa xảy ra hoặc chưa hoàn thành.\n1. A：她回家了吗？B：她还没有回家呢。\n2. A：他走了没有？B：他还没有走呢。\n3. A：你写完了吗？B：还没完呢。","s":"HSK2_26#34"},{"c":"ngu_phap","t":"Khi nào KHÔNG dùng 了","x":"Câu phủ định không dùng 了:\n我昨天没去商店。（不说：我昨天没去商店了。）\n她觉得不舒服，今天没有上课。（不说：……没有上课了。）\nĐộng tác mang tính thường xuyên thì cuối câu không dùng 了:\n每天早上她都去打太极拳。（不说：每天早上她都去打太极拳了。）\n她常来我家玩儿。（不说：她常来我家玩儿了。）","s":"HSK2_26#35"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"cāochǎng – cǎochǎng\nbǐsài – bìsè\nzhùhè – chùsuǒ\nyǐjīng – yǔjìng\ntuōfú – tuōfù\nzúqiú – chūqiū","s":"HSK2_26#41"}],"27":[{"c":"ngu_phap","t":"怎么了: hỏi tình hình, nguyên nhân","x":"Khi hỏi về tình hình đã xảy ra và nguyên nhân, lý do của nó thì dùng 怎么了 (Sao vậy?).\n1. A：你怎么了？B：我感冒了。\n2. A：玛丽怎么了？B：她肚子疼。\n3. A：你的电脑怎么了？B：不能上网了。","s":"HSK2_27#31"},{"c":"ngu_phap","t":"就 = chỉ (phạm vi, số lượng nhỏ)","x":"就 đứng trước cụm động – tân, biểu thị phạm vi, số lượng mà động tác đề cập đến là nhỏ, ít.\n我就喝了一杯啤酒。\n我就有一本词典。\n这种糖也不错，就吃一个吧。\n就吃了一些鱼和牛肉。","s":"HSK2_27#32"},{"c":"ngu_phap","t":"Lặp động từ ly hợp (AAB) và 别……了","x":"跳跳舞 là hình thức lặp lại của động từ ly hợp 跳舞; tương tự: 唱唱歌、睡睡觉、聊聊天……\n别……了 dùng trong khẩu ngữ, biểu thị sự an ủi hoặc khuyên nhủ: 别难过了。别哭了。上课了，请大家别说话了。","s":"HSK2_27#33"},{"c":"ngu_phap","t":"Trợ từ động thái 了: V + 了","x":"Động từ + 了: Biểu thị động tác đã hoàn thành.\nSo sánh: A：你喝吗？B：喝。A：他喝吗？B：他不喝。\nvới: A：你喝了吗？B：喝了。A：他喝了吗？B：他没（有）喝。","s":"HSK2_27#35"},{"c":"ngu_phap","t":"了 cuối câu và 了 sau động từ","x":"Trợ từ ngữ khí (cuối câu): biểu thị sự thay đổi, có trạng thái mới — 我现在胖了。(Bây giờ tôi béo rồi – trước đây không béo); 我以前很喜欢她，现在我不喜欢了。\nTrợ từ động thái (sau động từ): biểu thị hành động đã hoàn thành — 我买了三本书。","s":"HSK2_27#36"},{"c":"ngu_phap","t":"V + 了 + tân ngữ cần số lượng từ/định ngữ","x":"Khi động từ + 了 mang tân ngữ thì trước tân ngữ phải có số lượng từ hoặc từ ngữ khác làm định ngữ:\n我买了一本书。\n他喝了一瓶啤酒。\n我吃了一些鱼和牛肉。","s":"HSK2_27#37"},{"c":"ngu_phap","t":"Tân ngữ không định ngữ: thêm 了 cuối câu hoặc động tác 2","x":"Khi trước tân ngữ không có số lượng từ hoặc định ngữ, cuối câu phải có trợ từ ngữ khí 了:\n我买了书了。（我不买了。/ 你不要给我买了。）\n我们吃了晚饭了。（不吃了。/ 你不用给我们做了。）\n我喝了药了。（不喝了。/ 你放心吧。）\nNếu cuối câu không có 了 thì cần thêm động từ hoặc phân câu biểu thị động tác thứ hai xảy ra ngay sau đó:\n昨天，我买了书就回学校。\n晚上我们吃了饭就去跳舞。（说话的时间是下午）","s":"HSK2_27#38"},{"c":"ngu_phap","t":"Câu liên động: không đặt 了 sau V1","x":"Trong câu liên động, sau động từ thứ nhất (V1) không có 了.\n1. 他去上海参观了。（不说：他去了上海参观。）\n2. 她们坐飞机去香港了。（不说：她们坐了飞机去香港。）","s":"HSK2_27#39"},{"c":"ngu_phap","t":"Câu hỏi và phủ định với 了 động thái","x":"Câu hỏi: …了没（有）？ hoặc động từ + 没（有）+ động từ.\nA：你给妈妈打电话了没有？B：打了。\nA：她来了没有？B：她没来。\nA：你看电影了没有？B：看了。\nPhủ định: 没有 + động từ, sau động từ KHÔNG dùng 了.\n1. A：你吃了几片药？B：我没有吃药。\n2. A：你买了几张地图？B：我没有买地图。","s":"HSK2_27#40"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"dùzi – tùzi\ndàbiàn – dábiàn\njiéguǒ – jiēzhe\nxiāohuà – xiàohua\ngǎndào – kàn dào\ndànshì – dāngshí\nwǔhuì – wùhuì\nlìhai – lìhài","s":"HSK2_27#47"},{"c":"khac","t":"Cụm từ luyện tập","x":"头疼 / 牙疼 / 肚子疼\n头疼得很厉害 / 牙疼得很厉害 / 肚子疼得厉害\n别说了 / 别哭了 / 别喝了 / 别睡了 / 别看了 / 别去了\n检查身体 / 检查一下 / 检查了一下\n感到寂寞 / 感到高兴 / 感到不舒服","s":"HSK2_27#48"}],"28":[{"c":"tu_mo_rong","t":"客 và 厅: chiết tự + từ mở rộng","x":"客 Kè: Khách. Bộ thành phần: 宀 Miên + 各 Các. Mẹo nhớ: Trong nhà có các vị khách.\n客人 (danh từ): Khách, khách khứa.\n客气 (tính từ): Khách sáo, khách khí.\n厅 Tīng: Sảnh, phòng lớn. Bộ thành phần: 厂 Xưởng + 丁 Đinh.\n客厅 (kètīng – danh từ): Phòng khách.\n这套房子的客厅又大又干净，她很满意。 — Phòng khách của căn nhà này vừa rộng vừa sạch, cô ấy rất vừa ý.","s":"HSK2_28#17"},{"c":"ngu_phap","t":"Tính từ + 了（一）点儿: chưa vừa ý","x":"Tính từ + 了（一）点儿 biểu thị chưa đạt yêu cầu hoặc không phù hợp với tiêu chuẩn nào đó – tức không vừa ý.\n这几套房子，厨房、卧室还可以，但是客厅面积小了点儿。\n这种毛衣五百块一件，贵了点儿。\n这个语法难了点儿。","s":"HSK2_28#40"},{"c":"khac","t":"Câu luyện đối chiếu 就 – 才","x":"我六点钟就起床了。/ 他七点钟才起床。\n练习她一个小时就做完了。/ 我两个小时才做完。\n坐飞机一个小时就到了。/ 坐火车八个小时才到。\n明天我吃了早饭就去医院。/ 昨天我吃了早饭就去医院了。\n明天我下了课就去看她。/ 昨天我下了课就去看她了。","s":"HSK2_28#53"}],"29":[{"c":"ngu_phap","t":"Câu chữ 把 (giới thiệu sơ bộ)","x":"把这个句子翻译成汉语怎么说？ — Dịch câu này sang tiếng Trung thì nói thế nào?\nCấu trúc câu chữ 把 (giới từ): Chủ ngữ + 把 + người/vật bị tác động + hành động + kết quả – ai đó tác động vào người/vật nào đó và làm thay đổi trạng thái của nó.","s":"HSK2_29#9"},{"c":"ngu_phap","t":"Các từ làm bổ ngữ kết quả + ví dụ","x":"Động từ 完、懂、见、开、上、到、给、成 và tính từ 好、对、错、熟、早、晚 đều có thể đứng sau động từ làm bổ ngữ kết quả.\nKhẳng định: (1) 我听懂了老师的话。(2) 我看见玛丽了。她在操场打太极拳呢。(3) 今天的作业我做完了。(4) 我答错了两道题。\nPhủ định: 没（有）+ V + bổ ngữ kết quả (KHÔNG có 了): (5) 你没有听见吗？安娜在叫你。(6) 这课课文我没有看懂。(7) 我没有看见你的词典。(8) 这件衣服没洗干净。(9) 这道题我没做对。\nCâu hỏi ……了没有？: (10) A：你看见玛丽了没有？B：看见了。(11) A：今天的作业你做完了没有？B：还没做完呢。(12) A：这个题你做对了没有？B：没做对。","s":"HSK2_29#29"},{"c":"ngu_phap","t":"Vị trí tân ngữ với bổ ngữ kết quả","x":"Động từ + bổ ngữ kết quả + tân ngữ:\n我看错题了。（不说：我看题错了。）\n我没看见你的词典。（khác với 我没看你的词典。）\nĐộng từ + bổ ngữ kết quả + 了 + tân ngữ:\n我做错了两道题。\n我只翻译对了一个句子。","s":"HSK2_29#30"},{"c":"ngu_phap","t":"Bổ ngữ kết quả 上","x":"Biểu thị hai sự vật trở lên tiếp xúc với nhau: 关上门吧。请同学们合上书，现在听写。\nBiểu thị một sự vật gắn vào / lưu lại ở đâu đó: 请在这儿写上你的名字。你穿上这件毛衣试试。","s":"HSK2_29#31"},{"c":"ngu_phap","t":"Bổ ngữ kết quả 到 (3 cách dùng)","x":"Động tác đạt được mục đích: 我找到王老师了。罗兰买到那本书了。\nĐộng tác khiến sự vật đến được nơi nào đó (tân ngữ chỉ nơi chốn): 我昨天很晚才回到家。我们学到二十九课了。\nĐộng tác kéo dài đến một thời điểm: 星期六早上我睡到九点才起床。我每天晚上都学到十一二点。","s":"HSK2_29#33"},{"c":"ngu_phap","t":"Cụm chủ vị làm định ngữ","x":"(Chủ ngữ + vị ngữ) + 的 + trung tâm ngữ.\n田芳借给你的那本书你看完了没有？\n我们现在学的词大概有一千多个。\n你要的那本书我给你买到了。","s":"HSK2_29#34"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"kǎoshì – hǎoshì\ngùshi – gǔshī\ndìfang – dìfāng\nbànfǎ – fāngfǎ\nzāogāo – cǎobāo\njúzi – jùzi","s":"HSK2_29#41"},{"c":"khac","t":"Cụm từ luyện bổ ngữ kết quả","x":"回到了学校 / 回到了宿舍 / 回到了家 / 找到了人\n关上门 / 关上电视 / 开开门 / 开开电视\n洗完了 / 喝完了 / 读完了 / 看完了\n买到了 / 听到了 / 看见了 / 听见了\n看懂了 / 听懂了 / 做对了 / 说对了\n做错了题 / 写错了字 / 看错了时间 / 打错了电话\n看完了没有 / 做完了没有 / 做对了没有 / 写错了没有\n没有看完 / 没有做完 / 没有做对 / 没有写错","s":"HSK2_29#42"}],"30":[{"c":"tu_mo_rong","t":"Các cụm chỉ thời lượng","x":"一秒钟 / 五分钟 / 一刻钟 / 半个小时（钟头）/ 一个小时（钟头）/ 半天 / 一个上午 / 一个下午 / 一个晚上 / 一会儿 / 三天 / 一星期 / 三周 / 半个月 / 两个月 / 半年 / 一年 / 五十年 / 一百年","s":"HSK2_30#52"},{"c":"ngu_phap","t":"Giới từ 对 nêu đối tượng","x":"Giới từ 对 kết hợp với danh từ chỉ người, sự việc hoặc nơi chốn, nói rõ đối tượng của động tác.\n你对这儿的生活已经习惯了吧？\n他对我很好。\n练气功对身体很有好处。","s":"HSK2_30#39"},{"c":"ngu_phap","t":"好 + 一/几/多/久: nhấn mạnh nhiều, lâu","x":"Phó từ 好 dùng trước 一、几、多、久… nhấn mạnh số lượng nhiều, thời gian lâu. VD: 练了好几年了。\n他学了好几年了。\n我等了你好一会儿了。\n我们学了好多生词了。","s":"HSK2_30#39"},{"c":"ngu_phap","t":"Bổ ngữ thời lượng: định nghĩa và từ thường dùng","x":"Bổ ngữ thời lượng biểu đạt thời gian diễn ra của động tác hoặc thời gian duy trì của trạng thái.\nThường dùng: 一会儿、一分钟、一刻钟、半个小时、一个小时、半天、半个月、一个月、半年、一年.\nChủ ngữ + động từ + (了) + bổ ngữ thời lượng:\n她在大学学了两年。\n他在中国生活了一年。\n我每天都坚持锻炼一个小时。","s":"HSK2_30#41"},{"c":"ngu_phap","t":"Bổ ngữ thời lượng với tân ngữ","x":"Chủ ngữ + động từ + tân ngữ + động từ (lặp) + (了) + bổ ngữ thời lượng: 他游泳游了一个下午。她学汉语学了两个多月了。我写汉字写了半个小时。\nTân ngữ chỉ người thì không cần lặp động từ: 我找了你一个小时。我们在这儿等她一会儿吧。\nTân ngữ không phải đại từ nhân xưng: bổ ngữ thời lượng có thể đặt giữa động từ và tân ngữ, có thể thêm 的:\nA：你看了多长时间（的）电视？B：我看了一个小时（的）电视。\nA：你学了几年（的）汉语？B：我学了两年（的）汉语。\nA：他在北京住了多长时间？B：他在北京住了五天。","s":"HSK2_30#42"},{"c":"ngu_phap","t":"V了… và V了…了: đối chiếu","x":"她学了一年汉语。（现在可能已不学汉语了。）/ 她学了一年汉语了。（现在还在学习。）\n他在北京住了两年。（现在不在北京住。）/ 他在北京住了两年了。（现在还在北京住。）\n我吃了十个饺子。（可能不吃了。）/ 我吃了十个饺子了。（还在吃。）","s":"HSK2_30#43"},{"c":"ngu_phap","t":"Biểu thị số lượng xấp xỉ: 3 cách","x":"1. Dùng hai số liền nhau: 我每天晚上学习两三个小时。一件羽绒服要三四百块钱。\n2. Dùng 多: 这些苹果一共五斤多。这件毛衣二百多块。我来中国已经两个多月了。\n3. Dùng 几: 昨天去了十几个人。我们大学有几千留学生呢。","s":"HSK2_30#44"},{"c":"ngu_phap","t":"Động từ ly hợp: 3 đặc điểm","x":"1. Phần lớn không mang tân ngữ: 我去大使馆跟朋友见面。（不能说：我去大使馆见面朋友。）\n2. Bổ ngữ thời lượng và bổ ngữ động lượng chỉ đặt giữa kết cấu động – tân: 我睡了七个小时觉。（不能说：我睡觉了七个小时。）\n3. Hình thức lặp lại của một số động từ ly hợp là AAB: 游游泳、见见面、洗洗澡、跳跳舞。","s":"HSK2_30#45"},{"c":"ngu_am","t":"Phân biệt âm, thanh điệu","x":"búguò – bǔ kè\ncónglái – chóng lái\nyìbān – yíbàn\ngōngkè – gōngkē\nyóuyǒng – yǒuyòng\ngǎnxiè – gǎixiě","s":"HSK2_30#51"},{"c":"van_hoa","t":"Thành ngữ 三天打鱼，两天晒网","x":"三天打鱼，两天晒网 (sān tiān dǎ yú, liǎng tiān shài wǎng): Chỉ việc học tập hoặc làm việc thất thường, không kiên trì, bữa đực bữa cái, làm được chút lại nghỉ.","s":"HSK2_30#36"}],"31":[{"c":"ngu_phap","t":"怎么说呢","x":"怎么说呢: Nói thế nào nhỉ – biểu thị không dễ nói ra, không biết nói như thế nào.","s":"HSK3_01#45"},{"c":"ngu_phap","t":"还是: biểu thị sự lựa chọn","x":"还是: hay là – biểu thị sự lựa chọn sau khi đã so sánh giữa hai sự vật.\nA：我们去上海还是去西安？B：还是去西安吧。\n我们还是坐火车去吧。(已经与坐飞机或坐汽车等做了比较)\n我还是喜欢古典音乐。(已与现代音乐或流行音乐等做了比较)","s":"HSK3_01#45"},{"c":"ngu_phap","t":"这几年","x":"这几年 có nghĩa là 最近几年 (mấy năm gần đây, mấy năm nay). Đại từ nghi vấn 几 ở đây biểu thị số lượng nhỏ hơn 10.\n这几年变化很大\n上海的气温比北京高好几度","s":"HSK3_01#46"},{"c":"ngu_am","t":"Luyện phát âm","x":"chéngshì – chéngshí\ntiānqì – diànqì\nyùbào – yìbào\nqìwēn – qùwén\nfàndiàn – fángjiān\nchàngpiàn – chángjiàn\nmíngqǔ – míngqì\nliúxíng – lǚxíng","s":"HSK3_01#63"},{"c":"ngu_am","t":"Luyện đọc cụm từ và câu","x":"歌迷　球迷　电影迷　京剧迷　舞迷\n高得多　大得多　好得多　多得多　漂亮得多\n飞机比火车快 – 火车没有飞机快\n田芳比张东考得好 – 张东没有田芳考得好\n麦克跑得比我快 – 爱德华跑得比麦克更快\n今天比昨天暖和 – 今天的气温比昨天高两度","s":"HSK3_01#64"}],"32":[{"c":"ngu_am","t":"Luyện phát âm","x":"jìjié – jùjué\nyíyàng – yìyàng\njiāxiāng – jiāqiáng\nqìhòu – jīgòu\nzhǐshì – zhīshi\nyíqiè – yìxiē","s":"HSK3_02#32"},{"c":"ngu_am","t":"Luyện đọc cụm từ","x":"这两个一样　这两张桌子一样\n这两辆汽车颜色不一样　这两件毛衣大小不一样\n他考得跟玛丽一样好　他说得跟玛丽一样流利\n我跟你一样喜欢唱歌　我跟你一样喜欢旅行\n不但好而且很便宜　不但会唱而且唱得很好","s":"HSK3_02#33"}],"33":[{"c":"ngu_phap","t":"着什么急 – 什么 biểu thị không vừa ý","x":"什么 mang sắc thái không vừa ý, phản đối đối phương:\n说什么？别说了，上课了。\n着什么急？时间还早呢。\n你笑什么？有什么可笑的？","s":"HSK3_03#39"},{"c":"ngu_phap","t":"该……了: nên … rồi","x":"该……了: nên … rồi.\n十二点了，该睡觉了。\n时间到了，该出发了。","s":"HSK3_03#39"},{"c":"ngu_am","t":"Luyện phát âm","x":"huá xuě – huàxué\nlǚyóu – lǐyóu\njīngyíng – jīngyīng\nfā cái – fā dāi\nzháojí – zhàojí\ndiànchí – diànshì\nchídào – zhīdào\nyuànyì – yuányì","s":"HSK3_03#49"},{"c":"ngu_am","t":"Luyện đọc cụm từ","x":"天热了　天冷了　下雨了　下雪了\n不来了　不去了　不发烧了　头不疼了\n冬天到了，快下雪了　春天来了，天（气）暖和了\n夏天了，天（气）热了　秋天了，天（气）凉快了\n要开车了　要下雨了　飞机就要起飞了\n圣诞节就要到了　新年快要到了　学校要放假了\n该起床了　该吃饭了　该出发了　该下课了　该走了　该睡觉了\n高兴地告诉我　着急地对我说　客气地对他讲\n愉快地工作　努力地学习　快乐地生活","s":"HSK3_03#50"}],"34":[{"c":"ngu_am","t":"Luyện phát âm","x":"dōngxi – dōng xī\nshùnbiàn – suíbiàn\nmáfan – mǎi fàn\nxīnkǔ – xìngfú\nzhùyì – zhǔyi\nwèn hǎo – wènhào\nyāoqiú – yāoqǐng\nqīngchu – qīngchú","s":"HSK3_04#48"},{"c":"ngu_am","t":"Luyện đọc bổ ngữ xu hướng","x":"上来　下来　进来　出来　回来　过来　起来\n上去　下去　进去　出去　回去　过去\n带来　带去　拿来　拿去　跑来　跑去\n上楼来　进教室来　回学校来\n下楼去　出教室去　到大使馆去\n带来一些东西　买来一本词典\n捎去一些苹果　带去一件衣服","s":"HSK3_04#49"},{"c":"van_hoa","t":"Cách xưng hô thân thuộc của người Trung Quốc","x":"小 + họ: xưng hô với người trẻ tuổi – 小林、小赵\n老 + họ: xưng hô với người lớn tuổi hơn – 老王、老张","s":"HSK3_04#37"}],"35":[{"c":"ngu_am","t":"Luyện phân biệt âm","x":"jīnglì – jīnglǐ; gǎnmào – kàn bào\nzhùyuàn – chūyuàn; zhōngyī – zhòng yì\nfāngfǎ – fàn fǎ; zhā zhēn – cházhèng\nyǎnzòu – yuánqiú; gāngqín – gǎnqíng","s":"HSK3_05#50"},{"c":"khac","t":"Luyện cụm từ","x":"来过 去过 吃过 喝过\n好听 好看 好吃 好玩儿\n好极了 冷极了 热极了 好看极了\n第一次 第二天 第三年 第四节课\n来过中国 吃过馒头 学过汉语 打过篮球\n打过电话 喝过中国茶 听过中国歌 看过中国电影\n来过一次中国 吃过一次北京烤鸭 得过一次感冒\n一次也没去过 一次也没看过 一遍也没读过","s":"HSK3_05#51"}],"36":[{"c":"tu_mo_rong","t":"Từ thay thế cho 马马虎虎","x":"还可以 (hái kěyǐ): khá ổn, cũng được\n还行 (hái xíng): cũng được, tạm ổn\n一般般 (yìbānbān): bình thường thôi, không có gì đặc sắc","s":"HSK3_06#35"}],"40":[{"c":"khac","t":"Luyện tập: cụm từ với 着 và 倒","x":"倒酒、倒水、倒茶、倒咖啡；听着、看着、说着、坐着、走着、笑着、站着、玩着、等着；拿着、放着、摆着、挂着、穿着、戴着、贴着、躺着、提着；挂着灯笼、挂着地图、挂着衣服、挂着画；穿着西服、穿着裙子、戴着手表、戴着眼镜；带着照相机、带着护照、带着孩子、带着学生；做着作业、打着手机、上着课、吃着饭；坐着听课、站着上课、躺着看书、笑着回答。","s":"HSK3_10#44"}]}};
